    pointer("pointermove", { buttons: 0 }); mouse("mousemove", {});
    pointer("pointerdown", { button: 0, buttons: 1 }); mouse("mousedown", { button: 0, buttons: 1 });
    pointer("pointerup", { button: 0, buttons: 0 }); mouse("mouseup", { button: 0, buttons: 0 });
