  const readThemePrev = () => {
    try {
      const data = JSON.parse(localStorage.getItem(THEME_PREV_KEY) ?? "null");
      return data && typeof data === "object" && !Array.isArray(data) ? data : {};
    } catch { return {}; }
  };
