  // поэтому кэш обычной высоты (state.natural), в отличие от шрифта, не сбрасываем.
  const removeSize = source => {
    detachSheet(sizeSheet);
    try { sizeSheet.replaceSync(""); } catch {}
    themeState.size = null;
    themeState.sizeSource = source ?? null;
  };
  const applySize = (size, source) => {
    const clean = normalizeSize(size);
    if (!clean) { removeSize(source); return null; }
    try { sizeSheet.replaceSync(sizeCss(clean)); } catch { return null; }
    if (!adoptSheet(sizeSheet)) return null;
    themeState.size = clean;
    themeState.sizeSource = source ?? null;
    return clean;
  };
  // «Живой» панели — главный (WF204, решение Элвиса 09.10 02:50; как Swift
  // `ProjectPaint.liveLook` WF200): живой фон и его схема у окна ВСЕГДА из look
  // у `*` (нет его там — фон выключен), а неон и плотность — свои, по обычной
  // цепочке. Без этого сброс окна («🧹 Всё как у Claude» пишет look "none",
  // который сильнее `*`) и старые записи чатов с aurora:false навсегда гасили
  // «Живой» у чата. Одна точка — applyLayer: через неё идут восстановление, смена
  // чата, команда окна и «всем окнам»; примерка показывает ровно то, что примеряют.
  const liveLookOver = value => {
    const all = entryLayer(themeEntry(readThemeMap()[THEME_ALL_KEY]), "look");
    const own = value && typeof value === "object" ? value : {};
    const aurora = all?.aurora === true;
    return normalizeLook({ neon: own.neon, dense: own.dense, aurora, scheme: aurora ? all.scheme : undefined, motion: aurora ? all.motion : undefined });
  };
  // Своя часть look окна — то, что сброс окна вправе перекрыть у `*`.
  const lookOwnPart = look => Boolean(look && (look.neon === true || look.dense === true));
  const applyLayer = (layer, value, source) => {
    if (layer === "font") { if (value) applyFont(value, source); else removeFont(source); return; }
    if (layer === "size") { if (value) applySize(value, source); else removeSize(source); return; }
    if (layer === "look") { applyLook(source === "preview" ? value : liveLookOver(value), source); return; }
    if (value) applyTheme(value, source); else removeTheme(source);
  };
  const applyLayers = (layers, source) => {
    for (const layer of THEME_LAYERS) if (layer in layers) applyLayer(layer, layers[layer], source);
  };

  // Порядок восстановления у КАЖДОГО слоя свой: запись чата (`id:<id>`, а нет её
  // — `chat:<заголовок>`; см. chatEntry) → своя сессия окна → у главного окна
  // запись окна (`main`) → запись «для всех». Чат стоит ПЕРВЫМ нарочно: сессия у
  // окна одна на все разговоры, и
  // стоя выше она перекрывала бы цвет чата, в который окно только что вернулось
  // (разбор критика, п. 2). Тема у окна своя, а шрифт общий — законная пара,
  // поэтому слои и разведены. Явный сброс («none») сильнее следующего уровня и
  // переживает перезапуск. Возвращает true, когда ждать больше нечего (ключ уже
  // известен). clear=true — «конец предпросмотра»: слой, которого в хранилище
  // нет, надо не оставить как есть (на экране сейчас примеренные цвета), а
  // снять. Смена чата сюда не ходит — у неё свой путь, applyChatEntry.
  const restoreTheme = (clear, onlyLayers) => {
    if (!themable) return true;
    const session = readSessionEntry();
    const map = readThemeMap();
    const chat = chatEntry(map);
    // Запись окна берёт только главное окно: у подчинённого своего `main` нет,
    // и чужой он не касается.
    const own = isMainWindow() ? mapEntry(map, THEME_MAIN_KEY) : null;
    const all = themeEntry(map[THEME_ALL_KEY]);
    for (const layer of (onlyLayers ?? THEME_LAYERS)) {
      const fromChat = entryLayer(chat, layer);
      if (fromChat !== undefined) { applyLayer(layer, fromChat, "chat"); continue; }
      const fromSession = entryLayer(session, layer);
      if (fromSession !== undefined) { applyLayer(layer, fromSession, "session"); continue; }
      const fromWindow = entryLayer(own, layer);
      if (fromWindow !== undefined) { applyLayer(layer, fromWindow, "window"); continue; }
      const fromAll = entryLayer(all, layer);
      if (fromAll !== undefined) applyLayer(layer, fromAll, "all");
      else if (clear) applyLayer(layer, null, null);
    }
    return themeKey() != null;
  };

  // То же значение слоя, что взяло бы восстановление, но БЕЗ применения: нужно
  // размеру, у которого половинки независимы, — команда «размер ответов 16» без
  // этого стёрла бы выбранный размер вопросов.
  const storedLayer = layer => {
    if (!themable) return null;
    const map = readThemeMap();
    const chain = [
      chatEntry(map),
      readSessionEntry(),
      isMainWindow() ? mapEntry(map, THEME_MAIN_KEY) : null,
      themeEntry(map[THEME_ALL_KEY]),
    ];
    for (const entry of chain) {
      const value = entryLayer(entry, layer);
      if (value !== undefined) return value;
    }
    return null;
  };

  // Запись по ключу и по слоям. Сброс пишем маркером "none" только когда у ЭТОГО
  // слоя есть запись «для всех» — иначе запись лишняя. Пустая запись не хранится.
  // Основа записи — mapEntry: у ключа чата это может быть старая запись `w:`, и
  // взять её обязательно, иначе перенос потерял бы второй слой.
  const setMapLayers = (map, key, layers) => {
    const entry = mapEntry(map, key) ?? {};
    const all = themeEntry(map[THEME_ALL_KEY]);
    for (const layer of THEME_LAYERS) {
      if (!(layer in layers)) continue;
      if (layers[layer]) entry[layer] = layers[layer];
      // Сброс look перекрывает у `*` лишь неон и плотность: живой фон — всегда от `*` (WF204).
      else if (layer === "look" ? lookOwnPart(entryLayer(all, layer)) : entryLayer(all, layer)) entry[layer] = "none";
      else delete entry[layer];
    }
    if (Object.keys(entry).length) map[key] = { ...keepOwner(entry, map[key]), at: Date.now() }; else delete map[key];
    // Перенос старой записи: всё, что в ней было, уже в entry.
    const legacy = legacyKey(key);
    if (legacy != null) delete map[legacy];
  };

  // Куда пишется выбор «тема этого окна»: запись чата — её увидит любое окно с
  // этим разговором, — и у главного окна ещё и `main`, чтобы окно «в целом»
  // помнило цвет и не теряло его на новом чате. У безымянного чата ключа нет
  // (chatKey отдаёт null на заголовках-заглушках), и выбор ложится только в
  // `main` да в сессию — иначе он достался бы всем безымянным чатам разом.
  // WF35: пока id известен, пишем ОБА ключа чата — id главный, имя остаётся
  // тенью для окон, которые id ещё не знают.
  const writeKeys = () => {
    const keys = [];
    const id = chatIdKey();
    if (id) keys.push(id);
    const title = chatTitleKey();
    if (title) keys.push(title);
    if (isMainWindow()) keys.push(THEME_MAIN_KEY);
    return keys;
  };
  const writeLayers = layers => {
    // Перенос ДО записи обязателен: setMapLayers начинает с mapEntry(map, key),
    // и без переноса запись `id:` родилась бы с одним слоем этой команды.
    migrateChatKey();
    const keys = writeKeys();
    if (keys.length) {
      const map = readThemeMap();
      for (const key of keys) setMapLayers(map, key, layers);
      // Тень теперь этого чата (z1-r01): окно знает id — ставит себя владельцем.
      const id = chatIdKey();
      const title = chatTitleKey();
      if (id && title && map[title] && typeof map[title] === "object") map[title].by = id.slice(THEME_ID_PREFIX.length);
      writeThemeMap(map);
    }
    storeSessionLayers(layers);
  };
  // Выбор сделан до того, как у окна появился заголовок (about:blank сразу после
  // открытия) или пока чат ещё безымянный: записываем, когда ключ чата появится,
  // но не дольше десяти секунд — дальше это уже не «тот самый выбор». Заголовок-
  // заглушка ключом не считается, и ждать под ней нечего — она не запись чата.
  const flushPendingLayers = () => {
    const layers = themeState.pending;
    if (!layers) return;
    if (now() > themeState.pendingUntil) { themeState.pending = null; return; }
    if (!chatKey()) return;
    themeState.pending = null;
    writeLayers(layers);
  };

  const stopChatWatch = () => {
    if (themeState.chatTimer) { clearInterval(themeState.chatTimer); themeState.chatTimer = 0; }
    if (themeState.chatObserver) {
      try { themeState.chatObserver.disconnect(); } catch {}
      themeState.chatObserver = null;
    }
  };
  track(stopChatWatch);
  // Смена чата в главном окне — это смена document.title, больше ничего: страница
  // не перезагружается, инжект заново не приходит. Поэтому за заголовком следим
  // всё время жизни окна и на каждую смену перечитываем хранилище. В подчинённом
  // окне тот же сторож ловит момент, когда заголовок наконец появился.
  //
  // Чат, родившийся в окне (прежнего ключа нет: домашний экран, безымянный чат),
  // берёт ТОЛЬКО свою запись, и только те слои, которые в ней есть. Записи нет —
  // на экране не трогаем ничего: ⌘N и «Обкэшить» открывают чат без записи, и
  // окно обязано остаться того же цвета (слово Элвиса; разбор критика WF9, п. 3).
  //
  // Переход из чата в ДРУГОЙ чат (WF82, #7103) — полный порядок слоёв, как на
  // инжекте: запись чата → сессия окна → `main` → «всем», а слоя нет нигде —
  // снять. Слово Элвиса 22.09: «у двух нижних [закреплённых] тема меняется: пришли
  // из зелёного — зелёная, из „Ночи кода“ — оранжевая… своей темы что ли нет?».
  // Записей у этих чатов не было вовсе (замер WF82: в копии карты у приложения —
  // 121 запись, последняя 23.09 01:27 — их id нет), и правило «не трогать ничего»
  // оставляло им цвет того чата, откуда пришли. Теперь такой чат — в цвете окна, и вид его не
  // зависит от пути. Цвет проекта окну приносит приложение (покраска по проекту,
  // 4–15 с после перехода), и та же команда пишет чату его запись — со второго
  // захода чат сразу в своём цвете. Двойная смена возможна один раз на чат: если
  // окно было в цвете записи прошлого чата, а тема окна и проекта другие.
  // Живые цвета слой темы держат сами — его здесь не трогаем, иначе окно мигало
  // бы до следующего тика круга.
  const applyChatEntry = () => {
    const entry = chatEntry(readThemeMap());
    if (!entry) return;
    for (const layer of THEME_LAYERS) {
      const value = entryLayer(entry, layer);
      if (value !== undefined) applyLayer(layer, value, "chat");
    }
  };
  const syncChatTheme = () => {
    if (!state.alive || !themable) return;
    const key = chatKey();
    touchThemeMap();
    if (key === themeState.chatKey) return;
    // Пока идёт предпросмотр, на экране намеренно не то, что в хранилище: ключ не
    // запоминаем, чтобы смена чата не «съелась» и применилась после конца примерки.
    if (themeState.previewing) return;
    const from = themeState.chatKey;
    themeState.chatKey = key;
    // Сначала дописываем несохранённый выбор: иначе восстановление затрёт на
    // экране только что выбранную тему.
    flushPendingLayers();
    // У попапа id приезжает ПОЗЖЕ инжекта (карту попапов наполняет probe), и без
    // этого вызова перенос записи на `id:` в попапе не случился бы никогда.
    try { migrateChatKey(); } catch {}
    // Из чата в чат — полный порядок слоёв (#7103). Цепочка «Нового окна» (12б)
    // проходит домашний экран быстрее круга сторожа и возвращает окно назад —
    // пока она идёт, окно живёт по старому правилу, как при ⌘N.
    if (from && key && state.newWindow?.busy !== true) {
      try { restoreTheme(true, liveState.on ? THEME_LAYERS.filter(layer => layer !== "theme") : THEME_LAYERS); } catch {}
      return;
    }
    try { applyChatEntry(); } catch {}
  };
  const watchChatTitle = () => {
    stopChatWatch();
    themeState.chatKey = chatKey();
    if (!themable) return;
    // Наблюдатель ловит смену заголовка тем же кадром, опрос — страховка на
    // случай, когда <title> подменили целиком или наблюдатель не встал.
    try {
      const host = document.head ?? null;
      if (host && typeof MutationObserver === "function") {
        const watcher = new MutationObserver(() => { try { syncChatTheme(); } catch {} });
        watcher.observe(host, { childList: true, subtree: true, characterData: true });
        themeState.chatObserver = watcher;
      }
    } catch { themeState.chatObserver = null; }
    themeState.chatTimer = setInterval(() => {
      if (!state.alive) { stopChatWatch(); return; }
      try { syncChatTheme(); } catch {}
      try { syncHomeFolderTheme(); } catch {}
    }, THEME_TITLE_TICK_MS);
  };

  // Вид домашнего экрана по папке (#6845, слово Элвиса: «когда я меняю здесь название проекта, чтобы
  // тема сразу менялась под название проекта»). Вид проекта знает только приложение (покраска по
  // проекту, план WF37 C2): папку чипа оно узнаёт кругом probe раз в 4 с — это и было «не сразу».
  // Страница помнит, каким видом приложение (или выбор Элвиса) покрасило домашний экран при этой
  // папке, и на смене папки в списке показывает его сама, тем же тиком сторожа заголовка. Запись
  // карты не трогаем — её сделает команда приложения следом; папки ещё не видели — ждём её, как раньше.
  // Пока идёт «Новое окно», чип показывает папку БУДУЩЕГО чата: chatsFolder тогда молчит, и смену
  // после цепочки мы сменой не считаем.
  const HOME_FOLDER_THEMES_KEY = "myclaude-home-folders-v1";
  const HOME_FOLDER_THEMES_LIMIT = 40;
  const homeFolderState = { folder: null };
  const readHomeFolderThemes = () => {
    try {
      const data = JSON.parse(localStorage.getItem(HOME_FOLDER_THEMES_KEY) ?? "null");
      return data && typeof data === "object" && !Array.isArray(data) ? data : {};
    } catch { return {}; }
  };
  // Выбор лёг в `main` на домашнем экране — запоминаем его за папкой чипа (зовёт runThemeCommand).
  const homeFolderRemember = () => {
    if (!isMainWindow() || location.pathname !== NEW_WINDOW_HOME_PATH) return;
    const folder = chatsFolder(false);
    if (!folder) return;
    homeFolderState.folder = folder;
    const entry = mapEntry(readThemeMap(), THEME_MAIN_KEY);
    const saved = readHomeFolderThemes();
    delete saved[folder];
    if (entry && Object.keys(entry).length) saved[folder] = entry;
    const keys = Object.keys(saved).slice(-HOME_FOLDER_THEMES_LIMIT);
    try {
      if (!keys.length) localStorage.removeItem(HOME_FOLDER_THEMES_KEY);
      else localStorage.setItem(HOME_FOLDER_THEMES_KEY, JSON.stringify(Object.fromEntries(keys.map(key => [key, saved[key]]))));
    } catch {}
  };
  const syncHomeFolderTheme = () => {
    if (!themable || !isMainWindow() || location.pathname !== NEW_WINDOW_HOME_PATH || themeState.previewing) {
      homeFolderState.folder = null;
      return;
    }
    const folder = chatsFolder(true);
    if (!folder) { if (state.newWindow?.busy === true) homeFolderState.folder = null; return; }
    if (folder === homeFolderState.folder) return;
    const from = homeFolderState.folder;
    homeFolderState.folder = folder;
    // Первый взгляд (пришли на домашний экран) — не смена: окно держит свой цвет, как при ⌘N.
    if (!from) return;
    const entry = readHomeFolderThemes()[folder];
    if (!entry || typeof entry !== "object") return;
    const all = themeEntry(readThemeMap()[THEME_ALL_KEY]);
    for (const layer of THEME_LAYERS) {
      // Живые цвета держат слой темы сами (как у смены чата).
      if (layer === "theme" && liveState.on) continue;
      const own = entryLayer(entry, layer);
      if (own !== undefined) { applyLayer(layer, own, "window"); continue; }
      const fromAll = entryLayer(all, layer);
      applyLayer(layer, fromAll ?? null, fromAll !== undefined ? "all" : null);
    }
  };

  // Окно адресуют заголовком, как в «Обкэшить»; заголовка нет — берёт окно под
  // фокусом. Подчинённое окно (about:blank) себя в фокусе может и не считать.
  // Необязательное поле match (WF15) адресует окно ПУТЁМ страницы
  // ("/epitaxy/local_<id>" — приложение берёт его из status.json лоадера) и
  // сильнее заголовка: у главного окна на вкладке Claude Code заголовок —
  // заглушка «Claude», и такой же носят безымянные попапы, так что команда
  // по заголовку ушла бы веером им всем. Поля нет — поведение прежнее.
  // Необязательное поле chat (WF29) адресует окно ID ЧАТА и стоит МЕЖДУ match и
  // заголовком: у попапа путь — "blank", и match ему бесполезен, а заголовок он
  // носит снимком имени чата на момент выноса в окно — чат с тех пор могли
  // переименовать, и по заголовку окно не опознаётся вовсе (задача #5455).
  // Свой id страница знает синхронно (myChatId(), раздел 12в): главное окно —
  // из пути, попап — из кэша ответа родителя. Команда приходит событием, ждать
  // промиса ей нечем; id неизвестен — команда не наша, и приложение пришлёт её
  // заголовком на следующем тике. Лучше не покраситься, чем покраситься чужим
  // проектом. match и chat разом приложение не шлёт никогда.
  const addressed = detail => {
    if (typeof detail.match === "string") return location.pathname === detail.match;
    if (typeof detail.chat === "string") {
      const id = myChatId();
      return Boolean(detail.chat) && id === detail.chat;
    }
    const title = typeof detail.title === "string" ? detail.title.trim() : "";
    return title ? windowTitle() === title : document.hasFocus();
  };

  // Команда меню, порядок полей по контракту WF12: {id, action:"theme", at,
  // scope:"window"|"all", title, preview, theme|null, font|null,
  // size:{answer?,question?}|null, look:{aurora,neon,dense,scheme?,motion?}|null}
  // (look — WF83; ключа в объекте нет — тумблер выключен; scheme — WF146; motion — #9994; fly* — #10015).
  // Поле frame (снятая рамка, #9471; его ещё шлёт гашение приложения) не читается: команда с одним frame — мимо.
  // Поля слоя нет — слой не трогаем, null — сброс слоя, значение — применить.
  // У размера то же правило действует и на КАЖДУЮ половину (WF19): поля половины
  // нет — не трогаем, число — поставить, null — снять её одну («Как у Claude» в
  // «Размер ответов ▸» не уносит с собой размер вопросов). "size":null по-прежнему
  // снимает обе — этим ходит «🧹 Всё как у Claude».
  // «Для всех» перекрывает СВОЙ слой у всех окон и чужой не трогает: «шрифт
  // всем» не снимает тем у окон, «тема всем» не снимает их шрифтов.
  // «Для окна» адресуется заголовком, как «Обкэшить», либо необязательным
  // полем match — путём страницы (WF15, см. addressed()).
  // Примерка была, а закрепили не все слои: остальные — назад из хранилища.
  const endPreviewExcept = committedLayers => {
    if (!themeState.previewing) return;
    themeState.previewing = false;
    themeState.previewLayers = [];
    const rest = THEME_LAYERS.filter(layer => !committedLayers.includes(layer));
    if (rest.length) restoreTheme(true, rest);
  };

  const runThemeCommand = detail => {
    if (!themable || !detail || typeof detail !== "object") return false;
    const layers = {};
    for (const layer of THEME_LAYERS) {
      if (!(layer in detail)) continue;
      // Размер — единственный слой, у которого команда богаче записи: половину
      // можно снять по отдельности (WF19, normalizeSizeCommand). Остальные слои
      // разбирает общая карта.
      layers[layer] = layer === "size"
        ? normalizeSizeCommand(detail[layer])
        : LAYER_NORMALIZE[layer](detail[layer]);
    }
    // Размер — единственный слой с половинками: «Размер ответов ▸ 16» приходит
    // без поля question, и оно обязано остаться прежним. Недостающую половину
    // дописываем здесь, и дальше слой ходит по коду цельным, как тема и шрифт.
    // Основа у примерки — то, что сейчас на экране (мышь ведут по подменю и
    // половинки примеряются одна за другой), у закрепления — хранилище: иначе
    // выбор «размер вопросов» утащил бы за собой примеренный размер ответов.
    if (layers.size) {
      const base = detail.preview === true
        ? themeState.size
        : (detail.scope === "all"
          ? entryLayer(themeEntry(readThemeMap()[THEME_ALL_KEY]), "size")
          : storedLayer("size"));
      const merged = { ...(base ?? {}), ...layers.size };
      // Единственное место, где снятая половина исчезает, — сразу после слияния и
      // ДО экрана (applyLayers), карты (writeLayers), сессии (storeSessionLayers) и
      // отложенной записи (themeState.pending): в хранилище половина со значением
      // null читается как «слоя нет» (entryLayer), и запись вышла бы неверной.
      for (const half of SIZE_HALVES) if (merged[half] == null) delete merged[half];
      // Снята последняя половина — слоя больше нет вовсе: это полный сброс, как
      // "size":null (и как старый пустой {}).
      layers.size = Object.keys(merged).length ? merged : null;
    }
    // Предпросмотр (мышь ведут по подменю тем и шрифтов): слои из команды идут
    // ТОЛЬКО в таблицы стилей, хранилища они не касаются вовсе — иначе проход
    // по списку записал бы в карту каждую тему, мимо которой проехала мышь.
    // Предпросмотр всегда адресован одному окну, scope тут не при чём.
    if (detail.preview === true) {
      if (Object.keys(layers).length === 0 || !addressed(detail)) return false;
      // Новая примерка перекрывает прежнюю (WF31, #5453): слои, которые примерялись
      // до неё и в эту команду не попали, возвращаются из хранилища. Иначе проезд по
      // «🔤 Шрифт ▸» оставлял бы чужой шрифт на всех цветах, мимо которых мышь пойдёт
      // дальше. Возврат стоит ПОСЛЕ guard нарочно: команда, адресованная ЧУЖОМУ окну,
      // наши слои не трогает вовсе.
      const rest = themeState.previewLayers.filter(layer => !(layer in layers));
      if (rest.length) restoreTheme(true, rest);
      applyLayers(layers, "preview");
      themeState.previewing = true;
      themeState.previewLayers = Object.keys(layers);
      return true;
    }
    // Конец предпросмотра: меню закрылось, ничего не выбрав. Оба слоя
    // возвращаем из хранилища, а слой, записи о котором нигде нет, снимаем.
    if (detail.preview === false && Object.keys(layers).length === 0) {
      if (!addressed(detail)) return false;
      restoreTheme(true);
      themeState.previewing = false;
      themeState.previewLayers = [];
      return true;
    }
    if (Object.keys(layers).length === 0) return false;
    if (detail.scope === "all") {
      const map = readThemeMap();
      const next = {};
      const all = themeEntry(map[THEME_ALL_KEY]);
      // #5743: «всем окнам» — подложка. Свой слой у окна снимаем (теперь его задаёт общая
      // запись), но не насовсем: снятое ложится на склад, а снятие общего слоя
      // («Как у Claude» → «Вернуть» в «Оформлении» панели) отдаёт его окнам назад.
      // Склад слоя заводится заново, только когда общего слоя не было: смена темы всем
      // с синей на красную снимать уже нечего, и склад первой смены обязан уцелеть.
      // Команду исполняет каждое окно, поэтому всё идемпотентно: второе окно снимать
      // уже нечего, а возврат не трогает слой, который у записи есть.
      const setting = Object.keys(layers).filter(layer => layers[layer]);
      const clearing = Object.keys(layers).filter(layer => !layers[layer]);
      const prev = readThemePrev();
      const prevBefore = JSON.stringify(prev);
      for (const layer of setting) {
        if (entryLayer(all, layer) !== undefined) continue;
        for (const saved of Object.values(prev)) if (saved && typeof saved === "object") delete saved[layer];
      }
      for (const entryKey of new Set([...Object.keys(map), ...Object.keys(prev)])) {
        if (entryKey === THEME_ALL_KEY) continue;
        const value = map[entryKey];
        const entry = themeEntry(value);
        const saved = prev[entryKey] && typeof prev[entryKey] === "object" ? prev[entryKey] : null;
        for (const layer of setting) {
          if (!(layer in entry)) continue;
          const owner = shadowOwner(value);
          prev[entryKey] = { ...(prev[entryKey] ?? {}), [layer]: entry[layer], ...(owner ? { by: owner } : {}) };
          delete entry[layer];
        }
        for (const layer of clearing) if (!(layer in entry) && saved && layer in saved) entry[layer] = saved[layer];
        if (!Object.keys(entry).length) continue;
        next[entryKey] = value === undefined && saved?.by ? { ...entry, by: saved.by } : keepOwner(entry, value);
      }
      for (const [layer, value] of Object.entries(layers)) {
        if (value) all[layer] = value; else delete all[layer];
      }
      if (Object.keys(all).length) next[THEME_ALL_KEY] = all;
      writeThemeMap(next, true, map);
      if (JSON.stringify(prev) !== prevBefore) writeThemePrev(prev);
      // Сессия окна: общий слой — в неё, снятый — из неё совсем (иначе "none" закрыл бы `main`).
      const setLayers = {};
      for (const layer of setting) setLayers[layer] = layers[layer];
      if (setting.length) storeSessionLayers(setLayers);
      if (clearing.length) dropSessionLayers(clearing);
      // Закрепление гасит предпросмотр: слой, которого в команде нет, возвращаем из
      // хранилища (примерили тему, закрепили шрифт — тема не должна зависнуть).
      endPreviewExcept(Object.keys(layers));
      applyLayers(setLayers, "all");
      // Снятый общий слой — порядком восстановления: личный слой чата вернулся со склада.
      if (clearing.length) restoreTheme(true, clearing);
      return true;
    }
    if (!addressed(detail)) return false;
    endPreviewExcept(Object.keys(layers));
    writeLayers(layers);
    applyLayers(layers, "window");
    try { homeFolderRemember(); } catch {}
    // Ключа чата ещё нет (about:blank без заголовка): запись чата дописываем,
    // когда заголовок появится (см. syncChatTheme).
    if (!chatKey()) {
      themeState.pending = layers;
      themeState.pendingUntil = now() + THEME_TITLE_WAIT_MS;
    }
    return true;
  };

  // Возврат тем после переустановки Claude (WF35). Переустановка стирает
  // localStorage страниц — вместе с ним умирает вся карта тем, и пять окон
  // Элвиса становятся серыми (#5473). Копию карты держит приложение в файле
  // ~/Library/Application Support/MyClaude/window-themes.json и присылает её
  // одной командой на все окна:
  //   {id, action:"themes-restore", at, scope:"all", entries:{<ключ>:{theme?,font?,size?,look?}}}
  // (frame из старых записей приложения не читается — слоя нет, #9471).
  // Страница НЕ заменяет свою память присланной, а ДОЛИВАЕТ недостающие слои:
  // так команда идемпотентна (память цела — не меняется ни байта), и спрашивать
  // окно «ты пуста?» не нужно вовсе. Явный сброс приезжает маркером "none" и
  // остаётся сбросом — «Как у Claude» переживает переустановку наравне с цветом.
  const RESTORE_KEY_LIMIT = 200;
  const RESTORE_KEY_MAX_LENGTH = 200;
  // Ключ из чужих рук: только наши пять видов и без пустого хвоста у префикса.
  const restoreKeyOk = key => {
    if (typeof key !== "string" || !key.length || key.length > RESTORE_KEY_MAX_LENGTH) return false;
    if (key === THEME_ALL_KEY || key === THEME_MAIN_KEY) return true;
    for (const prefix of [THEME_ID_PREFIX, THEME_CHAT_PREFIX, THEME_LEGACY_PREFIX]) {
      if (key.startsWith(prefix)) return key.length > prefix.length;
    }
    return false;
  };
  // Слой из чужих рук: "none"/null — сброс, значение — через ту же нормализацию,
  // что и команда меню; мусор равен отсутствию слоя.
  const restoreLayer = (entry, layer) => {
    if (!(layer in entry)) return undefined;
    const raw = entry[layer];
    if (raw === "none" || raw == null) return "none";
    return LAYER_NORMALIZE[layer](raw) ?? undefined;
  };
  const restoreState = { at: 0, keys: 0, merged: 0, painted: false };
  const runThemesRestoreCommand = detail => {
    if (!themable || !detail || typeof detail !== "object") return false;
    const entries = detail.entries;
    if (!entries || typeof entries !== "object" || Array.isArray(entries)) return false;
    const map = readThemeMap();
    let keys = 0;
    let merged = 0;
    for (const [key, value] of Object.entries(entries)) {
      if (keys >= RESTORE_KEY_LIMIT) break;
      if (!restoreKeyOk(key)) continue;
      const incoming = themeEntry(value);
      keys += 1;
      const mapEntryBefore = map[key];
      const current = mapEntry(map, key);
      const entry = current ? { ...current } : {};
      let added = 0;
      for (const layer of THEME_LAYERS) {
        // Всё, что у страницы уже есть, не трогаем вовсе — в том числе "none".
        if (current && layer in current) continue;
        const next = restoreLayer(incoming, layer);
        if (next === undefined) continue;
        entry[layer] = next;
        added += 1;
      }
      if (!added) continue;
      // Владелец тени (z1-r01): свой сильнее присланного; мусор не берём.
      const owner = shadowOwner(map[key]) ?? shadowOwner(value);
      map[key] = owner && key.startsWith(THEME_CHAT_PREFIX) && owner.length <= RESTORE_KEY_MAX_LENGTH
        ? { ...entry, by: owner } : entry;
      const stamp = themeStamp(current ? mapEntryBefore : value);
      if (stamp) map[key].at = stamp;
      merged += added;
    }
    if (merged) writeThemeMap(map, false);
    restoreState.at = now();
    restoreState.keys = keys;
    restoreState.merged = merged;
    // Экран трогаем, только если он наш: примерка мышью и живые цвета показывают
    // не то, что в хранилище, и перекраска сбила бы их обоих.
    restoreState.painted = !themeState.previewing && !liveState.on;
    if (restoreState.painted) { try { restoreTheme(false); } catch {} }
    return true;
  };
  // -- Края прокрутки живого вида (WF185) ----
  // Слово Элвиса 09.10 03:40: «Полосу прокрутки в режиме живом убери вообще, она только отвлекает»;
  // 03:42: «и сверху и снизу сделай плавный тоненький фейд, чтобы текст плавно терялся, а не обрезался
  // жёстко». Только живой фон (look.aurora): полос прокрутки нет нигде (прокрутка колесом и тачпадом
  // та же), у прокручиваемой области — тонкое затухание с той стороны, куда ещё есть что крутить:
  // у самого верха верхнего нет, у самого низа — нижнего, так первая и последняя строки целы.
  // Сторону знает метка SCROLL_FADE_ATTRIBUTE = top | bottom | both: её ставит прокрутка любой
  // области (событие ловим на документе) и раз в секунду обход известных областей Claude — лента,
  // список чатов, поле ввода, панели (их Tailwind-классы overflow-*-auto). Классический вид — правил
  // нет, метки снимаются: всё как у Claude.
  const SCROLL_FADE_ATTRIBUTE = "data-myclaude-scroll-fade";
  const SCROLL_FADE_PX = 14;
  const SCROLL_FADE_SELECTOR = [
    '[data-testid="epitaxy-virtual-transcript"]', ".dframe-nav-scroll",
    '[class~="overflow-y-auto"]', '[class~="overflow-auto"]', '[class~="overflow-y-scroll"]',
  ].join(",");
  // Поле и рамка, снятые сверху с рамки плиток (WF192), — шапке колонки обратно.
  const SCROLL_TOP_RETURN = "calc(var(--tiles-padding, 8px) + 1px)";
  // Низ видимой части (WF197): лента Claude длиннее своей ячейки (инлайн height: calc(100% + высота доки),
  // замер 09.10 в окне Рика: лента 1012 при ячейке 527) — в широком виде её низ за краем окна, и нижнее
  // затухание у 100 % уходило туда. Сколько ленты ниже видимого края, страница кладёт переменной узлу
  // (scrollFadeMark); затухание кончается на видимом крае, ниже — прозрачно (там ничего не видно).
  const SCROLL_FADE_CUT_VARIABLE = "--myclaude-scroll-cut";
  const SCROLL_FADE_BOTTOM = `var(${SCROLL_FADE_CUT_VARIABLE}, 0px)`;
  const SCROLL_FADE_MASKS = {
    top: `linear-gradient(to bottom, transparent 0, #000 ${SCROLL_FADE_PX}px)`,
    bottom: `linear-gradient(to bottom, #000 calc(100% - ${SCROLL_FADE_BOTTOM} - ${SCROLL_FADE_PX}px), transparent calc(100% - ${SCROLL_FADE_BOTTOM}))`,
    both: `linear-gradient(to bottom, transparent 0, #000 ${SCROLL_FADE_PX}px, #000 calc(100% - ${SCROLL_FADE_BOTTOM} - ${SCROLL_FADE_PX}px), transparent calc(100% - ${SCROLL_FADE_BOTTOM}))`,
  };
  const scrollFadeCss = () => {
    const rules = [
      // Полос прокрутки нет (Chromium: scrollbar-width сильнее ::-webkit-scrollbar — пишем оба).
      "* { scrollbar-width: none !important; }",
      "::-webkit-scrollbar { display: none !important; width: 0 !important; height: 0 !important; }",
      // WF192 (слово Элвиса 09.10 04:10: «там сейчас полоска, по ней режется фейд… фейд сделать от самого края окна
      // Claude»): рамка плиток Claude (инлайн-стиль с --tiles-padding) держит сверху поле 8 px и рамку 1 px — лента
      // начиналась ниже края окна и резалась о него. Сверху их нет: лента и её затухание — от самого края. Полоса
      // перетаскивания окна Claude (.draggable, 7 px сверху) остаётся: область окна Electron считает по стилю
      // app-region, а не по тому, что лежит поверх, — окно таскается за верх, как было. Шапку правой колонки (и
      // шапку над лентой при названии слева) возвращаем на прежнее место — сдвигается только лента.
      `div[style*="--tiles-padding"]:has(.tiles-shell) { padding-top: 0 !important; border-top-width: 0 !important; }`,
      `div[style*="--tiles-padding"] .epitaxy-chat-panel:not([data-myclaude-headless]) .epitaxy-titlebar { margin-top: ${SCROLL_TOP_RETURN} !important; }`,
    ];
    const mask = layers => `-webkit-mask-image: ${layers.join(", ")} !important; mask-image: ${layers.join(", ")} !important;` +
      (layers.length > 1 ? " -webkit-mask-composite: source-in !important; mask-composite: intersect !important;" : "");
    for (const [side, edge] of Object.entries(SCROLL_FADE_MASKS)) {
      const at = `[${SCROLL_FADE_ATTRIBUTE}="${side}"]`;
      rules.push(`${at} { ${mask([edge])} }`);
      // Лента с угловым затуханием под кнопками окна и кружком (applyCornerFade) — маски складываются.
      rules.push(`${at}[data-myclaude-corner-fade] { ${mask([CORNER_FADE_MASK, edge])} }`);
      rules.push(`${at}[data-myclaude-corner-fade][${RING_FADE_ATTRIBUTE}] { ${mask([CORNER_FADE_MASK, RING_FADE_MASK, edge])} }`);
    }
    return rules;
  };
  // Полоса прокрутки классического вида — шире и удобнее (#9845, слово Элвиса: «полосу прокрутки тоненькую эту
  // прожать, чтобы было удобно»). Только лента чата — там читают и листают; список чатов, поле ввода и меню —
  // как у Claude. Дорожка SCROLL_BAR_PX — в неё легко попасть мышью; ползунок в покое тоньше (поле прозрачной
  // рамкой), под курсором и при захвате — почти во всю дорожку и плотнее; цвет — вторичный текст темы, светлая
  // и тёмная одним правилом. Живой фон — полос нет, как было: правила выше с !important сильнее (WF185). Вес
  // (0,0,1) — сильнее только общего `* { scrollbar-width: thin }` Claude и унаследованного scrollbar-color
  // (Chromium рисует ::-webkit-scrollbar лишь при auto у обоих). Место под полосу Claude держит с обеих сторон
  // (`scrollbar-gutter: stable both-edges`) — с широкой полосой колонка текста теряла 24 px, слева впустую (#10111).
  // #11216 (слово Элвиса 30.10 17:20: «полоса прокрутки здесь слишком широкая… поуже сделать, суперпрозрачную…
  // едва-едва заметная»): дорожка 8, ползунок в покое — нитка 2 px в 18 % цвета; под курсором и при захвате
  // шире и плотнее, как было, — попасть мышью по-прежнему можно. Та же нитка — у поля ввода (его прокрутка в широком
  // виде — div:has(> .ProseMirror), в узком — корень поля с ручкой): серая полоса Claude стояла рядом и отвлекала так же.
  const SCROLL_BAR_PX = 8;
  const SCROLL_TRACK_CUT_VARIABLE = "--myclaude-track-cut";
  const SCROLL_BAR_AREA = 'html :where([data-testid="epitaxy-virtual-transcript"], [data-cds="ChatComposer"] div:has(> .ProseMirror), [data-myclaude-editor-root])';
  const SCROLL_BAR_INK = share => `color-mix(in srgb, var(--cds-text-secondary, currentColor) ${share}%, transparent)`;
  lateRules.push(
    `${SCROLL_BAR_AREA}{scrollbar-width:auto;scrollbar-color:auto;scrollbar-gutter:auto}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar{width:${SCROLL_BAR_PX}px;height:${SCROLL_BAR_PX}px;background:transparent}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-track,${SCROLL_BAR_AREA}::-webkit-scrollbar-corner{background:transparent}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-track:hover{background:${SCROLL_BAR_INK(4)}}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-thumb{min-height:40px;min-width:40px;border:3px solid transparent;border-radius:${SCROLL_BAR_PX}px;background:${SCROLL_BAR_INK(18)} padding-box}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-thumb:hover{border-width:1px;background-color:${SCROLL_BAR_INK(40)}}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-thumb:active{border-width:1px;background-color:${SCROLL_BAR_INK(55)}}`,
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-button{display:none}`,
    // #10110: лента длиннее ячейки на высоту доки (её низ за краем окна или под докой) — дорожка кончается на
    // видимом крае (запас — переменная SCROLL_TRACK_CUT_VARIABLE), у конца чата ползунок виден. Саму ленту не
    // укорачиваем: с ней на текст ложилась размытая полоса Claude под доку (page-88).
    `${SCROLL_BAR_AREA}::-webkit-scrollbar-track{margin-bottom:var(${SCROLL_TRACK_CUT_VARIABLE},0px)}`,
  );
  const scrollFadeOn = () => themeState.look?.aurora === true;
  // Сторона затухания по прокрутке узла: "" — крутить некуда (или живой вид выключен).
  const scrollFadeOf = node => {
    const room = Number(node?.scrollHeight) - Number(node?.clientHeight);
    if (!(room > 1)) return "";
    const top = Number(node.scrollTop) > 1;
    const bottom = Number(node.scrollTop) < room - 1;
    return top && bottom ? "both" : top ? "top" : bottom ? "bottom" : "";
  };
  // Сколько узла ниже видимого края: его ячейки (родителя) и окна.
  const scrollFadeCut = node => {
    try {
      const box = node.getBoundingClientRect();
      const cell = node.parentElement?.getBoundingClientRect?.();
      let edge = Number(window.innerHeight) || Infinity;
      if (cell && cell.height > 0) edge = Math.min(edge, cell.bottom);
      const cut = Math.round(box.bottom - edge);
      return cut > 1 && cut < box.height ? cut : 0;
    } catch { return 0; }
  };
  const scrollFadeMark = node => {
    if (node?.nodeType !== 1) return;
    const side = scrollFadeOn() ? scrollFadeOf(node) : "";
    if (side) { if (node.getAttribute(SCROLL_FADE_ATTRIBUTE) !== side) node.setAttribute(SCROLL_FADE_ATTRIBUTE, side); }
    else if (node.hasAttribute(SCROLL_FADE_ATTRIBUTE)) node.removeAttribute(SCROLL_FADE_ATTRIBUTE);
    const cut = side === "bottom" || side === "both" ? scrollFadeCut(node) : 0;
    const value = cut ? `${cut}px` : "";
    if ((node.style?.getPropertyValue(SCROLL_FADE_CUT_VARIABLE) ?? "") !== value) {
      if (value) node.style.setProperty(SCROLL_FADE_CUT_VARIABLE, value);
      else node.style?.removeProperty(SCROLL_FADE_CUT_VARIABLE);
    }
  };
  const scrollFadeState = { marks: 0 };
  const scrollFadeScan = () => {
    for (const node of document.querySelectorAll(`[${SCROLL_FADE_ATTRIBUTE}]`)) scrollFadeMark(node);
    if (scrollFadeOn()) for (const node of document.querySelectorAll(SCROLL_FADE_SELECTOR)) scrollFadeMark(node);
    scrollFadeState.marks = document.querySelectorAll(`[${SCROLL_FADE_ATTRIBUTE}]`).length;
    // Низ дорожки полосы ленты (#10110) — во всех видах: полоса видна там, где живого фона нет.
    for (const node of document.querySelectorAll('[data-testid="epitaxy-virtual-transcript"]')) {
      const cut = scrollFadeCut(node);
      const value = cut ? `${cut}px` : "";
      if ((node.style?.getPropertyValue(SCROLL_TRACK_CUT_VARIABLE) ?? "") !== value) {
        if (value) node.style.setProperty(SCROLL_TRACK_CUT_VARIABLE, value);
        else node.style?.removeProperty(SCROLL_TRACK_CUT_VARIABLE);
      }
    }
  };
  on(document, "scroll", event => { if (scrollFadeOn()) { try { scrollFadeMark(event.target); } catch {} } }, { capture: true, passive: true });
  track(() => { for (const node of document.querySelectorAll(`[${SCROLL_FADE_ATTRIBUTE}]`)) { node.removeAttribute(SCROLL_FADE_ATTRIBUTE); node.style?.removeProperty(SCROLL_FADE_CUT_VARIABLE); } });
  track(() => { for (const node of document.querySelectorAll('[data-testid="epitaxy-virtual-transcript"]')) node.style?.removeProperty(SCROLL_TRACK_CUT_VARIABLE); });

  // Осечка темы не должна утащить за собой ручку: раздел стоит выше её
  // постройки, и без этой обёртки любое падение на неготовой разметке оставило
  // бы окно вовсе без полоски.
  try { migrateChatKey(); restoreTheme(); watchChatTitle(); } catch {}
  // Возврат тем (WF35): когда приезжала команда themes-restore, сколько
  // ключей приняли, сколько слоёв долили и красилось ли окно (примерка и
  // живые цвета красить запрещают).
  statusPart("restore", () => ({
    at: restoreState.at || null,
    keys: restoreState.keys,
    merged: restoreState.merged,
    painted: restoreState.painted,
  }));
  // WF241: живой фон стоит — окно скрыто или дольше LOOK_IDLE_MS без фокуса.
  statusPart("lookStill", () => lookStill());
  // WF185: сколько областей прокрутки сейчас с затуханием края (живой вид; классический — 0).
  statusPart("scrollFades", () => scrollFadeState.marks);
  HATCH && Object.assign(HATCH, { scrollFadeOf, auroraCalm, LOOK_IDLE_MS, syncHomeFolderTheme });

  // ---- 2б. Полоса прогресса воркфлоу --------------------------------------
  // С WF84 (#7204, docs/design-strip-wf84.md) это ряд «мелких номеров» внутри
  // рамки поля, слева под строкой ввода: номер 12 точек на каждый воркфлоу
  // марафона, цвет — состояние (готов акцентом, идёт — контур с дышащей линией
  // шагов, ждёт тебя — жёлтый, упал — красный, впереди — пустой контур; весь
  // марафон «готово ✅» — зелёный). Состояние каждого номера — из двух вестей:
  // строки состояния чата (счёт и слово текущего) и сводки status.md (блок на
  // каждый номер, progressBadgeStates). Строка читается ТОЛЬКО у низа ленты:
  // прокрутил вверх — ряд стоит (progressRefresh). До WF84 были тонкая линия
  // (WF9–WF81) и капсулы с подписями (WF82, #7105) — их история в git log; от
  // них остались пул узлов, плавная заливка, пульс и попадание мышью.
  //
  // Источник — сам чат, а не хранилище: последняя строка состояния в ответах
  // ассистента («💭⚪[Проект](docs/status.md) · WF 6 из 7 · 40%💭», формат из
  // SkilZZZ/AGENTS.md). Поэтому каждое окно считает по своему разговору, ничего
  // не хранит и ни с кем не синхронизируется.
  //
  // Строки состояния нет — полосы нет вовсе (довод донора): пустая полоса
  // утверждала бы «марафон только начался» ровно там, где марафона нет.
  //
  // Подсказка — свой div, а не title: у полосы pointer-events:none (иначе она
  // ловила бы клики по полю ввода), а без указателя title не показывается вовсе.
  // По той же причине и наведение, и клик ловятся общими слушателями документа,
  // а не прозрачной накладкой над линией: накладка стояла бы поверх низа поля
  // ввода и съедала клики по нему.
  //
  // WF12 (подсказка по клику): наведение больше ничего не показывает — только
  // ставит «руку» в ±4 точках от линии. Подсказка открывается кликом по сегменту
  // и рассказывает про ОДИН воркфлоу, а не про весь марафон разом: раньше она
  // выскакивала сама, стоило мыши пройти над полем ввода, и закрывала пол-окна
  // сводкой. Повторный клик по тому же сегменту, Escape и клик мимо — закрывают.
  //
  // Отступление от плана: полоса не absolute внутри блока ввода, а fixed по
  // координатам — как и сама ручка. Довод записан в разделе 4 прямым текстом:
  // рамка поля живёт в чужом дереве, и свой узел туда лучше не вставлять. React
  // пересобирает низ окна на каждую смену модели, а position:absolute потребовал
  // бы ещё и менять position у чужого контейнера. Место на экране от этого не
  // меняется: считаем его по boundingClientRect рамки поля.
  const PROGRESS_ID = "myclaude-progress-bar";
  const PROGRESS_TIP_ID = "myclaude-progress-tip";
  const PROGRESS_CARD_ID = "myclaude-progress-card";
  // Вид карточки — по макету docs/9-card-opus-5.5.html (WF84, #7205), 9.1
  // «дорожка в столбик»: строки этапов рисует progressCardPaint, данные —
  // progressCardView.
  // Перечитывать ленту чаще раза в секунду незачем: строка состояния меняется
  // раз в ответ, а innerText сообщения — это принудительный reflow.
  const PROGRESS_MIN_GAP = 1000;
  // Страховочный перечёт: в тихом окне мутаций ленты может не быть вовсе.
  const PROGRESS_IDLE_MS = 10000;
  // Сколько последних ответов просматриваем. Строку состояния пишет каждый
  // ответ, поэтому дальше десятка забираться незачем, а перечитывать весь
  // длинный разговор раз в секунду — уже заметная работа.
  const PROGRESS_LOOKBACK = 12;
  // Цвет по состоянию: ждём Элвиса — жёлтый, упало — красный, «готово» —
  // зелёный (буква Элвиса 1A, WF22); «идёт» берёт акцент темы окна (её красит
  // раздел 2а). Жёлтый и красный достаются ТЕКУЩЕМУ сегменту — красным метится
  // ровно то место, где марафон встал; зелёное «готово» красит всю полосу.
  const PROGRESS_PAINT = { done: "#4dbb7d", wait: "#f5c542", fail: "#ef4444" };
  // ---- «мелкие номера» (WF84, #7204, макет docs/7-strip-opus-5.5.html) --------
  // Слово Элвиса 23.09: «Мелкие номера — прикольно… Зачем много места отнимать?».
  // Ряд капсул во всю ширину с подписями (#7105) сменился рядом маленьких
  // номеров слева, по левому краю текста поля: номер 12 точек высотой, без
  // подписей (время и слово — в карточку). Зазор 4, в тесноте 3; всё равно не
  // влезает — первые подряд готовые сливаются в один номер «1–9».
  const PROGRESS_BADGE_GAP = 4;
  const PROGRESS_BADGE_GAP_TIGHT = 3;
  // Предел номеров: марафон длиннее сорока воркфлоу — уже не марафон.
  const PROGRESS_SEG_MAX = 40;
  const PROGRESS_BADGE_HEIGHT = 12;
  const PROGRESS_BADGE_MIN = 18;
  // Ширина номера ставится узлу явно, по числу знаков: цифра 9-м кеглем —
  // около 5,5 точки, поля по 3. Явная ширина нужна подгонке («влезает ли
  // ряд») и попаданию мышью — у обоих одна и та же арифметика, что и на экране.
  const progressBadgeWidth = label => Math.max(PROGRESS_BADGE_MIN, Math.ceil(String(label ?? "").length * 5.5 + 6));
  // Место под ряд (#7189: «воздух между скриншотами и полоской»): от строки
  // ввода до номеров 6, от плиток вложений 8, плюс сам номер 12. Добавка к
  // нижнему полю рамки — 18 без вложений и 20 с ними (было 35).
  const PROGRESS_ROOM_TEXT = 6 + PROGRESS_BADGE_HEIGHT;
  const PROGRESS_ROOM_TILES = 8 + PROGRESS_BADGE_HEIGHT;
  // Плитки вложений в поле ввода: та же примета, что у раскладки вложений
  // (раздел 2а, attachmentsCss), и плашка вложения старой разметки.
  const PROGRESS_TILES_SELECTOR = "[data-cds-composer-attachments] [data-cds-attachment],.epitaxy-attachment-pill";
  // Зона попадания номера: его прямоугольник плюс 4 точки вверх и вниз (ТЗ
  // WF84, п. 5). Над номерами 6 точек пустого поля — текст поля не задет.
  const PROGRESS_HIT_SLACK = 4;
  // «При прокручивании чата вверх-вниз это поле не менялось» (слово Элвиса
  // 23.09): строку состояния читаем, только когда лента у низа. Допуск свой,
  // не TAIL_SLACK = 2: у низа лента дрожит на пару точек при стриминге.
  const PROGRESS_TAIL_SLACK = 64;
  // Запомненные строки по ключу чата (смена чата при ленте не у низа).
  const PROGRESS_KEYS_MAX = 32;
  // Смена цвета номера и появление нового — 200 мс.
  const PROGRESS_BADGE_MS = 200;
  // Уже этого якорь считается вырожденным: React как раз пересобирает низ окна,
  // и рамка на кадр съезжает в ноль. Тогда полоса садится на запасной якорь.
  const PROGRESS_MIN_WIDTH = 80;
  // ---- ряд с прокруткой (WF85, #7356) ----------------------------------------
  // Слово Элвиса 24.09: «когда workflow много, нужно сделать прокрутку
  // горизонтальную и желательно показывать под номер последнего с
  // многоточием… Нельзя же столько по высоте занимать». Ряд всегда одна
  // строка: не влез и после слияния «1–k» — справа слот хвоста «… N», номера
  // едут вбок под колесом. За краем колесо идёт с сопротивлением 0,35 и не
  // дальше 32 точек; кадр ведёт ряд к цели долей 0,22; 140 мс без колеса —
  // цель пружиной возвращается в границы; 8 с после колеса ряд сам к текущему
  // номеру не едет. Строка колеса (deltaMode 1) — 16 точек.
  const PROGRESS_TAIL_ID = "myclaude-progress-tail";
  const PROGRESS_SCROLL_RESIST = 0.35;
  const PROGRESS_SCROLL_OVER = 32;
  const PROGRESS_SCROLL_EASE = 0.22;
  const PROGRESS_SCROLL_SPRING_MS = 140;
  const PROGRESS_SCROLL_HOLD_MS = 8000;
  const PROGRESS_SCROLL_LINE = 16;
  // Между окном номеров и хвостом — зазор ряда плюс поле обрезки ряда
  // (overflow-clip-margin 3): иначе обрезанный номер залезал бы вплотную к хвосту.
  const PROGRESS_SCROLL_CLIP = 3;

  // Разбор строки состояния.
  // Значки состояния из шаблона строки. Порядок — старшинство: 🛑 сильнее ✋,
  // ✋ сильнее ✅, ✅ сильнее 💭. Шаблон несёт один и тот же значок по краям,
  // поэтому спорить им обычно не о чем; старшинство решает те случаи, когда в
  // строку попало два разных.
  // ⚠️ — «жду» по правилу AGENTS.md 08.09 (#5663, «рука непонятна»); ✋ остаётся для старых строк.
  // Сверяем без селектора VS16 («⚠»): в строку он попадает не всегда.
  // ❓ — «жду» строки нового образца (ELVIS.md 23.09, #7188).
  const PROGRESS_STATES = [["🛑", "fail"], ["✋", "wait"], ["⚠", "wait"], ["❓", "wait"], ["✅", "done"], ["💭", "run"]];
  // Строка состояния НОВОГО образца (ELVIS.md 23.09, #7188): слово и значок в
  // КОНЦЕ — «⚪[Проект](docs/status.md) · WF 2 из 3 · идёт 💭». Слово перед
  // значком обязательно: строка расхода под ней («… · Opus 5.5 Extra 💭»)
  // кончается тем же значком, но слова у неё нет (критик WF84, Б1).
  const PROGRESS_TAIL_RE = /[·•]\s*(идёт|жду|готово|упал)\s*(💭|❓|✅|🛑)\s*$/u;
  const PROGRESS_TAIL_WORDS = { "идёт": "run", "жду": "wait", "готово": "done", "упал": "fail" };
  const PROGRESS_TAIL_WF_RE = /WF\s+(\d+)\s+из\s+(\d+)/;
  // «WF 6 из 7 · 40%»: счёт марафона и процент текущего воркфлоу. Процента может
  // не быть (готовый воркфлоу пишется без него). «WF» — тоже необязательно, но
  // без него счёт засчитывается только рядом с ✅: «5 из 5» без значка — это
  // обычная фраза из ответа, а не строка состояния.
  const PROGRESS_RE = /(WF\s+)?(\d+)\s+из\s+(\d+)(?:\s*[·•]\s*(\d+)\s*%)?/g;
  // Имя проекта в строке состояния — markdown-ссылка `[Имя](docs/status.md)`.
  // Просмотрщик обычно уже развернул её в текст, но в сыром виде она встречается.
  const PROGRESS_LINK_RE = /\[([^\]]{1,80})\]\([^)\s]*\)/g;
  // Имя проекта — текст между маркером-кружком и первым « · ». По нему подсказка
  // ищет сводку, присланную командой status.
  const projectFromLine = (line) => {
    const head = String(line ?? "").replace(PROGRESS_LINK_RE, "$1").split(/\s+[·•]\s+/)[0] ?? "";
    const hit = head.match(/[\p{L}\p{N}][^\n]*/u);
    return hit ? hit[0].trim().slice(0, 80) : "";
  };
  // Берём ПОСЛЕДНЕЕ совпадение в тексте: строка состояния стоит последней
  // строкой ответа, а выше по тексту легко встречается пересказ чужой строки.
  // Разбор текста целиком: info — что рисовать, stop — «строка состояния есть,
  // и воркфлоу в ней нет» (#7188): поиск по старым ответам на этом кончается,
  // иначе чат, закончивший марафон строкой «· готово ✅», показывал бы полосу
  // трёхответной давности.
  const progressScan = (text) => {
    const source = String(text ?? "");
    if (source === "") return { info: null, stop: false };
    let tail = null;
    let tailAt = -1;
    let offset = 0;
    for (const raw of source.split("\n")) {
      if (PROGRESS_TAIL_RE.test(raw)) { tail = raw; tailAt = offset; }
      offset += raw.length + 1;
    }
    const old = progressParseOld(source);
    // Берётся та строка, что стоит НИЖЕ: у одной и той же строки обе формы
    // совпадают по началу, и тогда слово в конце сильнее значка в начале.
    if (tail == null || (old && old.at > tailAt)) {
      if (old) delete old.at;
      return { info: old, stop: false };
    }
    const word = tail.match(PROGRESS_TAIL_RE)[1];
    const count = tail.match(PROGRESS_TAIL_WF_RE);
    // Строка без «WF N из M» (воркфлоу нет) полоске не годится, но её слово нужно рамке
    // «ждут твоего слова» (#8282): «жду ❓» чаще всего как раз без счёта.
    if (!count) return { info: null, stop: true, word: PROGRESS_TAIL_WORDS[word] ?? null };
    const wf = Number(count[1]);
    const of = Number(count[2]);
    if (!(wf >= 1 && of >= 1)) return { info: null, stop: true };
    const state = PROGRESS_TAIL_WORDS[word];
    const done = state === "done";
    const share = done ? 1 : (wf - 1) / of;
    const total = Math.round(Math.min(1, Math.max(0, share)) * 1000) / 10;
    return { info: { wf, of, pct: done ? 100 : null, total, state, project: projectFromLine(tail) }, stop: false };
  };
  const parseProgressText = (text) => progressScan(text).info;
  // Старые формы: значок в НАЧАЛЕ строки, «WF N из M» без значка, одиночный
  // воркфлоу со значком по краям. at — начало строки находки (для спора с
  // новой формой в progressScan).
  const progressParseOld = (source) => {
    let found = null;
    PROGRESS_RE.lastIndex = 0;
    for (let match = PROGRESS_RE.exec(source); match; match = PROGRESS_RE.exec(source)) {
      // Значок засчитывается только в НАЧАЛЕ той же строки — по шаблону AGENTS.md
      // он там и стоит. Раньше хватало значка где угодно в строке, и «Тесты: 222
      // из 222 ✅» или «- шаги 3 из 3 ✅» из обычного ответа красили всю полосу
      // зелёным «готово» посреди работы (находка ревизии 08.09). Ведущие пробелы
      // допускаем: в попапах строка приезжает из текста всего окна, с отступом.
      const from = source.lastIndexOf("\n", match.index) + 1;
      const end = source.indexOf("\n", match.index);
      const line = source.slice(from, end === -1 ? source.length : end);
      const head = line.trimStart();
      // ⚠️ — это «⚠» + VS16, и селектор в строку попадает не всегда: сверяем по
      // голому значку, как и весь PROGRESS_STATES.
      const hit = PROGRESS_STATES.find(([icon]) => head.startsWith(icon));
      const mark = hit ? hit[1] : null;
      // Хвост #5714, решено 08.09: «WF N из M» ВОВСЕ без значка так и остаётся «идёт».
      // Слово «WF» пишем только мы, а берётся ПОСЛЕДНЕЕ совпадение — настоящая строка
      // состояния в конце ответа перебивает случайное упоминание выше по тексту, и
      // требовать значок незачем. Строгость нужна там, где «WF» нет: «5 из 5» без
      // значка — обычная фраза, и её пускает только ✅.
      if (!match[1] && mark !== "done") continue;
      const wf = Number(match[2]);
      const count = Number(match[3]);
      if (!Number.isFinite(wf) || !Number.isFinite(count) || wf < 1 || count < 1) continue;
      const done = mark === "done";
      const raw = match[4] === undefined ? null : Number(match[4]);
      const pct = done ? 100 : (raw == null ? null : Math.min(100, Math.max(0, raw)));
      // Прогресс марафона: закрытые воркфлоу целиком плюс доля текущего.
      // Готово — сразу полная полоса, сколько бы процентов ни было написано
      // рядом.
      const share = done ? 1 : ((wf - 1) + (pct ?? 0) / 100) / count;
      const total = Math.round(Math.min(1, Math.max(0, share)) * 1000) / 10;
      found = { wf, of: count, pct, total, state: mark ?? "run", project: projectFromLine(line), at: from };
    }
    if (found) return found;
    // Одиночный воркфлоу: марафона нет, и кусок «WF N из M» в строке опущен
    // (AGENTS.md) — остаётся «💭⚪Проект · 40%💭». Такую строку узнаём строго, по
    // одному и тому же значку с обоих краёв: иначе «✅ покрытие 80%» из любого
    // ответа стало бы прогрессом. Сегмент у неё один.
    let at = 0;
    for (const raw of source.split("\n")) {
      const from = at;
      at += raw.length + 1;
      const line = raw.trim();
      if (line.length < 3) continue;
      const hit = PROGRESS_STATES.find(([icon]) => line.startsWith(icon) && line.endsWith(icon));
      if (!hit) continue;
      const percent = line.match(/(\d+)\s*%/);
      const done = hit[1] === "done";
      if (!percent && !done) continue;
      const pct = done ? 100 : Math.min(100, Math.max(0, Number(percent[1])));
      found = { wf: 1, of: 1, pct, total: pct, state: hit[1], project: projectFromLine(line), at: from };
    }
    return found;
  };

  // ---- сводка проектов (команда status) ------------------------------------
  // Страница файлов не читает — сводку присылает приложение командой
  // {action:"status", scope:"all", projects:[{name, text}]}, где text — сырой
  // markdown status.md проекта. Держим её в памяти окна (не в хранилище: сводка
  // живёт минуту до следующей команды и общей для окон быть не обязана) и
  // показываем в подсказке полосы для того проекта, чьё имя стоит в строке
  // состояния этого чата.
  // С WF201 (класс #9159: до страницы доходили ~5 свежих проектов) — 64 проекта и 128 КБ: Swift
  // (StatusFeed.totalLimit) поднимет свой потолок отдельным батчем; разбор — один раз на приход команды.
  const STATUS_MAX_PROJECTS = 64;
  const STATUS_MAX_TEXT = 8000;
  // Общий потолок на команду со стороны страницы: приложение своё режет само, но
  // верить ему на слово нельзя — разбор сводки идёт в главном потоке окна.
  const STATUS_MAX_TOTAL = 128 * 1024;
  // Блок воркфлоу в сводке начинается с номера-клавиши: «1️⃣ Workflow ✅ готово».
  // Номер — ЦЕПОЧКА клавиш, а не одна (WF22): «2️⃣9️⃣» это 29, «4️⃣0️⃣» — 40, «🔟» — 10.
  // Читалась первая клавиша, и весь четвёртый десяток сводки числился четвёртым
  // воркфлоу.
  const STATUS_HEAD_RE = /^((?:\d\uFE0F?\u20E3|\u{1F51F})+)\s*(.*)$/u;
  const STATUS_KEYCAP_RE = /\d\uFE0F?\u20E3|\u{1F51F}/gu;
  const STATUS_DEFAULT_ICON = "⬜";
  // Состояние блока по заголовку — ОДНО правило на всех разборщиков status.md (WF145 свёл его в Swift
  // PanelProjects.stateMarks/stateWords и tools/pimp.py DIGEST_MARKS/WORDS; WF152 — страница). Значок
  // сильнее слова, порядок — по силе: упал → ждёт Элвиса → впереди → готово → идёт. ⏳ — идёт (до WF152
  // его страница не знала, и идущий блок выходил «впереди»); ⬜ — впереди, не «ждёт». Слова — кусок
  // слова строчными, тот же порядок: «запланирован» — впереди раньше «планирования» — идёт. Ни значка,
  // ни слова — впереди. Состояния страницы: fail/wait/todo/done/run. PROGRESS_STATES (строка чата)
  // этим не заменяется: там значок стоит в начале строки, и ❌/⬜ из обычного ответа полосой не станут.
  const STATUS_HEAD_MARKS = [
    [["🛑", "❌"], "fail"],
    [["✋", "⚠", "❓", "🙋", "⏸"], "wait"],
    [["⬜"], "todo"],
    [["✅", "🟢"], "done"],
    [["💭", "⏳"], "run"],
  ];
  const STATUS_HEAD_WORDS = [
    [["упал", "стоп", "сломал"], "fail"],
    [["заплан", "впереди", "в очереди"], "todo"],
    [["ждёт", "жду", "пауз"], "wait"],
    [["готов", "выложен"], "done"],
    [["идёт", "кодинг", "критик", "проверк", "исследов", "планирован", "ревизи"], "run"],
  ];
  const statusHeadState = (heading) => {
    const head = String(heading ?? "");
    for (const [marks, state] of STATUS_HEAD_MARKS) {
      const mark = marks.find(item => head.includes(item));
      if (mark) return { icon: mark, state };
    }
    const text = head.toLowerCase();
    for (const [words, state] of STATUS_HEAD_WORDS) {
      if (words.some(word => text.includes(word))) return { icon: "", state };
    }
    return { icon: "", state: "todo" };
  };
  // Четыре этапа воркфлоу (AGENTS.md): по ним заливается идущий сегмент и
  // строится карточка. Пятая роль в сводке («макет» и подобные) на заливку не
  // влияет и в карточку не идёт — этапов по букве Элвиса ровно четыре. Имена — его
  // словами (WF160, #9159: «планирование, критик, кодинг и тест»); роль «проверка» — тот же «тест».
  const STATUS_STAGES = [
    // «план», не «планирование» (#9195, слово Элвиса 09.10 02:35: «мне важно знать не „планирование“, а „план“»).
    { key: "plan", label: "план", re: /^план/i },
    // «ревизия», «ревью» — тот же критик, «гейт» — тот же тест (WF198:
    // роль «ревизия · 1 агент · Opus 5.5 high» у Dictator не попадала ни в один этап — модели не было видно).
    { key: "critic", label: "критик", re: /^(?:критик|ревизи|ревью|review)/i },
    { key: "code", label: "кодинг", re: /^кодинг/i },
    { key: "check", label: "тест", re: /^(?:проверк|тест|гейт)/i },
  ];
  // Колонка имени этапа в карточке: самое длинное — «кодинг» 13 px 600, ~48 точек (WF175: «план»
  // вместо «планирование», колонка была 100 под него).
  const PROGRESS_CARD_LABEL = 60;
  // Хвост строки роли — эффорт. Слово `extra` стоит здесь ради уже написанных
  // файлов (#5907): карточка показывает `xhigh` словами Claude Code («Extra»), и
  // где-то в сводке это слово могли записать сразу так — без него «Fable Extra»
  // перестало бы читаться как модель с эффортом вовсе.
  const STATUS_EFFORT_RE = /\s(low|medium|high|xhigh|extra|max)$/i;
  // Строка «обновлено 12:40» под заголовком сводки — единственная дата в
  // файле (AGENTS.md: не сегодня — «вчера 03:10» или число «15.09»). По ней
  // карточка решает, можно ли сказать «15 мин назад» (progressWhen, WF70):
  // относительные слова честны только у сегодняшнего файла. Шапка счёта
  // («4 воркфлоу», «2 готово», «1,4 ч») больше не читается: подвал с ней
  // Элвис убрал (#6247) — он путал, цифры про проект стояли под карточкой
  // одного воркфлоу.
  const STATUS_UPDATED_RE = /^обновлено:?\s+(.+)$/iu;
  const STATUS_UPDATED_DATE_RE = /^(\d{1,2}[./]\d{1,2}(?:[./]\d{2,4})?)/;
  const STATUS_UPDATED_CLOCK_RE = /^\d{1,2}:\d{2}(?![\d:])/;
  // «12:40» и «сегодня 12:40» → сегодня, «вчера 03:10» → вчера, «15.09» → дата;
  // ничего из этого не разобрали — null, и карточка говорит абсолютным временем.
  // Границу слова даёт взгляд вперёд: `\b` кириллицы не знает.
  const statusUpdated = (text) => {
    const tail = String(text ?? "").trim();
    const yesterday = tail.match(/^вчера(?![\p{L}])\s*(.*)$/iu);
    if (yesterday) return { kind: "yesterday", time: yesterday[1].trim() };
    const today = tail.match(/^сегодня(?![\p{L}])\s*(.*)$/iu);
    if (today) return { kind: "today", time: today[1].trim() };
    const date = tail.match(STATUS_UPDATED_DATE_RE);
    if (date) return { kind: "date", time: date[1] };
    const clock = tail.match(STATUS_UPDATED_CLOCK_RE);
    if (clock) return { kind: "today", time: clock[0] };
    return null;
  };
  const statusFeed = { at: 0, projects: new Map() };
  // «Сейчас: …» и «Ждёт Элвиса: …» (или «Ждёт пользователя: …» — так пишет
  // чат не у Элвиса) — строкой, не пунктом списка; жирное начертание и маркер
  // пункта на всякий случай прощаем.
  const STATUS_TAIL_LINE_RE = /^(?:[-*]\s+)?(?:\*\*)?(Сейчас|Ждёт (?:Элвиса|пользователя)):(?:\*\*)?\s*(.*)$/u;

  // Номер воркфлоу, с которого начинается строка сводки: «3️⃣ …» → 3, «🔟 …» → 10,
  // «2️⃣9️⃣ …» → 29. Разбираем по цифрам клавиш, а не по готовому значку: в сводке
  // встречается и запись без вариационного селектора («3⃣»), и та и другая — один
  // и тот же номер.
  const statusLineNumber = (line) => {
    const head = String(line ?? "").match(STATUS_HEAD_RE);
    if (!head) return null;
    let digits = "";
    for (const cap of head[1].match(STATUS_KEYCAP_RE) ?? []) {
      digits += cap === "\u{1F51F}" ? "10" : (cap.match(/\d/)?.[0] ?? "");
    }
    const number = Number(digits);
    return digits !== "" && Number.isFinite(number) ? number : null;
  };
  // Строка роли: «- кодинг · 2 агента · Opus max». Кто (агенты) и на чём (модель,
  // эффорт) стоят в любом порядке, части может не быть вовсе («- кодинг · Opus
  // max», «- проверка · 🔴 **Fable max**»). Значок 💭 в конце — необязательная
  // пометка идущего этапа (правило AGENTS.md пишет чат Max).
  const statusRole = (item) => {
    const running = /💭\s*$/.test(item);
    const parts = item.replace(/💭\s*$/, "").split(/\s*[·•]\s*/).map(part => part.trim()).filter(Boolean);
    const rest = parts.slice(1);
    const agentsAt = rest.findIndex(part => /аген/i.test(part) || part === "я" || part.startsWith("я "));
    // Жирное начертание и красный кружок «Fable max» — разметка сводки, а не имя
    // модели: снимаем их здесь, рисует их карточка сама.
    const who = rest.filter((part, index) => index !== agentsAt).join(" · ")
      .replace(/\*\*/g, "").replace(/^[^\p{L}\p{N}]+/u, "").trim();
    const effort = who.match(STATUS_EFFORT_RE);
    return {
      role: parts[0] ?? "",
      agents: agentsAt >= 0 ? rest[agentsAt] : "",
      model: effort ? who.slice(0, who.length - effort[0].length).trim() : who,
      effort: effort ? effort[1] : "",
      running,
    };
  };
  // Сводка написана списками, а не таблицей, поэтому разбираем построчно:
  // заголовок блока даёт номер и значок, первый пункт — «о чём», пункты с
  // разделителем и словом впереди — роли, «шаги N из M» и время — свои поля.
  // Разбор ОДИН на двух читателей (WF22): объекты блоков для карточки и
  // заливки и дата обновления файла (updated, WF70). Порядок проверок внутри
  // цикла менять нельзя — на нём стоят блоки и роли.
  const statusParse = (text) => {
    const blocks = [];
    let updated = null;
    let current = null;
    // Хвостовые строки для Элвиса (WF84, #7205): «Сейчас: …» и «Ждёт Элвиса: …».
    // Их пишет чат где угодно в файле, приложение с правкой S-K переносит их в
    // шапку сводки. Берётся ПОСЛЕДНЯЯ каждого вида; блоки и роли от них не
    // меняются.
    let nowLine = "";
    let waitFor = "";
    const flush = () => { if (current) blocks.push(current); current = null; };
    for (const raw of String(text ?? "").split("\n")) {
      const line = raw.trim();
      const title = line.match(STATUS_HEAD_RE);
      if (title) {
        flush();
        const head = statusHeadState(title[2]);
        current = {
          number: statusLineNumber(line), mark: title[1],
          icon: head.icon || STATUS_DEFAULT_ICON, state: head.state,
          about: "", steps: null, time: "", roles: [], past: [],
        };
        continue;
      }
      const tail = line.match(STATUS_TAIL_LINE_RE);
      if (tail) {
        const value = tail[2].replace(/\*\*/g, "").trim();
        if (value) { if (/^Сейчас/u.test(tail[1])) nowLine = value; else waitFor = value; }
        continue;
      }
      if (!current) {
        // До первого блока — строка «обновлено …», первая и единственная.
        const stamp = updated ? null : line.match(STATUS_UPDATED_RE);
        if (stamp) updated = statusUpdated(stamp[1]);
        continue;
      }
      if (!/^[-*]\s/.test(line)) continue;
      const item = line.replace(/^[-*]\s*/, "").trim();
      if (!item) continue;
      const steps = item.match(/^шаги\s+(\d+)\s+из\s+(\d+)/i);
      if (steps && !current.steps) current.steps = { done: Number(steps[1]), total: Number(steps[2]) };
      // «- прошлые шаги: планирование · я · Opus max; критика · 1 агент · Fable xhigh»
      // (шаблон AGENTS.md). Раньше вся строка становилась одной ролью с именем
      // «прошлые шаги: планирование», и на карточке у закрытых этапов стоял
      // прочерк — Элвис 13.09: «галочки стоят, а кто это делал, непонятно»
      // (#5977). Режем по «;» и разбираем каждый кусок как обычную роль. Ветка
      // стоит ДО «о чём»: сводку пишут люди и агенты, порядок пунктов в блоке
      // не гарантирован. Примета без `\w`: кириллицы он не знает вовсе.
      if (/^прошл\S*\s+шаг/i.test(item)) {
        current.past = item.replace(/^[^:]*:\s*/, "").split(/\s*;\s*/)
          .map(part => part.trim()).filter(part => part.includes("·"))
          .map(statusRole);
        continue;
      }
      if (!current.about && !/^шаги\b/i.test(item) && !/\d\s*:\s*\d/.test(item)) {
        current.about = item.replace(/^о\s+чём\s*:\s*/i, "");
        continue;
      }
      if (!current.time && /\d\s*:\s*\d/.test(item)) { current.time = item; continue; }
      const role = item.split(/\s*[·•]\s*/)[0] ?? "";
      if (item.includes("·") && !item.includes("→") && role && !/\d/.test(role)) current.roles.push(statusRole(item));
    }
    flush();
    return { blocks, updated, now: nowLine, waitFor };
  };
  const statusBlocks = (text) => statusParse(text).blocks;
  // Имя проекта в строке состояния и имя папки, которое прислало приложение,
  // совпадают не побуквенно (регистр, дефисы). Сравниваем по буквам и цифрам.
  const statusKey = (name) => String(name ?? "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
  // Точное имя выигрывает всегда, а по началу имени отвечаем ТОЛЬКО когда такой
  // сосед один (WF22): «VkusnoffKz» рядом с «VkusnoffKz-deploy» выбирался
  // алфавитом, то есть случайно.
  const statusFeedProject = (project) => {
    const key = statusKey(project);
    if (!key) return null;
    let near = null;
    let count = 0;
    for (const [name, item] of statusFeed.projects) {
      const other = statusKey(name);
      if (!other) continue;
      if (other === key) return item;
      if (other.startsWith(key) || key.startsWith(other)) { near = item; count += 1; }
    }
    return count === 1 ? near : null;
  };
  // Команда снаружи: разбираем сразу, а не при показе карточки — разбор дешевле
  // раза в минуту, чем на каждое движение мыши.
  const runStatusCommand = (detail) => {
    const list = Array.isArray(detail?.projects) ? detail.projects : null;
    if (!list) return false;
    const next = new Map();
    let budget = STATUS_MAX_TOTAL;
    for (const item of list.slice(0, STATUS_MAX_PROJECTS)) {
      const name = typeof item?.name === "string" ? item.name.trim().slice(0, 80) : "";
      const text = typeof item?.text === "string" ? item.text.slice(0, STATUS_MAX_TEXT) : "";
      if (!name || !text) continue;
      // Потолок выбран — остальные проекты отбрасываем целиком: половина сводки
      // в карточке хуже, чем её отсутствие.
      budget -= name.length + text.length;
      if (budget < 0) break;
      next.set(name, statusParse(text));
    }
    statusFeed.projects = next;
    statusFeed.at = Date.now();
    progressState.cardText = "";
    progressCardUI.text = "";
    // Со сводкой меняется и заливка идущего сегмента — она считается по этапам
    // блока (WF22). Перерисовываем полосу сразу, а не ждём страховочного
    // перечёта через десять секунд.
    try { placeProgress(); } catch {}
    if (progressState.tipOpen) { try { progressTipShow(); } catch {} }
    return true;
  };

  const progressState = {
    info: null, reason: "полоса ещё не считалась", at: 0, runs: 0, timer: 0, pulse: 0,
    // Найденная рамка поля, доли номеров (segments — для гейта: 100 готовый,
    // доля шагов у идущего, 0 впереди), номера как нарисованы (badges), место
    // ряда на экране и наведение (только курсор).
    frame: null, shell: null, segments: [], badges: [], gap: PROGRESS_BADGE_GAP, box: null, hovering: false,
    // Подсказка: какой номер открыт кликом (порядок в ряду, с нуля) и открыта ли
    // она вообще. Наведение карточку не показывает — только клик (WF12, п. 3).
    tipSegment: null, tipOpen: false, tipTick: 0,
    // Карточка (WF84, 9.1): её слепок, дышит ли она, строки этапов, строка
    // «сейчас», на что она встала — над полем или над номерами — и сколько
    // шагов подгонки под потолок сделано.
    cardText: "", cardPulse: false, cardBreathe: false, cardRows: [], cardNote: null, cardAnchor: null, cardFit: 0,
    // На чём сейчас сидит ряд: "рамка" или запасное "строка инструментов".
    anchor: null,
    // Место под ряд: рамка, которой добавили нижнее поле, её собственное поле
    // до нашей правки и сколько точек добавили сверху.
    roomNode: null, roomBase: 0, room: 0,
    // «Замереть у низа» (WF84): строка читается только у низа ленты. key — чей
    // чат прочитан, lastByKey — последнее прочитанное по ключу чата (потолок
    // PROGRESS_KEYS_MAX), source — откуда info на экране, frozen — ряд стоит,
    // потому что лента не у низа, atBottom — лента у низа (или её нет), blocks —
    // принята ли сводка (сверка номеров, progressFeedBlocks).
    key: null, lastByKey: new Map(), source: "нет", frozen: false, atBottom: true, blocks: false,
  };
  // Прокрутка ряда (WF85, #7356): on — режим прокрутки, x — сдвиг номеров
  // сейчас, target — куда их ведёт кадр, max — предел сдвига, view — окно
  // номеров на экране {left, right}, tail — хвост «… N» виден, user — последний
  // сдвиг от колеса, wheelAt — когда было колесо, key — для чего последний раз
  // ставилось «своё место» (номер, окно, число номеров), raf/spring — кадр и
  // пружина, wheel — висит ли слушатель колеса.
  const progressScroll = {
    on: false, x: 0, target: 0, max: 0, view: null, tail: false, user: false, wheelAt: 0, key: null,
    raf: 0, spring: 0, wheel: false,
  };

  // Полосу, подсказку и карточку сносим по id, как ручку и стили: упавшая на
  // середине установка оставляет их в окне, а реестра отмены у них уже нет.
  // Нижнее поле рамки — по метке: рамка чужая, сносить её нельзя, только
  // вернуть ей своё поле.
  for (const id of [PROGRESS_ID, PROGRESS_TIP_ID, PROGRESS_CARD_ID, PROGRESS_TAIL_ID]) {
    for (const orphan of document.querySelectorAll(`#${id}`)) orphan.remove();
  }
  for (const node of document.querySelectorAll(`[${PROGRESS_ROOM_ATTRIBUTE}]`)) {
    node.style.removeProperty("padding-bottom");
    node.style.removeProperty(PROGRESS_ROOM_VARIABLE);
    node.removeAttribute(PROGRESS_ROOM_ATTRIBUTE);
  }

  const progressBar = document.createElement("div");
  progressBar.id = PROGRESS_ID;
  // Никакого aria-live: ряд меняется на каждом ответе, и VoiceOver проговаривал
  // бы его без остановки (довод донора). Подпись ряда (aria-label) — словами:
  // «Воркфлоу: 1 готов, 2 идёт, 3 ждёт тебя» (ТЗ WF84, п. 5).
  progressBar.setAttribute("role", "img");
  // Стили — прямо в узел, без <style>: CSP страницы может не пустить нашу
  // таблицу (см. state.cssOk в разделе 4), а element.style ей неподвластен.
  for (const [name, value] of Object.entries({
    position: "fixed", display: "none", left: "0px", top: "0px", width: "0px",
    height: `${PROGRESS_BADGE_HEIGHT}px`, "align-items": "center", "justify-content": "flex-start",
    // Лишнее по ширине (длинный марафон в узком окне) обрезаем, но с полями
    // в 3 точки: обводка выбранного номера лежит на точку снаружи номера.
    gap: `${PROGRESS_BADGE_GAP}px`, overflow: "clip", "overflow-clip-margin": "3px",
    "pointer-events": "none", "z-index": "2147483645",
    // Ряд чуть приглушён, наведение — во всю силу (ТЗ WF84, п. 5).
    opacity: "0.85",
    // Сама коробка не анимируется НИКОГДА: место и ширину ей задаёт геометрия
    // окна (resize, ручка, смена якоря), и переход тут означал бы, что ряд
    // ползёт за краем поля ввода с опозданием. Пишем это прямым объявлением, а
    // не молчанием: страница вправе объявить переход на всё подряд.
    transition: "none",
  })) progressBar.style.setProperty(name, value);
  (document.body ?? document.documentElement).appendChild(progressBar);
  track(() => progressBar.remove());

  // Коробка карточки. Потолок высоты — 60 % окна, прокрутки нет намеренно:
  // узел прозрачен для мыши, колесо до него не доходит. Ширину и место считает
  // progressTipShow — над полем ввода и не шире его (WF84, 9.1).
  //
  // Карточка воркфлоу (WF84, вариант 9.1 макета docs/9-card-opus-5.5.html,
  // ТЗ docs/design-card-wf84.md): шапка «номер · плашка», «о чём», слева
  // дорожка этапов в столбик — кружок на этап и отрезки между ними (пройденное
  // зелёное, идущее акцентом и дышит, ждёт — жёлтое, упал — красное, впереди —
  // пустой контур), под текущим этапом одна строка из status.md («Твой ход: …»
  // или «Сейчас:»), внизу строка «когда» (WF70). Действий в карточке нет (слово
  // Элвиса 23.09: «Чат, план, отчёт, пауза — что такое?»). Узлы строим один раз
  // и потом только переписываем текст и стили.
  //
  // С WF160 (#9159, слово Элвиса 08.10 ~23:38: «стандартное подменю Workflow… какие модели, кто что
  // делает… Раньше было пизже») — этапы и модели; рисует узлы progressCardPaint. Номер в шапке —
  // капсулой, как в ряду, а не словом «Воркфлоу N» (правило №2 SkilZZZ/INTERFACES.md: один знак на объект).
  // Свой aria-hidden и никаких role/data-state: и раздел 16 (Escape), и
  // progressCovered ловят открытые накладки по role="dialog"/data-state="open" —
  // назовись карточка так, она сама себя и накрыла бы.
  const cardNode = (parent, styles) => {
    const node = document.createElement("div");
    for (const [name, value] of Object.entries(styles)) node.style.setProperty(name, value);
    parent.appendChild(node);
    return node;
  };
  // Строка «сейчас»: 12px, приставка «Твой ход:» отдельным узлом. Пустая —
  // display:none в самом узле (hidden слабее объявленного display). С WF160 (критик: «…» в узком
  // поле) — целиком, с переносом, без line-clamp и без среза: карточка растёт вверх.
  const progressNoteNode = (parent, extra = {}) => {
    const note = cardNode(parent, {
      "font-size": "12px", "line-height": "1.35", margin: "-3px 0 7px", padding: "0", position: "relative",
      display: "none", "white-space": "normal", "overflow-wrap": "anywhere", ...extra,
    });
    const prefix = document.createElement("span");
    prefix.style.setProperty("font-weight", "650");
    note.appendChild(prefix);
    const text = document.createElement("span");
    note.appendChild(text);
    return { note, prefix, text };
  };
  const progressCardUI = (() => {
    const tip = document.createElement("div");
    tip.id = PROGRESS_TIP_ID;
    tip.setAttribute("aria-hidden", "true");
    for (const [name, value] of Object.entries({
      position: "fixed", display: "none", left: "0px", top: "0px",
      // box-sizing своим объявлением: ширину карточке считаем сами, и хозяйская
      // раскладка страницы (content-box) вынесла бы её за край на поля и рамку.
      "box-sizing": "border-box",
      padding: "11px 13px 10px", "border-radius": "12px", "border-width": "1px", "border-style": "solid",
      font: "13px/1.4 -apple-system, system-ui, sans-serif", "white-space": "normal",
      "overflow-wrap": "anywhere", overflow: "hidden", "pointer-events": "none", "z-index": "2147483646",
    })) tip.style.setProperty(name, value);
    (document.body ?? document.documentElement).appendChild(tip);
    track(() => tip.remove());
    const card = document.createElement("div");
    card.id = PROGRESS_CARD_ID;
    card.setAttribute("aria-hidden", "true");
    // Верхних детей карточки ровно четыре: шапка, «о чём», этапы, «когда».
    const head = cardNode(card, {
      display: "flex", "align-items": "center", "column-gap": "10px", "row-gap": "4px", "flex-wrap": "wrap",
    });
    // Номер — капсула ряда, крупнее (цвета — progressCardPaint: цветом состояния, как номер в ряду).
    const title = cardNode(head, {
      display: "inline-block", "box-sizing": "border-box", height: "18px", "min-width": "22px", padding: "0 5px",
      "border-radius": "4px", font: "600 12px/18px -apple-system, system-ui, sans-serif",
      "font-variant-numeric": "tabular-nums", "text-align": "center", "white-space": "nowrap",
    });
    const where = cardNode(head, { "font-size": "12px" });
    // Плашка: точка цвета состояния и слово без эмодзи («идёт кодинг», «ждёт тебя»).
    const pill = cardNode(head, {
      display: "inline-flex", "align-items": "center", gap: "6px",
      "border-radius": "999px", padding: "1px 10px 1px 8px", "font-size": "12px", "font-weight": "650",
      "white-space": "nowrap",
    });
    const dot = cardNode(pill, {
      width: "6px", height: "6px", "border-radius": "50%", flex: "0 0 auto", "box-sizing": "border-box",
    });
    const pillText = cardNode(pill, {});
    // «О чём» — полностью, без многоточия и line-clamp (слово Элвиса 23.09, #7205):
    // это одна строка status.md, обычно до трёх строк карточки; длиннее — просто
    // переносится, не режется. Подгонка под потолок (progressCardFit) её не трогает.
    const about = cardNode(card, {
      "margin-top": "5px", display: "block", "white-space": "normal", "overflow-wrap": "anywhere",
    });
    const stages = cardNode(card, { "margin-top": "7px" });
    // Четыре строки этапов: [подсветка, дорожка[отрезок, кружок[знак, ореол]],
    // этап, кто, сейчас[приставка, текст]]. Колонка этапа — под самое длинное слово
    // («кодинг»; WF175); «кто» переносится, а не режется многоточием (#9158).
    const rows = STATUS_STAGES.map(() => {
      const row = cardNode(stages, {
        display: "grid", "grid-template-columns": `20px ${PROGRESS_CARD_LABEL}px minmax(0, 1fr)`, "column-gap": "8px",
        position: "relative",
      });
      const hl = cardNode(row, {
        position: "absolute", left: "24px", right: "-7px", top: "0", bottom: "0", "border-radius": "7px",
        display: "none", "pointer-events": "none", transition: "background-color 200ms",
      });
      const track = cardNode(row, { "grid-row": "1 / span 2", "grid-column": "1", position: "relative", "min-height": "28px" });
      const line = cardNode(track, { position: "absolute", left: "9px", width: "2px", top: "23px", bottom: "-5px", "border-radius": "1px" });
      const node = cardNode(track, {
        position: "absolute", left: "3px", top: "7px", width: "14px", height: "14px", "border-radius": "50%",
        display: "flex", "align-items": "center", "justify-content": "center", "box-sizing": "border-box",
        font: "800 9px/1 -apple-system, system-ui, sans-serif",
        transition: "background-color 200ms, color 200ms, box-shadow 200ms",
      });
      const glyph = cardNode(node, { "border-radius": "50%" });
      const halo = cardNode(node, { position: "absolute", inset: "-4px", "border-radius": "50%", display: "none", "pointer-events": "none" });
      const label = cardNode(row, {
        "grid-column": "2", "grid-row": "1", "line-height": "28px", "font-size": "13px", "font-weight": "600",
        "white-space": "nowrap", position: "relative", transition: "color 200ms",
      });
      const who = cardNode(row, {
        // Кто и модель — мельче, кеглем подписей (#9195: «модель ты сильно крупно сделал»; было 12).
        "grid-column": "3", "grid-row": "1", "line-height": "16px", padding: "6px 0", "font-size": "11px",
        "white-space": "normal", "overflow-wrap": "anywhere", "min-width": "0", position: "relative",
      });
      const note = progressNoteNode(row, { "grid-column": "2 / -1", "grid-row": "2" });
      return { row, hl, track, line, node, glyph, halo, label, who, ...note };
    });
    // Пятый узел этапов: строка «сейчас», когда этапа у воркфлоу нет (ролей в
    // блоке не записано) — встаёт под этапами отдельной строкой.
    const spare = progressNoteNode(stages, { margin: "2px 0 0" });
    // «Когда» — одна человеческая строка про ЭТОТ воркфлоу («Завершился 15 мин
    // назад · занял 50 мин», progressWhen, WF70, #6247). С переносом и без среза
    // (WF160: «…» нет нигде): в окне 280 она просто встаёт в две строки. Подвал —
    // второстепенное (правило №15 INTERFACES): обычным начертанием, приглушённо.
    // Показ (display) переписывается при каждой смене текста: атрибут hidden прячет
    // узел правилом `[hidden]{display:none}`, а оно слабее объявления в самом узле.
    const when = cardNode(card, {
      "margin-top": "8px", "padding-top": "7px", "border-top-width": "1px", "border-top-style": "solid",
      "font-size": "12.5px", "font-weight": "400", display: "block", "white-space": "normal",
    });
    tip.appendChild(card);
    // Дыхание карточки (ТЗ 9.1, п. 7): ореол кружка идущего этапа, подсветка его
    // строки и точка в плашке — три слота, такт общий с номером в ряду. text — слепок
    // показанного (ключ перерисовки), fit — шаг подгонки, states — состояния строк этапов.
    return {
      tip, card, head, title, where, pill, dot, pillText, about, stages, rows, spare, when,
      slots: { halo: { anim: null }, hl: { anim: null }, dot: { anim: null } },
      text: "", fit: 0, states: [], note: null, breathe: false,
    };
  })();
  const {
    tip: progressTip, card: progressCard, title: progressCardTitle, where: progressCardWhere, pill: progressCardPill,
    dot: progressCardDot, pillText: progressCardPillText, about: progressCardAbout, stages: progressCardStages,
    rows: progressCardRows, spare: progressCardSpare, when: progressCardWhen,
  } = progressCardUI;

  // Цвет полосы — акцент окна (accentColor, раздел 2а): оформление красится им
  // ещё на восстановлении слоёв — то есть до этого раздела.
  const progressAccent = accentColor;
  // Номер на залитой капсуле по макету тёмный — но только там, где он читается:
  // у светлых тем акцент тёмный («Апельсин» #a31000), и чёрная цифра на нём
  // пропадает. Из двух цветов берём тот, что контрастнее (WCAG, contrastRatio).
  // Акцент приходит тройкой в hsl(…) (accentColor) или hex; иное — тёмный.
  const PROGRESS_INK_DARK = "#0b0d10";
  const PROGRESS_INK_LIGHT = "#ffffff";
  const progressHex = color => {
    const text = String(color ?? "").trim();
    if (/^#[0-9a-f]{3,8}$/i.test(text)) return normalizeHex(text, "#000000");
    const hsl = text.match(/^hsla?\(\s*([\d.]+)(?:deg)?[\s,]+([\d.]+)%[\s,]+([\d.]+)%/i);
    if (hsl) return hexFromHsl(Number(hsl[1]), Number(hsl[2]) / 100, Number(hsl[3]) / 100);
    // rgb(…) и голая тройка «77,187,125» (тона кожи карточки) — тоже цвет.
    const rgb = text.match(/^(?:rgba?\(\s*)?(\d{1,3})[\s,]+(\d{1,3})[\s,]+(\d{1,3})\s*(?:[,/)]|$)/i);
    if (!rgb) return null;
    return `#${rgb.slice(1, 4).map(part => Math.min(255, Number(part)).toString(16).padStart(2, "0")).join("")}`;
  };
  const progressInk = paint => {
    const hex = progressHex(paint);
    if (!hex) return PROGRESS_INK_DARK;
    return contrastRatio(hex, PROGRESS_INK_DARK) >= contrastRatio(hex, PROGRESS_INK_LIGHT)
      ? PROGRESS_INK_DARK : PROGRESS_INK_LIGHT;
  };

  // Кромка, на которой сидит полоса. Сама .epitaxy-prompt бывает обёрткой без
  // границы, а рамку рисует её потомок (border или box-shadow) — садиться надо
  // на ту кромку, которую видит глаз. Ищем неглубоко и с ограничением по числу
  // узлов: проход зовётся до четырёх раз в секунду.
  const PROGRESS_FRAME_SELECTOR = ".epitaxy-prompt";
  const PROGRESS_FRAME_DEPTH = 3;
  const PROGRESS_FRAME_BUDGET = 32;
  const PROGRESS_FRAME_SLACK = 24;
  const framePainted = (node) => {
    let computed = null;
    try { computed = getComputedStyle(node); } catch { return false; }
    if (!computed) return false;
    if ((parseFloat(computed.borderBottomWidth) || 0) > 0) return true;
    const shadow = String(computed.boxShadow ?? "");
    return shadow !== "" && shadow !== "none";
  };
  const paintedChild = (root) => {
    const base = root.getBoundingClientRect();
    let level = [root];
    let budget = PROGRESS_FRAME_BUDGET;
    for (let depth = 0; depth < PROGRESS_FRAME_DEPTH && level.length > 0 && budget > 0; depth += 1) {
      const next = [];
      for (const node of level) {
        for (const kid of node.children ?? []) {
          if (budget <= 0) break;
          budget -= 1;
          const rect = kid.getBoundingClientRect();
          // Рамка — во всю ширину поля и с тем же низом. Всё, что заметно уже
          // (кнопки, значки), не рамка и внутрь себя её не прячет.
          if (rect.width < base.width - PROGRESS_FRAME_SLACK) continue;
          if (Math.abs(rect.bottom - base.bottom) <= PROGRESS_FRAME_SLACK && framePainted(kid)) return kid;
          next.push(kid);
        }
      }
      level = next;
    }
    return null;
  };
  // Коробка, в которой живёт САМО поле: от редактора вверх до первой
  // обведённой (border или box-shadow) коробки во всю ширину. Её низ глаз и
  // видит низом поля, и к нему липнет полоса (#6890).
  //
  // Почему не ищем сверху вниз: у paintedChild рамкой считается только та
  // коробка, чей низ совпадает с низом .epitaxy-prompt (допуск 24 точки), а под
  // полем стоит строка модели. Живой замер 21.09: расхождение 26 точек — и
  // рамкой становился сам .epitaxy-prompt, полоса съезжала ПОД строку модели.
  // Стоило строке стать на пару точек ниже — и полоса прыгала обратно на поле.
  const editorFrame = (root) => {
    const start = state.editorRoot?.isConnected ? state.editorRoot
      : (state.editor?.isConnected ? state.editor : null);
    if (!start || !root.contains(start)) return null;
    const base = root.getBoundingClientRect();
    for (let node = start; node && node !== root; node = node.parentElement) {
      const rect = node.getBoundingClientRect();
      if (rect.width < base.width - PROGRESS_FRAME_SLACK) continue;
      if (framePainted(node)) return node;
    }
    return null;
  };

  const progressFrame = (block) => {
    const shell = state.shell?.isConnected && block.contains(state.shell) ? state.shell : null;
    const cached = progressState.frame;
    // Кэш годится, пока жива и сама найденная рамка, и та рамка поля, от которой
    // мы её нашли: React пересобирает низ окна целиком.
    if (cached?.isConnected && block.contains(cached) && progressState.shell === shell) return cached;
    progressState.shell = shell;
    let root = shell?.closest?.(PROGRESS_FRAME_SELECTOR) ?? null;
    if (!root?.isConnected) root = block.querySelector(PROGRESS_FRAME_SELECTOR);
    if (!root?.isConnected) root = shell;
    if (!root?.isConnected) return null;
    // Коробка поля сильнее общего поиска: она и есть та кромка, к которой
    // полоса липнет. Нет её (чужая разметка, Claude Code) — прежний путь.
    progressState.frame = editorFrame(root) ??
      (framePainted(root) ? root : (paintedChild(root) ?? root));
    return progressState.frame;
  };

  // Меню модели и effort раскрываются вверх ровно над этой границей, а полоса
  // висит поверх страницы и рисовалась бы сквозь них. Хит-тест, как у ручки
  // (раздел 8), здесь не нужен: полоса ничего не ловит мышью, хватает
  // пересечения с открытым меню или модалкой. Сверяем всю высоту ряда.
  const progressCovered = (top, bottom, left, right) => {
    for (const node of document.querySelectorAll(OVERLAY_SELECTOR)) {
      const rect = node.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) continue;
      if (rect.top <= bottom + 2 && rect.bottom >= top - 2 && rect.left <= right && rect.right >= left) return true;
    }
    return false;
  };

  // ---- сегмент ↔ блок сводки (WF22, по номеру с WF70) ------------------------
  // Сперва ПО НОМЕРУ: с 15.09 status.md держит воркфлоу только ЭТОГО чата и
  // нумерует их с единицы (AGENTS.md), так что номер сегмента «WF N из M» и
  // номер блока — один и тот же счёт. Пока сводка нумеровала по проекту,
  // соединяли по значку, и готовый или запланированный сегмент часто
  // оставался без блока: карточка писала «ещё не расписан», хотя в status.md
  // всё есть (#6130, #5884). Блока с таким номером нет (старые и архивные
  // сводки) — прежний путь по значку.
  const progressBlockAt = (info, number) => {
    if (!info) return null;
    const blocks = statusFeedProject(info.project)?.blocks ?? [];
    if (blocks.length === 0) return null;
    const own = blocks.find(block => block.number === number);
    if (own) return own;
    // Идущий блок — ПОСЛЕДНИЙ с 💭 в заголовке: в сводке рядом легко висит
    // недописанный старый.
    let runAt = -1;
    for (let index = 0; index < blocks.length; index += 1) if (blocks[index].state === "run") runAt = index;
    // Идущий сегмент — он же. ✋ и 🛑 в сводке значков не имеют: чат ждёт Элвиса
    // или упал на том же самом блоке, который в сводке помечен 💭.
    if (info.state !== "done" && number === info.wf) return runAt >= 0 ? blocks[runAt] : null;
    // Готовый сегмент k из D — k-й с ХВОСТА среди ✅: последние готовые блоки
    // проекта и есть воркфлоу этого чата. Свой номер карточка называет честно.
    const doneCount = info.state === "done" ? info.of : info.wf - 1;
    if (number <= doneCount) {
      const done = blocks.filter(block => block.state === "done");
      return done[done.length - 1 - (doneCount - number)] ?? null;
    }
    // Будущий — ⬜ с головы, но только те, что стоят ПОСЛЕ идущего.
    const todo = blocks.filter((block, index) => block.state === "todo" && index > runAt);
    return todo[number - info.wf - 1] ?? null;
  };
  // Четыре этапа блока и который из них идёт. Явная пометка 💭 в строке роли
  // сильнее порядка записи; её нет — идущим считаем ПОСЛЕДНИЙ записанный этап
  // (по шаблону AGENTS.md роли дописывают по мере прохождения).
  const progressStages = (block) => {
    const rows = STATUS_STAGES.map(stage => ({
      key: stage.key, label: stage.label,
      // Роль ищем сперва среди текущих, потом среди прошлых шагов: у закрытых
      // этапов «кто» живёт только там (#5977).
      role: block?.roles.find(role => stage.re.test(role.role))
        ?? block?.past?.find(role => stage.re.test(role.role)) ?? null,
    }));
    let now = rows.findIndex(row => row.role?.running);
    if (now < 0) for (let index = 0; index < rows.length; index += 1) if (rows[index].role) now = index;
    return { rows, now };
  };
  // Какие этапы показывает карточка (WF198, #9159, слово Элвиса 08.10 ~23:38: «шаги три из трёх…
  // Я там четыре шага вижу»): только те, что у Workflow есть, — записанные ролью; ролей меньше, чем
  // «шаги N из M», — добираем до M по частоте в сводках (кодинг, тест, критик, план). Ни ролей, ни
  // числа шагов — все четыре, как было. Ответ — номера строк progressStages по порядку.
  const PROGRESS_STAGE_FILL = [2, 3, 1, 0];
  const progressStagesShown = (rows, steps) => {
    const shown = new Set(rows.flatMap((row, index) => (row.role ? [index] : [])));
    const total = Number(steps?.total);
    if (!(total > 0) && !shown.size) return rows.map((row, index) => index);
    for (const index of PROGRESS_STAGE_FILL) if (shown.size < total && index < rows.length) shown.add(index);
    return [...shown].sort((x, y) => x - y);
  };
  // Заливка идущего сегмента (буква 1A): не проценты — их в строке состояния
  // больше нет (AGENTS.md 07.09), — а ПРОЙДЕННЫЕ ЭТАПЫ из четырёх. Каждый этап
  // четверть, идущий даёт половину своей четверти. Ролей в блоке нет — считаем
  // по «шаги N из M»; нет и их — минимум, чтобы сегмент вообще был виден (#5543).
  const PROGRESS_MIN_FILL = 8;
  // Потолок ширины карточки: в широком окне она остаётся такой же компактной, как в
  // узком (слово Элвиса 07.09 22:50).
  const PROGRESS_CARD_MAX_WIDTH = 400;
  // «О чём» с WF84 (#7205) не режется — только пробелы в одну строку (progressLine); с WF160
  // и «сейчас» тоже (срез «…» по числу знаков — progressClip — снят).
  const progressLine = text => String(text ?? "").replace(/\s+/g, " ").trim();
  const progressBlockFill = (block) => {
    if (!block) return null;
    if (block.state === "done") return 100;
    const { rows, now } = progressStages(block);
    // Роли записаны все разом и без 💭, а «шаги 0 из M» — этапы ещё не пройдены:
    // без этого сводка WF22 давала 87,5 % на нулевом шаге (проверка WF22, риск 1).
    const marked = rows.some(row => row.role?.running);
    const unstarted = !marked && block.steps != null && block.steps.done === 0;
    if (now >= 0 && !unstarted) return (now + 0.5) * (100 / rows.length);
    if (block.steps && block.steps.total > 0) return block.steps.done / block.steps.total * 100;
    return null;
  };
  const progressFill = (info) => {
    if (!info) return 0;
    if (info.state === "done") return 100;
    // Процент из строки состояния сильнее сводки: его пишут чаты, которые ещё не
    // перечитали правила, и врать про них незачем.
    const share = info.pct != null ? info.pct : progressBlockFill(progressBlockAt(info, info.wf));
    return Math.max(PROGRESS_MIN_FILL, Math.min(100, share ?? 0));
  };

  // ---- состояние каждого номера (WF84, ТЗ docs/design-strip-wf84.md, п. 2) ----
  // Две вести, и ни одна не зависит от места в ленте. Чат сообщает строкой
  // состояния (счёт M, текущий N, слово текущего), проект — сводкой status.md
  // (блок на каждый номер со своим значком — в том числе два 💭 разом).
  //
  // Сводку берём, только если она СЕГОДНЯШНЯЯ (строка «обновлено 12:40» или
  // сегодняшнее число) и её номера ровно покрывают 1…M: блоков меньше M, больше
  // M или номер повторился — это сводка чужого чата того же проекта или старая
  // форма, и номера рисуются по одной строке (не выдумываем, чего нет в обоих).
  const progressFeedToday = (feed, nowMs = Date.now()) => {
    const updated = feed?.updated;
    if (!updated) return false;
    if (updated.kind === "today") return true;
    if (updated.kind !== "date") return false;
    const at = new Date(nowMs);
    return Number.isFinite(at.getTime()) && progressDateIsToday(updated.time, at);
  };
  const progressFeedBlocks = (info, count) => {
    const feed = statusFeedProject(info?.project);
    if (!feed || !progressFeedToday(feed)) return null;
    const numbered = feed.blocks.filter(block => block.number != null);
    if (numbered.length !== count) return null;
    const seen = new Set();
    for (const block of numbered) {
      if (block.number < 1 || block.number > count || seen.has(block.number)) return null;
      seen.add(block.number);
    }
    return numbered;
  };
  // Состояние блока → вид номера. ⬜ в сводке — «впереди» (plan).
  const PROGRESS_BADGE_OF = { done: "done", run: "run", wait: "wait", fail: "fail", todo: "plan" };
  // Правило слияния на КАЖДЫЙ номер k (ТЗ, п. 2): «готово ✅» строки закрывает
  // все; есть блок k принятой сводки — его состояние (для k = N строка сильнее
  // по правилу WF70, progressBlockState); блока нет — по строке: до N готов,
  // N — слово строки, после — впереди. share — ширина линии шагов идущего
  // (100 у готового, 0 впереди).
  const progressBadgeStates = (info) => {
    const count = Math.max(1, Math.min(PROGRESS_SEG_MAX, Math.round(info.of) || 1));
    const wf = Math.max(1, Math.min(count, Math.round(info.wf) || 1));
    const blocks = info.state === "done" ? null : progressFeedBlocks(info, count);
    const states = [];
    const shares = [];
    for (let number = 1; number <= count; number += 1) {
      const block = blocks ? blocks.find(item => item.number === number) ?? null : null;
      let state = "plan";
      if (info.state === "done") state = "done";
      else if (block) state = PROGRESS_BADGE_OF[number === wf ? progressBlockState(block, info, number) : block.state] ?? "plan";
      else state = number < wf ? "done" : (number === wf ? (PROGRESS_BADGE_OF[info.state] ?? "run") : "plan");
      let share = state === "done" ? 100 : 0;
      if (state === "run") {
        share = number === wf ? progressFill(info)
          : Math.max(PROGRESS_MIN_FILL, Math.min(100, progressBlockFill(block) ?? 0));
      }
      states.push(state);
      shares.push(share);
    }
    return { states, shares, blocks: Boolean(blocks) };
  };
  // Номера ряда с подгонкой под ширину (ТЗ, п. 3): зазор 4, не влезает — 3,
  // всё равно не влезает — первые подряд готовые сливаются в один «1–9» (вид
  // готового, клик — карточка последнего из слитых). Идущие, ждущие и упавшие
  // не сливаются никогда. avail — ширина ряда в точках (нет рамки — без
  // предела). Чистая функция: её гоняют тесты.
  // Ширина ряда номеров с зазорами — та же арифметика у подгонки и у прокрутки.
  const progressRowNeed = (list, gap) => list.reduce((sum, item) => sum + progressBadgeWidth(item.label), 0) +
    gap * Math.max(0, list.length - 1);
  const progressBadges = (info, avail = Infinity) => {
    if (!info) return { items: [], gap: PROGRESS_BADGE_GAP, blocks: false };
    const { states, shares, blocks } = progressBadgeStates(info);
    let items = states.map((state, index) => ({
      n: index + 1, first: index + 1, last: index + 1, label: String(index + 1), state, share: shares[index],
    }));
    const need = progressRowNeed;
    let gap = PROGRESS_BADGE_GAP;
    if (need(items, gap) > avail) {
      gap = PROGRESS_BADGE_GAP_TIGHT;
      if (need(items, gap) > avail) {
        let lead = 0;
        while (lead < items.length && items[lead].state === "done") lead += 1;
        if (lead >= 2) {
          const label = `1–${lead}`;
          items = [{ n: label, first: 1, last: lead, label, state: "done", share: 100, merged: true }, ...items.slice(lead)];
        }
      }
    }
    return { items, gap, blocks };
  };
  // Подпись ряда словами (ТЗ, п. 5): «Воркфлоу: 1 готов, 2 идёт, 3 ждёт тебя».
  const PROGRESS_BADGE_WORDS = { done: "готов", run: "идёт", wait: "ждёт тебя", fail: "упал", plan: "впереди" };
  const progressAria = items => `Воркфлоу: ${items.map(item => `${item.label} ${PROGRESS_BADGE_WORDS[item.state] ?? ""}`.trim()).join(", ")}`;

  // ---- пульс идущего этапа (WF22, буква 1A) --------------------------------
  // Дышит ОТДЕЛЬНЫЙ слой, а не тень или фон: анимировать box-shadow значит
  // перерисовывать тень каждый кадр, а прозрачность composited-слоя ничего не
  // стоит. Ключевые кадры — Web Animations (element.animate): своей таблицы
  // стилей у полосы нет и заводить её нельзя (CSP страницы, раздел 4), а
  // @keyframes без таблицы не бывает.
  // Вдох и выдох за 3600 мс — примерно 17 дыханий в минуту, спокойный
  // человеческий ритм (слово Элвиса 08.09 вечер: «очень плавное, не
  // отвлекающее»). Прежние 2400 читались подмигиванием. Такт ОДИН на всё окно —
  // номер в ряду и карточка (решение WF84: ТЗ полоски писало 2400, карточки —
  // 3600, согласовано 3600).
  const PROGRESS_PULSE_MS = 3600;
  // Синусоида, а не мигание: easing стоит у КАЖДОГО кадра, а не в options.
  // Общий easing растянул бы весь круг разом, и на вершине вышел бы угол —
  // ровно то моргание, от которого уходим; покадровый ease-in-out даёт нулевую
  // скорость и в нижней точке, и в верхней. Все кадры идут от выдоха к вдоху и
  // обратно — вершина у всех слоёв в одной точке такта.
  const progressBreath = (low, high = "1") => [
    { opacity: low, easing: "ease-in-out" }, { opacity: high, easing: "ease-in-out" }, { opacity: low },
  ];
  // Линия шагов идущего номера: 0,45 → 1 (ТЗ, п. 3).
  const PROGRESS_LINE_FRAMES = progressBreath("0.45");
  // Карточка (ТЗ 9.1, п. 7): ореол кружка, подсветка строки, точка в плашке.
  const PROGRESS_HALO_FRAMES = progressBreath("0.18");
  const PROGRESS_HL_FRAMES = progressBreath("0.35");
  const PROGRESS_DOT_FRAMES = progressBreath("0.3");
  // Скрытое окно и «поменьше движения» в системе гасят пульс: Electron всё равно
  // придушит таймеры перекрытого окна, а анимация останется висеть.
  const progressMotionOk = () => {
    if (document.hidden) return false;
    try { return !matchMedia("(prefers-reduced-motion: reduce)").matches; } catch { return true; }
  };
  // slot — любой объект с полем anim (номер или слот карточки): вторую анимацию
  // на тот же узел не заводим, а снимаем ровно свою.
  //
  // Фаза общая (ТЗ 9.1, п. 7): у каждой анимации startTime = 0 — все с одной
  // длительностью идут от начала шкалы документа, и два идущих номера, кружок,
  // строка и точка вдыхают вместе, даже если открыты в разное время.
  const progressPulse = (slot, node, on, frames, rest) => {
    if (!node) return;
    if (!on || !progressMotionOk()) {
      if (slot.anim) { try { slot.anim.cancel(); } catch {} slot.anim = null; }
      node.style.setProperty("opacity", rest);
      return;
    }
    if (slot.anim) return;
    try {
      slot.anim = node.animate(frames, { duration: PROGRESS_PULSE_MS, iterations: Infinity });
      try { slot.anim.startTime = 0; } catch {}
    } catch { slot.anim = null; node.style.setProperty("opacity", rest); }
  };
  // Живые номера слева направо.
  const progressCells = [];
  // Покой слоёв карточки, когда она не дышит (ТЗ 9.1, п. 7).
  const progressCardRest = { halo: "0.6", hl: "1", dot: "1" };
  const progressCardPulse = on => {
    const ui = progressCardUI;
    const row = ui.rows[ui.states.findIndex(state => state === "run")] ?? null;
    progressPulse(ui.slots.halo, row?.halo ?? null, on && row != null, PROGRESS_HALO_FRAMES, progressCardRest.halo);
    progressPulse(ui.slots.hl, row?.hl ?? null, on && row != null, PROGRESS_HL_FRAMES, progressCardRest.hl);
    progressPulse(ui.slots.dot, ui.dot, on, PROGRESS_DOT_FRAMES, progressCardRest.dot);
  };
  const progressCardPulseStop = () => {
    for (const slot of Object.values(progressCardUI.slots)) {
      if (slot.anim) { try { slot.anim.cancel(); } catch {} slot.anim = null; }
    }
  };
  // Пересобрать пульсы по тому, что уже решил последний проход: зовётся на
  // visibilitychange, где меняется не ряд, а только право двигаться.
  const progressPulseSync = () => {
    for (const item of progressCells) progressPulse(item, item.line, item.pulse, PROGRESS_LINE_FRAMES, "1");
    if (!progressState.tipOpen) { progressCardPulseStop(); return; }
    progressCardPulseStop();
    progressCardPulse(progressState.cardBreathe === true);
    progressState.cardPulse = Boolean(progressCardUI.slots.dot.anim);
  };
  on(document, "visibilitychange", () => { try { progressPulseSync(); } catch {} });
  // Снятие: анимация переживает и удаление узла из разметки, и dispose().
  track(() => {
    for (const item of progressCells) {
      if (item.anim) { try { item.anim.cancel(); } catch {} item.anim = null; }
    }
    progressCardPulseStop();
  });

  // Узел номера: цифра и линия шагов идущего (2 точки у нижнего края, ширина —
  // доля шагов). Рождается прозрачным и без переходов: цвета ему впишет тот же
  // проход progressApply, и вписать их надо мгновенно, а проявиться — за
  // 200 мс (ТЗ, п. 3).
  const PROGRESS_BADGE_TRANS = `background-color ${PROGRESS_BADGE_MS}ms ease, color ${PROGRESS_BADGE_MS}ms ease, ` +
    `box-shadow ${PROGRESS_BADGE_MS}ms ease, opacity ${PROGRESS_BADGE_MS}ms ease`;
  const progressCell = () => {
    const cell = document.createElement("div");
    for (const [name, value] of Object.entries({
      position: "relative", flex: "0 0 auto", "box-sizing": "border-box", height: `${PROGRESS_BADGE_HEIGHT}px`,
      "min-width": `${PROGRESS_BADGE_MIN}px`, padding: "0 3px", "border-radius": "3px", overflow: "hidden",
      "text-align": "center", font: `600 9px/${PROGRESS_BADGE_HEIGHT}px -apple-system, system-ui, sans-serif`,
      "font-variant-numeric": "tabular-nums", "white-space": "nowrap", "pointer-events": "none",
      "outline-offset": "1px", opacity: "0", transition: "none",
    })) cell.style.setProperty(name, value);
    const num = document.createElement("span");
    num.style.setProperty("position", "relative");
    const line = document.createElement("div");
    for (const [name, value] of Object.entries({
      position: "absolute", left: "0", bottom: "0", height: "2px", width: "0%", display: "none",
      "pointer-events": "none", transition: "width 400ms linear",
    })) line.style.setProperty(name, value);
    cell.appendChild(num);
    cell.appendChild(line);
    return { cell, num, line, anim: null, pulse: false, born: true };
  };
  // Пул: число номеров меняется только с марафоном, но узел — это и его цвет с
  // переходом; лишние хвостом уходят сразу, недостающие проявляются.
  const progressBuild = (count) => {
    while (progressCells.length > count) {
      const item = progressCells.pop();
      if (item.anim) { try { item.anim.cancel(); } catch {} item.anim = null; }
      item.cell.remove();
    }
    while (progressCells.length < count) {
      const item = progressCell();
      progressBar.appendChild(item.cell);
      progressCells.push(item);
    }
  };

  // Гасим карточку И забываем выбранный сегмент. Раньше снимался только display,
  // а `tipOpen` оставался true — и хвост progressApply (`if (progressState.tipOpen)
  // progressTipShow()`) возвращал карточку на экран САМ, без клика, как только в
  // ленте снова появлялась строка состояния: перешёл по сайдбару в другой чат — и
  // она выскочила поверх поля ввода с чужим воркфлоу (находка ревизии 08.09).
  // Открывается карточка только кликом Элвиса.
  const progressTipHide = () => {
    progressState.tipOpen = false;
    progressState.tipSegment = null;
    progressState.cardRows = [];
    progressState.cardNote = null;
    progressState.cardAnchor = null;
    progressCardUI.states = [];
    progressTipTickStop();
    progressState.cardPulse = false;
    progressState.cardBreathe = false;
    progressCardPulseStop();
    // Закрытие мгновенное (ТЗ 9.1, п. 7): переход появления снимаем.
    progressTip.style.setProperty("transition", "none");
    if (progressTip.style.display !== "none") progressTip.style.setProperty("display", "none");
    // Обводка выбранного номера уходит вместе с карточкой.
    for (const item of progressCells) item.cell.style.setProperty("outline", "none");
  };
  // Коробки номеров на экране: живой прямоугольник узла, а в стенде (узлы без
  // раскладки) — та же арифметика, что поставила им ширину (progressApply).
  // Сдвиг прокрутки (WF85) живой прямоугольник уже несёт в себе (translateX) —
  // вычитаем его только в арифметике, иначе номер сдвинулся бы дважды.
  const progressBadgeBoxes = () => {
    const box = progressState.box;
    const items = progressState.badges;
    if (!box || items.length === 0) return [];
    const boxes = [];
    let left = box.left - (progressScroll.on ? progressScroll.x : 0);
    for (let index = 0; index < items.length; index += 1) {
      const width = progressBadgeWidth(items[index].label);
      let rect = null;
      try { rect = progressCells[index]?.cell.getBoundingClientRect() ?? null; } catch {}
      if (rect && rect.width > 0) boxes.push({ left: rect.left, right: rect.right });
      else boxes.push({ left, right: left + width });
      left += width + (progressState.gap ?? PROGRESS_BADGE_GAP);
    }
    return boxes;
  };
  // Номер под точкой x: его прямоугольник плюс половина зазора с каждой
  // стороны (ТЗ, п. 5). Мимо номеров, но в ряду — номер текущего воркфлоу N.
  // В режиме прокрутки (WF85) ловятся только номера, видные в окне номеров, а
  // мимо них — ничего: текущий мог уехать за край, и карточка встала бы к
  // номеру, которого не видно.
  const progressSegmentAt = (x) => {
    const items = progressState.badges;
    if (!progressState.box || items.length === 0) return null;
    const half = (progressState.gap ?? PROGRESS_BADGE_GAP) / 2;
    const boxes = progressBadgeBoxes();
    const view = progressScroll.on ? progressScroll.view : null;
    if (view && (x < view.left || x > view.right)) return null;
    for (let index = 0; index < boxes.length; index += 1) {
      if (view && (boxes[index].right <= view.left || boxes[index].left >= view.right)) continue;
      if (x >= boxes[index].left - half && x <= boxes[index].right + half) return index;
    }
    if (view) return null;
    const wf = progressState.info?.wf ?? 1;
    const current = items.findIndex(item => wf >= item.first && wf <= item.last);
    return current >= 0 ? current : items.length - 1;
  };
  // Состояние ОДНОГО воркфлоу словом: до текущего — готов, после — запланирован,
  // сам текущий — по значку строки состояния. ✅ у всего марафона закрывает всё.
  // Так считается, когда блока сводки на сегмент нет; нашёлся — состояние даёт
  // блок (progressBlockState).
  const PROGRESS_WORDS = { done: "готов", run: "идёт", wait: "ждёт", fail: "упал", todo: "запланирован" };
  const progressWord = (info, number) => {
    if (info.state === "done" || number < info.wf) return "готов";
    if (number > info.wf) return "запланирован";
    return PROGRESS_WORDS[info.state] ?? "идёт";
  };
  // Состояние найденного блока — из ЕГО заголовка, а не из счёта чата (WF70):
  // у VkusnoffKz три блока 💭 при строке «WF 1 из 3», и второй сегмент по счёту
  // выходил «запланирован», хотя в сводке он идёт. Одно исключение — текущий
  // сегмент при ⚠️/🛑 в строке состояния: в сводке таких значков нет, чат ждёт
  // Элвиса или упал на том же блоке, что помечен 💭, и бейдж обязан сказать
  // «ждёт тебя» (слово Элвиса 07.09 22:50).
  const progressBlockState = (block, info, number) => {
    if (block.state === "run" && number === info.wf && (info.state === "wait" || info.state === "fail")) {
      return info.state;
    }
    // Строка чата уже говорит 💭/⚠️/🛑 на этом воркфлоу, а заголовок блока ещё ⬜
    // (оркестратор не переписал) — верим строке: иначе полоса пульсирует «идёт», а
    // карточка на том же сегменте твердит «Ещё не начат» (проверка WF70).
    if (block.state === "todo" && number === info.wf && ["run", "wait", "fail"].includes(info.state)) {
      return info.state;
    }
    return block.state;
  };
  // Номер воркфлоу по номеру в ряду: обычно это его порядок, а у слитого «1–9»
  // — последний из слитых (ТЗ, п. 3).
  const progressNumberAt = (index) => {
    const info = progressState.info;
    if (!info) return null;
    const items = progressState.badges;
    if (items.length === 0) return Math.max(1, Math.min(info.of || 1, (index ?? 0) + 1));
    const item = items[Math.min(items.length - 1, Math.max(0, index ?? 0))];
    return item.last;
  };
  // Эмодзи в карточке с WF84 нет (9.1: состояние читается кружком дорожки и
  // точкой плашки). Слово плашки — по состоянию.
  const PROGRESS_CARD_PILL = { done: "готов", run: "идёт", wait: "ждёт тебя", fail: "упал", todo: "запланирован" };
  // Блока про этот воркфлоу в присланных сводках не нашлось. Раньше здесь стояло
  // «сводки нет», и Элвис читал это как поломку (08.09, #5807: «он же неспроста
  // там ячейка стоит»). Ячейка правда есть: её место в счёте чата уже написано в
  // заголовке и строке под ним, и остаётся сказать честно — про сам воркфлоу
  // ещё ничего не записано. Ключ — слово состояния из progressWord.
  const PROGRESS_CARD_BLANK = {
    "запланирован": "ещё не расписан — что в нём будет, запишем, когда дойдёт очередь",
    "готов": "уже сделан — что в нём было, не записали",
  };
  // Идущий (ждущий, упавший) без блока — ничего не пишем (#7188: «пока не
  // записан» Элвис читал как «воркфлоу нет, а полоска врёт»).
  const PROGRESS_CARD_BLANK_ANY = "";
  // Кожа карточки — ЗАПАСНАЯ (цвета темы не прочитались) и источник тонов G/Y/R
  // тройками (готово, ждёт, упал). С WF84 фон, текст и акцент берутся от темы
  // окна (progressTextColor, progressFieldColor, accentColor); синий `run`
  // отсюда больше не рисуется.
  const PROGRESS_CARD_SKIN = {
    dark: {
      back: "#33373f", line: "rgba(255,255,255,.16)", text: "#eef0f4", dim: "#aab0bc",
      shadow: "0 18px 44px rgba(0,0,0,.62),0 2px 6px rgba(0,0,0,.45)",
      run: "126,160,255", ok: "77,187,125", wait: "245,197,66", fail: "238,106,95", todo: "150,155,165",
    },
    light: {
      back: "#ffffff", line: "rgba(20,24,32,.16)", text: "#171a20", dim: "#666c7a",
      shadow: "0 18px 44px rgba(20,24,32,.24),0 2px 6px rgba(20,24,32,.12)",
      run: "47,98,216", ok: "31,154,90", wait: "196,138,0", fail: "204,58,48", todo: "130,136,150",
    },
  };
  // Эффорт словами самого Claude Code (#5907). У ползунка Effort пять делений —
  // Low · Medium · High · Extra · Max, — а сводки пишут «xhigh»: Элвис это слово
  // не читает («он не выкупит, короче»). Переводим ТОЛЬКО на показе: файлы
  // сводок пишут и читают агенты, и там слово остаётся прежним. Чего в списке
  // нет, не выдумываем — показываем как написано.
  const PROGRESS_EFFORT_WORDS = {
    low: "Low", medium: "Medium", high: "High", xhigh: "Extra", extra: "Extra", max: "Max",
  };
  // «×1» в конце записи модели: «Fable xhigh ×1». Знак берём и математический, и
  // латинскую «x», и кириллическую «х» — диктуется голосом, пишется по-разному.
  const PROGRESS_TIMES_RE = /\s*[×xх*]\s*(\d+)\s*$/i;
  // Сколько моделей помещается в колонку «кто»: в окне 280 она 126 точек, и
  // третья запись уводит строку на третью строчку карточки. Остаток прячем за
  // «и ещё N».
  const PROGRESS_WHO_MODELS = 2;
  // Одна запись «кто»: «Fable xhigh ×1» → Fable Extra, счёт 1. Счёт здесь
  // необязателен — у «- проверка · 🔴 **Fable max**» его нет вовсе.
  const progressModel = (text) => {
    const line = String(text ?? "").replace(/\s+/g, " ").trim();
    if (!line) return null;
    const times = line.match(PROGRESS_TIMES_RE);
    const name = (times ? line.slice(0, line.length - times[0].length) : line).trim();
    if (!name) return null;
    const effort = name.match(STATUS_EFFORT_RE);
    const model = effort ? name.slice(0, name.length - effort[0].length).trim() : name;
    const word = effort ? (PROGRESS_EFFORT_WORDS[effort[1].toLowerCase()] ?? effort[1]) : "";
    return {
      text: [model, word].filter(Boolean).join(" "),
      count: times ? Number(times[1]) : null,
      // Fable max — красный кружок и жирным (слово Элвиса 04.09 21:10): по нему
      // видно, где потрачена дорогая модель. Примета считается по записи, так
      // что и в списке из двух моделей она не теряется.
      fable: /fable/i.test(model) && /^max$/i.test(effort?.[1] ?? ""),
    };
  };
  // Сколько агентов стояло на этапе: «1 агент», «2 агента» → число. «я» числа не
  // даёт — это слово Элвиса про себя, оно и остаётся словом.
  const progressAgentsCount = (text) => {
    const digits = String(text ?? "").match(/\d+/);
    return digits ? Number(digits[0]) : null;
  };
  // Кто делал этап. Раньше строка читалась как «2 агента · Opus max» и «2 агента
  // · Fable xhigh ×1, Fable high ×1» — Элвис попросил убрать и «N агентов», и
  // «×N» (#5908): число стоит ПОСЛЕ модели, «Opus Max 2», «Fable Extra 1, Fable
  // High 1». Нет ни того ни другого — показываем модель без числа.
  // Этап, пропущенный явно: роль записана словом «пропущен» / «пропуск» («- критик · пропущен»).
  const progressSkipped = role => Boolean(role) && /(?:^|[\s·])пропу(?:щ|ск)/iu.test(` ${role.agents ?? ""} ${role.model ?? ""} ${role.effort ?? ""}`);
  const progressWho = (role) => {
    if (!role) return { text: "—", fable: false };
    // Режем список ТОЛЬКО по запятой и точке с запятой. Раньше в разделители
    // входила и «·», а ею Codex/Astra разделяет части одной записи («project_audit
    // независимо, root по интерфейсу · gpt-6-astra») — половинки занимали оба
    // места, и имя модели пропадало с карточки вовсе.
    const models = [role.model, role.effort].filter(Boolean).join(" ")
      .split(/\s*[,;]\s*/).map(progressModel).filter(Boolean);
    const agents = progressAgentsCount(role.agents);
    // Счёт агентов из строки роли годится, только когда модель одна и своего
    // числа у неё нет: у списка «×1, ×1» числа уже стоят при моделях, а сумма их
    // и есть те самые «2 агента».
    if (models.length === 1 && models[0].count === null && agents !== null) models[0].count = agents;
    // Знак «×» перед числом вернул Элвис 13.09 (#5976): «Opus Max 1» он читает
    // как номер версии модели, а «Opus Max ×1» — как «одна штука». Само
    // «N агентов» при этом не возвращается, уходил именно счётчик словами.
    const shown = models.slice(0, PROGRESS_WHO_MODELS)
      .map(item => [item.fable ? `🔴 ${item.text}` : item.text, item.count === null ? "" : `×${item.count}`]
        .filter(Boolean).join(" "));
    const rest = models.length - shown.length;
    const list = [shown.join(", "), rest > 0 ? `и ещё ${rest}` : ""].filter(Boolean).join(" ");
    // «я» остаётся впереди и через точку: «я · Fable Extra» (слово Элвиса).
    // Число агентов уходит к модели — но только если модель вообще написана:
    // у голого «- кодинг · 2 агента» сказать больше нечего, и строку показываем
    // как есть, а не прочерком.
    // «я» остаётся, даже когда рядом стоит число («я + 1 агент»): иначе Элвис
    // пропадал бы со своей же строки плана.
    const mine = /(^|[\s+])я([\s+]|$)/u.test(String(role.agents ?? ""));
    const word = mine ? "я"
      : (models.length === 0 || agents === null ? String(role.agents ?? "").trim() : "");
    const text = [word, list].filter(Boolean).join(" · ");
    // Красный кружок и жирное — примета ПОКАЗАННЫХ записей: спряталась за «и ещё
    // N» — и жирной строки быть не должно, иначе непонятно, за что она жирная.
    return { text: text || "—", fable: models.slice(0, PROGRESS_WHO_MODELS).some(item => item.fable) };
  };
  // Строка времени блока: «21:15 → закончит примерно в 23:30 · идёт 45 мин». Слово
  // «примерно» Элвис попросил убрать (#5909) — в шаблоне правил его больше нет,
  // но в десятках уже написанных сводок оно осталось, поэтому чистим на показе.
  // Границу слова тут даёт взгляд вперёд, а не `\b`: `\b` в JS считает словом
  // только латиницу с цифрами, и у кириллицы он не срабатывает вовсе.
  const progressTime = (text) => String(text ?? "")
    .replace(/\s*примерно(?![\p{L}\p{N}])/giu, "").replace(/\s+/g, " ").trim();
  // ---- строка «когда» (WF70, #6247) ------------------------------------------
  // Внизу карточки — одна человеческая строка про ЭТОТ воркфлоу: «Завершился
  // 15 мин назад · занял 50 мин», «Идёт 25 мин · начался в 13:05 · закончит в
  // 13:50», «Ждёт тебя · идёт 40 мин», «Ещё не начат». Стояли счёт проекта
  // («2 воркфлоу, 2 готово · 1,4 ч» — цифры про весь проект под карточкой одного
  // воркфлоу) и «09:45 → 10:35 · 50 мин · шаги 1 из 1» — Элвис: «оно путает»,
  // и что он сам эту строку не понимает. Часы «сейчас» функция получает снаружи и
  // сама их не спрашивает — чистая, тесты ставят любое «сейчас».
  //
  // Относительные слова («только что», «15 мин назад», «идёт 25 мин») — ТОЛЬКО
  // когда сводка обновлена сегодня (updated.kind === "today", строка «обновлено
  // 12:40» без даты) и отметка блока не позже «сейчас»; иначе честно абсолютом:
  // «Завершился вчера в 10:35», «Идёт · начался в 13:05». Отметка позже
  // «сейчас» у сегодняшнего файла — часы в сводке чужие (файл от вчера, который
  // не переписали), и считать от них назад нельзя.
  const PROGRESS_CLOCK_RE = /(\d{1,2})\s*:\s*(\d{2})/;
  // Часы «10:35» → минуты от полуночи и текст как написан; часов нет — null.
  const progressClock = (text) => {
    const hit = String(text ?? "").match(PROGRESS_CLOCK_RE);
    if (!hit) return null;
    const hours = Number(hit[1]);
    const minutes = Number(hit[2]);
    if (hours > 23 || minutes > 59) return null;
    return { at: hours * 60 + minutes, text: `${hit[1]}:${hit[2]}` };
  };
  // Длительность словами сводки (AGENTS.md): минуты до часа, дальше часы с
  // одним знаком и запятой — «50 мин», «1,5 ч», «2 ч».
  const progressSpan = (minutes) => {
    const whole = Math.max(0, Math.round(minutes));
    if (whole < 60) return `${whole} мин`;
    return `${String(Math.round(whole / 6) / 10).replace(".", ",")} ч`;
  };
  // Части строки времени: начало — часы слева от стрелки; справа либо конец
  // («10:35»), либо срок («закончит в 16:00»); хвост после последнего « · » —
  // длительность, как её записали («50 мин», «идёт 1,8 ч»).
  const progressTimeParts = (text) => {
    const line = progressTime(text);
    const arrow = line.indexOf("→");
    const dot = line.lastIndexOf("·");
    const body = dot >= 0 ? line.slice(0, dot) : line;
    const left = arrow >= 0 ? body.slice(0, arrow) : body;
    const right = arrow >= 0 ? body.slice(arrow + 1) : "";
    const finish = /закончит/iu.test(right);
    return {
      start: progressClock(left),
      end: finish ? null : progressClock(right),
      until: finish ? progressClock(right) : null,
      tail: dot >= 0 ? line.slice(dot + 1).trim() : "",
    };
  };
  // Когда файл не сегодняшний, «Завершился в 10:35» получает день: «вчера в
  // 10:35», «15.09 в 10:35».
  const progressDay = (updated) => {
    if (updated?.kind === "yesterday") return "вчера ";
    if (updated?.kind === "date" && updated.time) return `${updated.time} `;
    return "";
  };
  // «17.09», «17.09.2026», «17.09.26» — это дата `at`? Год без цифр — считаем этот.
  const progressDateIsToday = (text, at) => {
    const m = String(text ?? "").match(/^(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?/);
    if (!m) return false;
    const year = m[3] ? (m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3])) : at.getFullYear();
    return Number(m[1]) === at.getDate() && Number(m[2]) === at.getMonth() + 1 && year === at.getFullYear();
  };
  const progressWhen = (block, now, updated) => {
    if (!block) return "";
    if (block.state === "todo") return "Ещё не начат";
    const { start, end, until, tail } = progressTimeParts(block.time);
    const at = new Date(now);
    // «обновлено 17.09.2026» сегодняшним числом — тоже сегодня (проверка WF70):
    // Dictator и NightWolf пишут в шапку дату, а не часы.
    const today = Number.isFinite(at.getTime())
      && (updated?.kind === "today" || (updated?.kind === "date" && progressDateIsToday(updated.time, at)));
    const nowAt = at.getHours() * 60 + at.getMinutes();
    // Сколько минут прошло от отметки до «сейчас»; нельзя сказать — null.
    const since = (clock) => (today && clock && clock.at <= nowAt ? nowAt - clock.at : null);
    if (block.state === "done") {
      const gone = since(end);
      const head = gone === null
        ? (end ? `Завершился ${progressDay(updated)}в ${end.text}` : "Завершился")
        : (gone < 1 ? "Завершился только что" : `Завершился ${progressSpan(gone)} назад`);
      // «занял» — хвост строки, если это длительность («50 мин»); хвоста нет или
      // он не про то («идёт 1,8 ч» у блока, который закрыли, не переписав
      // время) — разница часов, через полночь с добавкой суток.
      const took = /^\d/.test(tail) ? tail
        : (start && end ? progressSpan((end.at - start.at + 1440) % 1440) : "");
      return took ? `${head} · занял ${took}` : head;
    }
    // Идёт, ждёт, упал: состояние уже на плашке шапки («идёт кодинг», «ждёт тебя», «упал») — здесь
    // его не повторяем (правило №5 INTERFACES, WF160), только когда: «Начался 25 мин назад, в 13:05»,
    // не сегодня — с днём («Начался вчера в 13:05»). Ждёт или упал — срок «закончит» ни о чём.
    const gone = since(start);
    const head = !start ? ""
      : (gone === null ? `Начался ${progressDay(updated)}в ${start.text}`
        : (gone < 1 ? "Начался только что" : `Начался ${progressSpan(gone)} назад, в ${start.text}`));
    if (block.state !== "run" || !until) return head;
    return head ? `${head} · закончит в ${until.text}` : `Закончит в ${until.text}`;
  };
  // ---- карточка 9.1: данные и вид (WF84, #7205) ------------------------------
  // Карточка не ýже 240 и не шире поля, ýже 320 — «узкая» (строки этапов 24 вместо 28).
  const PROGRESS_CARD_MIN_WIDTH = 240;
  const PROGRESS_CARD_NARROW = 320;
  const PROGRESS_CARD_WAIT_PREFIX = "Твой ход: ";
  // Воркфлоу k по одной строке чата, когда блока нет: до текущего — готов,
  // после — впереди, сам текущий — слово строки.
  const progressLineState = (info, number) => {
    if (info.state === "done" || number < info.wf) return "done";
    if (number > info.wf) return "todo";
    return info.state ?? "run";
  };
  // Данные карточки воркфлоу k (ТЗ полоски, п. 6) — всё из уже существующих
  // разборов (statusBlocks, statusParse, progressStages, progressWho); новых
  // разборов status.md здесь нет. waitFor — строка «Ждёт Элвиса:» сводки (только
  // у ждущего), now — строка «Сейчас:»; обе только у воркфлоу N из строки чата
  // и только у сегодняшней сводки. Приходят они в шапке команды status, если
  // её шлёт приложение с правкой S-K (StatusFeed.compact); без неё — пусто.
  const progressCardData = (number, info = progressState.info, nowMs = Date.now()) => {
    if (!info || number == null) return null;
    const feed = statusFeedProject(info.project);
    const block = progressBlockAt(info, number);
    const blockState = block ? progressBlockState(block, info, number) : null;
    const state = blockState ?? progressLineState(info, number);
    const stages = progressStages(block);
    const own = number === info.wf && progressFeedToday(feed, nowMs);
    return {
      number: block ? (block.number ?? number) : number, of: info.of, state,
      word: block ? (PROGRESS_WORDS[blockState] ?? "идёт") : progressWord(info, number),
      about: block?.about ?? "", steps: block?.steps ?? null,
      stages: stages.rows.map(row => ({
        name: row.label, who: progressWho(row.role).text,
        model: row.role?.model ?? "", effort: row.role?.effort ?? "", running: Boolean(row.role?.running),
      })),
      when: block ? progressWhen(blockState === block.state ? block : { ...block, state: blockState }, nowMs, feed?.updated) : "",
      waitFor: own && state === "wait" ? (feed?.waitFor ?? "") : "",
      now: own ? (feed?.now ?? "") : "",
      project: info.project ?? "", chatWord: PROGRESS_WORDS[info.state] ?? "идёт",
      source: progressState.source, frozen: progressState.frozen,
    };
  };
  // Вид карточки (ТЗ 9.1, п. 6): чистая функция без DOM, её гоняют тесты;
  // рисование (progressTipShow) только переносит результат в узлы.
  //
  // Состояние строк этапов — от СЫРОГО состояния блока: готовый — пройдены все
  // этапы (WF160, критик: этап без записанной роли — тоже пройден ✓, как было на
  // карточке у Элвиса; «пропущен» точкой — только когда роль так и записана:
  // «- критик · пропущен»); идёт, ждёт, упал (💭, ✋/⚠️/❓,
  // 🛑 в заголовке) — до текущего пройдены, текущий — состояние воркфлоу (так
  // ⚠️/🛑 строки чата красят кружок), после — впереди; запланированный (и ⬜,
  // который строка чата подняла в «идёт») — все впереди. Нет 💭 ни на одной
  // роли и «шаги 0 из M» — текущий первый этап (как `unstarted` у заливки):
  // запланированный блок пишет все роли разом, и без правила идущей
  // становилась «проверка».
  const progressCardView = (info, number, nowMs = Date.now()) => {
    const data = progressCardData(number, info, nowMs);
    if (!data) return null;
    const block = progressBlockAt(info, number);
    const state = data.state;
    const stages = progressStages(block);
    const marked = stages.rows.some(row => row.role?.running);
    // Строки — только этапы этого Workflow (progressStagesShown, WF198); состояние считается по всем четырём,
    // «не начат» — первый показанный этап.
    const shown = progressStagesShown(stages.rows, block?.steps);
    const now = !marked && block?.steps && block.steps.done === 0 ? shown[0] : stages.now;
    const raw = block?.state ?? null;
    const live = raw === "run" || raw === "wait" || raw === "fail";
    const passed = row => (progressSkipped(row.role) ? "skip" : "done");
    const rows = stages.rows.map((row, index) => {
      let rowState = "todo";
      if (raw === "done") rowState = passed(row);
      else if (live && now >= 0) {
        if (index < now) rowState = passed(row);
        else if (index === now) rowState = state === "done" || state === "todo" ? raw : state;
      }
      // Роли нет — «кто» пусто, а не «—» (критик WF160: прочерк читался «не делали»).
      const who = row.role ? progressWho(row.role) : { text: "", fable: false };
      return { label: row.label, who: who.text, fable: who.fable, state: rowState };
    }).filter((row, index) => shown.includes(index));
    const at = rows.findIndex(row => row.state === "run" || row.state === "wait" || row.state === "fail");
    let note = null;
    // «Сейчас» и «Твой ход» — целиком (WF160: без «…»), только пробелы в одну строку.
    if (block && data.waitFor && state === "wait") {
      note = { row: at, kind: "wait", prefix: PROGRESS_CARD_WAIT_PREFIX, text: progressLine(data.waitFor) };
    } else if (block && data.now && (state === "run" || state === "fail")) {
      note = { row: at, kind: "now", prefix: "", text: progressLine(data.now) };
    }
    const pill = state === "run" && at >= 0 && rows[at].state === "run" ? `идёт ${rows[at].label}`
      : (PROGRESS_CARD_PILL[state] ?? "идёт");
    return {
      // Слово одно на всю карточку — русское (#5911). С WF160 на экране вместо него капсула
      // номера (number, progressCardPaint); слово остаётся в слепке карточки для гейта.
      title: `Воркфлоу ${data.number}`, number: data.number,
      // «В проекте» на карточке не пишется (слово Элвиса 08.09): подпись
      // остаётся только у чата без блока.
      where: block ? "" : `${number}-й из ${info.of} в этом чате`,
      pill: { tone: state, text: pill },
      about: block ? (progressLine(block.about) || "—") : (PROGRESS_CARD_BLANK[data.word] ?? PROGRESS_CARD_BLANK_ANY),
      stages: Boolean(block), rows, note, when: data.when,
      // Дышит только то, что работает (готовый больше не дышит).
      breathe: state === "run",
    };
  };
  // Слепок карточки — он же ключ перерисовки (status().progress.tip.card):
  // последней стоит «когда», на гейте её сверяют по краям.
  const progressCardKey = view => [
    view.title, view.where, view.pill.text, view.about,
    ...(view.stages ? view.rows.map(row => `${row.label} ${row.state} ${row.who}`) : []),
    view.note ? `${view.note.prefix}${view.note.text}` : "", view.when,
  ].filter(Boolean).join(" · ");
  // Подгонка под потолок (ТЗ 9.1, п. 3). С WF160 ничего не режется «…» (ни «сейчас», ни «когда»):
  // единственный шаг — не влезла карточка — спрятать строку «сейчас» целиком.
  const progressCardFit = (level, note) => {
    const ui = progressCardUI;
    const target = note ? (note.row >= 0 ? ui.rows[note.row] : ui.spare) : null;
    for (const item of [...ui.rows, ui.spare]) {
      item.note.style.setProperty("display", item === target && level < 1 ? "block" : "none");
    }
  };
  // Нарисовать карточку view (progressCardUI): тексты, цвета темы окна, капсула номера, дорожка
  // этапов, подгонка под потолок maxHeight. cap — капсула номера {label, paint}: paint — её цвета
  // (как номер в ряду). Место на экране — у вызывающего (progressTipShow); ответ — появляется ли
  // карточка только что (тогда после места — progressCardReveal).
  const progressCardPaint = (view, frame, width, maxHeight, cap) => {
    const ui = progressCardUI;
    const narrow = width < PROGRESS_CARD_NARROW;
    // Цвета от темы окна — на каждом показе (ТЗ 9.1, п. 5).
    const dark = progressDark();
    const skin = PROGRESS_CARD_SKIN[dark ? "dark" : "light"];
    const T = progressTextColor(frame);
    const F = progressFieldColor(frame);
    const A = progressAccent();
    const G = `rgb(${skin.ok})`;
    const Y = `rgb(${skin.wait})`;
    const R = `rgb(${skin.fail})`;
    const Yt = dark ? Y : "rgb(150,104,0)";
    const tone = { done: G, run: A, wait: Y, fail: R, todo: T, skip: T };
    const tint = progressTint;
    const key = progressCardKey(view);
    const fresh = ui.text !== key;
    if (fresh) {
      ui.text = key;
      ui.fit = 0;
      // Только textContent: сводку пишут чаты, разметки в ней быть не может.
      ui.title.textContent = cap.label;
      ui.where.textContent = view.where;
      ui.where.hidden = view.where === "";
      ui.where.style.setProperty("display", view.where === "" ? "none" : "block");
      ui.pillText.textContent = view.pill.text;
      ui.about.textContent = view.about;
      ui.about.hidden = view.about === "";
      ui.about.style.setProperty("display", view.about === "" ? "none" : "block");
      ui.when.textContent = view.when;
      ui.when.hidden = view.when === "";
      ui.when.style.setProperty("display", view.when === "" ? "none" : "block");
      ui.stages.hidden = !view.stages;
      ui.stages.style.setProperty("display", view.stages ? "block" : "none");
      for (let order = 0; order < ui.rows.length; order += 1) {
        const node = ui.rows[order];
        const row = view.rows[order];
        // Этапов у Workflow меньше четырёх (WF198) — лишние строки прячутся.
        node.row.style.setProperty("display", row ? "grid" : "none");
        if (!row) continue;
        node.label.textContent = row.label;
        node.who.textContent = row.who;
        node.glyph.textContent = { done: "✓", wait: "!", fail: "✕" }[row.state] ?? "";
        const mine = view.note && view.note.row === order;
        node.prefix.textContent = mine ? view.note.prefix : "";
        node.text.textContent = mine ? view.note.text : "";
      }
      const spare = view.note && view.note.row < 0;
      ui.spare.prefix.textContent = spare ? view.note.prefix : "";
      ui.spare.text.textContent = spare ? view.note.text : "";
      // Смена содержимого — пульс пересобирается: идущая строка могла смениться.
      progressCardPulseStop();
    }
    for (const [name, value] of Object.entries(cap.paint)) ui.title.style.setProperty(name, value);
    // Коробка: фон — поле плюс 7 % текста (в светлой теме само поле), обводка —
    // текст 15 %, тень кожи.
    for (const [name, value] of Object.entries({
      background: dark ? `color-mix(in srgb, ${F}, ${T} 7%)` : F, color: T,
      "border-color": tint(T, 15), "box-shadow": skin.shadow,
      width: `${width}px`, "max-height": `${maxHeight}px`,
    })) ui.tip.style.setProperty(name, value);
    ui.where.style.setProperty("color", tint(T, 60));
    ui.about.style.setProperty("color", tint(T, 84));
    ui.when.style.setProperty("color", tint(T, 62));
    ui.when.style.setProperty("border-top-color", tint(T, 14));
    // Плашка: фон — цвет состояния 15 %, текст — цвет состояния (у «ждёт» — Yt),
    // точка — цвет состояния; у «запланирован» точка пустым контуром.
    const pillTone = view.pill.tone;
    const todoPill = pillTone === "todo";
    for (const [name, value] of Object.entries({
      background: todoPill ? tint(T, 8) : tint(tone[pillTone] ?? A, 15),
      color: todoPill ? tint(T, 62) : (pillTone === "wait" ? Yt : (tone[pillTone] ?? A)),
    })) ui.pill.style.setProperty(name, value);
    ui.dot.style.setProperty("background", todoPill ? "transparent" : (tone[pillTone] ?? A));
    ui.dot.style.setProperty("box-shadow", todoPill ? `inset 0 0 0 1.5px ${tint(T, 45)}` : "none");
    // Строки этапов: дорожка, этап, кто, подсветка текущей.
    const lineTo = state => ({
      done: tint(G, 85), skip: tint(G, 85), todo: tint(T, 24),
      run: `linear-gradient(${tint(G, 85)}, ${A})`, wait: `linear-gradient(${tint(G, 85)}, ${Y})`,
      fail: `linear-gradient(${tint(G, 85)}, ${R})`,
    })[state] ?? tint(T, 24);
    const rowHeight = narrow ? 24 : 28;
    for (let order = 0; order < ui.rows.length; order += 1) {
      const node = ui.rows[order];
      const row = view.rows[order];
      if (!row) continue;
      const state = row.state;
      const hot = state === "run" || state === "wait" || state === "fail";
      node.track.style.setProperty("min-height", `${rowHeight}px`);
      node.label.style.setProperty("line-height", `${rowHeight}px`);
      // «Кто» переносится (#9158, без «…»): первая строка — на линии этапа.
      node.who.style.setProperty("padding", `${(rowHeight - 16) / 2}px 0`);
      const next = view.rows[order + 1];
      node.line.style.setProperty("display", next ? "block" : "none");
      node.line.style.setProperty("top", narrow ? "21px" : "23px");
      node.line.style.setProperty("bottom", narrow ? "-3px" : "-5px");
      if (next) node.line.style.setProperty("background", lineTo(next.state));
      // Кружок: 14×14, у «впереди» — контур 12×12, у «пропущен» — точка 6×6.
      const size = state === "todo" ? 12 : (state === "skip" ? 6 : 14);
      const shift = state === "todo" ? 1 : (state === "skip" ? 4 : 0);
      const top = (narrow ? 5 : 7) + shift;
      const paint = {
        done: { background: G, color: progressInk(G), "box-shadow": "none" },
        run: { background: "transparent", color: A, "box-shadow": `inset 0 0 0 2px ${A}` },
        wait: { background: Y, color: progressInk(Y), "box-shadow": `0 0 0 3px ${tint(Y, 22)}` },
        fail: { background: R, color: progressInk(R), "box-shadow": `0 0 0 3px ${tint(R, 20)}` },
        todo: { background: "transparent", color: T, "box-shadow": `inset 0 0 0 1.5px ${tint(T, 34)}` },
        skip: { background: tint(T, 30), color: T, "box-shadow": "none" },
      }[state];
      for (const [name, value] of Object.entries({
        ...paint, width: `${size}px`, height: `${size}px`, left: `${3 + shift}px`, top: `${top}px`,
      })) node.node.style.setProperty(name, value);
      // Ядро идущего — точка 6×6 акцентом; у остальных знак — просто текст.
      node.glyph.style.setProperty("width", state === "run" ? "6px" : "auto");
      node.glyph.style.setProperty("height", state === "run" ? "6px" : "auto");
      node.glyph.style.setProperty("background", state === "run" ? A : "transparent");
      node.halo.style.setProperty("display", state === "run" ? "block" : "none");
      node.halo.style.setProperty("box-shadow", `0 0 0 2px ${tint(A, 32)}, 0 0 9px 2px ${tint(A, 42)}`);
      node.label.style.setProperty("color", {
        done: tint(T, 90), run: A, wait: Yt, fail: R,
      }[state] ?? tint(T, 50));
      node.who.style.setProperty("font-weight", row.fable ? "700" : "400");
      node.who.style.setProperty("color", row.fable || hot ? T : (state === "done" ? tint(T, 62) : tint(T, 45)));
      node.hl.style.setProperty("display", hot ? "block" : "none");
      node.hl.style.setProperty("background", hot ? tint(tone[state], 16) : "transparent");
      node.note.style.setProperty("color", tint(T, 76));
      node.prefix.style.setProperty("color", Yt);
    }
    ui.spare.note.style.setProperty("color", tint(T, 76));
    ui.spare.prefix.style.setProperty("color", Yt);
    ui.states = view.stages ? view.rows.map(row => row.state) : [];
    ui.note = view.note ? `${view.note.prefix}${view.note.text}` : null;
    ui.breathe = view.breathe;
    progressCardFit(ui.fit, view.note);
    // Появление: прозрачность 0 → 1 и сдвиг на 4 точки, 140 мс; при «поменьше
    // движения» — сразу. Закрытие мгновенное (progressTipHide).
    const appearing = ui.tip.style.getPropertyValue("display") !== "block";
    if (appearing) {
      ui.tip.style.setProperty("transition", "none");
      ui.tip.style.setProperty("opacity", progressMotionOk() ? "0" : "1");
      ui.tip.style.setProperty("transform", progressMotionOk() ? "translateY(4px)" : "none");
    }
    ui.tip.style.setProperty("display", "block");
    // Подгонка под потолок — только при смене содержимого и не больше одного
    // замера за показ.
    if (fresh) {
      let level = 0;
      try {
        while (level < 1 && ui.tip.scrollHeight > maxHeight) {
          level += 1;
          progressCardFit(level, view.note);
        }
      } catch {}
      ui.fit = level;
    }
    return appearing;
  };
  // Проявить карточку, уже стоящую на месте, и завести дыхание: дышит только идущий, при
  // разрешённом движении; иначе всё стоит — ореол .6, подсветка 1, точка 1.
  const progressCardReveal = appearing => {
    const ui = progressCardUI;
    if (appearing) {
      if (progressMotionOk()) {
        try { ui.tip.getBoundingClientRect(); } catch {}
        ui.tip.style.setProperty("transition", "opacity 140ms ease-out, transform 140ms ease-out");
      }
      ui.tip.style.setProperty("opacity", "1");
      ui.tip.style.setProperty("transform", "none");
    }
    for (const node of ui.rows) {
      if (node !== ui.rows[ui.states.indexOf("run")] || !ui.breathe) {
        node.halo.style.setProperty("opacity", progressCardRest.halo);
        node.hl.style.setProperty("opacity", progressCardRest.hl);
      }
    }
    progressCardPulse(ui.breathe);
  };
  const progressTipShow = () => {
    const info = progressState.info;
    const segment = progressState.tipSegment;
    if (!progressState.tipOpen || segment == null || !info ||
        !progressState.box || progressBar.style.display === "none") { progressTipHide(); return; }
    const number = progressNumberAt(segment);
    const view = progressCardView(info, number, Date.now());
    if (!view) { progressTipHide(); return; }
    const frame = progressState.frame?.isConnected ? progressState.frame : null;
    let frameRect = null;
    try { frameRect = frame ? frame.getBoundingClientRect() : null; } catch {}
    if (frameRect && !(frameRect.width > 0)) frameRect = null;
    // Ширина — по полю ввода: не шире его и не шире 400, не ýже 240 и не шире
    // окна минус поля.
    const width = Math.round(Math.min(innerWidth - 12,
      Math.max(PROGRESS_CARD_MIN_WIDTH, Math.min(PROGRESS_CARD_MAX_WIDTH, frameRect?.width ?? PROGRESS_CARD_MAX_WIDTH))));
    const maxHeight = Math.round(innerHeight * 0.6);
    // Капсула номера — номер и вид номера в ряду (progressBadgePaint): у старой сводки с номерами по
    // проекту номер блока другой (view.number), но на экране один знак на объект — номер ряда.
    const T = progressTextColor(frame);
    const accent = progressAccent();
    const badge = PROGRESS_BADGE_OF[view.pill.tone] ?? "plan";
    const cap = { label: String(number), paint: progressBadgePaint(badge, {
      accent, text: T, light: !progressDark(), done: info.state === "done" ? PROGRESS_PAINT.done : accent,
    }) };
    const appearing = progressCardPaint(view, frame, width, maxHeight, cap);
    progressState.cardText = progressCardUI.text;
    progressState.cardFit = progressCardUI.fit;
    progressState.cardRows = progressCardUI.states;
    progressState.cardNote = progressCardUI.note;
    // Место — уже по показанной карточке: до показа высоты у неё нет. Над полем
    // ввода, по его левому краю (ТЗ 9.1, п. 3); поле растянуто до потолка —
    // по-старому, над рядом номеров.
    const rect = progressTip.getBoundingClientRect();
    const height = rect.height || 0;
    const left = Math.max(6, Math.min(frameRect ? frameRect.left : progressState.box.left, innerWidth - width - 6));
    let top = frameRect ? frameRect.top - height - 8 : -1;
    progressState.cardAnchor = "поле";
    if (top < 6) {
      top = Math.max(6, progressState.box.top - height - 8);
      progressState.cardAnchor = "номера";
    }
    progressTip.style.setProperty("left", `${Math.round(left)}px`);
    progressTip.style.setProperty("top", `${Math.round(top)}px`);
    // Обводка выбранного номера — текст 55 % с отступом 1 точка (ТЗ, п. 5).
    for (let index = 0; index < progressCells.length; index += 1) {
      progressCells[index].cell.style.setProperty("outline", index === segment ? `1.5px solid ${progressTint(T, 55)}` : "none");
    }
    progressState.cardBreathe = view.breathe;
    progressCardReveal(appearing);
    progressState.cardPulse = Boolean(progressCardUI.slots.dot.anim);
  };
  // Строка «когда» на открытой карточке считает минуты от часов, а перерисовка
  // приходит только с командой status — та едет лишь когда сводка изменилась
  // (StatusFeed шлёт по смене digest). Открытая карточка говорила бы «15 мин
  // назад» и через час. Поэтому пока карточка открыта — свой тик раз в минуту
  // (проверка WF70); закрылась — тика нет.
  const PROGRESS_TIP_TICK_MS = 60000;
  const progressTipTickStop = () => {
    if (progressState.tipTick) { clearInterval(progressState.tipTick); progressState.tipTick = 0; }
  };
  const progressTipTickStart = () => {
    if (progressState.tipTick) return;
    progressState.tipTick = setInterval(() => {
      if (!progressState.tipOpen) { progressTipTickStop(); return; }
      try { progressTipShow(); } catch {}
    }, PROGRESS_TIP_TICK_MS);
  };
  track(progressTipTickStop);
  // Закрыть = погасить: выбор снимает сам progressTipHide.
  const progressTipClose = () => { progressTipHide(); };
  // Клик по полосе: по тому же сегменту — закрыть, по другому — переключить.
  // Пустой контур (строки состояния нет) карточке рассказать нечего.
  const progressTipToggle = (segment) => {
    if (segment == null || !progressState.info) { progressTipClose(); return; }
    if (progressState.tipOpen && progressState.tipSegment === segment) { progressTipClose(); return; }
    progressState.tipSegment = segment;
    progressState.tipOpen = true;
    progressTipShow();
    progressTipTickStart();
  };
  // Попадание в открытую карточку. Своя проверка нужна потому, что узел
  // прозрачен для мыши (pointer-events:none, чтобы не съедать клики по полю
  // ввода под ним): без неё клик по самой карточке гасил бы её же.
  const progressCardHit = (x, y) => {
    if (!progressState.tipOpen || progressTip.style.display === "none") return false;
    try {
      const rect = progressTip.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) return false;
      return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
    } catch { return false; }
  };

  // ---- прокрутка ряда (WF85, #7356) ---------------------------------------
  // Хвост «… N» — свой fixed-узел рядом с рядом, а не его ребёнок: номера
  // считают детьми ряда клик, тесты и карточка, а ряд режет всё за окном
  // номеров. Узел — тот же, что у номера (шрифт, скругление, цвета по
  // состоянию номера N), прозрачен для мыши: клик по нему ловит progressHit.
  const progressTailItem = progressCell();
  const progressTail = progressTailItem.cell;
  progressTail.id = PROGRESS_TAIL_ID;
  progressTail.setAttribute("aria-hidden", "true");
  for (const [name, value] of Object.entries({
    position: "fixed", display: "none", left: "0px", top: "0px", "z-index": "2147483645",
    transition: PROGRESS_BADGE_TRANS,
  })) progressTail.style.setProperty(name, value);
  (document.body ?? document.documentElement).appendChild(progressTail);
  track(() => progressTail.remove());
  // Хвост гаснет, когда ряд доехал до конца (слот остаётся — ряд не прыгает),
  // и светится вместе с рядом на наведении.
  const progressTailShade = () => {
    if (!progressScroll.on) return;
    progressTail.style.setProperty("opacity", progressScroll.tail ? (progressState.hovering ? "1" : "0.85") : "0");
  };
  // Сдвиг номеров — translateX у каждого: сама коробка ряда стоит и режет.
  const progressScrollPaint = () => {
    const scroll = progressScroll;
    const shift = scroll.on && scroll.x !== 0 ? `translateX(${-Math.round(scroll.x * 100) / 100}px)` : "";
    for (const item of progressCells) {
      if (shift) item.cell.style.setProperty("transform", shift);
      else item.cell.style.removeProperty("transform");
    }
    scroll.tail = scroll.on && scroll.x < scroll.max - 1;
    progressTailShade();
  };
  const progressScrollClamp = value => Math.max(0, Math.min(progressScroll.max, value));
  // Кадр: x догоняет цель долей 0,22, ближе полуточки — встаёт на неё.
  const progressScrollFrame = () => {
    const scroll = progressScroll;
    scroll.raf = 0;
    if (!scroll.on) return;
    const diff = scroll.target - scroll.x;
    scroll.x = Math.abs(diff) < 0.5 ? scroll.target : scroll.x + diff * PROGRESS_SCROLL_EASE;
    progressScrollPaint();
    if (scroll.x !== scroll.target) scroll.raf = requestAnimationFrame(progressScrollFrame);
  };
  // «Поменьше движения» и скрытое окно — сразу на место, без кадров.
  const progressScrollRun = () => {
    const scroll = progressScroll;
    if (!scroll.on) return;
    if (!progressMotionOk()) {
      if (scroll.raf) { cancelAnimationFrame(scroll.raf); scroll.raf = 0; }
      scroll.x = scroll.target;
      progressScrollPaint();
      return;
    }
    if (!scroll.raf) scroll.raf = requestAnimationFrame(progressScrollFrame);
  };
  // Колесо за краем: цель переводим обратно в «сырой» путь колеса, прибавляем
  // сдвиг и снова сжимаем всё, что за краем, — так переход через край ровный.
  const progressScrollPush = (target, delta) => {
    const max = progressScroll.max;
    const k = PROGRESS_SCROLL_RESIST;
    const raw = target < 0 ? target / k : (target > max ? max + (target - max) / k : target);
    const next = raw + delta;
    if (next < 0) return Math.max(-PROGRESS_SCROLL_OVER, next * k);
    if (next > max) return Math.min(max + PROGRESS_SCROLL_OVER, max + (next - max) * k);
    return next;
  };
  const onProgressWheel = (event) => {
    const scroll = progressScroll;
    if (!scroll.on || !progressHit(event.clientX, event.clientY)) return;
    event.preventDefault();
    event.stopPropagation();
    const dx = Number(event.deltaX) || 0;
    const dy = Number(event.deltaY) || 0;
    let delta = Math.abs(dx) > Math.abs(dy) ? dx : dy;
    if (event.deltaMode === 1) delta *= PROGRESS_SCROLL_LINE;
    else if (event.deltaMode === 2) delta *= Math.max(1, (scroll.view?.right ?? 0) - (scroll.view?.left ?? 0));
    if (delta === 0) return;
    // Карточка стоит на месте, номера уезжают из-под неё — закрываем (критик WF85).
    if (progressState.tipOpen) progressTipClose();
    scroll.user = true;
    scroll.wheelAt = Date.now();
    scroll.target = progressScrollPush(scroll.target, delta);
    if (scroll.spring) clearTimeout(scroll.spring);
    scroll.spring = setTimeout(() => {
      scroll.spring = 0;
      scroll.target = progressScrollClamp(scroll.target);
      progressScrollRun();
    }, PROGRESS_SCROLL_SPRING_MS);
    progressScrollRun();
  };
  // Не-пассивный wheel на документе отнимает у Chromium быструю прокрутку ленты
  // на потоке композитора (критик WF85, В6) — слушатель висит ТОЛЬКО в режиме
  // прокрутки.
  const progressWheel = (want) => {
    if (want === progressScroll.wheel) return;
    progressScroll.wheel = want;
    if (want) document.addEventListener("wheel", onProgressWheel, { capture: true, passive: false });
    else document.removeEventListener("wheel", onProgressWheel, { capture: true });
  };
  const progressScrollOff = () => {
    const scroll = progressScroll;
    if (scroll.raf) { cancelAnimationFrame(scroll.raf); scroll.raf = 0; }
    if (scroll.spring) { clearTimeout(scroll.spring); scroll.spring = 0; }
    progressWheel(false);
    const was = scroll.on;
    Object.assign(scroll, { on: false, x: 0, target: 0, max: 0, view: null, tail: false, user: false, wheelAt: 0, key: null });
    if (progressTail.style.display !== "none") progressTail.style.setProperty("display", "none");
    if (was) progressScrollPaint();
  };
  track(progressScrollOff);
  // Клик по хвосту — плавно к концу ряда.
  const progressScrollEnd = () => {
    if (progressState.tipOpen) progressTipClose();
    progressScroll.user = false;
    progressScroll.target = progressScroll.max;
    progressScrollRun();
  };
  // Своё место: номер текущего воркфлоу (с соседями, если влезают) в окне —
  // при появлении ряда, смене номера, окна или числа номеров. Было колесо
  // меньше 8 с назад — не вмешиваемся; «своё место» догонит на следующем проходе.
  const progressScrollOwn = (items, gap, view, wf, instant) => {
    const scroll = progressScroll;
    const key = `${wf}|${view}|${items.length}`;
    if (!instant && scroll.key === key) return;
    if (!instant && Date.now() - scroll.wheelAt < PROGRESS_SCROLL_HOLD_MS) return;
    scroll.key = key;
    const current = items.findIndex(item => wf >= item.first && wf <= item.last);
    if (current < 0) return;
    const starts = [];
    let left = 0;
    for (const item of items) { starts.push(left); left += progressBadgeWidth(item.label) + gap; }
    const span = (from, to) => [starts[from], starts[to] + progressBadgeWidth(items[to].label)];
    let [a, b] = span(Math.max(0, current - 1), Math.min(items.length - 1, current + 1));
    if (b - a > view) [a, b] = span(current, current);
    let target = progressScrollClamp(scroll.target);
    if (a < target) target = a;
    else if (b > target + view) target = b - view;
    scroll.target = progressScrollClamp(target);
    scroll.user = false;
    if (instant) {
      if (scroll.raf) { cancelAnimationFrame(scroll.raf); scroll.raf = 0; }
      scroll.x = scroll.target;
    } else progressScrollRun();
  };

  const progressHide = () => {
    progressScrollOff();
    progressState.box = null;
    progressState.anchor = null;
    progressState.badges = [];
    progressState.segments = [];
    // Ряд ушёл с экрана (меню накрыло его, окно уехало) — дышать нечему.
    for (const item of progressCells) {
      item.pulse = false;
      progressPulse(item, item.line, false, PROGRESS_LINE_FRAMES, "1");
    }
    // Полосы нет — не о чем и подсказке: держать её открытой над пустым местом
    // (меню накрыло линию, окно уехало) не за что.
    progressTipClose();
    if (progressBar.style.display !== "none") progressBar.style.setProperty("display", "none");
  };

  // ---- место под ряд номеров (#7105, WF84) ---------------------------------
  // Рамка поля растёт вниз ровно на ряд номеров. Не своим узлом
  // внутри рамки — её дерево пересобирает React, и чужой узел там лишний риск
  // (довод раздела 4), — а её же нижним полем: инлайном и с important, как
  // всё наше на чужих узлах (CSP может не пустить таблицу, раздел 4). Поле, а
  // не прозрачная граница: обводку рамки Claude рисует тенью ВНУТРЬ (inset,
  // замер 23.09), и граница вынесла бы низ рамки за её же обводку. Своё поле
  // Claude (8 точек, класс py-2) читаем ДО нашей правки и только дополняем до
  // нужного: меньше, чем было у Claude, не ставим никогда.
  const progressRoomClear = () => {
    const node = progressState.roomNode;
    progressState.roomNode = null;
    progressState.roomBase = 0;
    progressState.room = 0;
    if (!node) return;
    try {
      node.style.removeProperty("padding-bottom");
      node.style.removeProperty(PROGRESS_ROOM_VARIABLE);
      node.removeAttribute(PROGRESS_ROOM_ATTRIBUTE);
    } catch {}
  };
  track(progressRoomClear);
  // room — сколько точек добавить к СВОЕМУ нижнему полю рамки (WF84: 18 без
  // вложений, 20 с ними); рамки нет или 0 — вернуть рамке её собственное.
  // Ответ — поменялась ли геометрия рамки.
  const progressRoomSet = (node, room) => {
    let base = 0;
    if (node && room > 0) {
      if (progressState.roomNode === node) base = progressState.roomBase;
      else { try { base = parseFloat(getComputedStyle(node).paddingBottom) || 0; } catch {} }
    }
    const extra = node && room > 0 ? Math.max(0, Math.round(room)) : 0;
    const target = extra > 0 ? node : null;
    const value = `${base + extra}px`;
    if (progressState.roomNode === target && (!target || (progressState.room === extra &&
        target.style.getPropertyValue("padding-bottom") === value))) return false;
    // Лента за полем не следит (#5869, раздел 10): место под капсулы поле
    // отнимает у неё снизу, и последние строки уехали бы под поле. Стояла
    // лента внизу — вернём вниз, как на смене ступени.
    let tail = null;
    let down = false;
    try { tail = tailScroller(); down = tailAtBottom(tail); } catch {}
    if (progressState.roomNode !== target) progressRoomClear();
    if (target) {
      target.style.setProperty("padding-bottom", value, "important");
      // Добавку — ещё и переменной: по ней широкий вид поднимает кнопку
      // отправки над рядом (layoutCss, раздел 2а).
      target.style.setProperty(PROGRESS_ROOM_VARIABLE, `${extra}px`);
      if (!target.hasAttribute(PROGRESS_ROOM_ATTRIBUTE)) target.setAttribute(PROGRESS_ROOM_ATTRIBUTE, "");
      progressState.roomNode = target;
      progressState.roomBase = base;
      progressState.room = extra;
    }
    if (down && tail?.isConnected) { try { tail.scrollTop = tail.scrollHeight; } catch {} }
    return true;
  };

  // Плитки вложений в поле: над номерами тогда воздух 8, а не 6 (#7189).
  // Один запрос на проход (раскладка зовёт ряд до четырёх раз в секунду) —
  // по блоку ввода: плитки живут в коробке поля, а она внутри блока.
  const progressHasTiles = (frame) => {
    const box = state.composerBlock?.isConnected ? state.composerBlock : frame;
    try { return Boolean(box?.querySelector?.(PROGRESS_TILES_SELECTOR)); } catch { return false; }
  };
  // Цвета номера (ТЗ, п. 3) — от темы, не константы: A — акцент, T — цвет
  // текста поля, жёлтый и красный — PROGRESS_PAINT. Готовые в идущем марафоне
  // — акцентом; весь марафон «готово ✅» — зелёным (буква Элвиса 1A: готово —
  // сигнал продолжать). Светлая тема: жёлтый плотнее, красный бледнее, а его
  // цифра — тёмно-красная (белая на светлом пропала бы).
  const progressBadgePaint = (state, { accent, text, light, done }) => {
    const tint = progressTint;
    switch (state) {
      case "done": return { background: tint(done, 30), "box-shadow": "none", color: tint(text, 72) };
      case "run": return { background: "transparent", "box-shadow": `inset 0 0 0 1px ${tint(accent, 85)}`, color: accent };
      case "wait": return { background: tint(PROGRESS_PAINT.wait, light ? 75 : 48), "box-shadow": "none", color: tint(text, 92) };
      case "fail": return {
        background: tint(PROGRESS_PAINT.fail, light ? 30 : 52), "box-shadow": "none",
        color: light ? "rgb(150,20,20)" : tint(text, 95),
      };
      default: return { background: "transparent", "box-shadow": `inset 0 0 0 1px ${tint(text, 22)}`, color: tint(text, 42) };
    }
  };

  // Одно место решает и про причину, и про видимость: иначе status().progress
  // рассказывал бы одно, а окно показывало другое. Ряда нет совсем (рамки нет,
  // поле свёрнуто) — рамка получает своё поле назад; ряд лишь спрятался под
  // открытым меню — место остаётся, иначе поле прыгало бы с каждым меню.
  const progressOff = (reason) => {
    progressState.reason = reason;
    progressRoomSet(null, 0);
    progressHide();
  };
  const progressApply = () => {
    const block = state.composerBlock?.isConnected ? state.composerBlock : null;
    if (!block) { progressOff("нет блока композера"); return; }
    // Якорь основной — рамка поля: ряд живёт в её нижнем поле. Запасной — верх
    // строки инструментов (там полоса стояла до WF9): рамки может не оказаться
    // вовсе (чужая разметка) или она вырождается на кадр, пока React
    // пересобирает низ окна. Лучше на пару точек ниже, чем пропасть.
    const frame = progressFrame(block);
    let frameRect = frame?.isConnected ? frame.getBoundingClientRect() : null;
    const onFrame = frameRect != null && frameRect.width >= PROGRESS_MIN_WIDTH;
    const rowRect = onFrame || !state.modelRow?.isConnected
      ? null
      : state.modelRow.getBoundingClientRect();
    const rect = onFrame ? frameRect : rowRect;
    if (!rect) { progressOff("нет рамки поля"); return; }
    const info = progressState.info;
    if (rect.width < PROGRESS_MIN_WIDTH || rect.bottom <= 0 || rect.top >= innerHeight) {
      progressOff("рамка поля вне окна");
      return;
    }
    // Свёрнутое поле — режим чтения (#6651, слово Элвиса 20.09: «всё скрывай,
    // даже полоску внизу, чтобы оставалась одна полосочка»): ряда нет вовсе.
    if (state.stage === STAGE_COLLAPSED) { progressOff("поле свёрнуто — режим чтения"); return; }
    // Строки состояния нет или в ней нет воркфлоу — ряда нет (#7188, слово
    // Элвиса 23.09: выводить её незачем).
    if (!info) { progressOff("нет строки состояния"); return; }
    // Место под ряд — нижним полем рамки: 18 точек, с плитками вложений 20
    // (воздух 6 и 8 над номером в 12). Рамка выросла — мерим её заново.
    const tiles = onFrame && progressHasTiles(frame);
    if (progressRoomSet(onFrame ? frame : null, tiles ? PROGRESS_ROOM_TILES : PROGRESS_ROOM_TEXT) && onFrame) {
      frameRect = frame.getBoundingClientRect();
    }
    // Слева — по левому краю ТЕКСТА поля (макет 7), справа — столько же от
    // правого края рамки. Край текста — редактор; он чужой или вне рамки —
    // отступ по скруглению рамки, как у ручки.
    let left = Math.round(rect.left);
    let width = Math.round(rect.width);
    if (onFrame) {
      let textLeft = null;
      try {
        const node = state.editor?.isConnected ? state.editor : (state.editorRoot?.isConnected ? state.editorRoot : null);
        const box = node ? node.getBoundingClientRect() : null;
        if (box && box.width > 0 && box.left >= frameRect.left && box.left < frameRect.left + frameRect.width / 2) textLeft = box.left;
      } catch {}
      const inset = textLeft == null ? handleInset(progressState.frame ?? state.shell) : textLeft - frameRect.left;
      left = Math.round(frameRect.left + inset);
      width = Math.max(0, Math.round(frameRect.width - inset * 2));
    }
    const { items, gap, blocks } = progressBadges(info, width);
    // Номер садится над СВОИМ полем рамки Claude (у низа рамки остаётся её
    // родное поле, 8 точек): от текста до номера — наша добавка минус номер.
    // На запасном якоре — над кромкой строки инструментов.
    const top = onFrame
      ? Math.round(frameRect.top + frameRect.height - progressState.roomBase - PROGRESS_BADGE_HEIGHT)
      : Math.round(rect.top) - PROGRESS_BADGE_HEIGHT - 1;
    if (progressCovered(top, top + PROGRESS_BADGE_HEIGHT, left, left + width)) {
      progressState.reason = "полосу закрыло меню";
      progressHide();
      return;
    }
    progressState.reason = null;
    progressState.anchor = onFrame ? "рамка" : "строка инструментов";
    progressState.badges = items;
    progressState.segments = items.map(item => item.share);
    progressState.gap = gap;
    progressState.blocks = blocks;
    // Ряд сейчас спрятан — значит это его появление: ни первый показ при
    // открытии окна, ни возврат из-под закрывшегося меню анимировать нечего,
    // всё пишется сразу набело.
    const instant = progressBar.style.display !== "flex";
    progressBuild(items.length);
    const colors = {
      accent: progressAccent(), text: progressTextColor(onFrame ? frame : null), light: !progressDark(),
    };
    colors.done = info.state === "done" ? PROGRESS_PAINT.done : colors.accent;
    // Узлы, которым этот проход пишется без переходов: свежерождённые и все
    // подряд на появлении ряда. Переходы им вернём одним махом ниже.
    const quiet = [];
    for (let index = 0; index < items.length; index += 1) {
      const item = progressCells[index];
      const badge = items[index];
      if (instant || item.born) {
        item.cell.style.setProperty("transition", "none");
        quiet.push(item);
      }
      for (const [name, value] of Object.entries(progressBadgePaint(badge.state, colors))) {
        item.cell.style.setProperty(name, value);
      }
      item.cell.style.setProperty("width", `${progressBadgeWidth(badge.label)}px`);
      if (item.num.textContent !== badge.label) item.num.textContent = badge.label;
      // Линия шагов идущего: 2 точки у нижнего края, ширина — доля шагов (не
      // меньше PROGRESS_MIN_FILL), дышит 0,45 → 1 в общий такт 3,6 с.
      const running = badge.state === "run";
      item.line.style.setProperty("display", running ? "block" : "none");
      item.line.style.setProperty("background", colors.accent);
      item.line.style.setProperty("width", `${running ? Math.max(PROGRESS_MIN_FILL, badge.share) : 0}%`);
      item.pulse = running;
      progressPulse(item, item.line, item.pulse, PROGRESS_LINE_FRAMES, "1");
      if (!progressState.tipOpen || progressState.tipSegment !== index) item.cell.style.setProperty("outline", "none");
      if (instant) item.cell.style.setProperty("opacity", "1");
    }
    if (quiet.length > 0) {
      // Принудительная раскладка одна на весь проход: без неё браузер сведёт обе
      // записи стиля в один пересчёт и проиграет движение от старых значений.
      try { progressBar.getBoundingClientRect(); } catch {}
      for (const item of quiet) {
        item.born = false;
        item.cell.style.setProperty("transition", PROGRESS_BADGE_TRANS);
        // Новый номер проявляется за 200 мс; на появлении ряда он всплыл выше.
        item.cell.style.setProperty("opacity", "1");
      }
    }
    // Не влезли и после слияния (WF85, #7356) — режим прокрутки: ряд режет
    // окно номеров, справа слот хвоста «… N» (U+2026, узкий неразрывный
    // пробел, последний номер; вид — состояние номера N).
    let view = width;
    const need = progressRowNeed(items, gap);
    if (need > width && items.length > 1) {
      const last = items[items.length - 1];
      const tailLabel = `…\u202F${last.last}`;
      const tailWidth = progressBadgeWidth(tailLabel);
      view = Math.max(0, width - tailWidth - gap - PROGRESS_SCROLL_CLIP);
      const entering = instant || !progressScroll.on;
      progressScroll.on = true;
      progressScroll.max = Math.max(0, need - view);
      progressScroll.view = { left, right: left + view };
      progressWheel(true);
      for (const [name, value] of Object.entries(progressBadgePaint(last.state, colors))) {
        progressTail.style.setProperty(name, value);
      }
      if (progressTailItem.num.textContent !== tailLabel) progressTailItem.num.textContent = tailLabel;
      progressTail.style.setProperty("width", `${tailWidth}px`);
      progressTail.style.setProperty("left", `${left + width - tailWidth}px`);
      progressTail.style.setProperty("top", `${top}px`);
      progressTail.style.setProperty("display", "block");
      progressScrollOwn(items, gap, view, info.wf, entering);
      // Окно сузилось или номеров стало меньше — сдвиг обратно в границы; пока
      // пружина не отпустила колесо, за краем стоять можно.
      if (!progressScroll.spring) {
        progressScroll.target = progressScrollClamp(progressScroll.target);
        if (progressScroll.x !== progressScrollClamp(progressScroll.x)) progressScrollRun();
      }
      progressScrollPaint();
    } else if (progressScroll.on) progressScrollOff();
    progressBar.style.setProperty("left", `${left}px`);
    progressBar.style.setProperty("top", `${top}px`);
    progressBar.style.setProperty("width", `${view}px`);
    progressBar.style.setProperty("gap", `${gap}px`);
    progressBar.style.setProperty("opacity", progressState.hovering ? "1" : "0.85");
    const label = progressAria(items);
    if (progressBar.getAttribute("aria-label") !== label) progressBar.setAttribute("aria-label", label);
    const title = `Воркфлоу ${info.wf} из ${info.of}` + (info.pct == null ? "" : ` · ${info.pct} %`);
    // Указателя ряд не ловит, и родной title на нём не покажется — он остаётся
    // для разбора окна (probe на гейте).
    if (progressBar.title !== title) progressBar.title = title;
    progressBar.style.setProperty("display", "flex");
    progressState.box = { left, right: left + width, top, bottom: top + PROGRESS_BADGE_HEIGHT };
    if (progressState.tipOpen) progressTipShow();
  };
  // Раскладку ручки полоса не имеет права уронить: её зовут из чужого кода.
  const placeProgress = () => { try { progressApply(); } catch {} };

  // Попадание по ряду (WF84, ТЗ п. 5): номера и ±4 точки по вертикали, по
  // горизонтали — весь ряд: клик по номеру открывает его карточку, клик по
  // пустому месту ряда — карточку текущего воркфлоу (progressSegmentAt).
  const progressHit = (x, y) => {
    const box = progressState.box;
    // Пустой контур (строки состояния нет) — только украшение: мышь не ловит,
    // клик под ним доходит до страницы (проверка WF22).
    if (!progressState.info) return false;
    if (!box || progressBar.style.display === "none") return false;
    if (y < box.top - PROGRESS_HIT_SLACK || y > box.bottom + PROGRESS_HIT_SLACK) return false;
    if (x < box.left || x > box.right) return false;
    // Меню, список или окно Claude над полосой сильнее неё (WF144, класс «наши слои уступают
    // меню», WF136 п.7): полоса прячется только на проходе раскладки и с другим запасом,
    // а нажатие по пункту, съеденное здесь на захвате, закрывало меню.
    try { if (document.elementFromPoint(x, y)?.closest?.(OVERLAY_SELECTOR)) return false; } catch {}
    // Ручка сильнее полосы: кликом по ней возвращают свёрнутое поле, и не уступи
    // мы здесь, вернуть его стало бы нечем — наш обработчик глушит клик на
    // захвате, до самой ручки. С 12.09 линии разведены (ручка на кромке строки
    // модели, полоса на низе блока), но уступка остаётся: их разводит
    // геометрия, а она у Claude меняется без предупреждения.
    // Дубли у краёв окна (#6743) стоят там же, где полоса на свёрнутом поле, и
    // уступка им нужна ровно по той же причине, что и ручке.
    try {
      for (const node of [handle, superTop, superBottom]) {
        if (node.style.display === "none") continue;
        const rect = node.getBoundingClientRect();
        if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) return false;
      }
    } catch {}
    return true;
  };
  // Курсор — единственное, что даёт наведение (план WF12, п. 3): подсказка
  // открывается кликом. Полоса ничего не ловит мышью (pointer-events:none), и
  // своего курсора у неё быть не может, поэтому «руку» ставим корню документа и
  // снимаем ровно её же — чужой курсор (перетаскивание ручки) не трогаем.
  const progressCursor = (hand) => {
    try {
      const root = document.documentElement;
      if (hand) { if (root.style.cursor !== "pointer") root.style.cursor = "pointer"; }
      else if (root.style.cursor === "pointer") root.style.cursor = "";
    } catch {}
  };
  track(() => progressCursor(false));
  const onProgressMove = (event) => {
    // Над карточкой «руку» не ставим: кликать по ней нечего, а линия под ней
    // может оказаться на том же месте у самого края окна.
    const inside = !state.dragging && !progressCardHit(event.clientX, event.clientY) &&
      progressHit(event.clientX, event.clientY);
    if (inside === progressState.hovering) return;
    progressState.hovering = inside;
    progressCursor(inside);
    // Наведение на ряд — во всю силу (ТЗ WF84, п. 5).
    progressBar.style.setProperty("opacity", inside ? "1" : "0.85");
    progressTailShade();
  };
  on(document, "mousemove", onProgressMove, { passive: true, capture: true });
  // Клик по полосе. Ловим на ЗАХВАТЕ и только внутри линии: там событие наше
  // целиком (preventDefault + stopPropagation), и полю ввода под ней оно не
  // достаётся. Мимо линии — не трогаем событие вовсе, только закрываем подсказку.
  const onProgressDown = (event) => {
    // Попадание в карточку проверяем ДО закрытия: она прозрачна для мыши, и без
    // этой проверки любой клик по ней самой её же и гасил бы. Событие при этом
    // не трогаем — под карточкой живёт лента, и выделять в ней текст Элвису
    // никто не мешает.
    if (progressCardHit(event.clientX, event.clientY)) return;
    if (!progressHit(event.clientX, event.clientY)) { progressTipClose(); return; }
    event.preventDefault();
    event.stopPropagation();
    // Правее окна номеров — хвост «… N» (WF85): плавно к концу ряда.
    if (progressScroll.on && event.clientX > (progressScroll.view?.right ?? Infinity)) {
      try { progressScrollEnd(); } catch {}
      return;
    }
    try { progressTipToggle(progressSegmentAt(event.clientX)); } catch {}
  };
  on(document, "pointerdown", onProgressDown, { capture: true });
  // Escape закрывает подсказку. Слушатель свой, а не ветка в разделе 16: там
  // Escape ГЛОТАЕТСЯ насовсем, и подсказка обязана закрыться раньше. Этот
  // слушатель встаёт первым (раздел 2б идёт по файлу выше) и потому успевает.
  const onProgressKey = (event) => {
    if (event.key === "Escape" && progressState.tipOpen) progressTipClose();
  };
  on(window, "keydown", onProgressKey, { capture: true });
  // Указатель ушёл из окна — движений больше не будет, и «рука» осталась бы
  // висеть. То же на потере фокуса окном. Подсказку это не закрывает: её
  // открыли кликом, и родное меню приложения как раз отнимает фокус.
  const onProgressLeave = () => {
    if (!progressState.hovering) return;
    progressState.hovering = false;
    progressCursor(false);
    progressBar.style.setProperty("opacity", "0.85");
    progressTailShade();
  };
  on(document, "mouseleave", onProgressLeave, { passive: true });
  on(window, "blur", onProgressLeave, { passive: true });

  // Идём от последнего ответа к более старым и останавливаемся на первом, где
  // строка нашлась: это и есть «последняя по ленте».
  // Слово строки состояния последнего ответа («жду», «упал»…), и без «WF N из M» (#8282).
  let progressTailWord = null;
  const progressRead = () => {
    progressTailWord = null;
    // Сторожа «чат пустой» здесь нет намеренно (#5855): приметы разговора
    // (CHAT_STARTED_SELECTOR, isFreshChat) в главном окне с десятью ответами на
    // экране дают НОЛЬ — «Message actions» живёт только под мышью (замер 12.09
    // 17:51). Чужое из окна отсекает не он, а панель разговора в запасном пути.
    // Те же приметы ответа, что у «Обкэшить» (ANSWER_SELECTOR + answerUsable): разметка
    // claude.ai и окна Claude Code разная, свой узкий селектор в 1.40609.1 не находил ничего.
    let nodes = [];
    try {
      // Плюс строки виртуальной ленты Claude Code: у ответа с шагами инструментов
      // aria-label «Message N» достаётся строке шагов, а итоговый текст (со строкой
      // состояния) лежит отдельной строкой без приметы (замер 04.09 21:00).
      const all = [...document.querySelectorAll(`${ANSWER_SELECTOR},[data-testid="transcript-row"]`)]
        .filter(answerUsable);
      nodes = all.filter(node => !all.some(other => other !== node && other.contains(node)));
    } catch {}
    const stop = Math.max(0, nodes.length - PROGRESS_LOOKBACK);
    for (let index = nodes.length - 1; index >= stop; index -= 1) {
      const node = nodes[index];
      if (!node?.isConnected) continue;
      // Черновик в поле ввода ответом не считается: там Элвис вполне может
      // держать недописанную строку состояния.
      if (state.composerBlock?.contains(node)) continue;
      const scan = progressScan(node.innerText ?? node.textContent ?? "");
      if (scan.info || scan.stop) { progressTailWord = scan.info?.state ?? scan.word ?? null; return scan.info; }
    }
    // Примет хватило (не меньше PROGRESS_LOOKBACK ответов), а строки в последних нет — её и нет. Запасной
    // путь здесь читал innerText всей панели в каждом таком чате (до раза в секунду) и показывал ряд из
    // ответа старше PROGRESS_LOOKBACK (ревизия WF247).
    if (nodes.length >= PROGRESS_LOOKBACK) return null;
    // Запасной путь: в окнах «Open in new window» приметы ответа почти не совпадают
    // (проверено 04.09: 0–3 узла на сотню сообщений, лента виртуальная). Тогда читаем
    // текст ПАНЕЛИ РАЗГОВОРА без черновика в поле ввода — в нём строка состояния есть.
    //
    // Панели, а не всего окна (#5855): в текст body попадает сайдбар с ЧУЖИМИ чатами и
    // наша же карточка подсказки со строками сводки — чат без своей строки состояния брал
    // этот текст за свой. Замер 12.09 17:47: панель есть во всех окнах Claude Code
    // (главном и вынесенных), поле ввода, сайдбар и наши слои лежат ВНЕ её.
    //
    // Панели нет вовсе — значит и разговора нет (домашний экран после ⌘N): читать нечего,
    // и полоска остаётся пустым контуром. Прежнее падение на body делало ровно то, от чего
    // затевалась правка (находка проверяющего 12.09): «новый чат» Элвиса — это и есть
    // домашний экран, где панели не бывает.
    //
    // Селекторов два, и в живом окне они попадают в ДВА ВЛОЖЕННЫХ узла одной и той же
    // панели (замер 12.09 18:30: .epitaxy-chat-panel-body и лента внутри неё) — поэтому
    // сперва оставляем только внешние. Их больше одной — окно разделено на два чата, и
    // своя панель та, что стоит над нашим полем ввода: первая по документу показывала бы
    // чужой чат всему окну.
    try {
      const found = [...document.querySelectorAll('.epitaxy-chat-panel-body,[data-testid="epitaxy-virtual-transcript"]')];
      const panels = found.filter(node => !found.some(other => other !== node && other.contains(node)));
      let panel = panels[0] ?? null;
      const box = state.composerBlock?.isConnected ? state.composerBlock.getBoundingClientRect() : null;
      if (panels.length > 1 && box) {
        let best = -Infinity;
        for (const node of panels) {
          const rect = node.getBoundingClientRect();
          const share = Math.min(rect.right, box.right) - Math.max(rect.left, box.left);
          if (share > best) { best = share; panel = node; }
        }
      }
      if (panel == null) return null;
      let text = panel.innerText ?? "";
      const draft = (state.composerBlock?.innerText ?? "").trim();
      if (draft && text.endsWith(draft)) text = text.slice(0, -draft.length);
      else if (draft) text = text.replace(draft, "");
      const scan = progressScan(text);
      progressTailWord = scan.info?.state ?? scan.word ?? null;
      return scan.info;
    } catch { return null; }
  };

  // «Замереть у низа» (WF84, ТЗ п. 2; слово Элвиса 23.09: «при прокручивании
  // чата вверх-вниз это поле не менялось… показывалось реально, что сейчас
  // происходит»). Лента виртуальная: прокрутил вверх — последних ответов в DOM
  // нет, и «последней» становилась старая строка. Поэтому строку читаем только
  // у низа ленты; ленты нет (домашний экран, чужая разметка) — читаем как
  // раньше. Ответ: true — у низа, false — не у низа, null — ленты нет.
  const progressAtBottom = () => {
    const tail = tailScroller();
    if (!tail?.isConnected) return null;
    return Number(tail.scrollHeight) - Number(tail.clientHeight) - Number(tail.scrollTop) <= PROGRESS_TAIL_SLACK;
  };
  // Ключ чата для запомненной строки: id чата, у окна без него — ключ окна.
  // Не sessionKey() сам по себе: у главного окна он один на все чаты («main»), и
  // смена чата в окне была бы незаметна.
  const progressKey = () => {
    try { return chatKey() ?? sessionKey() ?? "окно"; } catch { return "окно"; }
  };
  const progressRemember = (key, info) => {
    const map = progressState.lastByKey;
    map.delete(key);
    map.set(key, { info, at: Date.now() });
    while (map.size > PROGRESS_KEYS_MAX) map.delete(map.keys().next().value);
  };
  const progressRefresh = () => {
    if (!state.alive || !state.watching) return;
    progressState.at = now();
    progressState.runs += 1;
    const key = progressKey();
    let bottom = null;
    try { bottom = progressAtBottom(); } catch {}
    progressState.atBottom = bottom !== false;
    if (bottom === false) {
      // Лента не у низа — чтения НЕТ, ряд стоит. Сменился чат в окне — берём
      // запомненное для ЭТОГО чата; нет его — ряда нет (не строка прежнего).
      progressState.frozen = true;
      if (key !== progressState.key) {
        progressState.info = progressState.lastByKey.get(key)?.info ?? null;
        progressState.key = key;
      }
      progressState.source = progressState.info ? "запомнено" : "нет";
    } else {
      progressState.frozen = false;
      progressState.info = progressRead();
      progressState.key = key;
      progressRemember(key, progressState.info);
      progressState.source = progressState.info ? "низ ленты" : "нет";
    }
    progressApply();
  };
  // Троттлинг откладыванием, а не пропуском: последняя мутация ленты — как раз
  // та, что дописала строку состояния, и терять её нельзя.
  const progressSchedule = () => {
    if (progressState.timer || !state.alive || !state.watching) return;
    const wait = Math.max(0, PROGRESS_MIN_GAP - (now() - progressState.at));
    if (wait === 0) { progressRefresh(); return; }
    progressState.timer = setTimeout(() => {
      progressState.timer = 0;
      try { progressRefresh(); } catch {}
    }, wait);
  };
  track(() => { if (progressState.timer) { clearTimeout(progressState.timer); progressState.timer = 0; } });
  // Тихое окно мутаций не даёт вовсе (чат открыт и не двигается), поэтому сверх
  // тика ленты — редкий страховочный перечёт.
  progressState.pulse = setInterval(() => { try { progressRefresh(); } catch {} }, PROGRESS_IDLE_MS);
  track(() => { clearInterval(progressState.pulse); progressState.pulse = 0; });
  // Полоса прогресса воркфлоу (раздел 2б): что вычитано из строки состояния
  // последнего ответа и почему полосы нет (или почему она пустым контуром). total — доля всего
  // марафона в процентах, pct — процент текущего воркфлоу, segments — доли
  // нарисованных сегментов слева направо (в узком окне их сливают в один).
  statusPart("progress", () => ({
    wf: progressState.info?.wf ?? null,
    of: progressState.info?.of ?? null,
    pct: progressState.info?.pct ?? null,
    total: progressState.info?.total ?? null,
    state: progressState.info?.state ?? null,
    segments: progressState.segments.slice(),
    // Мелкие номера (WF84, #7204): номер (слитый — строкой «1–9»), его
    // состояние (done | run | wait | fail | plan) и доля шагов.
    badges: progressState.badges.map(item => ({ n: item.n, state: item.state, share: item.share })),
    // Откуда строка на экране: "низ ленты" | "запомнено" | "нет"; frozen —
    // лента не у низа и ряд стоит; atBottom — лента у низа (или её нет);
    // blocks — сводка принята сверкой номеров 1…M.
    source: progressState.source,
    frozen: progressState.frozen,
    atBottom: progressState.atBottom,
    blocks: progressState.blocks,
    // Сколько точек нижнего поля рамка отдала под ряд сверх своего (18, с
    // плитками вложений 20).
    room: progressState.room,
    // На чём сидит ряд: "рамка" или запасное "строка инструментов".
    anchor: progressState.anchor,
    reason: progressState.reason,
    // Прокрутка ряда (WF85, #7356): сдвиг номеров и его предел в точках,
    // виден ли хвост «… N», был ли последний сдвиг от колеса. Вне режима
    // прокрутки — {x:0, max:0, tail:false, user:false}.
    scroll: {
      x: Math.round(progressScroll.x), max: Math.round(progressScroll.max),
      tail: progressScroll.tail, user: progressScroll.user,
    },
    // Карточка (WF84, 9.1): какой номер открыт кликом (порядок в ряду, с
    // нуля), открыта ли, дышит ли, её слепок через « · »
    // (последней — строка «когда», WF70; тикает с часами, на гейте сверять
    // по краям), состояния строк этапов, строка «сейчас» и на что она
    // встала — "поле" или "номера".
    tip: {
      segment: progressState.tipSegment, open: progressState.tipOpen,
      pulse: progressState.cardPulse,
      card: progressState.tipOpen ? (progressState.cardText || null) : null,
      rows: progressState.tipOpen ? progressState.cardRows.slice() : [],
      note: progressState.tipOpen ? progressState.cardNote : null,
      anchor: progressState.tipOpen ? progressState.cardAnchor : null,
    },
  }));
  // Сводка проектов из команды status: имя проекта, взятое из строки
  // состояния этого чата. at и projects — для гейта: видно, дошла ли
  // команда и под какими именами.
  statusPart("statusFeed", () => ({
    project: progressState.info?.project ?? null,
    at: statusFeed.at,
    projects: [...statusFeed.projects.keys()],
  }));
  HATCH && Object.assign(HATCH, { parseProgressText, progressScan, progressBadges, progressBadgeStates,
    progressBadgeWidth, progressFill, progressWhen, progressInk, progressCardData, statusBlocks, statusParse,
    statusHeadState, statusLineNumber, statusKey, statusFeedProject, progressState, progressRefresh });

  // ---- 2в. Живые цвета ----------------------------------------------------
  // Окна плавно едут по цветовому кругу. Приложение шлёт ОДНУ команду
  // live-colors на все окна разом, дальше каждое окно считает свой цвет само.
  // Крутить цвет командами из Swift нельзя: канал (command.json) держит зазор
  // 0,6 с между записями, а лоадер раз в 500 мс берёт из файла только ПОСЛЕДНЮЮ
  // запись — на «плавненько» этого не хватит, зато очередь меню и сводки такой
  // поток задушил бы.
  //
  // Цвет считается ОТ СТЕННЫХ ЧАСОВ, а не накоплением тиков. Отсюда два
  // свойства даром: epoch и period у всех окон одни, поэтому в режиме «все одним
  // цветом» окна сходятся сами, без единого байта между ними; а придушенное
  // фоновое окно (Electron режет таймеры перекрытых окон до 1 Гц) после
  // пробуждения оказывается на правильном цвете, а не отстаёт на всё время сна.
  //
  // Палитры страница не считает: их присылает приложение кольцом опорных точек
  // из того же генератора, что и «Раскрасить по кругу» (AutoPaint с его
  // подтяжкой контраста), а страница между соседними точками смешивает цвета
  // покомпонентно. Вторая копия формул контраста в JS через месяц разъехалась бы
  // со Swift.
  //
  // Хранилища тем живые цвета не касаются вовсе: идут через applyTheme(…, "live")
  // мимо writeLayers. Выключили — restoreTheme поднял тему чата/окна по обычному
  // приоритету, как будто ничего не было. Своё состояние (кольцо, скорость,
  // режим) лежит отдельным ключом в localStorage: он у окон Claude общий, и
  // окно, открытое во время крутёжа, подхватывает цвет само, без команды —
  // в том числе когда приложение уже не запущено.
  const LIVE_KEY = "myclaude-live-v1";
  const LIVE_PHASE_KEY = "myclaude-live-phase-v1";
  // Круг за минуту — предел снизу: при тике 500 мс это 3° за шаг, быстрее уже
  // не «цвет едет», а мигание. Медленнее часа — цвет стоит на месте.
  const LIVE_PERIOD_MIN = 60;
  const LIVE_PERIOD_MAX = 3600;
  const LIVE_PERIOD_DEFAULT = 300;
  // Шаг по кругу и потолок частоты. Тик считается ОТ СКОРОСТИ, от 500 мс до
  // секунды, шаг ≤ 3°. Чаще 500 мс нельзя — каждый тик это ≈200 строк CSS и
  // полный пересчёт стилей окна (гейт WF18); реже — видны ступени.
  const LIVE_STEP_DEG = 1.5;
  const LIVE_TICK_MIN_MS = 500; // гейт WF18: при 250 мс (круг за минуту) рендереры +100–160 % CPU, при 500 — вдвое легче; шаг ≤ 3°
  const LIVE_TICK_MAX_MS = 1000;
  // Полоса прогресса берёт акцент один раз при отрисовке и за темой сама не
  // едет (её пульс — 10 с), то есть рядом с уехавшим окном держала бы старый
  // цвет. Зовём её перекраску на ГРУБОМ шаге: раз в 30° глазу не отличить от
  // непрерывной, а обмер низа окна четыре раза в секунду не нужен никому.
  const LIVE_COARSE_DEG = 30;
  // Кольцо приходит снаружи: три точки — уже круг, больше семи десятков не
  // бывает и разбирать незачем.
  const LIVE_RING_MIN = 3;
  const LIVE_RING_MAX = 72;

  const liveState = {
    on: false, mode: "sync", period: LIVE_PERIOD_DEFAULT, epoch: 0, light: null,
    useLight: false, ring: null, phase: 0, phased: false, hue: null, coarse: null,
    timer: 0, source: null, paints: 0,
  };

  // Устойчивый хэш заголовка (FNV-1a) — запасной способ развести окна по кругу,
  // когда окна нет в присланном списке (открылось позже). Одно и то же имя
  // всегда даёт одну и ту же точку круга.
  const liveHash = text => {
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash = Math.imul(hash ^ text.charCodeAt(index), 16777619) >>> 0;
    }
    return hash;
  };
  // Сдвиг окна по кругу в режиме «каждое своим цветом»: место в списке окон
  // (слева направо, как у «Расставить») делит круг поровну. Окна с одинаковым
  // заголовком получат одну фазу — ровно как в автопокраске, где адресация тоже
  // по заголовку.
  const livePhaseFor = titles => {
    const title = windowTitle();
    const list = Array.isArray(titles) ? titles.filter(item => typeof item === "string") : [];
    const index = list.indexOf(title);
    if (list.length > 0 && index >= 0) return (360 * index) / list.length;
    return liveHash(title) % 360;
  };
  const liveReadPhase = () => {
    try {
      const raw = sessionStorage.getItem(LIVE_PHASE_KEY);
      if (raw == null) return null;
      const record = JSON.parse(raw);
      // Окно «Open in new window» стартует с КОПИЕЙ sessionStorage главного окна
      // (см. readSessionEntry): без сверки ключа попап взял бы его фазу и сел
      // на ту же точку круга.
      if (!record || typeof record !== "object" || record.key !== sessionKey()) return null;
      const phase = Number(record.phase);
      return Number.isFinite(phase) ? ((phase % 360) + 360) % 360 : null;
    } catch { return null; }
  };
  const liveWritePhase = phase => {
    const key = sessionKey();
    if (!key) return;
    try { sessionStorage.setItem(LIVE_PHASE_KEY, JSON.stringify({ key, phase })); } catch {}
  };
  // Фаза защёлкивается ОДИН раз на жизнь окна и дальше от заголовка не зависит:
  // у главного окна заголовок меняется на каждом чате (watchChatTitle), и
  // считай мы фазу каждый раз заново — окно перескакивало бы на другую точку
  // круга при каждой смене разговора. Список titles задаёт только начальное
  // распределение. Ключа сессии может ещё не быть (about:blank без заголовка) —
  // тогда фаза живёт в памяти окна, а на диск ляжет при следующем случае.
  //
  // Но защёлкивать НЕ ПО ЧЕМУ, пока имени у окна нет: попап («Новое окно») в
  // первые мгновения сидит на about:blank без заголовка, а безымянный чат носит
  // заглушку («Claude», «New chat») — по такому имени и хэш, и место в списке у
  // ВСЕХ окон одинаковые. Заперлись бы на нём — окна, открытые во время
  // крутёжа, поехали бы одним цветом навсегда, и меню это уже не чинило бы.
  // Поэтому фаза от ненастоящего имени временная: красим ею, но замок не ставим
  // (livePaint пересчитает, как только заголовок появится) и на диск не пишем.
  // Присланный список окон авторитетнее памяти окна и сильнее замка: нашли себя
  // в нём — считаем фазу заново даже при phased, иначе повторное «каждое окно
  // своим цветом» не развело бы окна, слипшиеся по заглушке.
  const liveLatchPhase = titles => {
    const title = windowTitle();
    const real = title !== "" && !THEME_TITLE_STUBS.has(title.toLowerCase());
    const listed = real && Array.isArray(titles) && titles.indexOf(title) >= 0;
    if (liveState.phased && !listed) { liveWritePhase(liveState.phase); return; }
    liveState.phase = (listed ? null : liveReadPhase()) ?? livePhaseFor(titles);
    // Место в списке бывает только у настоящего имени, поэтому «фаза
    // авторитетная ИЛИ имя настоящее» и сводится к одному условию.
    liveState.phased = real;
    if (real) liveWritePhase(liveState.phase);
  };

  // Кольцо — текст снаружи, за который мы не отвечаем: палитра только из шести
  // известных цветов и только hex. Шаг по кругу берём из самой длины кольца
  // (12 точек — 30°), чтобы приложение могло сгустить кольцо, не трогая страницу.
  const liveRing = (list, type) => {
    if (!Array.isArray(list) || list.length < LIVE_RING_MIN) return null;
    const base = THEME_FALLBACK[type];
    const ring = [];
    for (const item of list.slice(0, LIVE_RING_MAX)) {
      if (!item || typeof item !== "object" || Array.isArray(item)) return null;
      const stop = {};
      for (const key of THEME_PALETTE_KEYS) stop[key] = normalizeHex(item[key], base[key]);
      ring.push(stop);
    }
    return ring;
  };
  // Разбор команды и записи из хранилища — один и тот же: в localStorage лежит
  // ровно то, что пришло командой. Кольца нет вовсе — крутить нечем.
  const liveConfig = raw => {
    if (!raw || typeof raw !== "object") return null;
    const rings = raw.ring && typeof raw.ring === "object" ? raw.ring : {};
    const dark = liveRing(rings.dark, "dark");
    const light = liveRing(rings.light, "light");
    if (!dark && !light) return null;
    const period = Number(raw.period);
    const epoch = Number(raw.epoch);
    return {
      mode: raw.mode === "solo" ? "solo" : "sync",
      period: Number.isFinite(period)
        ? Math.min(LIVE_PERIOD_MAX, Math.max(LIVE_PERIOD_MIN, Math.round(period)))
        : LIVE_PERIOD_DEFAULT,
      // Часы окна и часы приложения — одни и те же; epoch не наш, но и не чужой.
      epoch: Number.isFinite(epoch) ? epoch : Date.now(),
      light: raw.light === true ? true : (raw.light === false ? false : null),
      ring: { dark: dark ?? light, light: light ?? dark },
    };
  };
  const liveRead = () => {
    try {
      const raw = JSON.parse(localStorage.getItem(LIVE_KEY) ?? "null");
      return raw?.on === true ? liveConfig(raw) : null;
    } catch { return null; }
  };
  const liveWrite = config => {
    try {
      if (!config) localStorage.removeItem(LIVE_KEY);
      else localStorage.setItem(LIVE_KEY, JSON.stringify({ on: true, ...config }));
    } catch {}
  };

  const liveHue = () => {
    const turns = (Date.now() - liveState.epoch) / (liveState.period * 1000);
    // В режиме «все одним цветом» фаза не участвует вовсе, но защёлкнутое
    // значение сохраняется: переключили режим — окно встало на свою точку круга,
    // а не пересчитало её заново.
    const phase = liveState.mode === "solo" ? liveState.phase : 0;
    return (((turns * 360 + phase) % 360) + 360) % 360;
  };
  // Между опорными точками кольца — прямая в sRGB, покомпонентно (mixHex,
  // раздел 2а). На шаге в 30° контраст промежуточных цветов лежит между
  // контрастами соседей, и глазу это заметно не больше самой смены цвета.
  const livePalette = (ring, hue) => {
    const place = hue / (360 / ring.length);
    const first = Math.floor(place) % ring.length;
    const second = (first + 1) % ring.length;
    const ratio = place - Math.floor(place);
    const palette = {};
    for (const key of THEME_PALETTE_KEYS) palette[key] = mixHex(ring[first][key], ring[second][key], ratio);
    return palette;
  };
  const livePaint = () => {
    if (!liveState.on) return;
    const ring = liveState.useLight ? liveState.ring?.light : liveState.ring?.dark;
    if (!ring || ring.length === 0) return;
    // Замка ещё нет — окно красится временной фазой (при первом мазке имени не
    // было). Пробуем на каждом мазке: заголовок появился — фаза села сама, новой
    // команды из меню для этого не нужно.
    if (!liveState.phased) liveLatchPhase(null);
    const hue = liveHue();
    const type = liveState.useLight ? "light" : "dark";
    // id виден в status().theme.id — на гейте по нему сразу читается, где окно
    // на круге и живой ли это слой вообще.
    const applied = applyTheme({
      id: `live-${type}-${Math.round(hue)}`, name: "Живые цвета", type,
      palette: livePalette(ring, hue),
    }, "live");
    if (!applied) return;
    liveState.hue = hue;
    liveState.paints += 1;
    const coarse = Math.floor(hue / LIVE_COARSE_DEG);
    if (coarse !== liveState.coarse) {
      liveState.coarse = coarse;
      try { placeProgress(); } catch {}
    }
  };
  // evenHidden — первый мазок (команда, подъём из памяти): его пускаем и в
  // спрятанное окно, чтобы к показу цвет был уже верный, но примерку темы он,
  // как и обычный тик, не трогает.
  const liveTick = evenHidden => {
    if (!liveState.on || !state.alive) return;
    // Предпросмотр сильнее: мышь ведут по подменю тем, и затирать примерку через
    // четверть секунды нельзя. Меню закрылось — крутёж продолжился сам.
    if (themeState.previewing) return;
    // Окна не видно — цвет не крутим (батарея). Догонит одним шагом, когда
    // вернётся: цвет считается от часов, а не копится тиками.
    if (document.hidden && !evenHidden) return;
    livePaint();
  };
  const liveInterval = () => Math.round(Math.min(LIVE_TICK_MAX_MS,
    Math.max(LIVE_TICK_MIN_MS, (liveState.period * 1000 * LIVE_STEP_DEG) / 360)));
  const liveStopTimer = () => {
    if (liveState.timer) { clearInterval(liveState.timer); liveState.timer = 0; }
  };
  // Снятие экземпляра (новый инжект по mtime) обязано погасить интервал: иначе в
  // окне крутили бы цвет два таймера сразу.
  track(liveStopTimer);
  const liveStop = restore => {
    liveStopTimer();
    const was = liveState.on;
    liveState.on = false;
    liveState.hue = null;
    liveState.coarse = null;
    liveState.source = null;
    if (!was || !restore) return;
    // Выключение — это ровно «вернуть прежнее»: слой темы поднимается из
    // хранилища по обычному приоритету (чат → сессия → окно → всем), а нет
    // записи нигде — снимается вовсе. Своей ветки отката у живых цветов нет,
    // потому что и запоминать было нечего.
    try { restoreTheme(true, ["theme"]); } catch {}
    try { placeProgress(); } catch {}
  };
  const liveRun = (config, source) => {
    liveStopTimer();
    liveState.on = true;
    liveState.mode = config.mode;
    liveState.period = config.period;
    liveState.epoch = config.epoch;
    liveState.light = config.light;
    // «Как окно сейчас» решается ОДИН раз, на приёме команды: дальше на экране
    // уже живая тема, и спрашивать её тип — спрашивать самих себя.
    liveState.useLight = config.light === null ? themeState.theme?.type === "light" : config.light;
    liveState.ring = config.ring;
    liveState.source = source;
    liveState.coarse = null;
    liveTick(true);
    liveState.timer = setInterval(() => { try { liveTick(); } catch {} }, liveInterval());
  };

  // Контракт WF18: {id, action:"live-colors", at, scope:"all", on, mode, period,
  // epoch, light, titles, ring:{dark,light}}. Выключение — {scope, on:false}, и
  // больше в нём полей нет. Команда одна на все окна, адресации по заголовку у
  // неё нет: своё окно каждая страница отбирает сама (themable).
  const runLiveCommand = detail => {
    if (!themable || !detail || typeof detail !== "object") return false;
    if (detail.on !== true) { liveWrite(null); liveStop(true); return true; }
    const config = liveConfig(detail);
    if (!config) return false;
    liveWrite(config);
    liveLatchPhase(detail.titles);
    liveRun(config, "command");
    return true;
  };
  // Окно, открытое во время крутёжа, поднимает его само: команды ему ждать
  // неоткуда — приложение шлёт её один раз, на нажатие в меню.
  const liveRestore = () => {
    if (!themable) return;
    const config = liveRead();
    if (!config) return;
    liveLatchPhase(null);
    liveRun(config, "storage");
  };
  // Догоняем цвет, как только окно снова видно: тик всё это время молчал.
  on(document, "visibilitychange", () => { try { liveTick(); } catch {} });
  // Осечка живых цветов не должна утащить за собой ручку и полоску — как и у
  // восстановления темы выше.
  try { liveRestore(); } catch {}
  // Живые цвета (раздел 2в): крутится ли круг, в каком режиме и с какой
  // скоростью, где на круге стоит окно (phase — его защёлкнутый сдвиг,
  // hue — тон прямо сейчас), из скольких точек кольцо, сколько раз окно
  // перекрашено и откуда взялся крутёж — из команды или из памяти окон.
  statusPart("live", () => ({
    on: liveState.on,
    mode: liveState.mode,
    period: liveState.period,
    light: liveState.on ? liveState.useLight : null,
    phase: Math.round(liveState.phase * 10) / 10,
    hue: liveState.hue == null ? null : Math.round(liveState.hue * 10) / 10,
    ring: liveState.ring?.dark?.length ?? 0,
    paints: liveState.paints,
    source: liveState.source,
  }));

  // ---- 2г. Широкий вид окна (WF65) -----------------------------------------
  // Раскладку делает CSS (layoutCss, раздел 2а); здесь — то, что страница обязана
  // знать сама: широкий ли сейчас вид, что при этом делать со ступенями поля и
  // рейка ширины правой колонки. Своих таймеров и наблюдателей раздел не
  // заводит: всё ходит в существующем проходе layout() (раздел 9).
  const SIDE_RAIL_ID = "myclaude-side-rail";
  // Рейка — копия рейки левой панели Claude (WF176, #9182: «у левой панельки… полоска
  // для изменения размера — правильно… у правой тоже должна быть такая полосочка»):
  // зона захвата 12 (w-3), пилюля 3×48 по центру высоты цветом text-muted, проявляется
  // на наведении через 200 мс за 200 мс (delay-200 duration-base) — замер 09.10.
  const SIDE_RAIL_WIDTH = 12;
  const SIDE_RAIL_PILL = 48;
  // Пауза перед появлением линии рейки на наведении — как у рейки Claude: случайный
  // проезд курсора её не зажигает.
  const SIDE_RAIL_REVEAL_MS = 200;
  const SIDE_RAIL_PILL_SELECTOR = '[data-cds="ResizeHandle"] [data-cds-part="resize-pill"]';
  // Ширина колонки, выбранная мышью: localStorage — окна Claude делят её, как и
  // ширину боковой панели у самого Claude. v2 с WF68: под v1 у Элвиса лежало
  // ровно 300 — тяга упёрлась в прежний минимум, и новая, узкая граница осталась
  // бы за этим числом невидимой; ширины v1 не читаются и не переносятся.
  const SIDE_STORAGE_KEY = "myclaude-wide-side-v2";
  // Доля к ней (WF197): ширина / ширина сетки в момент тяги, число 0…1. Отдельным ключом — v2 читают и
  // прежние страницы (Number() строки с долей дал бы NaN).
  const SIDE_SHARE_STORAGE_KEY = "myclaude-wide-side-share-v1";
  const layoutPanel = editor => {
    try {
      return editor?.closest?.(".epitaxy-chat-panel") ?? document.querySelector(".epitaxy-chat-panel");
    } catch { return null; }
  };
  // Единственный оракул: флаг, который CSS ставит на панель внутри контейнерного
  // запроса (см. layoutCss). На innerWidth не падаем никогда — стенды тестов
  // шириной 1200 обязаны оставаться узкими, а в бою второй порог разошёлся бы
  // с первым.
  const wideLayout = panel => {
    if (!panel?.isConnected) return false;
    try { return getComputedStyle(panel).getPropertyValue(WIDE_FLAG).trim() === "1"; } catch { return false; }
  };
  // Дока — правая колонка целиком: её левая кромка — кромка колонки, а ширина — колонка плюс COLUMN_PULL,
  // на который дока выезжает влево.
  const sideDock = panel => {
    try { return panel?.querySelector?.('[class~="group/approval-dock"]') ?? null; } catch { return null; }
  };
  // Ширина колонки — в единицах колонки (#6214): как переменная SIDE_VARIABLE, пол и sideMin. До WF261 здесь
  // отдавалась ширина доки, и status().layout.side было на 12 больше колонки рядом с sideMin в её единицах.
  const sideWidth = panel => {
    const dock = sideDock(panel);
    const box = dock?.isConnected ? dock.getBoundingClientRect() : null;
    return box && box.width > 0 ? Math.round(box.width) - COLUMN_PULL : null;
  };
  const readStoredSide = () => {
    try {
      const stored = Number(localStorage.getItem(SIDE_STORAGE_KEY));
      return Number.isFinite(stored) && stored >= SIDE_FLOOR ? Math.round(stored) : null;
    } catch { return null; }
  };
  const readStoredShare = () => {
    try {
      const share = Number(localStorage.getItem(SIDE_SHARE_STORAGE_KEY));
      return share > 0 && share <= 1 ? share : null;
    } catch { return null; }
  };
  // Сетка колонок — родитель шапки (обе формы пути, panelGridSelector); проценты сетки — от её ширины.
  const sideGridWidth = panel => {
    try {
      // 3.1623: между шапкой и колонкой — обёртки (раздел 2а, PANEL_TITLE_PATHS), в сетке они display: contents
      // и ширины не имеют; сетка — первый предок шапки с шириной.
      let grid = panel?.querySelector?.(".epitaxy-titlebar")?.parentElement;
      let width = grid?.isConnected ? grid.getBoundingClientRect().width : 0;
      while (!(width > 0) && grid?.parentElement && grid !== panel) {
        grid = grid.parentElement;
        width = grid === panel ? 0 : grid.getBoundingClientRect().width;
      }
      return width > 0 ? width : (panel?.getBoundingClientRect?.()?.width ?? 0);
    } catch { return 0; }
  };
  const sideShareFor = (panel, value) => {
    const grid = sideGridWidth(panel);
    return grid > 0 && value > 0 ? Math.min(1, value / grid) : null;
  };
  const chinRow = panel => {
    try { return sideDock(panel)?.querySelector?.(CHIN_ROW_SELECTOR) ?? null; } catch { return null; }
  };
  // Нижняя граница колонки по строке модели (WF68, #6212): натуральная ширина
  // строки — обе группы плюс её собственные поля — плюс зазор между группами
  // плюс обвязка колонки вокруг строки. Обвязка — замер, не константа: ширина
  // колонки (дока минус COLUMN_PULL, на который она выезжает влево) минус ширина
  // строки; сегодня это 12, но держится оно на трёх правилах layoutCss разом.
  // Строки нет или она пуста — SIDE_MIN, как до WF68. Ниже SIDE_FLOOR не
  // опускаемся, сверху режет clamp CSS долей панели.
  // Натуральная ширина узла строки (WF197, #9291): растянутый ребёнок (flex-grow — распорка Claude
  // «flex-1 basis-0» между группами) занимает всё свободное место строки, и его рамка — это ширина
  // колонки, а не нужная строке. До WF197 sideMinFor складывал рамки всех детей вместе с распоркой:
  // минимум выходил равным нынешней ширине, и колонка не уступала при сужении окна («она больше не
  // сжимается»). Растянутый узел — сумма натуральных ширин его детей и зазоров (пустая распорка — 0),
  // нерастянутый — его рамка. top — сам ряд: его рамку не берём никогда, только детей.
  const sideNatural = (node, top = false) => {
    let style = null;
    try { style = getComputedStyle(node); } catch {}
    const grow = Number.parseFloat(style?.flexGrow ?? style?.getPropertyValue?.("flex-grow") ?? "");
    if (!top && !(grow > 0)) return node.getBoundingClientRect?.()?.width ?? 0;
    const kids = [...(node.children ?? [])];
    const gap = Number.parseFloat(style?.columnGap ?? style?.getPropertyValue?.("column-gap") ?? "") || 0;
    let width = kids.reduce((sum, kid) => sum + sideNatural(kid), 0) + gap * Math.max(0, kids.length - 1);
    if (!top && width > 0) {
      width += (Number.parseFloat(style?.getPropertyValue?.("padding-left") ?? "") || 0) +
        (Number.parseFloat(style?.getPropertyValue?.("padding-right") ?? "") || 0);
    }
    return width;
  };
  const sideMinFor = panel => {
    const row = chinRow(panel);
    const dock = sideDock(panel);
    if (!row?.isConnected || row.children.length < 2 || !dock?.isConnected) return SIDE_MIN;
    const rowBox = row.getBoundingClientRect();
    const dockBox = dock.getBoundingClientRect();
    if (rowBox.width <= 0 || dockBox.width <= 0) return SIDE_MIN;
    const content = sideNatural(row, true);
    if (content <= 0) return SIDE_MIN;
    const computed = getComputedStyle(row);
    const padding = (Number.parseFloat(computed.getPropertyValue("padding-left")) || 0) +
      (Number.parseFloat(computed.getPropertyValue("padding-right")) || 0);
    const chrome = dockBox.width - COLUMN_PULL - rowBox.width;
    return Math.max(SIDE_FLOOR, Math.round(content + padding + SIDE_CHIN_GAP + chrome));
  };
  // Действующая нижняя граница — та, что лежит на панели: по ней и CSS, и рейка.
  const sideMinOf = panel => {
    const value = Number.parseFloat(panel?.style?.getPropertyValue(SIDE_MIN_VARIABLE) ?? "");
    return Number.isFinite(value) && value >= SIDE_FLOOR ? value : SIDE_MIN;
  };
  const storeSide = (value, share = null) => {
    try {
      if (value == null) localStorage.removeItem(SIDE_STORAGE_KEY);
      else localStorage.setItem(SIDE_STORAGE_KEY, String(Math.round(value)));
      if (value == null || !(share > 0)) localStorage.removeItem(SIDE_SHARE_STORAGE_KEY);
      else localStorage.setItem(SIDE_SHARE_STORAGE_KEY, String(Math.round(share * 10000) / 10000));
    } catch {}
  };
  const wideState = { on: false, panel: null, dragging: false, grip: 0, gaps: null, langPanel: null, floors: {} };
  // Пол колонки по факту (WF183, слово Элвиса 09.10 03:15: «Не давай уменьшать правую панель меньше, чем
  // можно… пропадает кругляшок с токенами»): ниже SIDE_FLOOR ещё и ширины, при которой встаёт нижняя строка
  // поля с кружком (12з¹, «chin»; замер «nav» блока 12п² снят вместе с блоком, page-60). Каждый замер — сколько
  // точек не хватает (need > 0) или лишних (need < 0) при нынешней ширине колонки (замер доки, не своя
  // переменная — её CSS мог поднять полом); пол = колонка + need. Пол — инлайн-переменной на панель
  // (её берёт clamp сетки) и границей тяги рейки.
  const sideFloorOf = () => Math.max(SIDE_FLOOR, ...Object.values(wideState.floors).filter(Number.isFinite));
  const sideFloorNeed = (kind, need) => {
    const panel = wideState.panel;
    if (!wideState.on || !panel?.isConnected || !Number.isFinite(need)) return;
    const width = sideWidth(panel);
    if (width == null) return;
    wideState.floors[kind] = Math.ceil(width + need);
    sideFloorPaint();
  };
  // Замера больше нет (чат сменился) — его пол снимается.
  const sideFloorDrop = kind => {
    if (!(kind in wideState.floors)) return;
    delete wideState.floors[kind];
    sideFloorPaint();
  };
  const sideFloorPaint = () => {
    const panel = wideState.panel;
    if (!panel?.style) return;
    const floor = sideFloorOf();
    if (floor <= SIDE_FLOOR) { if (panel.style.getPropertyValue(SIDE_FLOOR_VARIABLE)) panel.style.removeProperty(SIDE_FLOOR_VARIABLE); return; }
    const value = `${Math.round(floor)}px`;
    if (panel.style.getPropertyValue(SIDE_FLOOR_VARIABLE) !== value) panel.style.setProperty(SIDE_FLOOR_VARIABLE, value);
  };
  // Инлайн-переменные и атрибут на чужом узле снимаются вместе с экземпляром;
  // следующий прогон вернёт их на первом же проходе (ширину — из хранилища).
  track(() => {
    try { wideState.panel?.style?.removeProperty(SIDE_VARIABLE); } catch {}
    try { wideState.panel?.style?.removeProperty(SIDE_SHARE_VARIABLE); } catch {}
    try { wideState.panel?.style?.removeProperty(SIDE_MIN_VARIABLE); } catch {}
    try { wideState.panel?.style?.removeProperty(SIDE_FLOOR_VARIABLE); } catch {}
    try { wideState.panel?.style?.removeProperty(TITLE_INSET_VARIABLE); } catch {}
    try { titleAlignClear(wideState.panel); } catch {}
    try { clearGaps(wideState.panel); } catch {}
    try { if (wideState.langPanel?.getAttribute("lang") === "ru") wideState.langPanel.removeAttribute("lang"); } catch {}
    try { wideState.panel?.removeAttribute(TITLE_SIDE_ATTRIBUTE); } catch {}
    try { wideState.panel?.removeAttribute(SIDE_TIGHT_ATTRIBUTE); } catch {}
  });
  // Куда класть шапку: панель начинается у левого края окна (попап) — шапка
  // влево, в полосу под кнопками окна; иначе — вправо, над полем ввода. Главное
  // окно (#7913, WF102) — всегда вправо: лента во всю высоту, под кнопками окна
  // затухание (раздел 2ж).
  // Одно правило на два места (WF209): шапку кладёт applyTitleSide, а угол (cornerSpot, место head)
  // спрашивает его же ещё до метки на панели — иначе попап на первом проходе на кадр вставал бы в head.
  const titleGoesLeft = (panel, wide) => wide && !isMainWindow() && panel.getBoundingClientRect().left < TITLEBAR_CLEARANCE_LEFT;
  const applyTitleSide = (panel, wide) => {
    if (!panel) return;
    wideState.panel = panel;
    const left = titleGoesLeft(panel, wide);
    if (!left) {
      if (panel.hasAttribute(TITLE_SIDE_ATTRIBUTE)) panel.removeAttribute(TITLE_SIDE_ATTRIBUTE);
      panel.style.removeProperty(TITLE_INSET_VARIABLE);
      return;
    }
    const inset = `${location.href === "about:blank" ? TITLE_INSET_POPOUT : TITLE_INSET_MAIN}px`;
    if (panel.style.getPropertyValue(TITLE_INSET_VARIABLE) !== inset) panel.style.setProperty(TITLE_INSET_VARIABLE, inset);
    if (panel.getAttribute(TITLE_SIDE_ATTRIBUTE) !== "left") panel.setAttribute(TITLE_SIDE_ATTRIBUTE, "left");
  };
  // #9135: значок шапки колонки — левым краем по тексту поля. Значок — самый левый
  // видимый узел шапки (кнопка, картинка, название); сдвигается её ребёнок, в котором он
  // лежит. Прежний сдвиг из замера вычитаем — проходы сходятся, а не копят. Шапка слева,
  // узкий вид, нет поля — сдвиг снят.
  const titleAlign = { lead: null, shift: null, end: null, title: null, fade: false };
  // Затухание хвоста названия (WF185): метка — только пока текст правда не влез.
  const titleFadeMark = title => {
    if (titleAlign.title && titleAlign.title !== title) { try { titleAlign.title.removeAttribute(TITLE_FADE_ATTRIBUTE); } catch {} }
    titleAlign.title = title ?? null;
    let over = false;
    try { over = Boolean(title) && Number(title.scrollWidth) - Number(title.clientWidth) > 1; } catch {}
    titleAlign.fade = over;
    if (!title) return;
    if (over && !title.hasAttribute(TITLE_FADE_ATTRIBUTE)) title.setAttribute(TITLE_FADE_ATTRIBUTE, "");
    else if (!over && title.hasAttribute(TITLE_FADE_ATTRIBUTE)) title.removeAttribute(TITLE_FADE_ATTRIBUTE);
  };
  const titleAlignClear = panel => {
    try { titleAlign.lead?.removeAttribute?.(TITLE_LEAD_ATTRIBUTE); } catch {}
    titleFadeMark(null);
    titleAlign.lead = null;
    titleAlign.shift = null;
    titleAlign.end = null;
    if (panel?.style?.getPropertyValue(TITLE_SHIFT_VARIABLE)) panel.style.removeProperty(TITLE_SHIFT_VARIABLE);
    if (panel?.style?.getPropertyValue(TITLE_END_VARIABLE)) panel.style.removeProperty(TITLE_END_VARIABLE);
  };
  const applyTitleAlign = (panel, wide, editor) => {
    if (!panel || !wide || panel.getAttribute(TITLE_SIDE_ATTRIBUTE) === "left" || !editor?.isConnected) {
      titleAlignClear(panel);
      return;
    }
    const bar = panel.querySelector(".epitaxy-titlebar");
    let icon = null;
    let iconLeft = Infinity;
    for (const node of bar?.querySelectorAll?.("button, svg, img, [data-pane-title]") ?? []) {
      const box = node.getBoundingClientRect();
      // Название (с WF179 оно первое, #9206) — по началу ТЕКСТА: у кнопки Claude поле внутри.
      let inner = 0;
      if (node.matches?.("[data-pane-title]")) { try { inner = Number.parseFloat(getComputedStyle(node).getPropertyValue("padding-left")) || 0; } catch {} }
      if (box.width > 0 && box.height > 0 && box.left + inner < iconLeft) { icon = node; iconLeft = box.left + inner; }
    }
    let lead = icon;
    while (lead && lead.parentElement !== bar) lead = lead.parentElement;
    const text = editor.getBoundingClientRect();
    if (!lead || !(text.width > 0)) { titleAlignClear(panel); return; }
    let pad = 0;
    try { pad = Number.parseFloat(getComputedStyle(editor).getPropertyValue("padding-left")) || 0; } catch {}
    const applied = titleAlign.lead === lead ? titleAlign.shift ?? 0 : 0;
    const shift = Math.max(0, Math.min(TITLE_SHIFT_MAX, Math.round(text.left + pad - (iconLeft - applied))));
    if (titleAlign.lead !== lead) {
      try { titleAlign.lead?.removeAttribute?.(TITLE_LEAD_ATTRIBUTE); } catch {}
      titleAlign.lead = lead;
    }
    if (!lead.hasAttribute(TITLE_LEAD_ATTRIBUTE)) lead.setAttribute(TITLE_LEAD_ATTRIBUTE, "");
    titleAlign.shift = shift;
    const value = `${shift}px`;
    if (panel.style.getPropertyValue(TITLE_SHIFT_VARIABLE) !== value) panel.style.setProperty(TITLE_SHIFT_VARIABLE, value);
    // WF185 (слово Элвиса 09.10 03:20: «мониторчик — к самому краю, как по выравниванию, отступ от
    // правого края как у всех»): правый край значка Remote Control — по правому краю поля ввода
    // (по нему же стоят «Отправить», кружок лимитов и полоса Рика; замер 09.10: поле 941, значок 961).
    // Прежний отступ из замера вычитаем — проходы сходятся.
    const gutter = bar?.querySelector?.('[data-testid="epitaxy-origin-gutter"]');
    const field = editor.closest?.('[data-cds="ChatComposer"]') ?? null;
    const gutterBox = gutter?.isConnected ? gutter.getBoundingClientRect() : null;
    const fieldBox = field?.isConnected ? field.getBoundingClientRect() : null;
    if (gutterBox && fieldBox && gutterBox.width > 0 && fieldBox.width > 0) {
      const appliedEnd = Number.parseFloat(panel.style.getPropertyValue(TITLE_END_VARIABLE)) || 0;
      const end = Math.max(0, Math.min(TITLE_END_MAX, Math.round(gutterBox.right + appliedEnd - fieldBox.right)));
      titleAlign.end = end;
      const endValue = `${end}px`;
      if (panel.style.getPropertyValue(TITLE_END_VARIABLE) !== endValue) panel.style.setProperty(TITLE_END_VARIABLE, endValue);
    } else if (titleAlign.end != null) {
      titleAlign.end = null;
      panel.style.removeProperty(TITLE_END_VARIABLE);
    }
    titleFadeMark(bar?.querySelector?.("[data-pane-title]") ?? null);
  };
  const applySide = (panel, value, share = null) => {
    if (!panel) return;
    wideState.panel = panel;
    if (value == null) panel.style.removeProperty(SIDE_VARIABLE);
    else panel.style.setProperty(SIDE_VARIABLE, `${Math.round(value)}px`);
    if (value == null || !(share > 0)) panel.style.removeProperty(SIDE_SHARE_VARIABLE);
    else panel.style.setProperty(SIDE_SHARE_VARIABLE, `${Math.round(share * 10000) / 100}%`);
  };
  // Нижняя граница пересчитывается каждый проход: строка модели меняется со
  // сменой модели и эффорта, и колонка обязана следовать за ней в обе стороны.
  // Первый широкий проход меряет строку ещё при границе CSS по умолчанию (300),
  // второй — уже при своей; сходится сразу: группы не ужимаются, обвязка та же.
  const applySideMin = (panel, wide) => {
    if (!panel) return;
    wideState.panel = panel;
    if (!wide) {
      if (panel.style.getPropertyValue(SIDE_MIN_VARIABLE)) panel.style.removeProperty(SIDE_MIN_VARIABLE);
      if (panel.style.getPropertyValue(SIDE_FLOOR_VARIABLE)) panel.style.removeProperty(SIDE_FLOOR_VARIABLE);
      wideState.floors = {};
      if (panel.hasAttribute(SIDE_TIGHT_ATTRIBUTE)) panel.removeAttribute(SIDE_TIGHT_ATTRIBUTE);
      return;
    }
    const side = Number.parseFloat(panel.style.getPropertyValue(SIDE_VARIABLE));
    if (panel.hasAttribute(SIDE_TIGHT_ATTRIBUTE)) {
      if (Number.isFinite(side) && side < sideMinOf(panel)) return;
      panel.removeAttribute(SIDE_TIGHT_ATTRIBUTE);
      return;
    }
    const min = sideMinFor(panel);
    const value = `${min}px`;
    if (panel.style.getPropertyValue(SIDE_MIN_VARIABLE) !== value) panel.style.setProperty(SIDE_MIN_VARIABLE, value);
    if (Number.isFinite(side) && side < min) panel.setAttribute(SIDE_TIGHT_ATTRIBUTE, "");
  };
  // Поля правой колонки (#9148): каждый широкий проход — по полю ленты; узкий вид — снять.
  // С WF163 (33.5) — и просветы трёх столбиков: wideGapsFor по полю ряда, ширине тела ленты
  // и краю боковой панели; итог — четыре переменные на панели и status().layout.gaps.
  const GAP_VARIABLES = [DOCK_INSET_VARIABLE, DOCK_INSET_START_VARIABLE, FEED_START_VARIABLE, FEED_END_VARIABLE];
  const clearGaps = panel => {
    for (const name of GAP_VARIABLES) if (panel?.style?.getPropertyValue(name)) panel.style.removeProperty(name);
  };
  const applyDockInset = (panel, wide) => {
    if (!panel?.style) return;
    if (!wide) { clearGaps(panel); wideState.gaps = null; return; }
    let pad = NaN, column = NaN, menuGap = null;
    try {
      const source = panel.querySelector?.(DOCK_INSET_SOURCE);
      if (source) pad = Number.parseFloat(window.getComputedStyle(source).getPropertyValue("padding-left"));
    } catch { pad = NaN; }
    try {
      const body = panel.querySelector?.(".epitaxy-chat-panel-body")?.getBoundingClientRect?.();
      if (body?.width > 0) {
        column = body.width;
        const aside = document.querySelector("aside.dframe-sidebar");
        const side = aside && !aside.closest?.(".dframe-root[data-collapsed]") ? aside.getBoundingClientRect() : null;
        if (side?.width > 0 && side.right <= body.left + 1) menuGap = body.left - (side.right - MENU_ITEM_INSET);
      }
    } catch {}
    const gaps = wideGapsFor({ pad, column, menuGap });
    wideState.gaps = gaps;
    const values = [gaps.dockEnd, gaps.dockStart, gaps.feedStart, gaps.feedEnd];
    GAP_VARIABLES.forEach((name, index) => {
      const value = `${values[index]}px`;
      if (panel.style.getPropertyValue(name) !== value) panel.style.setProperty(name, value);
    });
  };
  // Переносы по-русски (#9148, 33.5): у страницы Claude lang="en-US", а hyphens: auto берёт
  // словарь по lang — русские слова не переносились бы. Панель чата получает lang="ru";
  // свой lang у панели или русская страница — не трогаем.
  const applyTextLang = panel => {
    try {
      if (!panel?.setAttribute || panel.hasAttribute("lang")) return;
      if (/^ru\b/i.test(document.documentElement?.getAttribute?.("lang") ?? "")) return;
      panel.setAttribute("lang", "ru");
      wideState.langPanel = panel;
    } catch {}
  };
  // Ступени в широком виде выключены: поле стоит на обычной высоте и растёт само
  // вместе с колонкой, ручки нет — свёрнутое поле тут исчезло бы навсегда.
  // Хранилище ступени при этом НЕ переписываем: возврат в узкий вид берёт ступень
  // оттуда, как при инжекте, — поле возвращается таким, каким его оставили.
  const syncWide = wide => {
    if (wide) {
      if (state.stage !== STAGE_NORMAL) {
        const stage = readStoredStage();
        const height = readStoredHeight();
        setStage(STAGE_NORMAL, { silent: true });
        if (stage != null) storeStage(stage);
        storeHeight(height);
      }
    } else if (wideState.on) {
      const stage = readStoredStage();
      if (stage != null && stage !== state.stage) setStage(stage, { silent: true });
    }
    wideState.on = wide;
  };
  // Рейка стоит fixed по координатам, как ручка и полоса: узел живёт в body, а не
  // в дереве Claude (довод раздела 4 — React пересобирает панель, и свой узел
  // внутри неё пришлось бы ловить заново). Место — левая кромка доки, во всю
  // высоту панели; в узком виде рейки нет.
  const placeSideRail = (panel, wide) => {
    if (!wide || !panel) {
      if (rail.style.display !== "none") rail.style.setProperty("display", "none");
      return;
    }
    // Сохранённая ширина ставится ДО замера: после неё колонка уже другая.
    if (!panel.style.getPropertyValue(SIDE_VARIABLE)) {
      const stored = readStoredSide();
      if (stored != null) {
        // Доли ещё нет (ширина выбрана до WF197) — берём её от нынешней сетки и запоминаем.
        let share = readStoredShare();
        if (share == null) { share = sideShareFor(panel, stored); if (share != null) storeSide(stored, share); }
        applySide(panel, stored, share);
      }
    }
    const dock = sideDock(panel);
    const box = dock?.isConnected ? dock.getBoundingClientRect() : null;
    const frame = panel.getBoundingClientRect();
    if (!box || box.width <= 0 || frame.height <= 0) {
      if (rail.style.display !== "none") rail.style.setProperty("display", "none");
      return;
    }
    rail.style.setProperty("display", "block");
    // Рейка — сразу правее полосы прокрутки ленты (#10110: над полосой она забирала её себе, и тянуть ленту было
    // нельзя); прокрутки нет (стенд, чужая сборка) — от кромки доки.
    const scroller = panel.querySelector('[data-testid="epitaxy-virtual-transcript"]');
    const scrollerBox = scroller?.isConnected ? scroller.getBoundingClientRect() : null;
    const railLeft = scrollerBox && scrollerBox.width > 0 ? scrollerBox.right : box.left;
    rail.style.setProperty("left", `${Math.round(railLeft)}px`);
    rail.style.setProperty("top", `${Math.round(frame.top)}px`);
    rail.style.setProperty("height", `${Math.round(frame.height)}px`);
    // Цвет — как у пилюли рейки левой панели (тема красит её text-muted); панели нет
    // (свёрнута, попап) — прежний, а до первого замера — запасной из CSS.
    let tint = "";
    try {
      const pill = document.querySelector(SIDE_RAIL_PILL_SELECTOR);
      if (pill) tint = getComputedStyle(pill).getPropertyValue("color") || getComputedStyle(pill).color || "";
    } catch {}
    if (tint && rail.style.getPropertyValue("color") !== tint) rail.style.setProperty("color", tint);
  };
  // Тяга: ширина колонки = ширина в момент захвата + сдвиг курсора влево, в границах
  // [пол, 60 % панели]. Значение уходит инлайн-переменной на панель, сетка
  // пересчитывается сама; отпустили — в хранилище. Двойной клик — умолчание.
  // До WF176 ширину считали от кромки доки, а дока шире колонки на COLUMN_PULL:
  // каждый захват без движения расширял колонку на 12 — «размер сбился» (#9182).
  const railSide = (panel, x) => {
    const frame = panel.getBoundingClientRect();
    return Math.round(Math.min(frame.width * SIDE_MAX_SHARE, Math.max(sideFloorOf(), wideState.grip - x)));
  };
  // Ширина колонки сейчас: замер доки без её выезда влево (с WF197 колонка бывает ýже своей переменной —
  // уступила долей), нет замера — своя переменная.
  const railColumn = panel => {
    const width = sideWidth(panel);
    if (width != null) return width;
    const own = Number.parseFloat(panel?.style?.getPropertyValue(SIDE_VARIABLE) ?? "");
    return Number.isFinite(own) && own > 0 ? own : null;
  };
  const onRailDown = event => {
    if (event.button !== 0) return;
    const panel = layoutPanel(state.editor);
    if (!panel) return;
    event.preventDefault();
    wideState.dragging = true;
    wideState.panel = panel;
    // grip — «ширина + x» захвата: ширина на ходу = grip − x, без скачка на захвате.
    const column = railColumn(panel);
    wideState.grip = (column ?? panel.getBoundingClientRect().right - event.clientX) + event.clientX;
    rail.dataset.dragging = "true";
    document.documentElement.style.cursor = "col-resize";
    document.documentElement.style.userSelect = "none";
    try { rail.setPointerCapture(event.pointerId); } catch {}
  };
  const onRailMove = event => {
    if (!wideState.dragging) return;
    const panel = wideState.panel;
    if (!panel?.isConnected) return;
    event.preventDefault();
    const value = railSide(panel, event.clientX);
    applySide(panel, value, sideShareFor(panel, value));
    layout();
  };
  const onRailUp = () => {
    if (!wideState.dragging) return;
    wideState.dragging = false;
    rail.dataset.dragging = "false";
    document.documentElement.style.cursor = "";
    document.documentElement.style.userSelect = "";
    const panel = wideState.panel;
    const value = Number.parseFloat(panel?.style?.getPropertyValue(SIDE_VARIABLE) ?? "");
    const share = Number.parseFloat(panel?.style?.getPropertyValue(SIDE_SHARE_VARIABLE) ?? "") / 100;
    if (Number.isFinite(value)) storeSide(value, share);
    scheduleLayout();
  };
  const onRailReset = () => {
    applySide(wideState.panel ?? layoutPanel(state.editor), null);
    storeSide(null);
    layout();
  };
  // Лоадер перечитал файл посреди тяги — курсор и запрет выделения на
  // documentElement сняли бы только по отпусканию, а обработчика уже нет.
  track(() => {
    if (!wideState.dragging) return;
    wideState.dragging = false;
    document.documentElement.style.cursor = "";
    document.documentElement.style.userSelect = "";
  });
  // Широкий вид (#7974): поле ввода в правой колонке — цветом ленты, с рамкой 1 px.
  statusPart("wide", () => ({ on: wideState.on, field: wideState.on ? "line" : null }));

  // ---- 2д. Левая панель Claude ýже заводского минимума (#6625) ------------
  // Claude держит ширину боковой панели переменной `--df-sidebar-width` на
  // `.dframe-root` и сам не даёт ей стать меньше 242 (aria-valuemin рейки
  // «Resize sidebar», замер 20.09). Тянут его же рейку левее минимума — ширину
  // ведём мы: своя переменная на корне + правило с !important (инлайновое
  // значение Claude без !important уступает). Пол — кнопка «Hide sidebar» и
  // переключатель Claude/Code вплотную (слово Элвиса: «вплотную, но уже не стоит»).
  // С WF176 (#9182: «левая панель тоже размер не меняет») своя ширина ведётся во
  // всём ходе рейки, до aria-valuemax: раньше за минимумом 242 мы отдавали ширину
  // Claude, а его состояние помнило свои 242 — на границе панель прыгала, а со
  // своей узкой шириной у пола (216) не тянулась вовсе. Двойной клик — Claude.
  const LEFT_ATTRIBUTE = "data-myclaude-left";
  const LEFT_VARIABLE = "--myclaude-left";
  const LEFT_STORAGE_KEY = "myclaude-left-side-v1";
  // #11618: подпись на обоих языках; в querySelector/closest — списком через запятую, без :is (так понимает и стаб тестов).
  const LEFT_RAIL_SELECTOR = '[data-cds="ResizeHandle"][aria-label="Resize sidebar"],[data-cds="ResizeHandle"][aria-label="Изменить размер боковой панели"]';
  const LEFT_BUTTONS_GAP = 4;
  const LEFT_FLOOR_FALLBACK = 190;
  const LEFT_MAX_FALLBACK = 420;
  // forced — ширину держим мы не по тяге, а ради кнопки «PMP» в строке «Hide sidebar» (раздел 12п⁴): не помним её.
  const leftState = { dragging: false, root: null, grip: 0, min: 242, max: LEFT_MAX_FALLBACK, floor: LEFT_FLOOR_FALLBACK, forced: false };
  const leftMaxOf = handle => {
    const max = Number(handle?.getAttribute?.("aria-valuemax"));
    return Number.isFinite(max) && max > 0 ? max : LEFT_MAX_FALLBACK;
  };
  const leftRoot = () => document.querySelector(".dframe-root");
  const applyLeft = (root, value) => {
    if (!root) return;
    leftState.root = root;
    if (value == null) {
      if (root.hasAttribute(LEFT_ATTRIBUTE)) root.removeAttribute(LEFT_ATTRIBUTE);
      root.style.removeProperty(LEFT_VARIABLE);
      return;
    }
    root.style.setProperty(LEFT_VARIABLE, `${Math.round(value)}px`);
    if (!root.hasAttribute(LEFT_ATTRIBUTE)) root.setAttribute(LEFT_ATTRIBUTE, "");
  };
  const readStoredLeft = () => {
    try {
      const stored = Number(localStorage.getItem(LEFT_STORAGE_KEY));
      return Number.isFinite(stored) && stored > 0 ? Math.round(stored) : null;
    } catch { return null; }
  };
  const storeLeft = value => {
    try {
      if (value == null) localStorage.removeItem(LEFT_STORAGE_KEY);
      else localStorage.setItem(LEFT_STORAGE_KEY, String(Math.round(value)));
    } catch {}
  };
  // Пол по живой геометрии: правый край последней кнопки строки окна (панель, назад, вперёд —
  // до WF155 считалась одна «Hide sidebar», и переключатель Claude/Code при 190 заезжал за край
  // панели на ленту, #9146) и переключателя, если он в этой строке (с WF166 он стоит сразу за
  // «вперёд», и пол — его правый край); плюс поле строки справа.
  const LEFT_TITLEBAR_PAD = 8;
  const leftFloor = aside => {
    const box = aside?.getBoundingClientRect();
    const bar = aside?.querySelector?.(".df-titlebar");
    const row = bar?.getBoundingClientRect();
    const ends = [...(bar?.querySelectorAll?.(".df-chrome-btn") ?? [])]
      .map(node => node.getBoundingClientRect()).filter(rect => rect.width > 0).map(rect => rect.right);
    if (!box || box.width <= 0 || !row || !ends.length) return LEFT_FLOOR_FALLBACK;
    let end = Math.max(...ends);
    const mode = bar.querySelector('[role="radiogroup"][aria-label="Mode"],[role="radiogroup"][aria-label="Режим"]')?.getBoundingClientRect();
    if (mode && mode.width > 0 && mode.top < row.bottom && mode.bottom > row.top) end = Math.max(end, mode.right);
    return Math.round(end - box.left + LEFT_TITLEBAR_PAD);
  };
  const onLeftDown = event => {
    if (event.button !== 0) return;
    const handle = event.target?.closest?.(LEFT_RAIL_SELECTOR);
    const root = leftRoot();
    const aside = root?.querySelector("aside.dframe-sidebar");
    if (!handle || !aside) return;
    const min = Number(handle.getAttribute("aria-valuemin"));
    leftState.dragging = true;
    leftState.root = root;
    leftState.min = Number.isFinite(min) && min > 0 ? min : 242;
    leftState.max = Math.max(leftState.min, leftMaxOf(handle));
    let need = 0;
    try { need = dockLeftFloor(aside); } catch { need = 0; }
    leftState.floor = Math.max(Math.min(leftState.min, leftFloor(aside)), need);
    leftState.grip = aside.getBoundingClientRect().right - event.clientX;
  };
  const onLeftMove = event => {
    if (!leftState.dragging) return;
    const root = leftState.root;
    if (!root?.isConnected) return;
    const aside = root.querySelector("aside.dframe-sidebar");
    const width = event.clientX + leftState.grip - (aside?.getBoundingClientRect().left ?? 0);
    applyLeft(root, Math.min(leftState.max, Math.max(leftState.floor, width)));
  };
  const onLeftUp = () => {
    if (!leftState.dragging) return;
    leftState.dragging = false;
    leftState.forced = false;
    const value = Number.parseFloat(leftState.root?.style?.getPropertyValue(LEFT_VARIABLE) ?? "");
    storeLeft(leftState.root?.hasAttribute(LEFT_ATTRIBUTE) && Number.isFinite(value) ? value : null);
    scheduleLayout();
  };
  const onLeftReset = event => {
    if (!event.target?.closest?.(LEFT_RAIL_SELECTOR)) return;
    leftState.forced = false;
    applyLeft(leftRoot(), null);
    storeLeft(null);
  };
  // Сохранённая ширина — на каждом проходе раскладки: корень Claude пересобирает.
  // С WF166 переключатель в строке окна — своя ширина не уже пола: узкая панель (190 до WF166)
  // раздвигается ровно настолько, чтобы переключатель не свешивался на ленту.
  // С WF277 (#10644) у открытой панели в строке «Hide sidebar» стоит кнопка «PMP» панели материалов: панель не ýже,
  // чем нужно ей (dockLeftFloor раздела 12п⁴), — и сверх минимума Claude; своей ширины нет — держим эту, не запоминая.
  const restoreLeft = () => {
    if (leftState.dragging) return;
    const root = leftRoot();
    if (!root) return;
    const aside = root.querySelector("aside.dframe-sidebar");
    const open = Boolean(aside) && !root.hasAttribute("data-collapsed");
    let need = 0;
    try { need = open ? dockLeftFloor(aside) : 0; } catch { need = 0; }
    const own = root.hasAttribute(LEFT_ATTRIBUTE) && !leftState.forced ? Number.parseFloat(root.style.getPropertyValue(LEFT_VARIABLE)) : readStoredLeft();
    if (own == null || !Number.isFinite(own)) {
      if (need > 0 && (leftState.forced || aside.getBoundingClientRect().width < need)) {
        if (Number.parseFloat(root.style.getPropertyValue(LEFT_VARIABLE)) !== need) applyLeft(root, need);
        leftState.forced = true;
      } else if (leftState.forced) { applyLeft(root, null); leftState.forced = false; }
      return;
    }
    leftState.forced = false;
    const floor = open ? leftFloor(aside) : 0;
    const max = Math.max(leftState.min, leftMaxOf(root.querySelector(LEFT_RAIL_SELECTOR)));
    const width = Math.min(max, Math.max(own, Math.min(leftState.min, floor), need));
    if (!root.hasAttribute(LEFT_ATTRIBUTE) || width !== own) applyLeft(root, width);
    if (width !== own && width !== need) storeLeft(width);
  };
  // Переключатель Claude/Code в строке окна (WF166, #9164): левый край — правый край «вперёд»
  // плюс зазор групп, по высоте — по центру кнопок окна; в точках боковой панели (она держит
  // position: absolute). Место — замером, а не числом: в режиме Chat строка у Claude своя.
  const placeModeSwitch = () => {
    const root = document.documentElement.style;
    const put = (name, value) => {
      if (value == null) { if (root.getPropertyValue(name)) root.removeProperty(name); return; }
      if (root.getPropertyValue(name) !== value) root.setProperty(name, value);
    };
    const frame = leftRoot();
    const aside = frame && !frame.hasAttribute("data-collapsed") ? frame.querySelector("aside.dframe-sidebar") : null;
    const back = aside?.querySelector?.('.df-titlebar .df-chrome-btn[aria-label="Forward"],.df-titlebar .df-chrome-btn[aria-label="Вперед"]')?.getBoundingClientRect();
    const mode = aside?.querySelector?.('.df-titlebar [role="radiogroup"][aria-label="Mode"],.df-titlebar [role="radiogroup"][aria-label="Режим"]');
    const box = aside?.getBoundingClientRect();
    if (!mode || !back || !(back.width > 0) || !box) {
      put(SIDE_SWITCH_LEFT_VARIABLE, null);
      put(SIDE_SWITCH_TOP_VARIABLE, null);
      cornerState.switch = null;
      return;
    }
    const left = Math.round(back.right - box.left + LEFT_BUTTONS_GAP);
    const top = Math.round(back.top - box.top + (back.height - MODE_BUTTON) / 2);
    put(SIDE_SWITCH_LEFT_VARIABLE, `${left}px`);
    put(SIDE_SWITCH_TOP_VARIABLE, `${top}px`);
    cornerState.switch = { left, top, size: MODE_BUTTON };
  };
  track(() => {
    const root = document.documentElement.style;
    root.removeProperty(SIDE_SWITCH_LEFT_VARIABLE);
    root.removeProperty(SIDE_SWITCH_TOP_VARIABLE);
  });
  track(() => {
    leftState.dragging = false;
    leftState.forced = false;
    try { applyLeft(leftState.root ?? leftRoot(), null); } catch {}
  });
  HATCH && Object.assign(HATCH, { leftFloor });

  // ---- 2е. Папка проекта у закреплённых чатов (#7102, WF82) ----------------
  // Слово Элвиса 22.09: у закреплённых «непонятно, к кому относится… папку в
  // начале имени, как в шапке». Список Recents в Claude Code разбит по проектам,
  // а Pinned — плоский. Имя берём там же, откуда его берёт шапка: у строки в
  // React-волокне лежит сессия (roamSession, раздел 12е), в ней source.data —
  // имя репозитория (repoInfo.name, его и показывает чип шапки) и папка (cwd).
  // Нет ни того, ни другого — чипа нет.
  //
  // Рисует CSS (правило в разделе 4): атрибут на подписи строки и ::before с
  // attr(). Текст строки не трогаем: первую строку innerText читают
  // переименование и сверка заголовка «Нового окна» (newWindowRowTitle) и обход
  // 12е, а сгенерированный ::before в innerText не попадает. Подпись React
  // пересоздаёт — атрибут ставится заново в каждом проходе раскладки (раздел 9),
  // своего наблюдателя и таймера у раздела нет.
  const PINNED_FOLDER_ATTRIBUTE = "data-myclaude-folder";
  const PINNED_LABEL_SELECTOR = "[data-row-label] > .dframe-fade-label";
  const PINNED_FOLDER_MAX = 80;
  // Настройка «Закреплённые» (#8743, слово Элвиса 04.10: «настройку, чтобы эти
  // штучки можно было отключить… название проекта и таймер»): команда
  // `pinned-look` {folder: true|false} всем окнам; в localStorage
  // лежит только «выключено» — нет ключа значит показывать, как было до настройки.
  // Выключенный чип снимает тот же проход раскладки, что ставит. Часиков у закреплённых с
  // page-64 нет (см. ниже): поле clock команды принимается и ничего не меняет.
  const PINNED_OFF_KEYS = { folder: "myclaude.pinnedFolderOff" };
  const pinnedShows = part => {
    try { return localStorage.getItem(PINNED_OFF_KEYS[part]) !== "1"; } catch { return true; }
  };
  const pinnedFolderName = (row, id) => {
    const data = roamSession(row, id)?.source?.data;
    const repo = typeof data?.repoInfo?.name === "string" ? data.repoInfo.name.trim() : "";
    return (repo || newWindowFolderName(typeof data?.cwd === "string" ? data.cwd : "")).slice(0, PINNED_FOLDER_MAX);
  };
  // Цвет плашки проекта у закреплённых (#7213) и у заголовков групп проектов (#7244) снят словом
  // Элвиса 11.10 01:40: «названия проектов не надо цветом выводить… сделай маленькими… чтоб они
  // оставались, но были маленькими, не мешались» — имя папки без цвета и плашки, мелко и тихо
  // (правило раздела 4); заголовки групп — как у Claude.
  const markPinnedFolders = () => {
    if (!isMainWindow()) return;
    const shown = pinnedShows("folder");
    for (const row of document.querySelectorAll(`${NEW_WINDOW_PINNED_SELECTOR} [data-row-key^="code:local_"]`)) {
      const label = row.querySelector(PINNED_LABEL_SELECTOR);
      if (!label) continue;
      const id = String(row.getAttribute("data-row-key") ?? "").split(":").pop() ?? "";
      const name = shown ? pinnedFolderName(row, id) : "";
      if (name) {
        if (label.getAttribute(PINNED_FOLDER_ATTRIBUTE) !== name) label.setAttribute(PINNED_FOLDER_ATTRIBUTE, name);
      } else if (label.hasAttribute(PINNED_FOLDER_ATTRIBUTE)) label.removeAttribute(PINNED_FOLDER_ATTRIBUTE);
    }
  };
  track(() => {
    for (const node of document.querySelectorAll(`[${PINNED_FOLDER_ATTRIBUTE}]`)) node.removeAttribute(PINNED_FOLDER_ATTRIBUTE);
  });
  // Часики кеша у закреплённых (#7912, WF102: «60:00 → 0:00» левее чипа папки) сняты целиком — слово
  // Элвиса 11.10 01:40: «отключи вот этот таймер… таймеры убери, это уже неактуальная тема». Узла у них
  // не было: метки на подписи строки и правила раздела 4; метки и ключ настройки прошлой страницы
  // убирает раздел 3. Отсчёт часа остался одному углу «Проект · чат» (раздел 2ж): его и считают.
  const PINNED_CLOCK_ATTRIBUTE = "data-myclaude-clock";
  const PINNED_CLOCK_LATE_ATTRIBUTE = "data-myclaude-clock-late";
  const PINNED_CLOCK_OFF_KEY = "myclaude.pinnedClockOff";
  const PINNED_CLOCK_HOUR_MS = 3600000;
  // Остаток часа в секундах → «59:07».
  const pinnedClockText = left => `${Math.floor(left / 60)}:${String(left % 60).padStart(2, "0")}`;
  // Поле folder команды — true|false (булево или строкой); поля нет или оно другое — ничего
  // не меняется. Ответ виден сразу, не дожидаясь прохода раскладки.
  const runPinnedLookCommand = detail => {
    for (const part of Object.keys(PINNED_OFF_KEYS)) {
      const value = String(detail?.[part]);
      if (value !== "true" && value !== "false") continue;
      try {
        if (value === "true") localStorage.removeItem(PINNED_OFF_KEYS[part]);
        else localStorage.setItem(PINNED_OFF_KEYS[part], "1");
      } catch {}
    }
    try { markPinnedFolders(); } catch {}
  };
  // Секундный тик ведёт часики угла (раздел 2ж, #7943): markCornerClock объявлен
  // ниже, но зовётся только из таймера — к тому времени он уже есть.
  const pinnedClockTimer = setInterval(() => {
    try { markCornerClock(); } catch {}
    // Края прокрутки живого вида (WF185): лента выросла без прокрутки — нижнее затухание.
    try { scrollFadeScan(); } catch {}
  }, 1000);
  track(() => clearInterval(pinnedClockTimer));
  // «Закреплённые» (#8743, раздел 2е): показывается ли имя папки (часиков с page-64 нет).
  statusPart("pinnedLook", () => ({ folder: pinnedShows("folder") }));

  // ---- 2ж. Угол «Проект · чат» и главное окно без шапки (#7911, #7913, WF102) ----
  // #7911 (слово Элвиса 26.09, приоритет номер один): «чтобы всегда в правом углу
  // это место было занято под название проекта… заголовок чата — аккуратненько там
  // же справа… как плавающий элемент… фейд какой-то наложить». В КАЖДОМ окне Claude
  // правый верхний угол — своя плашка в body: имя проекта целиком, чат — сколько
  // влезет, хвост — многоточием; фон — сплошной цвет фона окна (тема). WF103,
  // решение 12 (слово Элвиса 27.09: «этот фейд… сильно отвлекает глаза… тем же
  // цветом, что и чат… полоску… к самому верху прижимать… текст… максимально
  // близко к верхнему краю»): без затухания, плашка у верхнего края окна. Мышь её не ловит, окно таскать не мешает (без app-region), слой
  // ниже меню Claude (у них z 50) и попапов Пимпа. Стили — в самом узле: CSP
  // страницы нашу таблицу может не пустить (довод раздела 2б).
  // Имя проекта — как у чипа закреплённых (pinnedFolderName: репозиторий, иначе
  // папка) по строке своего чата в списке слева; строки нет (попап, список свёрнут)
  // — подпись плашки проекта в шапке Claude: она показывает то же имя репозитория,
  // а узел шапки жив и в главном окне без шапки (он только сжат). Чат —
  // [data-pane-title]: в главном окне document.title — «Claude» (живьём 26.09).
  // Дубль имени проекта в шапке прозрачен, пока угол виден (нажатия — ⋮ и меню
  // папки правым кликом — остаются); название чата в шапке прячется, только когда
  // угол на него наехал («дубль убрать, только если мешает», решение 2 плана WF102).
  const CORNER_ID = "myclaude-corner";
  const MAIN_DRAG_ID = "myclaude-main-drag";
  const CORNER_ATTRIBUTE = "data-myclaude-corner";
  const CORNER_TITLE_SELECTOR = ".epitaxy-titlebar [data-pane-title]";
  const CORNER_ORIGIN_SELECTOR = '.epitaxy-titlebar [data-testid="epitaxy-origin-label"]';
  // Плашка прижата к верху окна (top 0), текст по центру её 20 px — у самого края.
  const CORNER_HEIGHT = 20;
  // Слева от угла — место под кнопки окна: в окне 282 угол не шире 198.
  const CORNER_KEEP_LEFT = 84;
  // #9054 (слово Элвиса 08.10: «в правом верхнем углу жутко выглядит… слева, вот
  // где New, над New… красивой типографикой… название проекта, там название чата и
  // таймер… если эта штука свёрнута… там, где Remote Control»). Три места одного
  // узла: side — главное окно, список чатов открыт: над кнопкой New, место ей
  // даёт отступ сверху у списка (правило layoutCss; в дерево React узлов не
  // вставляем); row — список свёрнут или попап: строка шапки правее Remote Control,
  // поверх прозрачных названия и плашки проекта (нажатия — их, меню открывается);
  // corner — прежний угол, когда нет ни того ни другого (узкое окно без шапки).
  // WF209 (#9257, слово Элвиса 10.10 00:45: «сверху вот этот заголовок маленький… он должен крупненько
  // там быть по красоте»; 02:07 — эталон: крупное название чата в шапке колонки, значок справа).
  // Четвёртое место — head: широкий вид, списка над New нет, шапка колонки над полем есть. С WF179
  // значок Remote Control стоит у ПРАВОГО края шапки, строка «правее значка» там не набиралась (12 px),
  // угол падал в полоску corner и через cover гасил родное название 16/600. В head название видно
  // всегда (cover и row там не бывает), а угол — только проект и часики мелким тихим надзаголовком
  // над названием, по левой линии его текста (она же линия текста поля); имя чата в углу не дублируется.
  const CORNER_NEW_SELECTOR = 'button[aria-keyshortcuts="Meta+n"]';
  const CORNER_GUTTER_SELECTOR = '[data-testid="epitaxy-origin-gutter"]';
  // Ритм левой колонки (#9147, слово Элвиса 08.10 23:25: «выровнять всё… название чата и проекта
  // должно быть больше… типографика должна быть очень красивая»): от верха списка 4 — название
  // проекта 20 px и чат 14 px (две строки, 44), 8 — до New (у Claude над ним ещё свои 4). Левый
  // край обоих — линия значков New/Projects. Переключатель Claude/Code с WF166 — в строке окна.
  const CORNER_SIDE_TOP = 4;
  const CORNER_SIDE_TEXT = 44;
  const CORNER_SIDE_BOTTOM = 8;
  // WF190: правый край текста — на 4 левее правого края строк списка (их подложки); подсветка имени чата
  // под курсором выходит на эти 4 вправо и на 11 влево (поле строки Claude) — ровно в рамку подложки
  // строки списка: одна правая и одна левая граница колонки.
  const CORNER_SIDE_RIGHT = 12;
  // WF190 (слово Элвиса 09.10 03:50: «Разреши в две строки писать. Название чата можно и в три строки…
  // должен быть перенос, чтобы не вылезать справа: портит принцип приближенности»): имя чата над New
  // переносится по словам до трёх строк (14 px × 1.35 ≈ 19 на строку), хвост третьей затухает.
  const CORNER_SIDE_CHAT_LINES = 3;
  const CORNER_SIDE_CHAT_LINE = 19;
  const CORNER_LINES_MASK = {
    image: "linear-gradient(#000, #000), linear-gradient(to right, #000 calc(100% - 48px), transparent 100%)",
    size: "100% calc(100% - 1.35em), 100% 1.35em", position: "0 0, 0 100%", repeat: "no-repeat",
  };
  // Линия значков: кружок «+» у New, иначе слот значка; нет и его — поле строки Claude.
  const CORNER_LINE_SELECTOR = ".df-new-circle, .df-leading-slot, [data-cds=\"Icon\"]";
  const CORNER_LINE_FALLBACK = 10;
  // Часики (#9144, слово Элвиса 08.10 23:25: «таймер… поменьше… 10 минут — жёлтым… 5 минут —
  // красным. И тикать, и жирненьким стать»): ступени по оставшимся секундам.
  const CORNER_CLOCK_WARN_S = 600;
  const CORNER_CLOCK_ALARM_S = 300;
  const CORNER_CLOCK_ATTRIBUTE = "data-myclaude-clock";
  const CORNER_CLOCK_LOOKS = {
    calm: { color: "inherit", opacity: "0.5", "font-weight": "400" },
    warn: { color: "#f0c049", opacity: "1", "font-weight": "500" },
    alarm: { color: "#ff6b6b", opacity: "1", "font-weight": "700" },
    out: { color: "#ff6b6b", opacity: "1", "font-weight": "700" },
  };
  // Уже 150 строку шапки не делим: имя проекта с часиками не влезет целиком — прежний угол.
  const CORNER_ROW_MIN = 150;
  const cornerState = { on: false, project: "", chat: "", cover: false, clock: null, late: false, stage: null, mode: null, line: null, switch: null, lines: null, menu: null };
  const cornerNode = document.createElement("div");
  cornerNode.id = CORNER_ID;
  cornerNode.setAttribute("aria-hidden", "true");
  // Часики кеша (#7943, слово Элвиса 27.09: «в каждом чате… в одном и том же
  // месте, предсказуемо видеть время»); пороги — как у закреплённых
  // (pinnedClockText, раздел 2е). #9106 (слово Элвиса 08.10: «чтобы таймер был
  // возле… названия проекта, и чтобы таймер был маленьким») — сразу за именем
  // проекта в его строке, мелко и тихо, во всех трёх местах. Порядок в DOM
  // прежний (проект, чат, часики) — на месте их ставит order.
  const cornerClock = document.createElement("span");
  const cornerProject = document.createElement("b");
  const cornerChat = document.createElement("span");
  const cornerDot = document.createElement("i");
  cornerDot.textContent = "·";
  cornerChat.appendChild(cornerDot);
  const cornerChatText = document.createElement("span");
  cornerChat.appendChild(cornerChatText);
  cornerNode.appendChild(cornerProject);
  cornerNode.appendChild(cornerChat);
  cornerNode.appendChild(cornerClock);
  const cornerStyle = (node, props) => { for (const [name, value] of Object.entries(props)) node.style.setProperty(name, value); };
  cornerStyle(cornerNode, {
    position: "fixed", display: "none", "align-items": "center", "justify-content": "flex-end",
    "box-sizing": "border-box", top: "0px", right: "0px", height: `${CORNER_HEIGHT}px`,
    "max-width": `calc(100vw - ${CORNER_KEEP_LEFT}px)`, padding: "0 12px 0 8px",
    "pointer-events": "none", "user-select": "none", "-webkit-user-select": "none", "z-index": "30",
    font: "11px/1 -apple-system, system-ui, sans-serif", "white-space": "nowrap", color: "inherit",
    background: "var(--myclaude-corner-bg, transparent)",
  });
  // Имя проекта не сжимается никогда — сжимается чат. С WF185 (слово Элвиса 09.10 03:35: «должно быть
  // так же, как в Today — затемняется, фейд уходит») хвост не многоточием, а затуханием, как у строк
  // списка слева: маску ставит cornerFadeEnd, только когда текст правда не влез.
  cornerStyle(cornerProject, { flex: "0 0 auto", "font-weight": "600", opacity: "0.92" });
  cornerStyle(cornerChat, { flex: "0 1 auto", "min-width": "0", overflow: "hidden", "text-overflow": "clip", opacity: "0.62" });
  cornerStyle(cornerDot, { "font-style": "normal", padding: "0 5px" });
  // Вид каждого места (#9054) — полный набор свойств, смена места их переписывает.
  // side и row — сетка в две строки: «Проект 59:49», ниже — чат (#9106). Сетка, а
  // не перенос флекса: флекс с переносом при длинном имени сбрасывал бы часики на
  // свою строку; колонка minmax(0, max-content) режет имя, а колонка часиков не уже их
  // текста — часики всегда видны и всегда рядом с именем.
  // WF185 (слово Элвиса 09.10 03:20: «где название проекта, папки? Там же было»): чат во всю
  // строку (grid-column 1 / -1) отдавал свою ширину колонкам — длинное имя чата уходило в
  // колонку часиков (max-content), колонка проекта (минимум 0) сжималась в ноль, и «Rick»
  // пропадал при любом длинном чате (живьём: проект 0 px, часики 210, чат 218 при угле 189 —
  // он же «вылезал» за список слева). Чат теперь в размер колонок не вкладывается (contain:
  // inline-size) и берёт ширину сетки, а сетка во всю ширину угла: часики — 1fr у левого края.
  // corner — прежняя полоска; фон под ней размыт (#9054: в узких окнах сплошная
  // полоса «накладывается» на живой фон и текст ленты).
  const cornerLooks = (() => {
    const two = (project, chat, clock, lines = 0, quiet = "0.92") => ({
      display: "grid",
      node: {
        "grid-template-columns": "minmax(0, max-content) minmax(max-content, 1fr)", "align-items": "baseline",
        "flex-wrap": "nowrap", "align-content": "center", "justify-content": "start", height: "auto",
        "max-width": "none", padding: "0", font: `${project}px/1.3 -apple-system, system-ui, sans-serif`,
        background: "transparent", "border-bottom-left-radius": "0", "-webkit-backdrop-filter": "none",
      },
      // WF197: имя проекта кликабельно (родные меню проекта, cornerOriginOpen); подсветка — как у чата.
      // WF204: и в строке шапки (широкий вид) — меню проекта открывает имя, а не невидимая плашка у края.
      project: {
        flex: "", "min-width": "0", overflow: "hidden", "text-overflow": "clip", "letter-spacing": project >= 18 ? "-0.02em" : "-0.01em", "line-height": "1.25",
        "pointer-events": "auto", cursor: "pointer", "-webkit-app-region": "no-drag", margin: lines ? "0 -4px 0 -11px" : "", padding: lines ? "0 4px 0 11px" : "",
        "border-radius": lines ? "6px" : "4px", transition: "background-color 120ms ease-out", opacity: quiet,
      },
      chat: {
        flex: "", order: "3", "grid-column": "1 / -1", contain: "inline-size", "font-size": `${chat}px`, "line-height": "1.35", "font-weight": "400",
        // WF190: над New — перенос по словам до lines строк, имя кликабельно (меню чата Claude); в строке шапки — одна строка.
        "white-space": lines ? "normal" : "nowrap", "overflow-wrap": lines ? "break-word" : "", "max-height": lines ? `${Math.round(lines * 135) / 100}em` : "",
        "pointer-events": lines ? "auto" : "", cursor: lines ? "pointer" : "", margin: lines ? "0 -4px 0 -11px" : "", padding: lines ? "0 4px 0 11px" : "",
        "border-radius": lines ? "6px" : "", transition: lines ? "background-color 120ms ease-out" : "",
      },
      dot: { display: "none" },
      clock: { "font-size": `${clock}px`, "justify-self": "start" },
    });
    return {
      corner: {
        display: "flex",
        node: {
          "grid-template-columns": "", "align-items": "center",
          "flex-wrap": "nowrap", "align-content": "normal", "justify-content": "flex-end", height: `${CORNER_HEIGHT}px`,
          "max-width": `calc(100vw - ${CORNER_KEEP_LEFT}px)`, padding: "0 12px 0 8px", font: "11px/1 -apple-system, system-ui, sans-serif",
          background: "var(--myclaude-corner-bg, transparent)", "border-bottom-left-radius": "8px", "-webkit-backdrop-filter": "blur(12px)",
        },
        // WF204: имя проекта в углу — то же меню проекта, что над New (cornerOriginOpen).
        project: {
          flex: "0 0 auto", "min-width": "", overflow: "", "text-overflow": "", "letter-spacing": "", "line-height": "",
          "pointer-events": "auto", cursor: "pointer", "-webkit-app-region": "no-drag", margin: "", padding: "", "border-radius": "4px", transition: "background-color 120ms ease-out", opacity: "0.92",
        },
        chat: {
          flex: "0 1 auto", order: "2", "grid-column": "", contain: "", "font-size": "", "line-height": "", "font-weight": "",
          "white-space": "", "overflow-wrap": "", "max-height": "", "pointer-events": "", cursor: "", margin: "", padding: "", "border-radius": "", transition: "",
        },
        dot: { display: "" },
        clock: { "font-size": "10px", "justify-self": "" },
      },
      side: two(CORNER_SIDE_PROJECT_FONT, 14, 10, CORNER_SIDE_CHAT_LINES),
      row: two(13, 11, 10),
      // WF209 (#9257): «Проект 59:49» одной тихой строкой за названием колонки; имени чата в углу нет
      // (оно — само родное название рядом; его display гасит placeCorner).
      head: two(CORNER_HEAD_FONT, 11, 10, 0, CORNER_HEAD_OPACITY),
    };
  })();
  const cornerLook = mode => {
    if (cornerState.mode === mode) return;
    cornerState.mode = mode;
    const look = cornerLooks[mode];
    cornerStyle(cornerNode, look.node);
    cornerStyle(cornerProject, look.project);
    cornerStyle(cornerChat, look.chat);
    cornerStyle(cornerDot, look.dot);
    cornerStyle(cornerClock, look.clock);
    // Подсветка наведения — только над New (WF190): сменилось место — снимаем.
    if (mode !== "side" && cornerChat.style.getPropertyValue("background-color")) cornerChat.style.removeProperty("background-color");
    if (cornerProject.style.getPropertyValue("background-color")) cornerProject.style.removeProperty("background-color");
  };
  // Где стоять (#9054): место и рамка узла в точках окна.
  const cornerSpot = () => {
    const box = node => {
      try { return node?.isConnected ? node.getBoundingClientRect() : null; } catch { return null; }
    };
    if (isMainWindow()) {
      const bar = document.querySelector('[data-testid="sidebar"]');
      const newNode = bar?.querySelector?.(CORNER_NEW_SELECTOR);
      const next = box(newNode);
      const list = box(bar);
      const panel = box(document.querySelector(".epitaxy-chat-panel"));
      // Список пристыкован (панель чата правее него), а не всплыл поверх ленты. Свёрнутая панель (`data-collapsed`)
      // — не пристыкована, даже если лента правее списка: её сдвинула панель материалов (#10644, WF277), а список
      // прозрачен за левым краем — угол уходил под светофор.
      const collapsed = document.querySelector(".dframe-root")?.getAttribute?.("data-collapsed") === "true";
      if (next && list && panel && next.width > 0 && !collapsed && panel.left >= list.right - 1) {
        // #9147: одна вертикаль — значки New/Projects; по ней проект и чат.
        // Сам кружок «+» (на линии значков Projects/Artifacts), а не обёртка .df-leading-slot — она левее
        // на 3 px (замер 08.10: обёртка 14, кружок 17); querySelector со списком отдаёт первую по документу.
        const icon = box(newNode.querySelector?.(".df-new-circle") ?? newNode.querySelector?.(CORNER_LINE_SELECTOR));
        // +2: видимый край значков (Projects, Artifacts) правее рамки кружка на 2 px — выравниваем по глазу (снимок 08.10).
        const line = icon && icon.width > 0 ? icon.left + 2 : next.left + CORNER_LINE_FALLBACK;
        return {
          mode: "side", left: line, top: list.top + CORNER_SIDE_TOP, width: Math.max(0, list.right - CORNER_SIDE_RIGHT - line), height: CORNER_SIDE_TEXT,
          space: CORNER_SIDE_TOP + CORNER_SIDE_TEXT + CORNER_SIDE_BOTTOM,
        };
      }
    }
    // WF209 (#9257): шапка колонки широкого вида (не перенесённая влево) с названием чата — место head:
    // строка над названием, от левой линии его текста до правого края значка Remote Control (края поля).
    const chatPanel = document.querySelector(".epitaxy-chat-panel");
    const title = document.querySelector(CORNER_TITLE_SELECTOR);
    const head = title?.closest?.(".epitaxy-titlebar") ?? null;
    const titleBox = box(title);
    const headBox = box(head);
    if (titleBox && headBox && titleBox.width > 0 && titleBox.height > 0 && headBox.height > 0 &&
        wideLayout(chatPanel) && !titleGoesLeft(chatPanel, true)) {
      // Слово Элвиса 10.10 03:55 про page-51 («здоровенная полоса… интерфейс же лёгким должен быть… мне
      // она не нужна»): шапка не растёт. Проект и часики — тихо в строке самого названия, сразу за его
      // текстом и до значка Remote Control; названию места не хватает — им места нет, название важнее.
      // #10146 (Claude 2.42304): справа в шапке — кнопки Terminal, Changes, Browser, Files, View options; край —
      // самая левая из того, что правее названия (значок Remote Control или кнопка), иначе угол наезжал на них.
      const ends = [...head.querySelectorAll(`${CORNER_GUTTER_SELECTOR}, button`)].map(box)
        .filter(item => item && item.width > 0 && item.left >= titleBox.right).map(item => item.left);
      const end = (ends.length ? Math.min(...ends) : headBox.right) - CORNER_HEAD_GAP;
      const left = titleBox.right + CORNER_HEAD_GAP;
      return { mode: "head", left, top: titleBox.top, width: Math.max(0, end - left), height: titleBox.height };
    }
    const gutter = document.querySelector(`.epitaxy-titlebar ${CORNER_GUTTER_SELECTOR}`);
    const titlebar = gutter?.closest?.(".epitaxy-titlebar") ?? null;
    const lead = box(gutter);
    const bar = box(titlebar);
    if (lead && bar && lead.width > 0 && lead.height > 0 && bar.height > 0) {
      // Пока открыто меню проекта с имени (WF204), плашка стоит на имени (ORIGIN_OPEN_ATTRIBUTE) — край
      // строки берём прежний, иначе строка сжалась бы до имени и угол уехал бы из-под меню.
      const open = document.documentElement.hasAttribute(ORIGIN_OPEN_ATTRIBUTE) && cornerState.rowEnd != null;
      const pill = open ? null : box(titlebar.querySelector('[data-testid="epitaxy-origin-label"]')?.closest?.("button"));
      const end = open ? cornerState.rowEnd : pill && pill.width > 0 ? pill.right : bar.right - 8;
      cornerState.rowEnd = end;
      const left = lead.right + 4;
      if (end - left >= CORNER_ROW_MIN) return { mode: "row", left, top: bar.top, width: end - left, height: bar.height };
    }
    return { mode: "corner" };
  };
  // Часики не сжимаются и стоят сразу за именем (order 1, #9106): шрифт окна, не
  // моноширинный (с ним часики выглядели плохо), цифры одной ширины, тихие, 10–11 px.
  cornerStyle(cornerClock, {
    display: "none", flex: "0 0 auto", order: "1", "margin-left": "8px", "white-space": "nowrap",
    "font-weight": "400", "font-variant-numeric": "tabular-nums", "letter-spacing": "0.01em",
    color: "inherit", opacity: "0.5",
  });
  // Сироты упавшей установки — до вставки своих (раздел 3 идёт уже после неё).
  for (const orphan of document.querySelectorAll(`#${CORNER_ID}, #${MAIN_DRAG_ID}`)) orphan.remove();
  (document.body ?? document.documentElement).appendChild(cornerNode);
  track(() => cornerNode.remove());
  // WF190 (слово Элвиса 09.10 03:50: по нажатию на имя чата должно открываться то же самое меню,
  // что при нажатии наверху (Open in, Rename, Fork…), — это тоже название чата): имя чата
  // над New жмёт родную кнопку меню названия в шапке колонки (TITLE_MENU_SELECTOR, «More options for…»)
  // тем же нажатием, что и мышь (pressLikeMouse, раздел 12з) — меню Claude встаёт у своей кнопки.
  // Меню уже открыто — наше нажатие его закрыло (Claude закрывает по нажатию мимо), второй раз не
  // открываем. Только над New: в строке шапки угол прозрачен для мыши, жмут сами родные кнопки.
  const cornerMenuState = { wasOpen: false };
  // Та же кнопка, что у TITLE_MENU_SELECTOR (сосед «~» обёртки названия), — обходом соседей.
  const cornerMenuButton = () => {
    try {
      let node = document.querySelector(CORNER_TITLE_SELECTOR)?.parentElement?.nextElementSibling ?? null;
      while (node && node.tagName !== "BUTTON") node = node.nextElementSibling;
      return node;
    } catch { return null; }
  };
  const cornerHover = hot => {
    const value = hot && cornerState.mode === "side" ? "color-mix(in srgb, currentColor 10%, transparent)" : "";
    if (value) cornerSet(cornerChat, "background-color", value);
    else if (cornerChat.style.getPropertyValue("background-color")) cornerChat.style.removeProperty("background-color");
  };
  on(cornerChat, "pointerenter", () => cornerHover(true));
  on(cornerChat, "pointerleave", () => cornerHover(false));
  on(cornerChat, "pointerdown", () => {
    cornerMenuState.wasOpen = cornerMenuButton()?.getAttribute?.("aria-expanded") === "true";
  });
  on(cornerChat, "click", event => {
    if (cornerState.mode !== "side") return;
    try { event.preventDefault(); event.stopPropagation(); } catch {}
    const button = cornerMenuButton();
    const wasOpen = cornerMenuState.wasOpen;
    cornerMenuState.wasOpen = false;
    if (!button?.isConnected) { cornerState.menu = "no-button"; return; }
    if (wasOpen) { cornerState.menu = "closed"; return; }
    cornerState.menu = pressLikeMouse(button) ? "opened" : "no-button";
  });
  // Имя проекта над New (WF197, регресс WF185) — родные меню проекта Claude, как у плашки в шапке до
  // WF185 (#7334): левый клик — ⋮ шапки (Terminal / Changes / Browser, она привязана к плашке), правый —
  // меню самой плашки (Show in Finder / Change folder; так правый клик по плашке и работал, onOriginMenu).
  // Нажимаем родные кнопки тем же нажатием, что и мышь; плашку на время меню ставим на имя в углу
  // (ORIGIN_OPEN_ATTRIBUTE), чтобы меню встало у имени. Меню закрылось — плашка снова снята.
  const cornerOrigin = { timer: 0, at: 0, seen: false };
  const cornerOriginButtons = () => {
    try {
      const pill = document.querySelector(CORNER_ORIGIN_SELECTOR)?.closest?.("button") ?? null;
      // Группа названия — ребёнок шапки, в котором плашка; ⋮ — последняя кнопка-меню в группах правее.
      const bar = pill?.closest?.(".epitaxy-titlebar") ?? null;
      let lead = pill;
      while (lead && lead.parentElement !== bar) lead = lead.parentElement;
      let dots = null;
      for (let node = lead?.nextElementSibling; node; node = node.nextElementSibling) {
        const menus = [...node.children].filter(kid => kid.getAttribute?.("aria-haspopup") === "menu");
        if (menus.length) dots = menus.at(-1);
      }
      return { pill, dots };
    } catch { return { pill: null, dots: null }; }
  };
  const cornerOriginClose = () => {
    if (cornerOrigin.timer) { clearInterval(cornerOrigin.timer); cornerOrigin.timer = 0; }
    const root = document.documentElement;
    if (root.hasAttribute(ORIGIN_OPEN_ATTRIBUTE)) root.removeAttribute(ORIGIN_OPEN_ATTRIBUTE);
    root.style.removeProperty(ORIGIN_X_VARIABLE);
    root.style.removeProperty(ORIGIN_Y_VARIABLE);
  };
  track(cornerOriginClose);
  const cornerOriginOpen = (event, kind) => {
    try { event.preventDefault(); event.stopPropagation(); } catch {}
    const { pill, dots } = cornerOriginButtons();
    const button = kind === "finder" ? pill : dots ?? pill;
    if (!button?.isConnected) { cornerState.originMenu = "no-button"; return; }
    // Своё меню уже открыто — нажатие мимо его закрыло (как у имени чата), второй раз не открываем.
    if (cornerOrigin.timer && button.getAttribute?.("aria-expanded") === "true") { cornerOriginClose(); cornerState.originMenu = "closed"; return; }
    const root = document.documentElement;
    root.setAttribute(ORIGIN_OPEN_ATTRIBUTE, "");
    root.style.setProperty(ORIGIN_X_VARIABLE, "0px");
    root.style.setProperty(ORIGIN_Y_VARIABLE, "0px");
    try {
      const shell = pill.parentElement?.parentElement ?? pill;
      const from = shell.getBoundingClientRect();
      const to = cornerProject.getBoundingClientRect();
      if (from.width > 0 && to.width > 0) {
        root.style.setProperty(ORIGIN_X_VARIABLE, `${Math.round(to.left - from.left)}px`);
        root.style.setProperty(ORIGIN_Y_VARIABLE, `${Math.round(to.top - from.top)}px`);
      }
    } catch {}
    cornerState.originMenu = pressLikeMouse(button) ? (kind === "finder" ? "finder" : "project") : "no-button";
    if (cornerOrigin.timer) clearInterval(cornerOrigin.timer);
    // Меню было открыто и закрылось — плашку снимаем; не открылось вовсе — через 1,5 с.
    cornerOrigin.at = Date.now();
    cornerOrigin.seen = false;
    cornerOrigin.timer = setInterval(() => {
      const open = [pill, dots].some(node => node?.isConnected && node.getAttribute?.("aria-expanded") === "true");
      if (open) cornerOrigin.seen = true;
      else if (cornerOrigin.seen || Date.now() - cornerOrigin.at > 1500) cornerOriginClose();
    }, 250);
  };
  on(cornerProject, "pointerenter", () => cornerSet(cornerProject, "background-color", "color-mix(in srgb, currentColor 10%, transparent)"));
  on(cornerProject, "pointerleave", () => { if (cornerProject.style.getPropertyValue("background-color")) cornerProject.style.removeProperty("background-color"); });
  on(cornerProject, "click", event => cornerOriginOpen(event, "project"));
  on(cornerProject, "contextmenu", event => cornerOriginOpen(event, "finder"));
  track(() => { try { document.documentElement.removeAttribute(CORNER_ATTRIBUTE); } catch {} });
  // Отступ над New — переменная корня (#9147): правило layoutCss её читает.
  const cornerSideVars = spot => {
    const root = document.documentElement.style;
    const put = (name, value) => {
      if (value == null) { if (root.getPropertyValue(name)) root.removeProperty(name); return; }
      if (root.getPropertyValue(name) !== value) root.setProperty(name, value);
    };
    put(CORNER_SIDE_SPACE_VARIABLE, spot?.mode === "side" ? `${Math.round(spot.space)}px` : null);
    // WF209: у названия колонки (head) линия — левый край текста названия.
    cornerState.line = spot?.mode === "side" || spot?.mode === "head" ? Math.round(spot.left) : null;
  };
  track(() => { try { cornerSideVars(null); } catch {} });
  const cornerText = node => String(node?.textContent ?? "").replace(/\s+/g, " ").trim();
  // WF185 (класс «имя проекта пустое — угол пропадает»): у главного окна — строка своего чата, нет
  // её — подпись плашки проекта в шапке; у попапа наоборот (подпись — его собственная), а нет
  // подписи — строка своего чата в списке главного окна (window.opener, как у часиков).
  const cornerProjectName = () => {
    const main = isMainWindow();
    const label = () => cornerText(document.querySelector(CORNER_ORIGIN_SELECTOR)).slice(0, PINNED_FOLDER_MAX);
    if (!main) { const own = label(); if (own) return own; }
    const id = myChatId();
    if (id) {
      try {
        let doc = null;
        try { doc = main ? document : window.opener?.document; } catch {}
        const row = doc?.querySelector?.(`[data-testid="sidebar"] [data-row-key="code:${id}"]`);
        const name = row ? pinnedFolderName(row, id) : "";
        if (name) return name;
      } catch {}
    }
    return main ? label() : "";
  };
  const cornerChatTitle = () => {
    const pane = cornerText(document.querySelector(CORNER_TITLE_SELECTOR));
    if (pane) return pane.slice(0, 200);
    const title = windowTitle();
    return title && !THEME_TITLE_STUBS.has(title.toLowerCase()) ? title.slice(0, 200) : "";
  };
  const cornerHide = () => {
    cornerState.on = false;
    cornerState.lines = null;
    cornerState.cover = false;
    if (cornerNode.style.getPropertyValue("display") !== "none") cornerNode.style.setProperty("display", "none");
    if (document.documentElement.hasAttribute(CORNER_ATTRIBUTE)) document.documentElement.removeAttribute(CORNER_ATTRIBUTE);
    cornerSideVars(null);
  };
  const cornerSet = (node, name, value) => {
    if (node.style.getPropertyValue(name) !== value) node.style.setProperty(name, value);
  };
  // Фон окна: у тем Пимпа и у Claude он на body; прозрачный — берём корень.
  const cornerBackground = () => {
    const see = node => {
      try { return String(getComputedStyle(node).backgroundColor ?? "").trim(); } catch { return ""; }
    };
    const clear = color => !color || color === "transparent" || /^rgba\([^)]*,\s*0\)$/.test(color);
    // Живой фон слоя «Оформление» (WF139, #9104): плашка угла — только размытие, без сплошной заливки.
    if (themeState.look?.aurora === true) return "";
    // Живой фон картинкой (градиент) — сплошной полосой поверх не закрываем (#9054).
    // Под углом тогда только размытие.
    try {
      const image = document.body ? String(getComputedStyle(document.body).backgroundImage ?? "") : "";
      if (image && image !== "none") return "";
    } catch {}
    const body = document.body ? see(document.body) : "";
    if (!clear(body)) return body;
    const root = see(document.documentElement);
    return clear(root) ? "" : root;
  };
  // Время чата для часиков угла — updatedAtMs сессии его строки в списке слева,
  // то же поле, что у закреплённых. У попапа своего списка нет, но он открыт из
  // главного окна (разведка 27.09: window.opener — главное окно, его список
  // чатов виден попапу, строка своего чата в нём есть, волокно строки несёт ту же
  // сессию). Строки нет (список свёрнут, чат не показан) — источника нет, часиков нет.
  const cornerUpdatedAt = () => {
    const id = myChatId();
    if (!id) return 0;
    let doc = null;
    try { doc = isMainWindow() ? document : window.opener?.document; } catch {}
    const row = doc?.querySelector?.(`[data-testid="sidebar"] [data-row-key="code:${id}"]`);
    const last = row ? Number(roamSession(row, id)?.updatedAtMs) : 0;
    return last > 0 ? last : 0;
  };
  // Ступени (#9144): больше 10 минут — тихо; 10:00 и меньше — жёлтым; 5:00 и меньше — красным,
  // жирно и мягко «тикает» (пульс раз в секунду — правило листа по атрибуту, при «Уменьшить
  // движение» без пульса); время вышло — «вышло» красным, без пульса.
  const cornerClockStage = left => left <= 0 ? "out" : left <= CORNER_CLOCK_ALARM_S ? "alarm" : left <= CORNER_CLOCK_WARN_S ? "warn" : "calm";
  const markCornerClock = (nowMs = Date.now()) => {
    const last = cornerState.on ? cornerUpdatedAt() : 0;
    if (!last) {
      cornerState.clock = null;
      cornerState.late = false;
      cornerState.stage = null;
      cornerSet(cornerClock, "display", "none");
      if (cornerClock.hasAttribute(CORNER_CLOCK_ATTRIBUTE)) cornerClock.removeAttribute(CORNER_CLOCK_ATTRIBUTE);
      return;
    }
    const left = Math.max(0, Math.ceil((PINNED_CLOCK_HOUR_MS - (nowMs - last)) / 1000));
    const stage = cornerClockStage(left);
    const text = stage === "out" ? "вышло" : pinnedClockText(left);
    if (cornerClock.textContent !== text) cornerClock.textContent = text;
    for (const [name, value] of Object.entries(CORNER_CLOCK_LOOKS[stage])) cornerSet(cornerClock, name, value);
    if (cornerClock.getAttribute(CORNER_CLOCK_ATTRIBUTE) !== stage) cornerClock.setAttribute(CORNER_CLOCK_ATTRIBUTE, stage);
    cornerState.clock = text;
    cornerState.late = stage === "alarm" || stage === "out";
    cornerState.stage = stage;
    cornerSet(cornerClock, "display", "inline-block");
  };
  // Затухание хвоста (WF185): текст шире своего места — маска, влез — без маски. wrap (WF190, имя чата
  // над New в три строки): текст выше своих строк — первые строки целиком, хвост последней затухает.
  const cornerFadeEnd = (node, wrap = false) => {
    let over = false;
    try {
      over = wrap ? Number(node.scrollHeight) - Number(node.clientHeight) > 1 : Number(node.scrollWidth) - Number(node.clientWidth) > 1;
    } catch {}
    const look = !over ? null : wrap ? CORNER_LINES_MASK : { image: FADE_END_MASK, size: "", position: "", repeat: "" };
    for (const part of ["image", "size", "position", "repeat"]) {
      const value = look?.[part] ?? "";
      for (const name of [`-webkit-mask-${part}`, `mask-${part}`]) {
        if (value) cornerSet(node, name, value);
        else if (node.style.getPropertyValue(name)) node.style.removeProperty(name);
      }
    }
  };
  // Строк имени чата над New (WF190): по высоте текста, 1…3.
  const cornerChatLines = () => {
    if (!cornerState.chat) return 1;
    let height = 0;
    try { height = Number(cornerChat.scrollHeight); } catch {}
    return height > 0 ? Math.max(1, Math.min(CORNER_SIDE_CHAT_LINES, Math.round(height / CORNER_SIDE_CHAT_LINE))) : 1;
  };
  const placeCorner = () => {
    const project = themable ? cornerProjectName() : "";
    if (!project) { cornerHide(); return; }
    const chat = cornerChatTitle();
    if (cornerProject.textContent !== project) cornerProject.textContent = project;
    if (cornerChatText.textContent !== chat) cornerChatText.textContent = chat;
    cornerState.project = project;
    cornerState.chat = chat;
    const spot = cornerSpot();
    // #11676 (#11637, слово Элвиса 05.11: «справа в углу Рик написано… убери»): «Проект 59:06 · чат» справа
    // вверху (row, head, corner) не показывается, над New (side) — как был. Угол считается дальше (папка для
    // «здоровья», часики в status), метка корня "off": плашка проекта Claude в шапке спрятана, как при угле, а
    // название чата и кнопки попапа видны (правила cover/row/on их больше не гасят).
    if (spot.mode !== "side") {
      cornerLook(spot.mode);
      cornerSideVars(null);
      cornerState.lines = null;
      cornerState.on = true;
      cornerState.cover = false;
      cornerSet(cornerNode, "display", "none");
      if (document.documentElement.getAttribute(CORNER_ATTRIBUTE) !== "off") document.documentElement.setAttribute(CORNER_ATTRIBUTE, "off");
      markCornerClock();
      return;
    }
    // WF209: над названием колонки (head) имени чата в углу нет — оно крупно стоит прямо под ним.
    cornerSet(cornerChat, "display", chat && spot.mode !== "head" ? "block" : "none");
    cornerLook(spot.mode);
    if (spot.mode !== "corner") {
      cornerSet(cornerNode, "left", `${Math.round(spot.left)}px`);
      cornerSet(cornerNode, "top", `${Math.round(spot.top)}px`);
      cornerSet(cornerNode, "right", "auto");
      cornerSet(cornerNode, "width", `${Math.round(spot.width)}px`);
      // WF190: над New угол растёт на строки имени чата (ширина уже стоит — перенос по ней), отступ списка — с ним.
      cornerState.lines = spot.mode === "side" ? cornerChatLines() : null;
      if (cornerState.lines > 1) {
        spot.height += (cornerState.lines - 1) * CORNER_SIDE_CHAT_LINE;
        spot.space += (cornerState.lines - 1) * CORNER_SIDE_CHAT_LINE;
      }
      cornerSideVars(spot);
      cornerSet(cornerNode, "height", `${Math.round(spot.height)}px`);
      // head: за длинным названием места нет — проекта и часиков не видно вовсе (иначе часики, которым
      // сжиматься нельзя, вылезали на значок Remote Control; живьём 10.10 04:55).
      cornerSet(cornerNode, "display", spot.mode === "head" && spot.width < CORNER_HEAD_MIN ? "none" : cornerLooks[spot.mode].display);
      cornerState.on = true;
      cornerState.cover = false;
      if (document.documentElement.getAttribute(CORNER_ATTRIBUTE) !== spot.mode) document.documentElement.setAttribute(CORNER_ATTRIBUTE, spot.mode);
      markCornerClock();
      cornerFadeEnd(cornerProject);
      cornerFadeEnd(cornerChat, spot.mode === "side");
      return;
    }
    cornerSideVars(null);
    cornerState.lines = null;
    cornerSet(cornerNode, "left", "auto");
    cornerSet(cornerNode, "top", "0px");
    cornerSet(cornerNode, "width", "auto");
    // Верх — край окна (решение 12 WF103), правый край — по панели чата.
    let box = null;
    try {
      const panel = document.querySelector(".epitaxy-chat-panel");
      box = panel?.isConnected ? panel.getBoundingClientRect() : null;
    } catch {}
    const right = box && box.width > 0 ? Math.max(0, Math.round(innerWidth - box.right)) : 0;
    cornerSet(cornerNode, "right", `${right}px`);
    // Целиком в окне (#9272, класс «свой элемент у края режется»): угол отступил от правого края за панелью —
    // на столько же уже, иначе левый край уходил бы под кнопки окна и за левую кромку узкого окна.
    cornerSet(cornerNode, "max-width", `calc(100vw - ${CORNER_KEEP_LEFT + right}px)`);
    const bg = cornerBackground();
    if (bg) cornerSet(cornerNode, "--myclaude-corner-bg", bg);
    else if (cornerNode.style.getPropertyValue("--myclaude-corner-bg")) cornerNode.style.removeProperty("--myclaude-corner-bg");
    cornerSet(cornerNode, "display", "flex");
    cornerState.on = true;
    // Угол наехал на название чата в шапке — то прячется (см. layoutCss).
    let cover = false;
    try {
      const own = cornerNode.getBoundingClientRect();
      const title = document.querySelector(CORNER_TITLE_SELECTOR)?.getBoundingClientRect();
      cover = own.width > 0 && Boolean(title) && title.width > 0 && title.height > 0 &&
        title.right > own.left && title.top < own.bottom && title.bottom > own.top;
    } catch {}
    cornerState.cover = cover;
    const mark = cover ? "cover" : "on";
    if (document.documentElement.getAttribute(CORNER_ATTRIBUTE) !== mark) document.documentElement.setAttribute(CORNER_ATTRIBUTE, mark);
    markCornerClock();
    cornerFadeEnd(cornerChat);
  };

  // #7913 (слово Элвиса 26.09: «этот хедер нужно вообще убрать у главного… чтобы
  // по высоте освободить место»; кнопки окна — «пусть текст за ними ходит, фейд на
  // углы под цвет темы»). Только главное окно. Широкий вид: шапка всегда во второй
  // колонке, над полем ввода (applyTitleSide её влево не переносит), лента во всю
  // высоту. Узкий: шапка сжата до нуля и невидима (правило в layoutCss) — узел НЕ
  // убираем и не display:none: на нём держатся CHAT_FIBER_SELECTOR (кто этот чат) и
  // подпись проекта для угла. Меню названия (#7320) и ⋮ плашки проекта (#7334) в
  // узком главном окне уходят вместе с шапкой — переименовать можно из списка
  // чатов. Панель у левого края окна (список чатов свёрнут) — текст ленты под
  // кнопками окна затухает (applyCornerFade), а под самими кнопками — полоса, за
  // которую окно таскается: у главного окна своей там нет, была только шапка.
  const MAIN_HEADLESS_ATTRIBUTE = "data-myclaude-headless";
  const MAIN_DRAG_WIDTH = 76;
  const MAIN_DRAG_HEIGHT = 40;
  const mainHead = { panel: null, headless: false, drag: false };
  const mainDrag = document.createElement("div");
  mainDrag.id = MAIN_DRAG_ID;
  mainDrag.setAttribute("aria-hidden", "true");
  cornerStyle(mainDrag, {
    position: "fixed", display: "none", left: "0px", top: "0px",
    width: `${MAIN_DRAG_WIDTH}px`, height: `${MAIN_DRAG_HEIGHT}px`, "-webkit-app-region": "drag", "z-index": "29",
  });
  (document.body ?? document.documentElement).appendChild(mainDrag);
  track(() => mainDrag.remove());
  const clearMainHead = () => {
    try { mainHead.panel?.removeAttribute(MAIN_HEADLESS_ATTRIBUTE); } catch {}
    mainHead.panel = null;
    mainHead.headless = false;
  };
  track(clearMainHead);
  const applyMainHead = (panel, wide) => {
    const main = isMainWindow() && Boolean(panel?.isConnected);
    const headless = main && !wide;
    if (mainHead.panel && mainHead.panel !== panel) clearMainHead();
    if (headless) {
      mainHead.panel = panel;
      if (!panel.hasAttribute(MAIN_HEADLESS_ATTRIBUTE)) panel.setAttribute(MAIN_HEADLESS_ATTRIBUTE, "");
    } else if (panel?.hasAttribute?.(MAIN_HEADLESS_ATTRIBUTE)) panel.removeAttribute(MAIN_HEADLESS_ATTRIBUTE);
    mainHead.headless = headless;
    let left = Infinity;
    try { left = main ? panel.getBoundingClientRect().left : Infinity; } catch {}
    mainHead.drag = main && left < TITLEBAR_CLEARANCE_LEFT;
    cornerSet(mainDrag, "display", mainHead.drag ? "block" : "none");
  };
  statusPart("corner", () => ({
    on: cornerState.on && cornerNode.isConnected, project: cornerState.project || null,
    chat: cornerState.chat || null, cover: cornerState.cover,
    clock: cornerState.clock, late: cornerState.late, stage: cornerState.stage, mode: cornerState.mode,
    line: cornerState.line, switch: cornerState.switch ? { ...cornerState.switch } : null,
    // WF185: хвост имени проекта / чата затухает (не влез).
    tail: { project: Boolean(cornerProject.style.getPropertyValue("mask-image")), chat: Boolean(cornerChat.style.getPropertyValue("mask-image")) },
    // WF190: строк имени чата над New (null — не над New); чем кончилось нажатие на имя.
    lines: cornerState.lines, menu: cornerState.menu, originMenu: cornerState.originMenu ?? null,
  }));
  // Шапка (#7913): main — главное окно; headless — шапка сжата (узкий вид);
  // drag — полоса под кнопками окна; titleSide — шапка влево (только попапы).
  statusPart("head", () => ({
    main: isMainWindow(), headless: mainHead.headless, drag: mainHead.drag,
    titleSide: wideState.panel?.getAttribute?.(TITLE_SIDE_ATTRIBUTE) ?? null,
    // #9135: сдвиг значка шапки колонки до линии текста поля, px (null — не выравниваем).
    titleShift: titleAlign.shift,
    // WF185: отступ значка до правого края поля, px; хвост названия затухает (не влез).
    titleEnd: titleAlign.end, titleFade: titleAlign.fade,
  }));
  HATCH && Object.assign(HATCH, { markCornerClock });

  // ---- 2ж¹. Окно таскается за всю верхнюю полосу (#10984) ----------------------
  // Слово Элвиса 29.10.2026: «у пимпа вот там сверху не за что ухватиться сейчас… Слева, где закрыть, открыть, там
  // можно ухватиться. А где-то посередине сверху, например, вообще не хватается… вот эта вот вся область сверху».
  //
  // Почему так: это делает сам Пимп. У главного окна без шапки (раздел 2ж, #7913) шапка Claude — его полоса
  // перетаскивания — сжата до нуля, а взамен стоит только полоса 76×40 под кнопками окна (MAIN_DRAG_ID). Правее
  // кнопок окна таскать не за что: лента начинается от самого края (060, WF192), у Claude там лишь `.draggable` 7 px.
  //
  // Здесь: пока стоит полоса под кнопками (mainHead.drag), правее неё — своя полоса во всю ширину окна высотой
  // DRAG_STRIP_HEIGHT (верх ленты там всё равно затухает). Левый край — TITLEBAR_CLEARANCE_LEFT: между ними кнопка
  // Claude «Show sidebar» (82–110), её не накрываем. Узел — ПЕРВЫМ в body: Electron считает области окна в порядке
  // дерева, и позднее no-drag вырезает раннее drag, — все кнопки над полосой (угол «Проект · чат», PMP, галерея,
  // ручки поля, кнопки Claude) остаются нажимаемыми. Узел без id (метка DRAG_STRIP_ATTRIBUTE): нажатий у него нет,
  // слой как MAIN_DRAG_ID. Пропал из body (перерисовка) — вернётся на следующем проходе раскладки.
  const DRAG_STRIP_ATTRIBUTE = "data-myclaude-drag-strip";
  const DRAG_STRIP_ON_ATTRIBUTE = "data-myclaude-drag-strip-on";
  const DRAG_STRIP_HEIGHT = 28;
  const dragStrip = { node: null, on: false };
  for (const orphan of document.querySelectorAll(`[${DRAG_STRIP_ATTRIBUTE}]`)) orphan.remove();
  const dragStripMake = () => {
    const node = document.createElement("div");
    node.setAttribute(DRAG_STRIP_ATTRIBUTE, "");
    node.setAttribute("aria-hidden", "true");
    return node;
  };
  // Из прохода раскладки (раздел 4б, сразу после applyMainHead): показ — ровно когда стоит полоса под кнопками.
  const applyDragStrip = () => {
    // С 03.11.2026 полоса стоит у главного окна всегда (слово: «сверху перетягивание не работает»): между боковой
    // колонкой и окном чата у Claude — лишь `.draggable` 8 px.
    const on = isMainWindow();
    dragStrip.on = on;
    if (!on) {
      if (dragStrip.node?.hasAttribute(DRAG_STRIP_ON_ATTRIBUTE)) dragStrip.node.removeAttribute(DRAG_STRIP_ON_ATTRIBUTE);
      return;
    }
    const body = document.body;
    if (!body) return;
    dragStrip.node ??= dragStripMake();
    if (dragStrip.node.parentNode !== body) {
      try { body.insertBefore(dragStrip.node, body.firstChild); } catch { return; }
    }
    if (!dragStrip.node.hasAttribute(DRAG_STRIP_ON_ATTRIBUTE)) dragStrip.node.setAttribute(DRAG_STRIP_ON_ATTRIBUTE, "");
  };
  lateRules.push(
    `[${DRAG_STRIP_ATTRIBUTE}]{position:fixed;display:none;top:0;left:${TITLEBAR_CLEARANCE_LEFT}px;right:0;height:${DRAG_STRIP_HEIGHT}px;margin:0;padding:0;border:0;background:transparent;-webkit-app-region:drag;z-index:29}`,
    `[${DRAG_STRIP_ATTRIBUTE}][${DRAG_STRIP_ON_ATTRIBUTE}]{display:block}`,
  );
  track(() => { try { dragStrip.node?.remove(); } catch {} });
  // Полоса во всю ширину (#10984): стоит ли, первая ли в body (иначе кнопки до неё в дереве она бы накрыла).
  statusPart("dragStrip", () => ({ on: dragStrip.on && Boolean(dragStrip.node?.isConnected),
    first: Boolean(dragStrip.node && document.body?.firstChild === dragStrip.node) }));
  HATCH && Object.assign(HATCH, { applyDragStrip, dragStrip });
  // ---- 3. Сироты прошлых установок ---------------------------------------
  // Реестра у них могло и не быть (падение до его заполнения), а в окне они уже
  // висят. Сносим по id и по своим атрибутам — иначе полосок в окне остаётся
  // столько же, сколько было падений.
  for (const id of [STYLE_ID, HANDLE_ID, SIDE_RAIL_ID]) {
    for (const orphan of document.querySelectorAll(`#${id}`)) orphan.remove();
  }
  for (const node of document.querySelectorAll(`[${EDITOR_ROOT_ATTRIBUTE}],[${EDITOR_ATTRIBUTE}],[${BLOCK_ATTRIBUTE}],[${RING_PATH_ATTRIBUTE}],[${RING_ATTRIBUTE}]`)) {
    node.removeAttribute(EDITOR_ROOT_ATTRIBUTE);
    node.removeAttribute(EDITOR_ATTRIBUTE);
    node.removeAttribute(BLOCK_ATTRIBUTE);
    node.removeAttribute(RING_PATH_ATTRIBUTE);
    node.removeAttribute(RING_ATTRIBUTE);
    try { node.style.removeProperty(HEIGHT_VARIABLE); } catch {}
  }
  // Блок счёта Workflow у поля ввода (раздел 12п² до page-60) снят: его узлы, отступ под прокруткой
  // текста поля и запомненные фильтр и вид прошлой страницы убираются здесь.
  for (const orphan of document.querySelectorAll(`#${RICK_CELLS_ID},#${RICK_CARD_ID},#${RICK_FLOW_ID}`)) orphan.remove();
  for (const node of document.querySelectorAll(`[${RICK_ROOM_ATTRIBUTE}]`)) {
    node.removeAttribute(RICK_ROOM_ATTRIBUTE);
    try { node.style.removeProperty(RICK_ROOM_VARIABLE); } catch {}
  }
  try { localStorage.removeItem(RICK_FILTER_KEY); localStorage.removeItem(RICK_VIEW_KEY); } catch {}
  // Часики кеша у закреплённых чатов (раздел 2е до page-64) сняты: метки прошлой страницы на подписях
  // строк и её ключ настройки «таймер выключен» убираются здесь.
  // Только подписи строк: ту же метку data-myclaude-clock носит узел часиков угла (раздел 2ж).
  for (const node of document.querySelectorAll(`[data-row-label][${PINNED_CLOCK_ATTRIBUTE}],[data-row-label][${PINNED_CLOCK_LATE_ATTRIBUTE}]`)) {
    node.removeAttribute(PINNED_CLOCK_ATTRIBUTE);
    node.removeAttribute(PINNED_CLOCK_LATE_ATTRIBUTE);
  }
  try { localStorage.removeItem(PINNED_CLOCK_OFF_KEY); } catch {}
  // «Автосвёртка» (#6666) снята вместе с меню жёлтой кнопки (WF248 П2, лист 48 · 2.1): её флаг прошлой
  // страницы (команда auto-collapse) больше никто не читает — стирается здесь.
  try { localStorage.removeItem("myclaude.autoCollapse"); } catch {}

  // ---- 3а. Завершённые инструменты (#7976, WF120) -------------------------
  // Неизвестная разметка и любой выбор остаются видимыми. Edited опознаётся
  // по структуре и подписи, а не по одному data-find-omitted.
  const HIDE_TOOLS_KEY = "myclaude.hideTools";
  const HIDE_TOOLS_ATTRIBUTE = "data-myclaude-hide-tools";
  const HIDE_TOOLS_MARK = "data-myclaude-tool-done";
  const HIDE_TOOLS_GROUP = '[data-testid="transcript-row"] [data-cds="AssistantMessage"] [data-cds="TurnStatus"][data-tool-anchor][data-state="done"]';
  const HIDE_TOOLS_FILES = '[data-testid="transcript-row"] [data-cds="AssistantMessage"]:not([data-is-streaming="true"]) [data-find-omitted].contents:not([data-cds])';
  // Строка фоновых команд (слово Элвиса 11.10 06:27 по снимку «Background command completed · …»: «Я не
  // могу понять, ты закончил это делать или ещё чё-то думаешь дальше?»): обёртка без своего вида с одной
  // кнопкой [data-transcript-keeps-pin]. Прячется только законченное — «N running» и «N failed» на виду.
  const HIDE_TOOLS_TASKS = '[data-testid="transcript-row"] [data-cds="AssistantMessage"] div[data-find-omitted]:not([data-cds]):not(.contents)';
  const HIDE_TOOLS_TASKS_DONE = /^(?:\d+ background commands? completed|background command completed(?: ?·.*)?)$/i;
  const HIDE_TOOLS_DECISION = '.epitaxy-approval-card,[role="dialog"],[role="alertdialog"],[role="radiogroup"],[role="listbox"],form,textarea,input,select,[role="button"],a,[data-state="running"],[data-state="error"],[data-state="waiting"],[role="alert"]';
  // Claude 2.31226 (замер 11.10): у строки группы своя стрелка (button[data-cds-row-toggle]) и миниатюры
  // снимков (в [data-cds-row-media]) — это не выбор; карточка правок — строка на файл: имя и «+3 −0»
  // (кнопка файла — в li > span.contents). Прежняя разметка («Edited N files», группа без кнопок) жива.
  // Имя правленого файла в строке группы — span[role=button] внутри [data-cds-row]: ссылка, не выбор.
  const HIDE_TOOLS_GROUP_UNSAFE = 'button:not([data-cds-row-toggle],[data-cds-row-media] button)';
  const HIDE_TOOLS_GROUP_LINK = '[data-cds-row] span[role="button"]';
  const HIDE_TOOLS_GROUP_DECISION = HIDE_TOOLS_DECISION.replace('[role="button"]', `[role="button"]:not(${HIDE_TOOLS_GROUP_LINK})`);
  const HIDE_TOOLS_FILES_BUTTON = 'ul[role="list"] > li button[data-base-ui-tooltip-trigger]';
  const HIDE_TOOLS_FILES_DIFF = '.text-git-added,.text-git-removed';
  const HIDE_TOOLS_UNSAFE_BUTTON = `button:not([data-base-ui-tooltip-trigger])`;
  // Коробка поля ввода Claude (#9166а): правило в RULES раздела 4.
  const COMPOSER_BOX = '[data-cds="ChatComposer"] > div[class*="bg-surface"]';
  // Тихое выделение чата в списке слева (#9166б): доля цвета текста, прозрачно поверх фона.
  // WF182 (слово Элвиса 09.10 03:15 по снимку Pinned: «слишком яркая… выделение»): вдвое тише
  // (было 9 % и 6 %), наведение тише выделения.
  const SIDEBAR_SELECTED = "color-mix(in oklab, var(--cds-text-primary, currentColor) 4.5%, transparent)";
  const SIDEBAR_HOVER = "color-mix(in oklab, var(--cds-text-primary, currentColor) 3%, transparent)";
  // WF182 (#9166б для ленты, «выделение у текстов… слишком контрастное»): подложка реплики
  // человека — у Claude 5 % белого (--cds-bg-user-message), у нас вдвое тише и цветом текста темы.
  const USER_BUBBLE_FILL = "color-mix(in oklab, var(--cds-text-primary, currentColor) 2.5%, transparent)";
  // WF182 (#9164, «значок Code, активная вкладка — белое, яркое, бросается в глаза»): выбранный
  // значок Claude/Code — цветом соседних кнопок окна, чуть ярче их, и тонкая подложка; не белым.
  const MODE_ACTIVE_TINT = "color-mix(in oklab, var(--cds-text-secondary, currentColor) 75%, var(--cds-text-primary, currentColor))";
  const MODE_ACTIVE_FILL = "color-mix(in oklab, var(--cds-text-primary, currentColor) 6%, transparent)";
  // Точки чатов — тоном текста темы (page-64; акцент PMP #9166в снят словом Элвиса 11.10 01:40).
  const SIDEBAR_DOT_INK = "var(--cds-text-primary, currentColor)";
  const SIDEBAR_DOT_QUIET = "var(--cds-text-muted, currentColor)";
  // Поле «Search» под курсором: чуть плотнее покоя (покой — как выбранная строка).
  const SIDEBAR_SEARCH_HOVER = "color-mix(in oklab, var(--cds-text-primary, currentColor) 7%, transparent)";
  // Плашки ленты ответа (#9167), замер 09.10 (Claude 2.26454): строка инструментов
  // TurnStatus > [data-cds-row]; кнопка group/tool («Claude Code notice», «N background
  // commands completed»); карточка self-start isolate (318 px, «N background commands running»);
  // карточка Card ответа (файл, вложение) — не вложенная в другую карточку.
  const FEED_PLATES = [
    '[data-cds="TurnStatus"] > [data-cds-row]',
    'button[class~="group/tool"]',
    'button[class~="self-start"][class~="isolate"]',
    '[data-cds="Card"]:not([data-cds="Card"] *)',
  ].map(plate => `.epitaxy-chat-panel [data-cds="AssistantMessage"] ${plate}`).join(",");
  let hideToolsObserver = null;
  // Слово Элвиса 11.10 01:40 по карточке правок и строке «Ran N commands»: «Скрой… чтоб он мне это не
  // писал. Всё лишнее сейчас будем убирать» — без команды включено; выключено — только "0".
  const hideToolsOn = () => {
    try { return localStorage.getItem(HIDE_TOOLS_KEY) !== "0"; } catch { return true; }
  };
  const hideToolsSquash = node => (node.textContent ?? "").replace(/\s/g, "");
  const hideToolsEligible = node => {
    const group = node.matches(HIDE_TOOLS_GROUP);
    if (node.matches(HIDE_TOOLS_DECISION) || [...node.querySelectorAll(HIDE_TOOLS_DECISION)].some(item => !(group && item.matches(HIDE_TOOLS_GROUP_LINK))) ||
        node.closest('.epitaxy-approval-card,[role="dialog"],[role="alertdialog"],[role="alert"]') ||
        /\b(?:AskUserQuestion|ExitPlanMode|Asked a question)\b|Задан вопрос/i.test(node.textContent ?? "")) return false;
    if (group) return Boolean(node.getAttribute("data-tool-anchor")?.trim()) &&
      ![...node.querySelectorAll('button')].some(button => !button.hasAttribute("data-cds-row-toggle") && !button.closest("[data-cds-row-media]"));
    if (node.matches(HIDE_TOOLS_TASKS)) {
      const pins = [...node.querySelectorAll('button')];
      return pins.length === 1 && pins[0].hasAttribute("data-transcript-keeps-pin") && pins[0].getAttribute("aria-expanded") !== "true" &&
        HIDE_TOOLS_TASKS_DONE.test((pins[0].textContent ?? "").replace(/\s+/g, " ").trim()) && hideToolsSquash(node) === hideToolsSquash(pins[0]);
    }
    if (!node.matches(HIDE_TOOLS_FILES)) return false;
    const message = node.closest('[data-cds="AssistantMessage"]');
    if (message?.querySelector('[data-cds="TurnStatus"]:not([data-state="done"])')) return false;
    const buttons = [...node.querySelectorAll('button')];
    if (!buttons.length || !buttons.every(button => button.matches(HIDE_TOOLS_FILES_BUTTON))) return false;
    // The wrapper may also contain a plan or reply after a transcript update.
    // #11618: русский Claude — формы plural из каталога («Изменен 1 файл», «Изменено 2 файла / 5 файлов», «Изменено файлов: N»).
    if (buttons.every(button => /^(?:Edited \d+ files?|Изменено? \d+ файл(?:а|ов)?|Изменено файлов: \d+)$/.test((button.textContent ?? "").trim()))) return hideToolsSquash(node) === buttons.map(hideToolsSquash).join("");
    const rows = [...node.querySelectorAll('ul[role="list"] > li')];
    return rows.length > 0 && rows.every(row => row.querySelector(HIDE_TOOLS_FILES_DIFF)) && hideToolsSquash(node) === rows.map(hideToolsSquash).join("");
  };
  const hideToolsSync = () => {
    for (const node of document.querySelectorAll(`[${HIDE_TOOLS_MARK}],${HIDE_TOOLS_GROUP},${HIDE_TOOLS_FILES},${HIDE_TOOLS_TASKS}`)) {
      const safe = hideToolsOn() && hideToolsEligible(node);
      if (safe && !node.hasAttribute(HIDE_TOOLS_MARK)) node.setAttribute(HIDE_TOOLS_MARK, "");
      else if (!safe && node.hasAttribute(HIDE_TOOLS_MARK)) node.removeAttribute(HIDE_TOOLS_MARK);
    }
  };
  const hideToolsMark = () => {
    const root = document.documentElement;
    if (hideToolsOn()) {
      if (!root.hasAttribute(HIDE_TOOLS_ATTRIBUTE)) root.setAttribute(HIDE_TOOLS_ATTRIBUTE, "");
      if (!hideToolsObserver) {
        hideToolsObserver = new MutationObserver(hideToolsSync);
        hideToolsObserver.observe(root, { childList: true, subtree: true, characterData: true, attributes: true,
          attributeFilter: ["data-state", "data-is-streaming", "data-tool-anchor", "data-cds", "role", "class", "data-base-ui-tooltip-trigger"] });
      }
    } else {
      root.removeAttribute(HIDE_TOOLS_ATTRIBUTE);
      hideToolsObserver?.disconnect();
      hideToolsObserver = null;
    }
    hideToolsSync();
  };
  const hideToolsSet = value => {
    try {
      localStorage.setItem(HIDE_TOOLS_KEY, value ? "1" : "0");
    } catch {}
    hideToolsMark();
  };
  const hideToolsHidden = () => hideToolsOn() ? [...document.querySelectorAll(`[${HIDE_TOOLS_MARK}]`)]
    .filter(hideToolsEligible).length : 0;
  hideToolsMark();
  on(window, "storage", event => { if (event.key === HIDE_TOOLS_KEY || event.key === null) hideToolsMark(); });
  track(() => {
    hideToolsObserver?.disconnect();
    document.documentElement.removeAttribute(HIDE_TOOLS_ATTRIBUTE);
    for (const node of document.querySelectorAll(`[${HIDE_TOOLS_MARK}]`)) node.removeAttribute(HIDE_TOOLS_MARK);
  });
  // «Прятать инструменты» (#7976, раздел 3а): включено ли, сколько групп и списков правок спрятано сейчас.
  statusPart("hideTools", () => ({ on: hideToolsOn(), hidden: hideToolsHidden() }));
  HATCH && Object.assign(HATCH, { FEED_PLATES });

  // ---- 3а¹. Чистые ответы (#9398, WF209, контракт К-CA) ---------------------
  // Слово Элвиса 10.10 02:05: «не смотрю ни на контекст, ни кэши, ни новых. Ни ответ, ни чат, ни
  // опус… визуальным шумом… „Rick · идёт“ мне тоже не нужна. Давай ответы ещё чище делать»; облачко
  // «работа идёт» — «мне нравится». Прячется только ХВОСТ блока текста ответа: подряд идущие последние
  // абзацы верхнего уровня (не пункт списка, не таблица, не код), и только если КАЖДАЯ строка абзаца
  // служебная — строка состояния (ELVIS.md) или строки расхода (claude_footer.py). «Работа идёт 💭» и
  // «❗ Перечитка» остаются: абзац с ними виден целиком, но хвост они не обрывают. Строка отчёта
  // «… · готово ✅» посреди ответа — не хвост и не строка состояния, её не трогаем.
  // Узлы не удаляются: метка на абзаце + правило раздела 4. Вид — высота 0 и прозрачность, НЕ display
  // и не visibility: innerText такой абзац по-прежнему отдаёт, а через него ответ читают полоса 2б,
  // рамка «ждут твоего слова» и «Обкэшить». В идущем ответе последний блок текста ещё печатается — его
  // не трогаем (строка мигала бы на каждом слове); законченные блоки выше — можно.
  // Команда `clean-answers` {on:"true"|"false"} всем окнам; хранится в localStorage
  // ["myclaude.cleanAnswers"]: "0" — показывать, нет ключа (команды не было) — прятать.
  const CLEAN_ANSWERS_KEY = "myclaude.cleanAnswers";
  const CLEAN_ANSWERS_ATTRIBUTE = "data-myclaude-clean-answers";
  const CLEAN_ANSWERS_MARK = "data-myclaude-clean-line";
  const CLEAN_ANSWERS_MESSAGE = '[data-testid="transcript-row"] [data-cds="AssistantMessage"]';
  const CLEAN_ANSWERS_PROSE = '[data-cds="Prose"]';
  const CLEAN_NUMBER = "\\d+(?:[.,]\\d+)?\\s*[KM]?";
  const CLEAN_STATE_MARK = "(?:💭|❓|✅|🛑)";
  // Строки расхода: «Контекст 226K» / «Из кэша 96% · Новых 238K» / «Ответ 6.0M · Чат 6.0M · Opus 5.5
  // HIGH 💭» — каждая своей строкой или все одной (просмотрщик склеил); модели и значка может не быть.
  const CLEAN_USAGE_RE = new RegExp(`^(?:Контекст\\s+${CLEAN_NUMBER})?(?:\\s*[·•]?\\s*Из\\s+кэша\\s+\\d+\\s*%\\s*[·•]\\s*Новых\\s+${CLEAN_NUMBER})?` +
    `(?:\\s*[·•]?\\s*Ответ\\s+${CLEAN_NUMBER}\\s*[·•]\\s*Чат\\s+${CLEAN_NUMBER}(?:\\s*[·•]\\s*[^·•❗]{1,48}?)?(?:\\s*${CLEAN_STATE_MARK})?)?$`, "u");
  const CLEAN_NO_USAGE_RE = /^расход:\s*нет\s+данных$/iu;
  // Строка состояния: «<маркер>Проект · [WF N из M ·] идёт|жду|готово|упал <значок>». Маркер проекта
  // (эмодзи, не значок состояния) обязателен — по нему она отличается от строки отчёта «WF209 · готово ✅».
  const CLEAN_STATUS_RE = new RegExp(`^(?!${CLEAN_STATE_MARK}|❗)\\p{Extended_Pictographic}[\\uFE0F\\u200D\\p{Extended_Pictographic}]{0,6}\\s?` +
    `[\\p{L}\\p{N}][^·•]{0,59}?\\s+[·•]\\s+(?:WF\\s+\\d+\\s+из\\s+\\d+\\s+[·•]\\s+)?(?:идёт|жду|готово|упал)\\s*${CLEAN_STATE_MARK}$`, "u");
  // Остаются на виду: облачко «Работа идёт 💭» и «❗ Перечитка N мимо кэша» — своей строкой или слитая
  // со строками расхода в одну (тогда остаётся вся строка).
  const CLEAN_CLOUD_RE = /^Работа\s+идёт\s*(?:\d{1,3}\s*\/\s*\d{1,3}\s*)?💭(?:\s*\d{1,3}\s*\/\s*\d{1,3})?$/u;
  const CLEAN_REREAD_RE = /^(.*?)\s*❗\uFE0F?\s*Перечитка(?![\p{L}]).*$/u;
  // Разбор одной строки хвоста (чистая функция): "hide" — служебная, прятать; "keep" — служебная, но
  // остаётся на виду; null — обычный текст ответа.
  const cleanAnswerLine = raw => {
    const line = String(raw ?? "").replace(PROGRESS_LINK_RE, "$1").replace(/\s+/g, " ").trim();
    if (!line) return null;
    if (CLEAN_CLOUD_RE.test(line)) return "keep";
    const reread = line.match(CLEAN_REREAD_RE);
    if (reread) return !reread[1] || CLEAN_USAGE_RE.test(reread[1]) ? "keep" : null;
    if (CLEAN_USAGE_RE.test(line) || CLEAN_NO_USAGE_RE.test(line) || CLEAN_STATUS_RE.test(line)) return "hide";
    return null;
  };
  // Строки абзаца: перенос — <br> или перевод строки в тексте. Узел без детей, но с текстом
  // (стенд тестов) — сам себе текст.
  const cleanAnswerLines = node => {
    const lines = [""];
    const put = text => {
      const parts = String(text ?? "").split("\n");
      lines[lines.length - 1] += parts[0];
      for (const part of parts.slice(1)) lines.push(part);
    };
    const walk = item => {
      const kids = [...(item.childNodes ?? [])];
      if (!kids.length) { put(item.textContent); return; }
      for (const kid of kids) {
        if (kid.nodeType === 3) put(kid.nodeValue);
        else if (kid.nodeType === 1 && kid.tagName === "BR") lines.push("");
        else if (kid.nodeType === 1) walk(kid);
      }
    };
    walk(node);
    return lines.map(line => line.trim()).filter(Boolean);
  };
  // Хвост одного блока текста: абзацы верхнего уровня с конца, пока каждый — только из служебных строк.
  const cleanAnswerTail = prose => {
    // Абзацы лежат под обёрткой без своего вида (у Claude — div.contents).
    let host = prose;
    for (let depth = 0; depth < 2 && host.children.length === 1 && host.children[0].tagName === "DIV"; depth += 1) host = host.children[0];
    const hide = [];
    const blocks = [...host.children];
    for (let index = blocks.length - 1; index >= 0; index -= 1) {
      const block = blocks[index];
      if (block.tagName !== "P") break;
      const kinds = cleanAnswerLines(block).map(cleanAnswerLine);
      if (!kinds.length || kinds.includes(null)) break;
      if (kinds.every(kind => kind === "hide")) hide.push(block);
    }
    return hide;
  };
  const cleanAnswers = { on: true, observer: null };
  const cleanAnswersOn = () => {
    try { return localStorage.getItem(CLEAN_ANSWERS_KEY) !== "0"; } catch { return true; }
  };
  const cleanAnswersSync = () => {
    const want = new Set();
    if (cleanAnswers.on) {
      for (const message of document.querySelectorAll(CLEAN_ANSWERS_MESSAGE)) {
        const proses = [...message.querySelectorAll(CLEAN_ANSWERS_PROSE)];
        if (message.getAttribute("data-is-streaming") === "true") proses.pop();
        for (const prose of proses) for (const node of cleanAnswerTail(prose)) want.add(node);
      }
    }
    for (const node of document.querySelectorAll(`[${CLEAN_ANSWERS_MARK}]`)) {
      if (!want.has(node)) node.removeAttribute(CLEAN_ANSWERS_MARK);
    }
    for (const node of want) if (!node.hasAttribute(CLEAN_ANSWERS_MARK)) node.setAttribute(CLEAN_ANSWERS_MARK, "");
  };
  const cleanAnswersMark = () => {
    const root = document.documentElement;
    cleanAnswers.on = cleanAnswersOn();
    if (cleanAnswers.on) {
      if (!root.hasAttribute(CLEAN_ANSWERS_ATTRIBUTE)) root.setAttribute(CLEAN_ANSWERS_ATTRIBUTE, "");
      if (!cleanAnswers.observer) {
        // Сверка сразу в колбэке наблюдателя, до отрисовки (как у 3а): новая строка ленты не мелькает
        // служебным хвостом и не меняет высоту после первого замера. Своя метка в фильтр не входит.
        cleanAnswers.observer = new MutationObserver(() => { try { cleanAnswersSync(); } catch {} });
        cleanAnswers.observer.observe(root, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["data-is-streaming"] });
      }
    } else {
      root.removeAttribute(CLEAN_ANSWERS_ATTRIBUTE);
      cleanAnswers.observer?.disconnect();
      cleanAnswers.observer = null;
    }
    cleanAnswersSync();
  };
  const cleanAnswersSet = value => {
    try {
      if (value) localStorage.removeItem(CLEAN_ANSWERS_KEY);
      else localStorage.setItem(CLEAN_ANSWERS_KEY, "0");
    } catch {}
    cleanAnswersMark();
  };
  const cleanAnswersHidden = () => cleanAnswers.on ? document.querySelectorAll(`[${CLEAN_ANSWERS_MARK}]`).length : 0;
  cleanAnswersMark();
  on(window, "storage", event => { if (event.key === CLEAN_ANSWERS_KEY || event.key === null) cleanAnswersMark(); });
  track(() => {
    cleanAnswers.observer?.disconnect();
    document.documentElement.removeAttribute(CLEAN_ANSWERS_ATTRIBUTE);
    for (const node of document.querySelectorAll(`[${CLEAN_ANSWERS_MARK}]`)) node.removeAttribute(CLEAN_ANSWERS_MARK);
  });
  statusPart("cleanAnswers", () => ({ on: cleanAnswers.on, hidden: cleanAnswersHidden() }));
  HATCH && Object.assign(HATCH, { cleanAnswerLine, cleanAnswersSync });

  // ---- 3б. Плавное появление нового в ленте (#9165, WF165) ------------------
  // Слово Элвиса 09.10 00:05: новый ответ появляется слишком резко, рывком, и это
  // раздражает. Новая строка ленты (transcript-row с номером data-index больше
  // всех виденных в этом чате) проявляется: прозрачность 0→1 и подъём на FEED_ENTER_SHIFT за
  // FEED_ENTER_MS. Новый блок внутри идущего ответа (абзац, список, строка инструмента,
  // дописанный В КОНЕЦ без замены соседей) — только прозрачностью, без сдвига: текст не прыгает.
  // Не играет: при прокрутке (лента виртуальная — старые строки монтируются заново с меньшим
  // номером или далеко от хвоста), первые FEED_ENTER_QUIET мс после входа в чат и инжекта
  // (лента грузится целиком), при «Уменьшить движение». Узлы React не меняются — Web Animations
  // на самом узле (`translate` складывается с чужим transform); DOM-атрибутов нет.
  const FEED_ENTER_ROW = '[data-testid="transcript-row"]';
  const FEED_ENTER_MS = 220;
  const FEED_ENTER_BLOCK_MS = 180;
  const FEED_ENTER_SHIFT = 5;
  const FEED_ENTER_QUIET = 1200;
  const FEED_ENTER_TAIL = 2;
  // Только блоки: строчные куски (span) идущего текста не мигают по одному.
  const FEED_ENTER_BLOCKS = /^(?:P|UL|OL|PRE|BLOCKQUOTE|TABLE|H[1-6]|DIV)$/i;
  const FEED_ENTER_STREAM = '[data-cds="AssistantMessage"][data-is-streaming="true"]';
  const feedEnterState = { path: null, top: -1, quietUntil: 0, rows: 0, blocks: 0, still: 0 };
  const feedEnterIndex = row => {
    const raw = row?.getAttribute?.("data-index");
    const value = raw == null || raw === "" ? NaN : Number(raw);
    return Number.isInteger(value) && value >= 0 ? value : null;
  };
  const feedEnterTop = () => {
    let top = -1;
    for (const row of document.querySelectorAll(FEED_ENTER_ROW)) {
      const index = feedEnterIndex(row);
      if (index != null && index > top) top = index;
    }
    return top;
  };
  const feedEnterReset = () => {
    feedEnterState.path = location.pathname;
    feedEnterState.top = feedEnterTop();
    feedEnterState.quietUntil = now() + FEED_ENTER_QUIET;
  };
  const feedEnterPlay = (node, frames, duration) => {
    let still = false;
    try { still = matchMedia("(prefers-reduced-motion: reduce)").matches; } catch {}
    if (still || typeof node?.animate !== "function") { feedEnterState.still += 1; return false; }
    try { node.animate(frames, { duration, easing: "cubic-bezier(0.2, 0.7, 0.3, 1)" }); return true; } catch { return false; }
  };
  const feedEnterRow = row => {
    const index = feedEnterIndex(row);
    if (index == null || index <= feedEnterState.top) return;
    feedEnterState.top = index;
    if (now() < feedEnterState.quietUntil) return;
    // Хвост ленты: Claude метит строку расстоянием до конца; далеко от хвоста — это прокрутка.
    const tail = Number(row.getAttribute?.("data-perf-row-from-tail"));
    if (Number.isFinite(tail) && tail > FEED_ENTER_TAIL) return;
    if (feedEnterPlay(row, [{ opacity: 0, translate: `0 ${FEED_ENTER_SHIFT}px` }, { opacity: 1, translate: "0 0" }], FEED_ENTER_MS)) feedEnterState.rows += 1;
  };
  const feedEnterOnMutation = records => {
    if (feedEnterState.path !== location.pathname) { feedEnterReset(); return; }
    for (const record of records) {
      if (record.type !== "childList") continue;
      for (const node of record.addedNodes ?? []) {
        if (node?.nodeType !== 1) continue;
        if (node.matches?.(FEED_ENTER_ROW)) { feedEnterRow(node); continue; }
        const rows = node.querySelectorAll?.(FEED_ENTER_ROW) ?? [];
        if (rows.length) { for (const row of rows) feedEnterRow(row); continue; }
        // Блок идущего ответа: дописан в конец, соседей не заменял.
        if (now() < feedEnterState.quietUntil || (record.removedNodes?.length ?? 0) > 0) continue;
        if (!FEED_ENTER_BLOCKS.test(node.tagName ?? "")) continue;
        if (node.parentElement?.lastElementChild !== node || !node.closest?.(FEED_ENTER_STREAM)) continue;
        if (feedEnterPlay(node, [{ opacity: 0 }, { opacity: 1 }], FEED_ENTER_BLOCK_MS)) feedEnterState.blocks += 1;
      }
    }
  };
  feedEnterReset();
  HATCH && Object.assign(HATCH, { feedEnterOnMutation, feedEnterState, FEED_ENTER_MS });

  // ---- 4. Стили и сама полоска -------------------------------------------
  // WF173: текст ответа Claude (не реплики человека) и карточки файлов ленты (не поля ввода).
  const ANSWER_PROSE = '.epitaxy-chat-panel [data-cds="AssistantMessage"] [data-cds="Prose"]';
  // WF225 (#9426, слово Элвиса 10.10 по снимку раскрытой свёртки с полосой слева: при развороте
  // свёрнутые группы выделять так же — большая группа или небольшая, «так смотреть удобнее»).
  // Узел полосы — тело раскрытой <details> (метка open); под раскрытой кнопкой «Свернуть ответ»
  // полосы нет (слово Элвиса 10.10 10:47, page-61). Свои заголовки свёрток в полосе — отдельным
  // правилом (стрелка не сдвигается); в свёрнутом блоке «Прочитано» полосы нет — там узлы нулевой высоты.
  const FOLD_STRIP = `[${FOLD_BODY_ATTRIBUTE}="open"]:not([${FOLD_HEAD_ATTRIBUTE}],[${FOLD_RAW_ATTRIBUTE}],:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]) *)`;
  const FOLD_STRIP_HEAD = `[${FOLD_HEAD_ATTRIBUTE}][${FOLD_BODY_ATTRIBUTE}="open"]`;
  const FOLD_STRIP_LEFT = "calc(var(--myclaude-fold-mid, 7.4px) - .75px)";
  // В прозе Code — весом выше правил WF173, в прочих видах ленты — без неё (как у цитаты WF182).
  const foldStripRule = (tail, body) => `${ANSWER_PROSE} ${tail},${tail}{${body}}`;
  // «Работа идёт» одной строкой (раздел 12х¹): стрелка её строки стоит на 4 px левее стрелки свёрток.
  const WORK_STRIP_LEFT = "calc(var(--myclaude-fold-mid, 7.4px) - 4.75px)";
  // Полоса хода (WF245): шаг сектора вместе с зазором, ширина полосы (сжимается), тона.
  const WORK_BAR_GAP = 3;
  const WORK_BAR_STEP = `calc((100% + ${WORK_BAR_GAP}px) / var(--myclaude-work-n))`;
  const WORK_BAR_WIDTH = `min(calc(var(--myclaude-work-n) * 12px - ${WORK_BAR_GAP}px),180px)`;
  const WORK_BAR_FILL = "var(--cds-text-accent,currentColor)";
  const WORK_BAR_TONE = "color-mix(in srgb,currentColor 24%,transparent)";
  const FEED_FILE_TILE = '.epitaxy-chat-panel [data-cds="MessageAttachmentsFile"]:not([data-cds-composer-attachments] *)';
  // Превью HEIC (раздел 12м⁴): метка плитки с картинкой и самой картинки.
  const HEIC_ATTRIBUTE = "data-myclaude-heic";
  const HEIC_IMG_ATTRIBUTE = "data-myclaude-heic-img";
  // Карточки SendUserFile (#10603): квадрат Claude растёт до высоты 180 (метка кнопки и узлов до картинки),
  // ширина — переменной на кнопке.
  const HEIC_GROW_ATTRIBUTE = "data-myclaude-heic-grow";
  const HEIC_BOX_ATTRIBUTE = "data-myclaude-heic-box";
  const HEIC_WIDTH_VAR = "--myclaude-heic-w";
  const RULES = [
    // Полоска висит поверх всего и позиционируется координатами: рамка поля
    // живёт в чужом дереве, и вставлять в него свой узел — лишний риск.
    // Три полоски — одна и та же полоска (#6891, слово Элвиса 21.09: «все три
    // должны быть соосными… все одной толщиной»): зона захвата, линия и её
    // поведение общие, разница только в курсоре — за основную тянут, дубли у
    // краёв окна жмут.
    // `-webkit-app-region:no-drag` нужен всем трём. Верхний дубль садится на
    // титульную полосу Claude, а основная полоска заезжает на неё же, когда
    // поле растянуто до потолка (#6893, слово Элвиса 21.09: «хоть у меня стрелка
    // вниз — всё равно полоска должна отрабатывать»): титульная полоса таскает
    // окно, и без no-drag нажатие уходило в перетаскивание окна, а не в шаг.
    `#${HANDLE_ID},#${SUPER_TOP_ID},#${SUPER_BOTTOM_ID}{position:fixed;display:none;align-items:center;justify-content:center;height:${HANDLE_HEIGHT}px;padding:0;border:0;background:transparent;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag;touch-action:none;z-index:2147483646}`,
    `#${HANDLE_ID}{cursor:ns-resize}`,
    `#${SUPER_TOP_ID},#${SUPER_BOTTOM_ID}{cursor:pointer}`,
    // Едва заметная линия в цвет текста: 0.10 — слово Элвиса «полоска едва
    // заметная, при наведении видимая».
    // Линия в покое — .22 (#7201: при .10 на тёмных темах их «нету» вовсе).
    `#${HANDLE_ID}>span,#${SUPER_TOP_ID}>span,#${SUPER_BOTTOM_ID}>span{display:block;width:100%;height:2px;border-radius:999px;background:currentColor;opacity:.22;pointer-events:none;transition:height 120ms ease,opacity 120ms ease}`,
    `#${HANDLE_ID}:hover>span,#${HANDLE_ID}[data-dragging="true"]>span,#${SUPER_TOP_ID}:hover>span,#${SUPER_BOTTOM_ID}:hover>span{height:3px;opacity:.45}`,
    // Свёрнутое поле чаще возвращают кликом, поэтому курсор там не «тянуть», а
    // обычная рука, и сама полоска заметнее. Тяга вверх при этом тоже работает.
    `#${HANDLE_ID}[data-collapsed="true"]{cursor:pointer}`,
    `#${HANDLE_ID}[data-collapsed="true"]>span{height:3px;opacity:.30}`,
    `#${HANDLE_ID}[data-collapsed="true"]:hover>span{height:4px;opacity:.45}`,
    // Рейка ширины правой колонки (WF65, раздел 2г): прозрачная, при наведении и
    // тяге — акцентом (color ставит placeSideRail), как рейка боковой панели у
    // Claude.
    // Зона захвата 8 точек невидима; на наведении и тяге в её середине
    // проявляется линия в 3 точки — как рейка боковой панели у самого Claude
    // (слово Элвиса 17.09 02:00: «чтобы везде одинаково»).
    `#${SIDE_RAIL_ID}{position:fixed;display:none;width:${SIDE_RAIL_WIDTH}px;padding:0;border:0;background:transparent;cursor:col-resize;user-select:none;-webkit-user-select:none;touch-action:none;z-index:2147483646}`,
    // Линия проявляется не сразу, а после паузы — курсор и так каждую минуту
    // пересекает промежуток по дороге к полю ввода, и мгновенная линия «мигает,
    // бесит» (слово Элвиса 17.09 03:20); гаснет сразу. Яркость — вполсилы.
    // WF176 (#9182): пилюля как у рейки левой панели Claude — 3×48 по центру, цвет
    // text-muted (ставит placeSideRail замером пилюли Claude), появление 200 мс через 200 мс.
    `#${SIDE_RAIL_ID}{color:rgba(127,127,127,.75)}`,
    `#${SIDE_RAIL_ID}>span{position:absolute;left:50%;top:50%;width:3px;height:100%;max-height:${SIDE_RAIL_PILL}px;transform:translate(-50%,-50%);border-radius:999px;background:currentColor;opacity:0;pointer-events:none;transition:opacity 200ms cubic-bezier(.4,0,.2,1)}`,
    `#${SIDE_RAIL_ID}:hover>span{opacity:1;transition-delay:${SIDE_RAIL_REVEAL_MS}ms}`,
    `#${SIDE_RAIL_ID}[data-dragging="true"]>span{opacity:1;transition-delay:0ms}`,
    // Угловой фейд ленты в режиме чтения (раздел 6). Не в ноль и без резкой кромки
    // (слово Элвиса 20.09 06:30: «чтобы чуть-чуть просвечивал, ненавязчивый»; первая
    // редакция съедала две строки и гасила текст целиком).
    `[data-myclaude-corner-fade]{-webkit-mask-image:${CORNER_FADE_MASK};mask-image:${CORNER_FADE_MASK}}`,
    // Зеркальный фейд под кружком в режиме чтения (#6737, раздел 6). Отдельным
    // правилом с ДВУМЯ приметами, а не вторым слоем в правиле выше: слои маски
    // по умолчанию складываются (mask-composite:add), и там, где левый верхний
    // прозрачен, правый нижний непрозрачен — левый фейд #6656/#6658 пропал бы
    // совсем. Здесь слоёв два и composite intersect, а без кружка правило не
    // применяется вовсе и верхний фейд остаётся ровно таким, как был.
    `[data-myclaude-corner-fade][${RING_FADE_ATTRIBUTE}]{-webkit-mask-image:${CORNER_FADE_MASK},${RING_FADE_MASK};-webkit-mask-composite:source-in;mask-image:${CORNER_FADE_MASK},${RING_FADE_MASK};mask-composite:intersect}`,
    // Панель лимитов (раздел 12ж). Процент 5-часового прячем СВОИМ атрибутом:
    // узел остаётся на месте, React о нём не спотыкается. Своя полоса недели —
    // отрезки в ряд и подписи дней под ними; всё остальное (высота, цвет,
    // скругление) снято классами с родных полос, здесь этих чисел нет.
    // Прозрачность у каждой подписи своя, а не у ряда: opacity на родителе
    // создаёт группу, и сегодняшний день из неё уже не «ярче».
    `[data-myclaude-lim-hide]{display:none !important}`,
    // Дорожки полос видны на ЛЮБОЙ теме (#7064, слово Элвиса 22.09: «на розовой не видно
    // полосок, а важно, чтобы их было видно»). Цвет дорожки у Claude свой, и светлые темы
    // Пимпа красят фон панели почти в него — полоса пропадала целиком. Берём не фиксированный
    // серый (он потерялся бы на тёмных), а 14 % ТЕКУЩЕГО ЦВЕТА ТЕКСТА: на светлой теме текст
    // тёмный и дорожка тёмная, на тёмной — наоборот. Одно правило на все темы разом, проверять
    // каждую не нужно. Заливка внутри — своя, её не трогаем.
    `[data-myclaude-lim-panel] [role="progressbar"],[data-myclaude-lim-panel] [role="meter"],[data-myclaude-week="cell"]{background-color:color-mix(in srgb,currentColor 14%,transparent) !important;background-image:none !important}`,
    `[data-myclaude-week="bar"]{display:flex;gap:1px;align-items:stretch;margin-bottom:3px}`,
    `[data-myclaude-week="bar"]>*{flex:1 1 0;min-width:0}`,
    `[data-myclaude-week="days"]{display:flex;gap:1px;font-size:10px;line-height:1.5}`,
    `[data-myclaude-week="days"]>*{flex:1 1 0;min-width:0;text-align:center;opacity:.5}`,
    `[data-myclaude-week="days"]>[data-myclaude-week-on="true"]{opacity:1;font-weight:600}`,
    // Левая панель Claude ýже его минимума (раздел 2д) — только пристыкованная. У свёрнутой
    // этой же переменной Claude меряет выезжающий список и полосу над ним с переключателем
    // Claude/Code у правого края: при 190 вместо 242 переключатель вставал между «назад» и
    // «вперёд» (WF155, #9146: «когда подменюшку показываю, кнопки друг на друга накладываются»).
    `.dframe-root[${LEFT_ATTRIBUTE}]:not([data-collapsed]){--df-sidebar-width:var(${LEFT_VARIABLE}) !important}`,
    // Переключатель Claude/Code как кнопки окна (WF166, #9164; плашки WF155 сняты — «не надо под
    // ними делать эти фоны тёмные»): без дорожки и бегунка, кнопки 24 и иконка 16 в px — в обоих
    // режимах одного размера; невыбранная — цвет кнопок окна, выбранная и наведение — чуть ярче
    // их и тонкая подложка (WF182; было белым на --df-hover). Жирность иконки одна: Claude утолщает выбранный Code.
    `${MODE_SWITCH_SELECTOR}{--cds-segmented-control-track:transparent;height:${MODE_BUTTON}px !important;padding:0 !important;gap:0 !important;background:transparent !important;border:0 !important;box-shadow:none !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important}`,
    `${MODE_SWITCH_SELECTOR}>[aria-hidden="true"]{display:none !important}`,
    `${MODE_SWITCH_SELECTOR} [role="radio"]{width:${MODE_BUTTON}px !important;height:${MODE_BUTTON}px !important;min-width:0 !important;aspect-ratio:1 !important;padding:0 !important;border-radius:${MODE_RADIUS}px !important;background:transparent !important;color:var(--cds-text-secondary) !important}`,
    `${MODE_SWITCH_SELECTOR} [role="radio"]:is([data-checked],:hover){background:${MODE_ACTIVE_FILL} !important;color:${MODE_ACTIVE_TINT} !important}`,
    `${MODE_SWITCH_SELECTOR} [data-cds="Icon"]{font-size:${MODE_ICON}px !important;font-weight:533.3 !important}`,
    `${MODE_SWITCH_SELECTOR} svg{width:${MODE_ICON}px !important;height:${MODE_ICON}px !important}`,
    // #11618: те же правила для русского «Режим».
    `${MODE_SWITCH_RU}{--cds-segmented-control-track:transparent;height:${MODE_BUTTON}px !important;padding:0 !important;gap:0 !important;background:transparent !important;border:0 !important;box-shadow:none !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important}`,
    `${MODE_SWITCH_RU}>[aria-hidden="true"]{display:none !important}`,
    `${MODE_SWITCH_RU} [role="radio"]{width:${MODE_BUTTON}px !important;height:${MODE_BUTTON}px !important;min-width:0 !important;aspect-ratio:1 !important;padding:0 !important;border-radius:${MODE_RADIUS}px !important;background:transparent !important;color:var(--cds-text-secondary) !important}`,
    `${MODE_SWITCH_RU} [role="radio"]:is([data-checked],:hover){background:${MODE_ACTIVE_FILL} !important;color:${MODE_ACTIVE_TINT} !important}`,
    `${MODE_SWITCH_RU} [data-cds="Icon"]{font-size:${MODE_ICON}px !important;font-weight:533.3 !important}`,
    `${MODE_SWITCH_RU} svg{width:${MODE_ICON}px !important;height:${MODE_ICON}px !important}`,
    // Значок Remote Control у названия чата (WF166, #9164, снимок 18): включённый Claude красит
    // тёмной заливкой и цветом акцента — у нас просто значок цвета текста; наведение — как у Claude.
    `.epitaxy-titlebar [data-testid="epitaxy-origin-gutter"]{color:var(--cds-text-primary) !important}`,
    `.epitaxy-titlebar [data-testid="epitaxy-origin-gutter"] [data-cds-part="paint"]{background-color:transparent !important}`,
    `.epitaxy-titlebar [data-testid="epitaxy-origin-gutter"]:hover [data-cds-part="paint"]{background-color:var(--cds-fill-ghost-hover) !important}`,
    // Кнопка «Show sidebar» у светофора (слово Элвиса 22.10.2026: «просвечивает — раньше вокруг неё была
    // рамочка»): в 3.1623 она прозрачная поверх ленты — подложка цветом страницы и тонкая рамка. Подложка —
    // псевдоэлементом: фон самой кнопки перебивает правило прозрачности живого фона.
    `.df-collapsed-chrome ${uiAria(["Show sidebar", "Показать боковую панель"])}{box-shadow:0 0 0 1px var(--cds-border) !important;border-radius:8px !important}`,
    `.df-collapsed-chrome ${uiAria(["Show sidebar", "Показать боковую панель"])}::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:8px;background:var(--cds-page-bg,#131518)}`,
    // Часики угла (#9144): пять минут и меньше — мягкий пульс раз в секунду; «Уменьшить движение» — без него.
    `#${CORNER_ID}>[${CORNER_CLOCK_ATTRIBUTE}="alarm"]{animation:myclaude-clock-tick 1s ease-in-out infinite}`,
    `@keyframes myclaude-clock-tick{0%,100%{opacity:1}50%{opacity:.45}}`,
    `@media (prefers-reduced-motion: reduce){#${CORNER_ID}>[${CORNER_CLOCK_ATTRIBUTE}]{animation:none !important}}`,
    // Выезжающий список чатов (#7097, 2.2553.13, скрин Элвиса к задаче): у свёрнутой
    // левой панели Claude по наведению выдвигает её поверх ленты и поля ввода —
    // `.dframe-root[data-collapsed][data-hovering] .dframe-sidebar-body {opacity:1}`.
    // Фон у панели непрозрачный (замер WF82: rgb(23,23,26) при любой нашей теме),
    // а «просвечивали» сквозь неё НАШИ полоски: ручка, полоса прогресса, дубль у
    // нижнего края. Они живут в body над всем деревом Claude (его корень —
    // `isolation: isolate`), и z-index их под панель не спрячет. Пока панель
    // выдвинута — прячем их одним правилом, без замеров и таймеров: наведение и
    // уход мыши Claude отмечает атрибутом, и правило срабатывает тем же кадром.
    // visibility, а не display: display полосок ведёт раскладка (раздел 9), и
    // после ухода мыши они встают на место сами; спрятанные мышь не ловят.
    // С WF277 — и место панели материалов (12п⁴): подложка, рейка и полоса над ней. Кнопка «PMP» остаётся, как
    // «Show sidebar» рядом с ней: список выезжает от него же, и спрятанную кнопку было бы не нажать.
    `body:has(.dframe-root[data-collapsed][data-hovering]) :is(#${HANDLE_ID},#${SUPER_TOP_ID},#${SUPER_BOTTOM_ID},#${PROGRESS_ID},#${PROGRESS_TIP_ID},#${SIDE_RAIL_ID},#${MIC_ID},#${GALLERY_ID},#${PMP_ID},#${DOCK_PLACE_ID},#${DOCK_RAIL_ID},#${DOCK_DRAG_ID},#${PMP_PANEL_ID}){visibility:hidden !important}`,
    // Наши слои уступают меню Claude (WF144, класс WF136 п.5–6): пока открыто меню или список,
    // ручка, дубли полосы, микрофон, галерея и PMP мышь не ловят — сразу, тем же кадром, а не
    // на проходе раскладки (он не чаще LAYOUT_MIN_GAP): нажатие по пункту над ними не
    // сворачивает поле и не закрывает меню.
    // С WF179 — и при открытом поповере/диалоге Claude (CLAUDE_POPUP_SELECTOR).
    `body:has(${CLAUDE_POPUP_SELECTOR}) :is(#${HANDLE_ID},#${SUPER_TOP_ID},#${SUPER_BOTTOM_ID},#${MIC_ID},#${GALLERY_ID},#${PMP_ID},#${SIDE_RAIL_ID},#${DOCK_BUTTON_ID},#${DOCK_SIZES_ID},#${DOCK_RAIL_ID}),body:has(${CLAUDE_POPUP_SELECTOR}) :is(#${HANDLE_ID},#${SUPER_TOP_ID},#${SUPER_BOTTOM_ID},#${MIC_ID},#${GALLERY_ID},#${PMP_ID},#${SIDE_RAIL_ID},#${DOCK_BUTTON_ID},#${DOCK_SIZES_ID},#${DOCK_RAIL_ID}) *{pointer-events:none !important}`,
    // Папка проекта перед именем закреплённого чата (раздел 2е, #7102). С page-64 (слово Элвиса 11.10
    // 01:40: «названия проектов не надо цветом выводить… сделай маленькими… не мешались») — не плашка,
    // а мелкая тихая подпись: без заливки и цвета проекта, 10 px, приглушённый тон текста темы. На
    // узкой панели (#6625) не шире половины строки и режется многоточием, а имя чата уходит под родной
    // градиент Claude. По высоте — на базовой линии имени чата: у inline-block с overflow базовая линия —
    // нижний край поля, поэтому строка высотой в кегль и нижнее поле −0,12 em (выносные под линией; сверено снимком стенда ×4).
    `[data-testid="sidebar-pinned"] .dframe-fade-label[${PINNED_FOLDER_ATTRIBUTE}]::before{content:attr(${PINNED_FOLDER_ATTRIBUTE});display:inline-block;vertical-align:baseline;box-sizing:border-box;max-width:50%;margin:0 6px -.12em 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;line-height:1;font-weight:400;color:var(--cds-text-secondary);opacity:.72}`,
    // Кнопка «💬 Новый чат» под блоком передачи (раздел 12к, #7246):
    // подпись — из атрибута, в innerText ответа её нет.
    `[${CONTINUE_ATTRIBUTE}]{display:flex;margin:6px 0 4px}`,
    `[${CONTINUE_ATTRIBUTE}]>button{display:inline-flex;align-items:center;padding:4px 10px;border:1px solid color-mix(in srgb,currentColor 25%,transparent);border-radius:8px;background:color-mix(in srgb,currentColor 6%,transparent);color:inherit;font:inherit;font-size:13px;line-height:18px;cursor:pointer;-webkit-app-region:no-drag}`,
    `[${CONTINUE_ATTRIBUTE}]>button:hover{background:color-mix(in srgb,currentColor 12%,transparent)}`,
    `[${CONTINUE_ATTRIBUTE}]>button[aria-disabled="true"]{opacity:.6;cursor:default}`,
    `[${CONTINUE_ATTRIBUTE}]>button::after{content:attr(${CONTINUE_LABEL_ATTRIBUTE})}`,
    // Заголовок «ОТКРОЙ НОВЫЙ ЧАТ» — ссылка (WF88, К15): текст прежний,
    // пунктир цвета акцента, сплошной при наведении; ⏳/✓ — из ::after.
    `[${CONTINUE_LINK_ATTRIBUTE}]{cursor:pointer;color:var(--cds-text-accent,currentColor);text-decoration:underline dotted;text-underline-offset:3px}`,
    `[${CONTINUE_LINK_ATTRIBUTE}]:hover{text-decoration-style:solid}`,
    // Ждём Пимпа (#7865, макет 13 — выбор Элвиса 26.09 ~08:40: основа 1.1 «блик по буквам», вместо ⏳ —
    // крутящийся кружок из 1.5, кнопка наливается, как 1.7): по буквам ссылки бежит светлая полоса (копия
    // текста в ::before), в конце — кружок; «✓» — ровно.
    `@keyframes myclaude-shim{from{background-position:100% 0}to{background-position:0 0}}`,
    `@keyframes myclaude-spin{to{transform:rotate(360deg)}}`,
    `@keyframes myclaude-fill{from{background-size:0% 100%}to{background-size:88% 100%}}`,
    `[${CONTINUE_LINK_ATTRIBUTE}][${CONTINUE_LINK_STATE_ATTRIBUTE}]{position:relative}`,
    `[${CONTINUE_LINK_ATTRIBUTE}][${CONTINUE_LINK_STATE_ATTRIBUTE}="wait"]::before{content:attr(${CONTINUE_LINK_TEXT_ATTRIBUTE});position:absolute;left:0;top:0;right:0;pointer-events:none;background:linear-gradient(100deg,transparent 36%,rgba(255,255,255,.9) 50%,transparent 64%) 0 0/250% 100% no-repeat;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;animation:myclaude-shim 1.7s linear infinite}`,
    `[${CONTINUE_LINK_ATTRIBUTE}][${CONTINUE_LINK_STATE_ATTRIBUTE}="wait"]::after{content:"";display:inline-block;width:.6em;height:.6em;margin-left:.4em;border:.12em solid currentColor;border-right-color:transparent;border-radius:50%;vertical-align:.04em;animation:myclaude-spin .8s linear infinite}`,
    `[${CONTINUE_LINK_ATTRIBUTE}][${CONTINUE_LINK_STATE_ATTRIBUTE}="ack"]::after{content:" ✓"}`,
    // Кнопка: пока «⏳ Зову Пимпа…» — наливается акцентом до 88 % за 3 с, слева кружок, по буквам блик
    // (подпись без ⏳ — строка CONTINUE_LABEL_WAIT без первого слова); «✓» — налита целиком.
    `[${CONTINUE_ATTRIBUTE}]>button[${BUSY_ATTRIBUTE}]{opacity:1;background-image:linear-gradient(color-mix(in srgb,var(--cds-text-accent,#d97757) 30%,transparent),color-mix(in srgb,var(--cds-text-accent,#d97757) 30%,transparent));background-repeat:no-repeat;background-size:100% 100%}`,
    `[${CONTINUE_ATTRIBUTE}]>button[${BUSY_ATTRIBUTE}][${CONTINUE_LABEL_ATTRIBUTE}^="⏳"]{background-size:88% 100%;animation:myclaude-fill 3s cubic-bezier(.25,.7,.3,1) both}`,
    `[${CONTINUE_ATTRIBUTE}]>button[${BUSY_ATTRIBUTE}][${CONTINUE_LABEL_ATTRIBUTE}^="⏳"]::before{content:"";display:inline-block;width:.8em;height:.8em;margin-right:.45em;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:myclaude-spin .8s linear infinite}`,
    `[${CONTINUE_ATTRIBUTE}]>button[${BUSY_ATTRIBUTE}][${CONTINUE_LABEL_ATTRIBUTE}^="⏳"]::after{content:"${CONTINUE_WAIT_TEXT}";background:linear-gradient(100deg,currentColor 36%,color-mix(in srgb,currentColor 20%,#fff) 50%,currentColor 64%) 0 0/250% 100% no-repeat;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:myclaude-shim 1.7s linear infinite}`,
    // Идёт работа (#7772, WF97): ссылка и кнопка в это время aria-disabled,
    // курсор обычный; ссылка — прежняя простая, с ⏳/✓ из ::after (#7852, WF98:
    // перелива у неё и у кнопки больше нет, кнопка приглушена правилом выше).
    // Буквы переливаются только в плашке «⏳ Уже открываю окно…» (раздел 12б);
    // «уменьшить движение» — и там без перелива, просто приглушённо.
    `[${BUSY_ATTRIBUTE}]:not(button):not([${CONTINUE_LINK_ATTRIBUTE}]){background:linear-gradient(100deg,var(--cds-text-accent,#d97757) 36%,#fff 50%,var(--cds-text-accent,#d97757) 64%) 0 0/250% 100% no-repeat;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;animation:myclaude-shim 1.7s linear infinite}`,
    `[${CONTINUE_LINK_ATTRIBUTE}][${BUSY_ATTRIBUTE}]{cursor:default}`,
    // Карточка файла, пока приложение не ответило на клик (WF107, К3, #7772):
    // по плитке бежит блик, в углу ⏳; ссылка в тексте переливается правилом выше.
    `button[${BUSY_ATTRIBUTE}="file"]{position:relative;cursor:progress}`,
    `button[${BUSY_ATTRIBUTE}="file"]::after{content:"⏳";position:absolute;inset:0;display:flex;align-items:flex-start;justify-content:flex-end;padding:4px 6px;font-size:13px;line-height:1;border-radius:inherit;pointer-events:none;background:linear-gradient(100deg,transparent 36%,rgba(255,255,255,.28) 50%,transparent 64%) 0 0/250% 100% no-repeat;animation:myclaude-shim 1.7s linear infinite}`,
    `@media (prefers-reduced-motion: reduce){button[${BUSY_ATTRIBUTE}="file"]::after{animation:none !important;background:none !important}}`,
    // «Просмотрено» у карточек файлов (раздел 12м³, WF239). Галочка — круглая кнопка 24×24 в правом верхнем углу
    // карточки (знак 18 — по высоте плашки типа файла, от краёв 8, как поля карточки): в покое едва видна, под
    // курсором на карточке — видна, под курсором на ней самой — подложка; цвет — текста карточки, значит темы.
    // На фото — на тёмном кружке белым: читается на любой картинке. Просмотренная карточка — серая: всё её
    // содержимое, кроме галочки, приглушено и обесцвечено, рамка и размеры те же (лента не сдвигается); под
    // курсором и с фокусом проявляется, чтобы её можно было прочитать. Пока файл открывается, в углу ⏳ — галочки нет.
    `button[${SEEN_ATTRIBUTE}]{position:relative}`,
    `[${SEEN_CHECK_ATTRIBUTE}]{position:absolute;top:5px;right:5px;z-index:1;box-sizing:border-box;width:24px;height:24px;margin:0;padding:3px;border:0;border-radius:50%;background:transparent;color:inherit;line-height:0;cursor:pointer;opacity:.3;transition:opacity .15s,background-color .15s;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none}`,
    `[${SEEN_CHECK_ATTRIBUTE}]>svg{display:block;width:18px;height:18px;pointer-events:none}`,
    `[${SEEN_CHECK_ATTRIBUTE}] [data-k="fill"],[${SEEN_CHECK_ATTRIBUTE}][aria-pressed="true"] [data-k="line"]{display:none}`,
    `[${SEEN_CHECK_ATTRIBUTE}][aria-pressed="true"] [data-k="fill"]{display:inline}`,
    `[${SEEN_CHECK_ATTRIBUTE}][aria-pressed="true"]{opacity:.62}`,
    `button[${SEEN_ATTRIBUTE}]:hover>[${SEEN_CHECK_ATTRIBUTE}],button[${SEEN_ATTRIBUTE}]:focus-visible>[${SEEN_CHECK_ATTRIBUTE}]{opacity:.8}`,
    `[${SEEN_CHECK_ATTRIBUTE}]:hover,[${SEEN_CHECK_ATTRIBUTE}]:focus-visible{opacity:1 !important;background:color-mix(in srgb,currentColor 14%,transparent)}`,
    `[${SEEN_CHECK_ATTRIBUTE}]:active{background:color-mix(in srgb,currentColor 24%,transparent)}`,
    `[${SEEN_CHECK_ATTRIBUTE}]:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:-1px}`,
    `button[${SEEN_ATTRIBUTE}]:has(img)>[${SEEN_CHECK_ATTRIBUTE}]{color:#fff;background:rgba(0,0,0,.42);opacity:.45}`,
    `button[${SEEN_ATTRIBUTE}]:has(img)>[${SEEN_CHECK_ATTRIBUTE}][aria-pressed="true"]{opacity:.85}`,
    `button[${SEEN_ATTRIBUTE}]:has(img)>[${SEEN_CHECK_ATTRIBUTE}]:is(:hover,:focus-visible){background:rgba(0,0,0,.62)}`,
    `button[${SEEN_ATTRIBUTE}="on"]>:not([${SEEN_CHECK_ATTRIBUTE}]){opacity:.5;filter:grayscale(1);transition:opacity .15s,filter .15s}`,
    `button[${SEEN_ATTRIBUTE}="on"]:is(:hover,:focus-visible)>:not([${SEEN_CHECK_ATTRIBUTE}]){opacity:.85;filter:grayscale(.35)}`,
    `button[${BUSY_ATTRIBUTE}="file"]>[${SEEN_CHECK_ATTRIBUTE}]{visibility:hidden}`,
    `@media (prefers-reduced-motion: reduce){[${SEEN_CHECK_ATTRIBUTE}],button[${SEEN_ATTRIBUTE}="on"]>*{transition:none !important}}`,
    `@media (prefers-reduced-motion: reduce){[${BUSY_ATTRIBUTE}]:not(button):not([${CONTINUE_LINK_ATTRIBUTE}]){animation:none !important;background-image:none !important;-webkit-text-fill-color:currentColor !important;color:inherit !important;opacity:.6}[${CONTINUE_LINK_ATTRIBUTE}]::before,[${CONTINUE_LINK_ATTRIBUTE}]::after,[${CONTINUE_ATTRIBUTE}]>button::before,[${CONTINUE_ATTRIBUTE}]>button::after,[${CONTINUE_ATTRIBUTE}]>button{animation:none !important}}`,
    // Схлопнутый узел: не display:none, а полоска нулевой высоты — редактор
    // остаётся живым, черновик и фокус переживают сворачивание.
    `[${BLOCK_ATTRIBUTE}="collapsed"]{height:0 !important;min-height:0 !important;max-height:0 !important;padding-top:0 !important;padding-bottom:0 !important;margin-top:0 !important;margin-bottom:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // Ветка с кружком контекста (#6737, раздел 6): та же свёртка, но БЕЗ
    // opacity — она создаёт группу прозрачности, и никакой opacity:1 на
    // потомке кружок из неё уже не вытащит, — с overflow:visible (иначе
    // кружок срежет) и position:relative (чтобы absolute внутри считался от
    // неё, а не от неизвестно чего).
    `[${BLOCK_ATTRIBUTE}="collapsed-ring"]{height:0 !important;min-height:0 !important;max-height:0 !important;padding-top:0 !important;padding-bottom:0 !important;margin-top:0 !important;margin-bottom:0 !important;overflow:visible !important;position:relative !important;pointer-events:none !important}`,
    // Внутри пути к кружку остаётся только сам путь и кружок: модель, счётчики
    // и кнопка отправки уходят. Редактор и черновик не задеты — они в ДРУГОМ
    // ребёнке блока ввода и живут обычным collapsed (opacity:0, фокус цел).
    `[${RING_PATH_ATTRIBUTE}]>*:not([${RING_PATH_ATTRIBUTE}]):not([${RING_ATTRIBUTE}]){display:none !important}`,
    // Сам кружок: на своём месте справа внизу, видимый и нажимаемый. z-index
    // НИЖЕ ручки (2147483646) намеренно: иначе кружок перехватил бы клик по
    // полоске возврата, и вернуть поле стало бы нечем.
    // Свой микрофон у кружка (#6907) и глушилка родной подсказки на кружке
    // (#6906: «при наведении не надо показывать стандартную подсказку» —
    // вместо неё открывается сама панель лимитов).
    `#${MIC_ID}{position:fixed;display:none;align-items:center;justify-content:center;width:${MIC_SIZE}px;height:${MIC_SIZE}px;padding:0;border:0;background:transparent;cursor:pointer;opacity:.45;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none;touch-action:none;z-index:2147483645}`,
    `#${MIC_ID}:hover{opacity:.95}`,
    `#${MIC_ID}[data-live="true"]{opacity:1;color:#ef4444}`,
    // Диктатор пишет в это окно — значок ЯРКО мигает (#7704): красный с
    // ореолом, раз в секунду; «уменьшить движение» — горит без мигания.
    `@keyframes myclaude-mic-blink{0%{opacity:1}100%{opacity:.2}}`,
    `#${MIC_ID}[data-live="true"][data-mode="dictator"]{border-radius:50%;background:rgba(239,68,68,.18);filter:drop-shadow(0 0 4px rgba(239,68,68,.95));animation:myclaude-mic-blink .5s ease-in-out infinite alternate}`,
    // Место под значок у левого края нижней строки открытого поля (#7704).
    `${CHIN_SELECTOR}[${MIC_ROOM_ATTRIBUTE}]{padding-left:${MIC_ROOM_PAD}px !important}`,
    // Кнопка «▦ Галерея» (#7724, раздел 12п; макет docs/11.html, раздел 6): значок 2×2 без числа,
    // рамки и заливки (#9507 — число файлов только в подсказке); под курсором — плашка, как у соседней
    // PMP; нажата (фильтр этого чата) — плашка держится. Место под неё в нижней строке открытого поля
    // — полем справа у левой группы «+ Auto» (ширину ставит placeGallery).
    `#${GALLERY_ID}{position:fixed;display:none;align-items:center;justify-content:center;box-sizing:border-box;width:${GALLERY_WIDTH}px;height:${GALLERY_HEIGHT}px;padding:0;border:0;border-radius:4px;background:transparent;box-shadow:none;color:inherit;cursor:pointer;opacity:.75;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none;z-index:2147483645;transition:background-color .15s,opacity .2s}`,
    `#${GALLERY_ID}>svg{display:block;flex:none;width:${GALLERY_ICON}px;height:${GALLERY_ICON}px;pointer-events:none}`,
    `#${GALLERY_ID}:hover{opacity:1;background:rgba(127,127,127,.14)}`,
    `#${GALLERY_ID}:active{background:rgba(127,127,127,.24)}`,
    `#${GALLERY_ID}[data-fresh="true"],#${GALLERY_ID}[data-on="true"]{opacity:.9;color:inherit}`,
    `#${GALLERY_ID}[data-on="true"]{background:rgba(127,127,127,.2)}`,
    // В нижней строке поля (#9181: «квадратик сильно ярко») — цветом подписей строки (--k, как BY);
    // у кружка — как было. Значок в строке — тише подписей (WF183: «значок сильно яркий»).
    `#${GALLERY_ID}[data-spot="field"]{color:var(--k,inherit);opacity:1}`,
    `#${GALLERY_ID}[data-spot="field"]>svg{opacity:.7}`,
    `#${GALLERY_ID}[data-spot="field"]:hover>svg{opacity:1}`,
    `#${GALLERY_ID}[data-fresh="true"]::after{content:"";position:absolute;top:1px;right:0;width:4px;height:4px;border-radius:50%;background:rgba(245,158,11,.75);pointer-events:none}`,
    // В нижней строке поля точки «есть непросмотренные» нет (#9195: «светится сверху точка…»):
    // сколько не смотрел — в подсказке.
    `#${GALLERY_ID}[data-spot="field"][data-fresh="true"]::after{display:none}`,
    // Кнопка «PMP» (раздел 12п¹, #9136; #9507 — без чисел): тихая надпись «PMP» цветом текста окна,
    // без серой плашки и тени; под курсором и у открытой панели — плашка. Ждёт ответа — как есть,
    // приложение молчит — бледнее и контуром.
    `#${PMP_ID}{position:fixed;display:none;align-items:center;justify-content:center;box-sizing:border-box;width:${PMP_WIDTH}px;height:${PMP_HEIGHT}px;padding:0;border:0;background:transparent;box-shadow:none;color:inherit;cursor:pointer;opacity:1;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none;z-index:2147483645;transition:background-color .15s,opacity .2s}`,
    `#${PMP_ID}>.p{display:flex;align-items:center;height:100%;padding:0;border-radius:3px;background:transparent;color:inherit;font:600 10px/1 -apple-system,system-ui,sans-serif;letter-spacing:.2px;opacity:.7}`,
    // WF226 (снимок Элвиса 10.10): плашка под курсором и у открытой панели — по содержимому, с полями 5
    // слева и справа и высотой 20, как у соседних значков. Надпись с места не сходит: поле слева и
    // сверху взято наружу.
    `#${PMP_ID}[data-spot="field"]{width:fit-content !important;min-width:24px;height:20px;margin:-3px 0 0 -5px;padding:0 5px;justify-content:center}`,
    `#${PMP_ID}[data-spot="field"]{color:var(--k,inherit)}`,
    // В нижней строке поля надпись — цветом, гарнитурой и кеглем подписей строки (#9181: «все шрифты
    // разные»), строка 16, как у них (BP, O 5.5): базовая линия общая (#9195).
    `#${PMP_ID}[data-spot="field"]>.p{font:400 var(--rs,11px)/16px var(--rf,${RICK_FONT_FALLBACK});letter-spacing:0;opacity:1}`,
    `#${PMP_ID}:hover{background:rgba(127,127,127,.14);border-radius:4px}`,
    `#${PMP_ID}:hover>.p{opacity:1}`,
    `#${PMP_ID}:active{background:rgba(127,127,127,.24);border-radius:4px}`,
    `#${PMP_ID}[data-state="silent"]{opacity:.45}`,
    `#${PMP_ID}[data-state="silent"]>.p{padding:0 3px;box-shadow:inset 0 0 0 1px currentColor}`,
    `#${PMP_ID}[aria-expanded="true"]{background:rgba(127,127,127,.2);border-radius:4px}`,
    `#${PMP_ID}:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:2px;border-radius:4px}`,
    // Панель оркестрации на кнопке PMP (раздел 12п³, WF213; макет счётчика — docs/32.html, вариант 1.4).
    // Коробка — как у сводки проекта 12п²: фон и текст поля (--F, --T), обводка — текст 15 % (--L).
    // Тело прокручивается (полосы нет, низ затухает — data-more), команды под ним всегда на виду.
    // Одна колонка имён на оба блока (--nm). Жирное — заголовки блоков и шапка строки Workflow; имя
    // терминала — цветом проекта, смешанным с цветом текста (читается и на светлой теме); в блоке Workflow
    // цвета проектов нет (лист 48 · 1.2). Строка Workflow — одной строкой без переноса и многоточия
    // (лишнее прячет pmpFlowsLineFit), числа ярче имён; в раскрытом списке строки делит волосок, «упал» — красный (--R).
    // Плашка под строкой терминала — как тело свёртки 12ф: волосок 1,5 px под стрелкой строки, серая
    // подложка, выезжает сменой grid-template-rows. Строка длиннее двух строк режется, раскрытая — целиком.
    // WF226: команды из рамки не выпадают ни при какой высоте — сжимается тело (вес сжатия 9999 против 1),
    // а когда от него остались одни поля, команды прокручиваются сами (окно ниже их трёх строк).
    `#${PMP_PANEL_ID}{position:fixed;display:none;flex-direction:column;box-sizing:border-box;border-radius:12px;border:1px solid var(--L);background:var(--F);color:var(--T);box-shadow:var(--S);font:400 12px/16px -apple-system,system-ui,sans-serif;font-variant-numeric:tabular-nums;text-align:left;overflow-wrap:anywhere;z-index:2147483646;pointer-events:auto;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none}`,
    `#${PMP_PANEL_ID}>div{flex:1 9999 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none;padding:11px 14px 8px}`,
    `#${PMP_PANEL_ID}>div[data-more="true"]{-webkit-mask-image:linear-gradient(#000 calc(100% - 22px),transparent);mask-image:linear-gradient(#000 calc(100% - 22px),transparent)}`,
    `#${PMP_PANEL_ID} section+section{margin-top:12px}`,
    `#${PMP_PANEL_ID} h3{margin:0 0 3px;padding:0;font:600 12px/16px -apple-system,system-ui,sans-serif;color:inherit}`,
    `#${PMP_PANEL_ID} h3>span{font-weight:400;opacity:.6}`,
    `#${PMP_PANEL_ID} p{margin:0;padding:0}`,
    `#${PMP_PANEL_ID} [data-k="note"]{opacity:.65}`,
    `#${PMP_PANEL_ID} [data-k="row"]{position:relative;display:flex;align-items:flex-start;gap:8px;box-sizing:border-box;width:100%;min-height:22px;margin:0;padding:3px 0;border:0;border-radius:6px;background:transparent;color:inherit;font:inherit;text-align:left}`,
    `#${PMP_PANEL_ID} [data-k="nm"]{flex:0 0 var(--nm,64px);min-width:0;overflow:hidden;white-space:nowrap;font-weight:500;color:color-mix(in srgb,var(--c,currentColor) 70%,var(--T))}`,
    // Узкая панель (окно от 280): текст строки терминала и «2/3 · 1 идёт» проекта Workflow — под именем:
    // в колонке справа от имени им тесно.
    `#${PMP_PANEL_ID}[data-narrow="true"] [data-k="row"]{flex-wrap:wrap;row-gap:1px}`,
    `#${PMP_PANEL_ID}[data-narrow="true"] :is([data-k="tx"],[data-k="fw"]){flex:0 0 100%}`,
    `#${PMP_PANEL_ID} button{cursor:pointer;-webkit-app-region:no-drag}`,
    `#${PMP_PANEL_ID} button:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    `#${PMP_PANEL_ID} button[data-k="row"]::before{content:"▸";position:absolute;left:-11px;top:3px;font-size:10px;line-height:16px;opacity:.6}`,
    `#${PMP_PANEL_ID} button[data-k="row"][aria-expanded="true"]::before{content:"▾"}`,
    `#${PMP_PANEL_ID} button[data-k="row"]:hover{background:color-mix(in srgb,currentColor 8%,transparent);box-shadow:-12px 0 0 color-mix(in srgb,currentColor 8%,transparent),6px 0 0 color-mix(in srgb,currentColor 8%,transparent)}`,
    `#${PMP_PANEL_ID} button[data-k="row"][data-flat="true"]{cursor:default}`,
    `#${PMP_PANEL_ID} button[data-k="row"][data-flat="true"]::before{content:none}`,
    `#${PMP_PANEL_ID} button[data-k="row"][data-flat="true"]:hover{background:transparent;box-shadow:none}`,
    `#${PMP_PANEL_ID} [data-k="tx"]{flex:1 1 0;min-width:0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;opacity:.85}`,
    `#${PMP_PANEL_ID} [aria-expanded="true"]>[data-k="tx"]{display:block;-webkit-line-clamp:unset}`,
    `#${PMP_PANEL_ID} button[data-k="line"]{position:relative;display:block;box-sizing:border-box;width:100%;min-height:22px;margin:0;padding:3px 0;border:0;border-radius:6px;background:transparent;color:inherit;font:inherit;text-align:left}`,
    `#${PMP_PANEL_ID} button[data-k="line"]::before{content:"▸";position:absolute;left:-11px;top:3px;font-size:10px;line-height:16px;opacity:.6}`,
    `#${PMP_PANEL_ID} button[data-k="line"][aria-expanded="true"]::before{content:"▾"}`,
    `#${PMP_PANEL_ID} button[data-k="line"]:hover{background:color-mix(in srgb,currentColor 8%,transparent);box-shadow:-12px 0 0 color-mix(in srgb,currentColor 8%,transparent),6px 0 0 color-mix(in srgb,currentColor 8%,transparent)}`,
    `#${PMP_PANEL_ID} [data-k="ln"]{display:block;overflow:hidden;white-space:nowrap;text-overflow:clip}`,
    `#${PMP_PANEL_ID} [data-k="hd"]{font-weight:600}`,
    `#${PMP_PANEL_ID} [data-k="it"]>span{opacity:.65}`,
    `#${PMP_PANEL_ID} [data-k="it"]>b,#${PMP_PANEL_ID} [data-k="more"]{font-weight:600}`,
    `#${PMP_PANEL_ID} [data-kind="flow"]{padding:5px 0}`,
    `#${PMP_PANEL_ID} [data-kind="flow"]+[data-kind="flow"]{border-top:1px solid color-mix(in srgb,currentColor 10%,transparent);border-radius:0}`,
    `#${PMP_PANEL_ID} [data-k="fw"]{flex:1 1 0;min-width:0}`,
    `#${PMP_PANEL_ID} [data-k="fc"]>b{font-weight:600}`,
    `#${PMP_PANEL_ID} [data-k="fc"]>span{opacity:.65}`,
    `#${PMP_PANEL_ID} [data-k="fc"]>[data-fail]{opacity:1;color:var(--R)}`,
    `#${PMP_PANEL_ID} [data-k="fa"]{opacity:.85}`,
    `#${PMP_PANEL_ID} [data-k="plate"]{display:grid;grid-template-rows:0fr;transition:grid-template-rows .18s ease}`,
    `#${PMP_PANEL_ID} [data-k="plate"][data-open="true"]{grid-template-rows:1fr}`,
    `#${PMP_PANEL_ID} [data-k="plate"]>div{min-height:0;overflow:hidden;margin-left:-8px}`,
    `#${PMP_PANEL_ID} [data-k="plate"]>div>div{margin:2px 0 5px;padding:6px 10px 7px 6.5px;border-left:1.5px solid color-mix(in srgb,currentColor 45%,transparent);border-radius:0 8px 8px 0;background:rgba(127,127,127,.12)}`,
    `#${PMP_PANEL_ID} [data-k="pf"]+[data-k="pf"],#${PMP_PANEL_ID} [data-k="bar"]+p,#${PMP_PANEL_ID} [data-k="pm"]+[data-k="pf"],#${PMP_PANEL_ID} [data-k="pm"]+[data-k="pw"],#${PMP_PANEL_ID} [data-k="pf"]+[data-k="pw"]{margin-top:7px}`,
    `#${PMP_PANEL_ID} [data-k="pm"]{font-size:11px;opacity:.65}`,
    `#${PMP_PANEL_ID} [data-k="bar"]{display:block;height:2px;margin-top:4px;border-radius:1px;text-decoration:none;background:linear-gradient(90deg,var(--Y) var(--p,0%),color-mix(in srgb,currentColor 17%,transparent) var(--p,0%))}`,
    `#${PMP_PANEL_ID} [data-k="pw"]>b{font-weight:500}`,
    `#${PMP_PANEL_ID} [data-k="pw"]>span{opacity:.85}`,
    `#${PMP_PANEL_ID}>nav{flex:0 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none;display:flex;flex-wrap:wrap;gap:6px;padding:9px 14px 12px;border-top:1px solid color-mix(in srgb,currentColor 10%,transparent)}`,
    `#${PMP_PANEL_ID}>nav>button{box-sizing:border-box;min-height:24px;margin:0;padding:3px 10px;border:1px solid var(--L);border-radius:8px;background:transparent;color:inherit;font:400 12px/16px -apple-system,system-ui,sans-serif;white-space:nowrap}`,
    `#${PMP_PANEL_ID}>nav>button:hover{background:color-mix(in srgb,currentColor 10%,transparent)}`,
    `#${PMP_PANEL_ID}>nav>button:active{background:color-mix(in srgb,currentColor 18%,transparent)}`,
    // Главное действие одно — «Запустить Workflow»: залито; фразы Рику — контуром; «Настройки Пимпа»
    // (уводит из окна к панели у часов) — текстом у правого края.
    `#${PMP_PANEL_ID}>nav>button[data-act="settings"]{margin-left:auto;padding:3px 4px;border-color:transparent;opacity:.75}`,
    `#${PMP_PANEL_ID}>nav>button[data-act="settings"]:hover{opacity:1}`,
    `#${PMP_PANEL_ID}>nav>button[data-act="kickoff"]{border-color:transparent;background:color-mix(in srgb,currentColor 14%,transparent);font-weight:500}`,
    `#${PMP_PANEL_ID}>nav>button[data-act="kickoff"]:hover{background:color-mix(in srgb,currentColor 22%,transparent)}`,
    `@media (prefers-reduced-motion:reduce){#${PMP_PANEL_ID} [data-k="plate"]{transition:none}}`,
    // «+» у кнопки New в списке чатов (#9145, WF156): только значок, без серого кружка-заливки
    // Claude (`.df-new-circle`, rgb(44,44,42) по замеру 08.10) — и при наведении.
    `${NEW_PLUS_SELECTOR}{background:transparent!important;box-shadow:none!important}`,
    // Меню Claude раскрывается вверх поверх рамки поля — свои слои над полем уступают ему, иначе нажатие пункта
    // уходит в них (WF136). С WF179 (#9205, слово Элвиса 09.10 02:35: «смотри панель — всё просвечивает»): и
    // поповерам/диалогам Claude (панель лимитов над полем): панель оркестрации, полоска 2б, её подсказка,
    // карточка и хвост.
    `body:has(${CLAUDE_POPUP_SELECTOR}) :is(#${PMP_PANEL_ID},#${PROGRESS_ID},#${PROGRESS_TIP_ID},#${PROGRESS_CARD_ID},#${PROGRESS_TAIL_ID}){visibility:hidden!important}`,
    `${CHIN_SELECTOR} [${GALLERY_ROOM_ATTRIBUTE}]{margin-inline-end:var(${GALLERY_ROOM_VARIABLE},0px) !important;flex-shrink:0 !important}`,
    `#${MIC_HINT_ID}{position:fixed;display:none;max-width:calc(100vw - 16px);padding:5px 9px;border-radius:8px;background:rgba(24,24,27,.94);color:#fff;font:12px/16px -apple-system,system-ui,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;pointer-events:none;box-shadow:0 2px 10px rgba(0,0,0,.35);z-index:2147483646}`,
    // Заголовки «нужен Элвис» в финальном ответе мигают мягко (#7703, раздел
    // 12м): подсветка янтарём туда-обратно, цикл 1,4 с.
    `@keyframes myclaude-attn-blink{0%{background-color:rgba(245,158,11,0);box-shadow:0 0 0 0 rgba(245,158,11,0)}100%{background-color:rgba(245,158,11,.34);box-shadow:0 0 0 3px rgba(245,158,11,.34)}}`,
    `[${ATTN_ATTRIBUTE}]{border-radius:6px;animation:myclaude-attn-blink .7s ease-in-out infinite alternate}`,
    `@media (prefers-reduced-motion: reduce){#${MIC_ID}[data-live="true"][data-mode="dictator"],[${ATTN_ATTRIBUTE}]{animation:none !important}[${ATTN_ATTRIBUTE}]{background-color:rgba(245,158,11,.3)}}`,
    // Слова-действия «Скажи — и сделаю» (#7755, раздел 12р): фраза янтарём в
    // тон мигания 12м, выбранное — залито; отсчёт — пилюля с цифрой у заголовка.
    // Подчёркивания нет ни в каком состоянии (#9505, слово Элвиса 10.10 ~11:00: «жёлтые… такими же
    // жирненькими, но без подчёркивания… когда наводишь, понятно»): покой — цвет и жирность (фраза —
    // strong ответа), под курсором и при нажатии — подложка.
    `[${SAY_ATTRIBUTE}]{color:rgb(245,158,11) !important;text-decoration:none !important;cursor:pointer;border-radius:5px;padding:0 3px;margin:0 -3px;user-select:none;-webkit-user-select:none;transition:background-color .15s,color .15s}`,
    `[${SAY_ATTRIBUTE}]:hover{background-color:rgba(245,158,11,.18)}`,
    `[${SAY_ATTRIBUTE}]:active{background-color:rgba(245,158,11,.3)}`,
    `[${SAY_ATTRIBUTE}="on"]{background-color:rgb(245,158,11) !important;color:#1c1917 !important}`,
    `[${SAY_LEFT_ATTRIBUTE}]::after{content:attr(${SAY_LEFT_ATTRIBUTE});display:inline-block;vertical-align:middle;margin-left:10px;min-width:24px;height:24px;padding:0 6px;box-sizing:border-box;border-radius:12px;background:rgb(245,158,11);color:#1c1917;font:700 14px/24px ui-monospace,SFMono-Regular,Menlo,monospace;text-align:center;cursor:pointer;box-shadow:0 0 0 3px rgba(245,158,11,.3)}`,
    // Нажималки (#7843, #7842, раздел 12с): строка «⚪» нажимается — без подчёркивания (то же слово
    // #9505; до того — пунктир янтарём во всю строку): под курсором и при нажатии — подложка тем же
    // янтарём, вписанная — залита; кнопки — как «💬 Новый чат» 12к, подпись
    // из атрибута (в innerText, копию и «Обкэшить» не попадает), нажатая —
    // залита; занятая — приглушена, без перелива (#7852).
    `li[${NAZH_PICK_ATTRIBUTE}]{cursor:pointer;border-radius:5px;text-decoration:none !important;user-select:none;-webkit-user-select:none;transition:background-color .15s}`,
    `li[${NAZH_PICK_ATTRIBUTE}]:hover{background-color:rgba(245,158,11,.14)}`,
    `li[${NAZH_PICK_ATTRIBUTE}]:active{background-color:rgba(245,158,11,.22)}`,
    `li[${NAZH_PICK_ATTRIBUTE}="on"]{background-color:rgba(245,158,11,.3)}`,
    `[${NAZH_BOX_ATTRIBUTE}]{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 8px}`,
    `[${NAZH_BUTTON_ATTRIBUTE}]{display:inline-flex;align-items:center;padding:2px 9px;border:1px solid rgba(245,158,11,.55);border-radius:8px;background:rgba(245,158,11,.08);color:inherit;font:inherit;font-size:12px;line-height:18px;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag;vertical-align:middle}`,
    `[${NAZH_BUTTON_ATTRIBUTE}]:hover{background:rgba(245,158,11,.2)}`,
    `[${NAZH_BUTTON_ATTRIBUTE}]::after{content:attr(${NAZH_LABEL_ATTRIBUTE})}`,
    `[${NAZH_BUTTON_ATTRIBUTE}][${NAZH_ON_ATTRIBUTE}]{background:rgb(245,158,11);border-color:rgb(245,158,11);color:#1c1917}`,
    `[${NAZH_BUTTON_ATTRIBUTE}][aria-disabled="true"]{opacity:.6;cursor:default}`,
    `li>[${NAZH_BUTTON_ATTRIBUTE}],p>[${NAZH_BUTTON_ATTRIBUTE}]{margin-left:8px;padding:0 7px;font-size:11px}`,
    // «→ в чат» у блока кода (#7980, раздел 12с): в полосе «Copy code» — по центру, в одну строку.
    `[${NAZH_BUTTON_ATTRIBUTE}="code"]{align-self:center;white-space:nowrap}`,
    // Свёртки <details> (#9065, раздел 12ф): заголовок — строка с ▸/▾, подпись
    // из атрибута (копия и выделение её не видят).
    `[${FOLD_RAW_ATTRIBUTE}],[${FOLD_BODY_ATTRIBUTE}="closed"],[${FOLD_LONG_ATTRIBUTE}="closed"]{display:none !important}`,
    `[${FOLD_HEAD_ATTRIBUTE}]{display:block;width:fit-content;max-width:100%;margin:6px 0;padding:2px 8px 2px 4px;border-radius:6px;color:inherit;font-weight:600;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag;transition:background-color .15s,opacity .15s}`,
    `[${FOLD_HEAD_ATTRIBUTE}]::after{content:attr(${FOLD_LABEL_ATTRIBUTE})}`,
    `[${FOLD_HEAD_ATTRIBUTE}]:hover{background:rgba(127,127,127,.14)}`,
    `[${FOLD_HEAD_ATTRIBUTE}]:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    `[${FOLD_HEAD_ATTRIBUTE}]:active{background:rgba(127,127,127,.24)}`,
    `[${FOLD_HEAD_ATTRIBUTE}="open"]:not([${FOLD_WHOLE_ATTRIBUTE}]){margin-bottom:2px}`,
    // WF218 (#9426, слово Элвиса 10.10: «„Свернуть ответ“… мизерная, я её не вижу вообще… должно быть
    // лучше сделано, заметнее»): кнопка — плашка размером текста ответа, со стрелкой как у свёрток
    // (стрелка на той же вертикали: поле слева 8 px, сдвиг −4 px); у свёрнутого ответа — строка во
    // всю ширину с полоской слева, под первым абзацем.
    `[${FOLD_WHOLE_ATTRIBUTE}]{margin:8px 0 8px -4px;padding:4px 12px 4px 8px;border-radius:8px;background:rgba(127,127,127,.12)}`,
    `[${FOLD_WHOLE_ATTRIBUTE}="closed"]{width:auto;margin-left:calc(var(--myclaude-fold-mid, 7.4px) - .75px);padding-left:calc(10.75px - var(--myclaude-fold-mid, 7.4px) + 4px);border-left:1.5px solid currentColor;border-radius:0 8px 8px 0}`,
    `[${FOLD_WHOLE_ATTRIBUTE}]:hover{background:rgba(127,127,127,.2)}`,
    `[${FOLD_WHOLE_ATTRIBUTE}]:active{background:rgba(127,127,127,.3)}`,
    // WF173 (слово Элвиса 09.10 02:00 по снимку ответа Рика: «зачем эта фиолетовая линия… тоненькую,
    // цветом как эти надписи… кругляшки не нужны… отступ сильно большой… абзацы поближе, между
    // абзацами расстояние чуть побольше… сливается»). Только ответы Claude, реплики человека — нет.
    // Цитата: волосок 1,5 px цветом своего текста (не акцент темы), отступ 10 px.
    `${ANSWER_PROSE} blockquote{border-left:1.5px solid currentColor !important;padding-left:10px !important;margin-left:0 !important;margin-inline-start:0 !important}`,
    // WF176 (#9198): цитата — тело свёртки: волосок под центром ▾ заголовка (замер —
    // --myclaude-fold-mid, раздел 12ф), содержимое сдвигается вместе с ним.
    // WF182: волосок 1,5 px у тела свёртки в любом виде ленты (не только в прозе Code) — иначе
    // чужая ширина рамки сдвигала бы центр линии с центра ▾.
    `${ANSWER_PROSE} blockquote[${FOLD_BODY_ATTRIBUTE}],blockquote[${FOLD_BODY_ATTRIBUTE}]{margin-left:calc(var(--myclaude-fold-mid, 7.4px) - .75px) !important;margin-inline-start:calc(var(--myclaude-fold-mid, 7.4px) - .75px) !important;border-left-width:1.5px !important}`,
    // Строки абзаца плотнее, сами абзацы, списки и цитаты — врозь.
    `${ANSWER_PROSE} :is(p,li,blockquote){line-height:1.45 !important}`,
    `${ANSWER_PROSE} * + :is(p,ul,ol,blockquote){margin-top:.8em !important}`,
    `${ANSWER_PROSE} li + li{margin-top:.5em !important}`,
    // Маркеры списков тише: цветом второстепенного текста и мельче.
    `${ANSWER_PROSE} li::marker{color:var(--cds-text-secondary,currentColor);font-size:.8em}`,
    // В свёртке кругляшков нет вовсе и отступа под них — тоже: структуру держат интервалы.
    `${ANSWER_PROSE} :is(ul[${FOLD_BODY_ATTRIBUTE}],[${FOLD_BODY_ATTRIBUTE}] ul){list-style:none !important;padding-inline-start:0 !important;margin-inline-start:0 !important}`,
    // WF218 (#9426, слово Элвиса 10.10: «Почему оно полоской не отделяется, что свёрнуто?.. когда мы
    // workflow делаем, там же специальная полоска и отступ, а здесь-то почему этого нет»): волосок под ▾
    // и отступ 10 px были только у тела-цитаты (отчёты Workflow, WF176) — теперь у любого тела свёртки:
    // абзаца, списка, кода. У нумерованного списка поле под цифры своё; у блока со своим фоном (код)
    // линия прямая, фон начинается после отступа. Стоит после правила списков — при равном весе побеждает.
    foldStripRule(`${FOLD_STRIP}:not(blockquote,table)`, `margin-left:${FOLD_STRIP_LEFT} !important;margin-inline-start:${FOLD_STRIP_LEFT} !important;border-left:1.5px solid currentColor !important;border-top-left-radius:0 !important;border-bottom-left-radius:0 !important;background-clip:content-box !important`),
    // WF225: под кнопкой «Свернуть ответ» списки остаются списками — маркеры и цифры в своём поле
    // (в теле <details> кругляшков нет — правило WF173 выше); разделитель — своим правилом ниже.
    foldStripRule(`${FOLD_STRIP}:not(blockquote,ol,hr,table,ul:not([${FOLD_BODY_ATTRIBUTE}]))`, "padding-left:10px !important;padding-inline-start:10px !important"),
    // Полоска идёт вдоль всего раскрытого без разрывов: зазор между соседними узлами — их внутренним
    // полем (внешний отступ, верхний или нижний, рвал бы линию). WF225: у любого узла полосы и с обеих
    // сторон — заголовок h1–h3, код и таблица приходят со своими отступами.
    foldStripRule(FOLD_STRIP, "margin-top:0 !important;margin-bottom:0 !important;padding-top:.8em !important"),
    // #11478 (слово Элвиса 01.11: «заголовок… прижат к верхнему абзацу… а заголовок-то нижнего абзаца» — принцип
    // близости): первый узел тела под раскрытой головой (за её сырыми <p>) — почти вплотную к ней, последний перед
    // следующей головой или </details> — с полем снизу; полоса идёт сквозь поля.
    foldStripRule(`:is([${FOLD_HEAD_ATTRIBUTE}="open"]+[${FOLD_RAW_ATTRIBUTE}],[${FOLD_HEAD_ATTRIBUTE}="open"]+[${FOLD_RAW_ATTRIBUTE}]+[${FOLD_RAW_ATTRIBUTE}])+${FOLD_STRIP}:not(hr,table)`, "padding-top:.2em !important"),
    foldStripRule(`${FOLD_STRIP}:not(hr,table):has(+:is([${FOLD_RAW_ATTRIBUTE}],[${FOLD_HEAD_ATTRIBUTE}]))`, "padding-bottom:.8em !important"),
    // Разделитель: высота вместо внешних отступов (полоса не рвётся), сама черта — тихой линией после отступа.
    foldStripRule(`hr${FOLD_STRIP}`, "box-sizing:border-box !important;height:1.6em !important;padding:0 !important;border-width:0 0 0 1.5px !important;color:inherit !important;overflow:visible !important;background:linear-gradient(color-mix(in srgb,currentColor 25%,transparent),color-mix(in srgb,currentColor 25%,transparent)) no-repeat 10px 50%/calc(100% - 10px) 1px !important"),
    // Таблица без обёртки: поле у неё не работает (границы ячеек слиты) — отступ внешний, а линию
    // на всю высоту вместе с зазором сверху ведёт свой слой.
    foldStripRule(`table${FOLD_STRIP}`, `position:relative !important;margin-left:calc(${FOLD_STRIP_LEFT} + 11.5px) !important;margin-inline-start:calc(${FOLD_STRIP_LEFT} + 11.5px) !important;margin-top:.8em !important;padding-top:0 !important`),
    foldStripRule(`table${FOLD_STRIP}::before`, `content:"";position:absolute;left:-11.5px;top:calc(-.8em - 1px);bottom:-1px;border-left:1.5px solid currentColor;pointer-events:none`),
    // Свой заголовок свёртки внутри раскрытой (вложенная <details>; любая — под кнопкой «Свернуть
    // ответ»): место и стрелка те же, полоса внешней идёт сквозь его строку по вертикали ▾ и
    // расступается только вокруг самой стрелки — одна линия сверху донизу, без двойной и без сдвига.
    // Вложенная своей полосы правее не получает: узкому окну второй отступ дороже, чем граница
    // внутренней группы.
    `${FOLD_STRIP_HEAD}{position:relative}`,
    `${FOLD_STRIP_HEAD}::before{content:"";position:absolute;left:${FOLD_STRIP_LEFT};top:-6px;bottom:-6px;border-left:1.5px solid currentColor;pointer-events:none;-webkit-mask-image:linear-gradient(#000 calc(8px + .5lh - .5em),transparent calc(8px + .5lh - .5em) calc(8px + .5lh + .5em),#000 calc(8px + .5lh + .5em));mask-image:linear-gradient(#000 calc(8px + .5lh - .5em),transparent calc(8px + .5lh - .5em) calc(8px + .5lh + .5em),#000 calc(8px + .5lh + .5em))}`,
    `${FOLD_STRIP_HEAD}[${FOLD_HEAD_ATTRIBUTE}="open"]::before{bottom:-2px}`,
    // Раскрытая кнопка «Свернуть ответ»: полоса начинается сразу под ней, как под заголовком свёртки.
    `[${FOLD_WHOLE_ATTRIBUTE}="open"]{margin-bottom:2px}`,
    // «Прочитано» (#9377, раздел 12х; слово Элвиса 10.10: «слева нажимать… на зону… сереньким»,
    // «большими блоками… заметные, но всё же свёрнутые»). Дорожка — свой узел в строке ленты, слева
    // от текста; место и ширину даёт замер поля строки (переменные на корне). Текст ответа не сдвигается.
    // У самой дорожки не видно ничего ни в каком состоянии — ни волоска, ни края, ни подложки-полосы
    // (слово Элвиса 10.10 10:20 и 10:47: полоса слева — визуальный шум). Курсор на дорожке или фокус с
    // клавиатуры — тихой подложкой светится ВЕСЬ блок ответа: все его строки ленты, от дорожки до
    // правого края текста (#9506, слово Элвиса 10.10 ~11:00: «когда я на край навожу… должно
    // выделяться»), с задержкой, не сразу (#9649: «фоном со скруглёнными краешками… только с
    // задержкой») — уход гасит сразу. Подложка — слой дорожки цветом текста окна (светлая тема —
    // темнее фона, тёмная — светлее), без линии, скруглена у первой и последней строки; нажатий не
    // ловит — под ней текст как был.
    `[${READ_ZONE_ATTRIBUTE}]{position:absolute;top:0;bottom:0;left:var(${READ_LEFT_VARIABLE},2px);width:var(${READ_WIDTH_VARIABLE},20px);z-index:1;outline:none;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag}`,
    `[${READ_ZONE_ATTRIBUTE}]::before{content:"";position:absolute;top:0;bottom:0;left:0;width:var(${READ_SPAN_VARIABLE},100%);background:color-mix(in srgb,currentColor 8%,transparent);opacity:0;pointer-events:none;transition:opacity .15s}`,
    `[${READ_ZONE_ATTRIBUTE}][${READ_EDGE_ATTRIBUTE}~="top"]::before{border-top-left-radius:8px;border-top-right-radius:8px}`,
    `[${READ_ZONE_ATTRIBUTE}][${READ_EDGE_ATTRIBUTE}~="bottom"]::before{border-bottom-left-radius:8px;border-bottom-right-radius:8px}`,
    `[${READ_ZONE_ATTRIBUTE}]::after{content:"✓";position:sticky;top:8px;display:block;margin-right:4px;border-radius:4px;text-align:center;font-size:11px;line-height:16px;opacity:0;pointer-events:none;transition:opacity .15s}`,
    `[${READ_ZONE_ATTRIBUTE}][${READ_HOT_ATTRIBUTE}]::before{opacity:1;transition:opacity .2s ease .3s}`,
    `[${READ_ZONE_ATTRIBUTE}]:hover::after{opacity:.75}`,
    // Фокус с клавиатуры: блок подсвечен так же (метку ставит onReadHover), кольцо — у галочки, не вдоль дорожки.
    `[${READ_ZONE_ATTRIBUTE}]:focus-visible::after{opacity:.75;outline:2px solid rgba(245,158,11,.7);outline-offset:-1px}`,
    // Помечено: галочка у первой дорожки ответа (она же стоит в порядке Tab), линии нет.
    `[${READ_ZONE_ATTRIBUTE}="on"][tabindex="0"]::after{opacity:.75}`,
    // Поле слева от текста уже дорожки (узкое окно, «Поля» 5): галочке рядом с текстом места нет —
    // она только у свёрнутого блока; раскрытый ответ под курсором показывает подложка блока.
    `html[${READ_TIGHT_ATTRIBUTE}] [${READ_ZONE_ATTRIBUTE}]::after{margin-right:2px;font-size:10px}`,
    `html[${READ_TIGHT_ATTRIBUTE}] :not([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"])>[${READ_ZONE_ATTRIBUTE}]::after{opacity:0 !important}`,
    // Ответ ещё пишется — пометить нельзя: дорожка молчит.
    `[${READ_ZONE_ATTRIBUTE}][aria-disabled="true"]{cursor:default}`,
    `[${READ_ZONE_ATTRIBUTE}][aria-disabled="true"]::before{opacity:0 !important}`,
    `[${READ_ZONE_ATTRIBUTE}][aria-disabled="true"]::after{opacity:0 !important}`,
    // После перехода по «непрочитанные N» блок ответа коротко горит янтарём — той же подложкой.
    `@keyframes myclaude-read-hit{0%,40%{opacity:1;background-color:rgba(245,158,11,.16)}100%{opacity:0;background-color:rgba(245,158,11,0)}}`,
    `[${READ_ZONE_ATTRIBUTE}][${READ_HIT_ATTRIBUTE}]::before{animation:myclaude-read-hit 1.4s ease-out}`,
    // Свёрнутый прочитанный ответ. Узлы на местах, вид — высота 0 и прозрачность, НЕ display: innerText
    // такие строки отдаёт по-прежнему (полоса 2б, «Обкэшить», «ждут твоего слова», «Скажи — и сделаю»).
    `[${READ_ROW_ATTRIBUTE}="rest"]{height:0 !important;min-height:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // Блок — как свёрнутый ответ 12ф (WF218): полоска под ▾ свёрток, отступ 10 px, серая плашка; внутри —
    // первая строка ответа (затухает к правому краю) и тихая подпись. Своя полоска 12ф остаётся под срезом.
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]) [data-cds="AssistantMessage"]{position:relative;box-sizing:border-box !important;width:auto !important;min-height:0 !important;margin-left:calc(var(--myclaude-fold-mid, 7.4px) - .75px) !important;padding:4px 86px 4px 10px !important;gap:0 !important;border-left:1.5px solid currentColor;border-radius:0 8px 8px 0;background:rgba(127,127,127,.12);overflow:hidden !important;transition:background-color .15s}`,
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]) [data-cds="AssistantMessage"]::after{content:"прочитано";position:absolute;right:10px;top:0;bottom:0;display:flex;align-items:center;font-size:11px;line-height:1;opacity:.78;pointer-events:none}`,
    `[${READ_ROW_ATTRIBUTE}="bare"] [data-cds="AssistantMessage"]::before{content:"Ответ без текста";display:block;height:1.45em;padding-left:4px;overflow:hidden;opacity:.78}`,
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]) [data-cds="AssistantMessage"] :not([${READ_LINE_ATTRIBUTE}],[${READ_LINE_ATTRIBUTE}] *,:has([${READ_LINE_ATTRIBUTE}])){height:0 !important;min-height:0 !important;margin:0 !important;padding:0 !important;border:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    `[${READ_ROW_ATTRIBUTE}="head"] [data-cds="AssistantMessage"] :has([${READ_LINE_ATTRIBUTE}]){gap:0 !important;margin-top:0 !important;margin-bottom:0 !important;padding-top:0 !important;padding-bottom:0 !important;min-height:0 !important}`,
    `[${READ_ROW_ATTRIBUTE}="head"] [${READ_LINE_ATTRIBUTE}]{height:1.45em !important;margin:0 !important;overflow:hidden !important;opacity:.78;-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 40px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 40px),transparent)}`,
    `[${READ_ROW_ATTRIBUTE}="head"] [${READ_LINE_ATTRIBUTE}] *{white-space:nowrap !important}`,
    `[${READ_ROW_ATTRIBUTE}="head"] [${READ_LINE_ATTRIBUTE}] :is(h1,h2,h3,h4,h5,h6,[${FOLD_HEAD_ATTRIBUTE}]){margin:0 !important;padding-top:0 !important;padding-bottom:0 !important;border:0 !important;background:none !important;font-size:inherit !important}`,
    `[${READ_ROW_ATTRIBUTE}="head"] [${READ_LINE_ATTRIBUTE}]>:first-child,[${READ_ROW_ATTRIBUTE}="head"] [${READ_LINE_ATTRIBUTE}]>.contents>:first-child{margin-top:0 !important}`,
    // У свёрнутого блока галочка — на строке блока; курсор на дорожке подсвечивает его той же подложкой.
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"])>[${READ_ZONE_ATTRIBUTE}]::after{position:absolute;left:0;right:0;top:auto;bottom:6px}`,
    // Своя кнопка поверх блока: нажал — ответ раскрыт (пометка остаётся). Наведение, нажатие и фокус рисует плашка.
    `[${READ_OPEN_ATTRIBUTE}]{position:absolute;top:0;bottom:0;left:calc(var(${READ_LEFT_VARIABLE},2px) + var(${READ_WIDTH_VARIABLE},20px) + 2px);right:0;z-index:1;outline:none;cursor:pointer;-webkit-app-region:no-drag}`,
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]):has(>[${READ_OPEN_ATTRIBUTE}]:hover) [data-cds="AssistantMessage"]{background:rgba(127,127,127,.2)}`,
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]):has(>[${READ_OPEN_ATTRIBUTE}]:active) [data-cds="AssistantMessage"]{background:rgba(127,127,127,.3)}`,
    `:is([${READ_ROW_ATTRIBUTE}="head"],[${READ_ROW_ATTRIBUTE}="bare"]):has(>[${READ_OPEN_ATTRIBUTE}]:focus-visible) [data-cds="AssistantMessage"]{outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    // «непрочитанные N» — у правого края над полем ввода, на одной высоте со стрелкой «вниз» Claude
    // (в широком виде — слева от неё, правило в layoutCss). Подпись — из атрибута.
    `.group\\/approval-dock{--myclaude-read-pad-end:var(--chat-column-gutter-end,0px)}`,
    `#${READ_NEXT_ID}{position:absolute;right:var(--myclaude-read-pad-end,0px);bottom:calc(100% + 25px);z-index:1;display:flex;align-items:center;box-sizing:border-box;height:26px;padding:0 10px;border:1px solid var(--cds-border,rgba(127,127,127,.35));border-radius:13px;background:var(--cds-surface-3,rgba(127,127,127,.24));color:inherit;font-size:11px;line-height:1;font-variant-numeric:tabular-nums;white-space:nowrap;cursor:pointer;pointer-events:auto;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag;opacity:.8;transition:opacity .15s,border-color .15s}`,
    `#${READ_NEXT_ID}::after{content:attr(${READ_LABEL_ATTRIBUTE})}`,
    // Узкое окно: рядом со стрелкой «вниз» (она по середине) кнопке тесно — встаёт строкой выше.
    `@container tile-slot (max-width:399px){#${READ_NEXT_ID}{bottom:calc(100% + 64px)}}`,
    `@media (max-width:399px){#${READ_NEXT_ID}{bottom:calc(100% + 64px)}}`,
    `#${READ_NEXT_ID}:hover{opacity:1;border-color:currentColor}`,
    `#${READ_NEXT_ID}:active{opacity:.65}`,
    `#${READ_NEXT_ID}:focus-visible{opacity:1;outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    `@media (prefers-reduced-motion: reduce){[${READ_ZONE_ATTRIBUTE}]::before,[${READ_ZONE_ATTRIBUTE}]::after,#${READ_NEXT_ID}{transition:none !important}[${READ_ZONE_ATTRIBUTE}][${READ_HIT_ATTRIBUTE}]::before{animation:none;opacity:1;background-color:rgba(245,158,11,.16)}}`,
    // «Работа идёт» одной строкой (слово Элвиса 10.10 10:20, раздел 12х¹). Спрятанное серией — узлы на
    // местах, вид — высота 0 и прозрачность, НЕ display и не visibility: innerText ленты тот же (полоса
    // 2б, «Обкэшить», «ждут твоего слова», «Скажи — и сделаю»). Блок хода ещё и вне потока: пустые блоки
    // держали бы зазоры колонки; строка ленты — как свёрнутая строка «Прочитано».
    `[${WORK_ATTRIBUTE}="rest"]{position:absolute !important;height:0 !important;min-height:0 !important;margin:0 !important;padding:0 !important;border:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    `[${WORK_ATTRIBUTE}="row"]{height:0 !important;min-height:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // Ответ-точка (раздел 12х³) — так же: строка ленты на месте, высота 0; ничего не удаляется.
    `[${DOT_ATTRIBUTE}="row"],[${DOT_ATTRIBUTE}="gap"]{height:0 !important;min-height:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // Точка — последний блок хода: панель кнопок ответа (копия, ветка, глава, вслух, время) остаётся и
    // встаёт под текст выше с тем же зазором 6 px, что у обычного ответа; колонка текста — вне потока.
    `[${DOT_ATTRIBUTE}="text"]{position:absolute !important;height:0 !important;min-height:0 !important;margin:0 !important;padding:0 !important;border:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    `[${DOT_ATTRIBUTE}="tail"] [data-transcript-row]{margin-top:6px !important}`,
    // Строка-сводка — в системе свёрток 12ф: тот же знак ▸/▾ тем же весом, плашка под курсором, раскрытое
    // под полосой. Стрелка стоит на левой линии текста ответа (поле плашки вынесено влево). Подписи —
    // из атрибутов частей: текста в узле нет, копия и разбор ленты его не видят.
    `[${WORK_LINE_ATTRIBUTE}]{display:flex;align-items:center;gap:6px;box-sizing:border-box;width:fit-content;max-width:calc(100% + 4px);margin:0 0 0 -4px;padding:2px 6px 2px 4px;border-radius:6px;color:inherit;font-weight:400;white-space:nowrap;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-app-region:no-drag;transition:background-color .15s}`,
    `[${WORK_LINE_ATTRIBUTE}]:hover{background:rgba(127,127,127,.14)}`,
    `[${WORK_LINE_ATTRIBUTE}]:active{background:rgba(127,127,127,.24)}`,
    `[${WORK_LINE_ATTRIBUTE}]:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    `[${WORK_PART_ATTRIBUTE}]{flex:none}`,
    `[${WORK_PART_ATTRIBUTE}]::after{content:attr(${WORK_TEXT_ATTRIBUTE})}`,
    `[${WORK_PART_ATTRIBUTE}="arrow"]{font-weight:600}`,
    // Тихое — счёт шагов и вся строка прошедшей серии; цветом — только неудача (её отделяет цвет, без точки).
    `[${WORK_PART_ATTRIBUTE}="steps"],[${WORK_LINE_ATTRIBUTE}="done"] [${WORK_PART_ATTRIBUTE}="label"]{color:var(--cds-text-secondary,currentColor)}`,
    // Тесно (узкое окно, крупный шрифт) — сжимается счёт шагов; подпись и неудача остаются целыми.
    `[${WORK_PART_ATTRIBUTE}="steps"]{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}`,
    // Красный подмешан к цвету текста: на тёмной теме светлее, на светлой темнее — контраст с фоном от 4,5 : 1.
    `[${WORK_PART_ATTRIBUTE}="failed"]{color:color-mix(in srgb,#ef4444 65%,currentColor)}`,
    `[${WORK_PART_ATTRIBUTE}="failed"]:not([${WORK_TEXT_ATTRIBUTE}]){display:none}`,
    `@media (prefers-reduced-motion: reduce){[${WORK_LINE_ATTRIBUTE}]{transition:none}}`,
    // Одно и то же один раз (WF245): хвостовой абзац «Работа идёт» над свёрнутой серией — как хвосты К-CA;
    // так же — шаг первой строкой ответа (page-71), ответ под ним встаёт без своего верхнего отступа.
    `[${WORK_ATTRIBUTE}="head"]+*{margin-top:0 !important}`,
    `[${WORK_ATTRIBUTE}="echo"],[${WORK_ATTRIBUTE}="head"]{height:0 !important;min-height:0 !important;margin:0 !important;padding:0 !important;border:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // Полоса хода (WF245): N секторов по 2 px высотой, k залиты акцентом темы, остальные — тоном текста.
    // Числа счёта — из атрибута «k/N» в переменные; сектора режет маска, заливка — один переход.
    Array.from({ length: WORK_BAR_MAX + 1 }, (_, k) => `[${WORK_BAR_ATTRIBUTE}^="${k}/"]{--myclaude-work-k:${k}}${k ? `[${WORK_BAR_ATTRIBUTE}$="/${k}"]{--myclaude-work-n:${k}}` : ""}`).join(""),
    `[${WORK_PART_ATTRIBUTE}="bar"],p[${WORK_BAR_ATTRIBUTE}]::after{content:"";box-sizing:border-box;height:2px;border-radius:1px;background:linear-gradient(90deg,${WORK_BAR_FILL} calc((var(--myclaude-work-k) - var(--myclaude-work-live,0)) * ${WORK_BAR_STEP}),${WORK_BAR_TONE} 0);-webkit-mask:linear-gradient(90deg,#000 calc(100% - ${WORK_BAR_GAP}px),transparent 0) 0 0/${WORK_BAR_STEP} 100% repeat-x}`,
    `[${WORK_PART_ATTRIBUTE}="bar"]{position:relative;flex:0 1 auto;width:${WORK_BAR_WIDTH};min-width:0}`,
    `[${WORK_PART_ATTRIBUTE}="bar"]:not([${WORK_BAR_ATTRIBUTE}]){display:none}`,
    // Тесно — сжимается полоса (до нуля), счёт «k из N» остаётся целым.
    `[${WORK_PART_ATTRIBUTE}="bar"][${WORK_BAR_ATTRIBUTE}]~[${WORK_PART_ATTRIBUTE}="steps"]{flex:none}`,
    // Идущая серия: последний залитый сектор мягко дышит (свой слой поверх полосы); «Уменьшить движение» — стоит.
    `@keyframes myclaude-work-breath{from{opacity:1}to{opacity:.35}}`,
    `[${WORK_LINE_ATTRIBUTE}="live"] [${WORK_PART_ATTRIBUTE}="bar"]{--myclaude-work-live:1}`,
    `[${WORK_LINE_ATTRIBUTE}="live"] [${WORK_PART_ATTRIBUTE}="bar"]::before{content:"";position:absolute;top:0;bottom:0;left:calc((var(--myclaude-work-k) - 1) * ${WORK_BAR_STEP});width:calc(${WORK_BAR_STEP} - ${WORK_BAR_GAP}px);background:${WORK_BAR_FILL};animation:myclaude-work-breath 1.4s ease-in-out infinite alternate}`,
    `[${WORK_LINE_ATTRIBUTE}="live"] [${WORK_PART_ATTRIBUTE}="bar"][${WORK_BAR_ATTRIBUTE}^="0/"]::before{display:none}`,
    `@media (prefers-reduced-motion: reduce){[${WORK_LINE_ATTRIBUTE}="live"] [${WORK_PART_ATTRIBUTE}="bar"]::before{animation:none}}`,
    // Одиночная строка шага: абзац Claude на месте, его текст увезён за край (innerText тот же), на виду —
    // подпись без счёта и полоса; в узком окне полоса сжимается, строка не переносится.
    `p[${WORK_BAR_ATTRIBUTE}]{display:grid !important;grid-template:auto/max-content 0 minmax(0,${WORK_BAR_WIDTH});grid-auto-rows:0;align-items:center;white-space:nowrap !important;overflow:hidden !important;text-indent:-9999px}`,
    `p[${WORK_BAR_ATTRIBUTE}]::before{content:attr(${WORK_TEXT_ATTRIBUTE});grid-area:1/1;margin-right:8px;text-indent:0}`,
    `p[${WORK_BAR_ATTRIBUTE}]::after{grid-area:1/3}`,
    // Раскрытая серия — под полосой, как раскрытые свёртки (WF225): линия под стрелкой строки, отступ
    // 10 px; линия идёт сквозь зазоры между блоками и строками ленты, у первого блока — от его верха.
    `[${WORK_ATTRIBUTE}^="open"]{position:relative !important;box-sizing:border-box !important;padding-left:calc(${WORK_STRIP_LEFT} + 11.5px) !important}`,
    `[${WORK_ATTRIBUTE}^="open"]::before{content:"";position:absolute;left:${WORK_STRIP_LEFT};top:-16px;bottom:0;border-left:1.5px solid currentColor;pointer-events:none}`,
    `[${WORK_ATTRIBUTE}="open-first"]::before{top:-2px}`,
    // Карточки файлов в ленте (#9181, «восемь артефактов… ужасно выглядит»): у Claude каждая —
    // квадрат 120×120 с именем, размером и плашкой «HTML». Здесь — плашка в одну строку
    // «имя · размер», ряд плашек переносится; ссылка карточки та же — клик как у Claude.
    `${FEED_FILE_TILE}{width:auto !important;height:auto !important;min-width:0 !important;max-width:min(100%,240px) !important}`,
    `${FEED_FILE_TILE}>*{width:auto !important;height:auto !important;padding:3px 9px !important}`,
    `${FEED_FILE_TILE} .justify-between,${FEED_FILE_TILE} .justify-between>.flex-col{flex-direction:row !important;align-items:baseline !important;gap:6px !important}`,
    `${FEED_FILE_TILE} .justify-between>.flex-col .flex-col{flex-direction:row !important;gap:0 !important}`,
    `${FEED_FILE_TILE} .justify-between>:not(:first-child){display:none !important}`,
    `${FEED_FILE_TILE} .line-clamp-2{-webkit-line-clamp:1 !important;line-clamp:1 !important;font-size:12px !important}`,
    `${FEED_FILE_TILE} .text-caption{font-size:11px !important;flex-shrink:0}`,
    // Плитка .HEIC с пришедшей миниатюрой (раздел 12м⁴): вместо плашки с именем — фото высотой 120,
    // как плитки фото Claude; имя — в подсказке картинки. Миниатюры нет — плашка как была.
    `${FEED_FILE_TILE}[${HEIC_ATTRIBUTE}="on"]{padding:0 !important;overflow:hidden !important;cursor:pointer !important}`,
    `${FEED_FILE_TILE}[${HEIC_ATTRIBUTE}="on"]>:not([${HEIC_IMG_ATTRIBUTE}]){display:none !important}`,
    `${FEED_FILE_TILE}[${HEIC_ATTRIBUTE}="on"]>[${HEIC_IMG_ATTRIBUTE}]{display:block !important;width:auto !important;height:120px !important;max-width:100% !important;padding:0 !important;object-fit:cover;border-radius:inherit}`,
    // HTML и PDF (#10229) — карточка как в галерее: снимок верха страницы 260×170 над плашкой Claude (имя, размер);
    // снимок прозрачен для мыши — нажатие, правый клик и галочка «просмотрено» у плашки как были.
    // Карточка SendUserFile (#10383): миниатюра поверх плитки, нажатие проходит в карточку.
    `[${HEIC_ATTRIBUTE}^="card"]{position:relative !important;overflow:hidden !important}`,
    `[${HEIC_ATTRIBUTE}^="card"]>[${HEIC_IMG_ATTRIBUTE}]{position:absolute !important;inset:0;display:block !important;width:100% !important;height:100% !important;padding:0 !important;object-fit:cover;border-radius:inherit;pointer-events:none}`,
    `[${HEIC_ATTRIBUTE}="card-doc"]>[${HEIC_IMG_ATTRIBUTE}]{object-position:top}`,
    // #10603 (слово Элвиса 22.10: «превьюшки сделать HTML… как в PimpViewer… и джипы, и хейки, картинки вот так вот
    // отображать»): плашка SendUserFile (h-9 max-w-60) — карточка: превью 180 сверху (HTML и PDF — 240 в ширину, верх
    // страницы; фото — по пропорции 160…320), под ним та же плашка; превью прозрачно для мыши — нажатие, меню и
    // галочка у плашки как были. Квадраты Claude (вызов с картинкой) — высотой 180 по пропорции.
    `[${HEIC_ATTRIBUTE}^="plate"]{position:relative !important;width:var(${HEIC_WIDTH_VAR},240px) !important;max-width:100% !important;height:216px !important;padding-top:180px !important;border:1px solid rgba(255,255,255,.12) !important;border-radius:12px !important;overflow:hidden !important}`,
    `[${HEIC_ATTRIBUTE}^="plate"]>[${HEIC_IMG_ATTRIBUTE}]{position:absolute !important;top:0;left:0;display:block !important;width:100% !important;height:180px !important;max-width:none !important;margin:0 !important;padding:0 !important;object-fit:cover;object-position:top;border-bottom:1px solid rgba(255,255,255,.08);pointer-events:none}`,
    `[${HEIC_ATTRIBUTE}="plate-photo"]>[${HEIC_IMG_ATTRIBUTE}]{object-position:center}`,
    // Квадрат 120 самой карточки (вызов с картинкой): HTML и PDF — 240 в ширину, снимок 180 сверху, значок типа под
    // ним не нужен, имя и размер Claude — внизу.
    `[${HEIC_ATTRIBUTE}="square-doc"]{position:relative !important;width:240px !important;max-width:100% !important;height:auto !important;min-height:120px !important;padding-top:188px !important;justify-content:flex-end !important;border-radius:12px !important}`,
    `[${HEIC_ATTRIBUTE}="square-doc"]>[${HEIC_IMG_ATTRIBUTE}]{position:absolute !important;top:0;left:0;display:block !important;width:100% !important;height:180px !important;margin:0 !important;padding:0 !important;object-fit:cover;object-position:top;border-bottom:1px solid rgba(255,255,255,.08);pointer-events:none}`,
    `[${HEIC_ATTRIBUTE}="square-doc"]>div:first-child{display:none !important}`,
    // Чат Рика: карточку без нажатия Claude приглушает (opacity-70) — у Пимпа она нажимается (#10531), снимок — в полный цвет.
    `.opacity-70[${HEIC_ATTRIBUTE}]{opacity:1 !important}`,
    `:is(div,span):has(>:is([${HEIC_ATTRIBUTE}^="plate"],[${HEIC_ATTRIBUTE}="square-doc"],button[${HEIC_GROW_ATTRIBUTE}])){flex-wrap:wrap !important;align-items:flex-end !important}`,
    `button[${HEIC_GROW_ATTRIBUTE}]{width:var(${HEIC_WIDTH_VAR},120px) !important;max-width:100% !important;height:180px !important;max-height:none !important}`,
    `button[${HEIC_GROW_ATTRIBUTE}] [${HEIC_BOX_ATTRIBUTE}]{width:100% !important;height:100% !important;max-width:none !important;max-height:none !important}`,
    `button[${HEIC_GROW_ATTRIBUTE}] img:not([${HEIC_IMG_ATTRIBUTE}]){width:100% !important;height:100% !important;object-fit:cover !important}`,
    `${FEED_FILE_TILE}[${HEIC_ATTRIBUTE}="doc"]{position:relative !important;width:260px !important;max-width:min(100%,260px) !important;padding-top:170px !important;overflow:hidden !important}`,
    `${FEED_FILE_TILE}[${HEIC_ATTRIBUTE}="doc"]>[${HEIC_IMG_ATTRIBUTE}]{position:absolute !important;top:0;left:0;display:block !important;width:100% !important;height:170px !important;padding:0 !important;object-fit:cover;object-position:top;pointer-events:none}`,
    // Файл в поле ввода (#10345, снимок Элвиса 19.10: плитка 40 pt, а в ней путь крупным шрифтом
    // столбиком и вылезает за край): имя — мелко, одной строкой, обрезано. Пришла миниатюра (12м⁴) —
    // снимок во всю плитку под крестиком «Remove», текст спрятан.
    `[data-cds-composer-attachments] [data-cds="MessageAttachmentsFile"] :is(p,span,div):not(:has(button)):not(button *){min-width:0 !important;max-width:100% !important;overflow:hidden !important;white-space:nowrap !important;text-overflow:ellipsis !important;font-size:9px !important;line-height:12px !important}`,
    `[${HEIC_ATTRIBUTE}^="field"]{position:relative !important;isolation:isolate !important;padding:0 !important}`,
    `[${HEIC_ATTRIBUTE}^="field"] :is(p,span,div):not(:has(button)):not(button *):not([${HEIC_IMG_ATTRIBUTE}]){visibility:hidden !important}`,
    `[${HEIC_ATTRIBUTE}^="field"]>[${HEIC_IMG_ATTRIBUTE}]{position:absolute !important;inset:0;z-index:-1;display:block !important;width:100% !important;height:100% !important;padding:0 !important;object-fit:cover;border-radius:inherit;pointer-events:none}`,
    `[${HEIC_ATTRIBUTE}="field-doc"]>[${HEIC_IMG_ATTRIBUTE}]{object-position:top}`,
    // Bypass во всех чатах (#9060, раздел 12с¹): меню режимов, пока его открыла страница.
    `html[${BYPASS_QUIET_ATTRIBUTE}] :is([role="menu"],[role="listbox"]){opacity:0 !important;pointer-events:none !important}`,
    // Прятать инструменты (#7976, раздел 3а): законченная группа и список «Edited N
    // files» в строках ленты; где есть чем решать — видно (:has браузер сверяет вживую).
    // Группа внутри раскрытой серии «Работа идёт» (12х¹) видна: серию раскрывают, чтобы посмотреть шаги.
    `html[${HIDE_TOOLS_ATTRIBUTE}] ${HIDE_TOOLS_GROUP}[${HIDE_TOOLS_MARK}]:not([${WORK_ATTRIBUTE}^="open"]):not(:has(${HIDE_TOOLS_GROUP_DECISION},${HIDE_TOOLS_GROUP_UNSAFE})),html[${HIDE_TOOLS_ATTRIBUTE}] ${HIDE_TOOLS_FILES}[${HIDE_TOOLS_MARK}]:not(:has(${HIDE_TOOLS_DECISION},${HIDE_TOOLS_UNSAFE_BUTTON})){display:none !important}`,
    // Законченная строка фоновых команд — так же; внутри раскрытой серии «Работа идёт» видна.
    `html[${HIDE_TOOLS_ATTRIBUTE}] ${HIDE_TOOLS_TASKS}[${HIDE_TOOLS_MARK}]:not([${WORK_ATTRIBUTE}^="open"]){display:none !important}`,
    // Полоски глав Claude (nav «Session chapters») — ниже кнопок окна: при убранной боковой панели они
    // вставали под красную, жёлтую и зелёную (слово Элвиса 11.10 01:40, снимок 6).
    `.epitaxy-toc{top:48px !important}`,
    // Главы чата (раздел 12х², слово Элвиса 11.10 01:40: «чтоб главы были на таком же расстоянии, как
    // тексты… чтобы они не расширялись… все серенькие, но которая текущая — жирненькая. И когда навожу —
    // открывай подменю с названиями, оно так выезжает. И пусть весь интерфейс плавно затемнится»).
    // Дорожка: шаг полосок — шаг строк меню, поэтому названия выезжают РЯДОМ с полосками, а сами
    // полоски стоят на месте: дорожка лежит поверх меню, свои полоски строк меню спрятаны. Шаг,
    // толщина и яркость — переменные (настройка правой кнопкой); текущая — толще на 1 px и ярче на 30 пунктов
    // (#9758: было на 65 — «текущая глава сильно всё ещё яркая»), прочитанная зелёная — не ярче 60 %.
    // #10764 (скрин №3: полоски лежали на первых буквах текста — «должны быть левее… крупнее»): у Claude дорожка
    // с отступом 3/16 колонки, полоска 3/8 (короткие — 9/14 от неё, по центру), начало текста — около 9–10 px правее
    // края дорожки. Отступ снят, дорожка сдвинута на 4 px влево: полоска той же длины кончается до текста; крупнее —
    // толщиной и яркостью (CH_LOOK). Длиннее нельзя: длина растёт вправо, на текст.
    `${CH_RAIL}{position:relative;z-index:1;padding-block:6px !important;padding-inline-start:0 !important;translate:-4px 0;scrollbar-width:none}`,
    `${CH_RAIL}>li{flex:none;height:${CH_STEP} !important}`,
    `${CH_RAIL}>li>span{height:${CH_THICK} !important;width:calc(var(--chat-gutter,32px)*3/8) !important;background-color:var(--cds-text-primary,currentColor) !important;opacity:${CH_INK};transition:scale .2s,opacity .2s,height .2s,background-color .2s !important}`,
    `${CH_RAIL}>li>span[class~="bg-alpha-8"]{height:calc(${CH_THICK} + 1px) !important;opacity:min(1,calc(${CH_INK} + .3))}`,
    `${CH_RAIL}>li[${CH_READ_ATTRIBUTE}]>span{background-color:${CH_OK} !important;opacity:max(.6,${CH_INK})}`,
    // Меню показывает только страница (метка на nav): у Claude оно вылетает сразу и поверх полосок —
    // здесь с задержкой, выезжает слева; закрытое мышь не ловит. Пока открыто — дорожка пропускает
    // нажатия к строкам под ней.
    `${CH_MENU}{left:0 !important;top:0 !important;max-width:calc(100vw - 16px);padding-block:6px !important;translate:0 0 !important;transition:opacity .16s ease-out,transform .16s ease-out,visibility 0s linear .16s !important}`,
    `${CH_NAV_SELECTOR}:not([${CH_OPEN_ATTRIBUTE}])>div{visibility:hidden !important;opacity:0 !important;transform:translateX(-10px) !important;pointer-events:none !important}`,
    `${CH_NAV_SELECTOR}[${CH_OPEN_ATTRIBUTE}]>div{visibility:visible !important;opacity:1 !important;transform:none !important;pointer-events:auto !important;transition-delay:0s !important}`,
    `${CH_NAV_SELECTOR}[${CH_OPEN_ATTRIBUTE}]>ol[aria-hidden="true"]{pointer-events:none !important}`,
    `${CH_MENU}>ol{gap:0 !important;padding-inline:0 !important;scrollbar-width:none}`,
    // Панель шире, названия целиком (page-71, слово Элвиса 11.10 07:27: «многоточия-то эти не нужны… чтобы они
    // пошире, вот эта панель была… чтобы заголовки видел»): ширина — по самому длинному названию, не шире 560 и
    // окна; длиннее — перенос, строка растёт, а её полоска дорожки встаёт против неё (chAlign).
    `${CH_MENU}{width:max-content !important;min-width:min(240px,calc(var(${CH_ROOM_VARIABLE},100vw) - 16px)) !important;max-width:min(560px,calc(var(${CH_ROOM_VARIABLE},100vw) - 16px)) !important}`,
    `${CH_MENU}>ol>li{position:relative;flex:none;height:auto !important;min-height:${CH_STEP}}`,
    // Строка (тот же день: «галочки… справа… до них далеко тянуться. Давай галочки поставим вот: минус, потом
    // галочка… ну и название»): полоска дорожки, галочка, звёздочка (#9758), название. Название начинается правее
    // звёздочки (отступ дорожки 3/16 колонки + полоска 3/8 + 2, галочка 26, звёздочка 24, зазор 4); кегль не больше
    // 13 и не выше строки.
    `${CH_MENU}>ol>li>button:not([${CH_CHECK_ATTRIBUTE}],[${CH_STAR_ATTRIBUTE}]){height:auto !important;min-height:${CH_STEP} !important;gap:0 !important;padding-block:0 !important;padding-inline:calc(var(--chat-gutter,32px)*9/16 + 58px) 12px !important;text-align:left !important}`,
    `${CH_MENU}>ol>li>button>span[aria-hidden="true"]{display:none !important}`,
    `${CH_MENU}>ol>li>button>span:not([aria-hidden]){display:block !important;white-space:normal !important;overflow:visible !important;text-overflow:clip !important;overflow-wrap:anywhere;-webkit-line-clamp:unset !important;font-size:clamp(10px,calc(${CH_STEP} - 6px),13px) !important;line-height:min(18px,${CH_STEP}) !important}`,
    // Галочка «прочитано» — настоящая кнопка сразу за полоской: контур круга с галочкой, отмеченная — залита зелёным.
    `[${CH_CHECK_ATTRIBUTE}]{position:absolute;top:0;left:calc(var(--chat-gutter,32px)*9/16 + 6px);display:flex;align-items:center;justify-content:center;box-sizing:border-box;width:26px;height:100%;margin:0;padding:0;border:0;border-radius:5px;background:transparent;color:var(--cds-text-secondary,currentColor);opacity:.5;cursor:pointer;-webkit-app-region:no-drag;transition:opacity .15s,color .15s}`,
    `[${CH_CHECK_ATTRIBUTE}]>svg{display:block;width:min(15px,calc(${CH_STEP} - 4px));height:min(15px,calc(${CH_STEP} - 4px));pointer-events:none}`,
    `[${CH_CHECK_ATTRIBUTE}]>svg>[data-k="fill"],[${CH_CHECK_ATTRIBUTE}][aria-pressed="true"]>svg>[data-k="line"]{display:none}`,
    `[${CH_CHECK_ATTRIBUTE}][aria-pressed="true"]>svg>[data-k="fill"]{display:inline}`,
    `[${CH_CHECK_ATTRIBUTE}][aria-pressed="true"]{color:${CH_OK};opacity:1}`,
    `[${CH_CHECK_ATTRIBUTE}]:is(:hover,:focus-visible){opacity:1}`,
    `[${CH_CHECK_ATTRIBUTE}]:active{opacity:.65}`,
    `[${CH_CHECK_ATTRIBUTE}]:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:-2px}`,
    // Затемнение окна: свой узел размером с меню, тень от него — на всё окно. Сам узел прозрачен и мышь
    // не ловит: меню под ним светлое и рабочее, остальное притемнено и нажимается как обычно.
    `#${CH_DIM_ID}{position:fixed;left:0;top:0;width:0;height:0;box-sizing:border-box;border-radius:8px;background:transparent;box-shadow:0 0 0 200vmax rgba(0,0,0,.42);pointer-events:none;visibility:hidden;opacity:0;transition:opacity .2s ease-out,visibility 0s linear .2s;z-index:2147483647}`,
    `#${CH_DIM_ID}[data-on="true"]{visibility:visible;opacity:1;transition-delay:0s}`,
    // Панель настройки вида (правая кнопка по дорожке или меню) — в языке панели PMP: те же цвета
    // (--F, --T, --L, --S), скругление 12, текст 12/16; три строки «имя · ползунок · число» одной сеткой.
    `#${CH_SET_ID}{position:fixed;display:none;box-sizing:border-box;width:236px;max-width:calc(100vw - 16px);padding:10px 12px;border-radius:12px;border:1px solid var(--L);background:var(--F);color:var(--T);box-shadow:var(--S);font:400 12px/16px -apple-system,system-ui,sans-serif;font-variant-numeric:tabular-nums;text-align:left;z-index:2147483647;pointer-events:auto;-webkit-app-region:no-drag;user-select:none;-webkit-user-select:none}`,
    `#${CH_SET_ID} h3{margin:0 0 6px;padding:0;font:600 12px/16px -apple-system,system-ui,sans-serif;color:inherit}`,
    `#${CH_SET_ID} label{display:grid;grid-template-columns:76px minmax(0,1fr) 34px;align-items:center;column-gap:8px;height:24px;margin:0;padding:0;font:inherit;color:inherit}`,
    `#${CH_SET_ID} label>[data-k="num"]{text-align:right;opacity:.65;white-space:nowrap}`,
    `#${CH_SET_ID} input{box-sizing:border-box;width:100%;min-width:0;height:16px;margin:0;padding:0;accent-color:var(--T);cursor:pointer}`,
    `#${CH_SET_ID} input:focus-visible,#${CH_SET_ID} button:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:2px}`,
    `#${CH_SET_ID} [data-k="foot"]{display:flex;justify-content:flex-end;margin-top:6px}`,
    `#${CH_SET_ID} button{box-sizing:border-box;height:24px;margin:0;padding:0 10px;border:1px solid var(--L);border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:11px;line-height:1;cursor:pointer;transition:background-color .15s,opacity .15s}`,
    `#${CH_SET_ID} button:hover{background:color-mix(in srgb,var(--T) 10%,transparent)}`,
    `#${CH_SET_ID} button:active{background:color-mix(in srgb,var(--T) 18%,transparent)}`,
    `#${CH_SET_ID} button[aria-disabled="true"]{opacity:.45;cursor:default;background:transparent}`,
    `@media (prefers-reduced-motion: reduce){${CH_MENU},${CH_RAIL}>li>span,#${CH_DIM_ID},[${CH_CHECK_ATTRIBUTE}],#${CH_SET_ID} button{transition:none !important}}`,
    // Чистые ответы (#9398, раздел 3а¹): служебный хвост ответа — высота 0 и прозрачность, а НЕ display и
    // не visibility: innerText такой абзац по-прежнему отдаёт (полоса 2б, «ждут твоего слова», «Обкэшить»).
    `html[${CLEAN_ANSWERS_ATTRIBUTE}] ${CLEAN_ANSWERS_PROSE} p[${CLEAN_ANSWERS_MARK}]{height:0 !important;min-height:0 !important;margin:0 !important;padding:0 !important;border:0 !important;overflow:hidden !important;opacity:0 !important;pointer-events:none !important}`,
    // #9166а (WF165, слово Элвиса 09.10 00:05: «всё должно быть прозрачно… из-за того, что есть
    // сейчас рамка, я ничего не понимаю»): коробка поля ввода прозрачна и без обводки, кольца
    // и тени ВО ВСЕХ видах и состояниях (наведение, фокус — shadow-composer-*), не только с живым
    // фоном и не только в широком виде (#8132 отменён этим словом). Рамку прячет цвет: ширина и
    // тень «0 0 0 0» остаются — по ним editorFrame находит коробку (#6890).
    `${COMPOSER_BOX}{background-color:transparent !important;background-image:none !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important;border-color:transparent !important;box-shadow:0 0 0 0 transparent !important;outline:none !important}`,
    // #9993 (слово Элвиса 16.10 19:40: «именно в вертикальном режиме… рамка есть такая, которая поле
    // ввода символизирует, её нужно ставить… когда это поле внизу находится»): в главном окне, где поле
    // внизу, у прозрачной коробки видна её же рамка — 1 px сплошной, как у коробки в широком виде, цветом
    // линии темы (--cds-border, им же делится колонка широкого вида), скругление — Claude. Сильнее правила
    // выше и правила живого фона (.dframe-root впереди); широкий вид (правило колонки в @container сильнее
    // этого), свёрнутое поле (метка BLOCK_ATTRIBUTE на коробке или её предке) и попап «Open in new window»
    // (в нём .dframe-root нет) — без рамки, как были.
    `.dframe-root ${COMPOSER_BOX}:not([${BLOCK_ATTRIBUTE}^="collapsed"],[${BLOCK_ATTRIBUTE}^="collapsed"] *){border-width:1px !important;border-style:solid !important;border-color:var(--cds-border) !important}`,
    // #9166б: выбранный и наведённый чат в списке слева — тихая подложка цветом текста (4,5 % и 3 %, WF182),
    // без заливки акцентом (тема ставила 30 % акцента — «слишком ярко выделено») и без свечения.
    // Переменные Claude переопределены на панели и на самой строке — ближе, чем у темы (корень,
    // .cds-root, [data-mode]), и сильнее её; кольцо-свечение фокуса строки (focus-visible) снято.
    `aside.dframe-sidebar,aside.dframe-sidebar [data-row]{--df-selected:${SIDEBAR_SELECTED} !important;--df-hover:${SIDEBAR_HOVER} !important}`,
    `aside.dframe-sidebar [data-row],aside.dframe-sidebar [data-row-main-button]{box-shadow:none !important}`,
    // WF182: подложка реплики человека в ленте — переменная Claude на самой реплике (ближе корня темы).
    `[data-cds="UserMessage"]{--cds-bg-user-message:${USER_BUBBLE_FILL} !important}`,
    // Точки чатов — белые, тоном текста темы (слово Элвиса 11.10 01:40: «цветами не надо красить вот эти
    // кругляшки… фиолетовый кругляшок… Белые же должны быть просто»; акцент PMP #9166в снят). У Claude
    // «готов» — акцент, «ждёт» — жёлтая: здесь обе цветом текста; «идёт» — приглушённым, как у Claude, и
    // мигает по-прежнему; кружок «простаивает» — родной контур цветом строки. Цвет остался одной
    // ошибке (data-kind=error) — её пропустить нельзя; значок clay — картинка, не точка.
    `aside.dframe-sidebar .status-dot:not([data-kind="error"],[data-kind="clay"]){background:${SIDEBAR_DOT_INK} !important}`,
    `aside.dframe-sidebar .status-dot[data-kind="running"]{background:${SIDEBAR_DOT_QUIET} !important}`,
    // Поле «Search» списка слева — в тон панели (то же слово: «поиск очень жирный… не должно так
    // контрастно быть»): вместо тёмной плашки --cds-fill-field — подложка выбранной строки (4,5 % цвета
    // текста), под курсором чуть плотнее; кольца и тени нет (правило [data-row] выше), вес обычный.
    `aside.dframe-sidebar .df-search-field{background-color:${SIDEBAR_SELECTED} !important;background-image:none !important;font-weight:400 !important}`,
    `aside.dframe-sidebar .df-search-field:hover{background-color:${SIDEBAR_SEARCH_HOVER} !important}`,
    // #9167 (слово Элвиса: «все элементы должны прижиматься к правому. Либо они крошечные, либо
    // прижимаются к правому краю»): плашки ленты ответа — строки инструментов («Ran N commands»,
    // «Claude Code notice»), карточка «N background commands», карточки-вложения — по правому
    // краю колонки ленты, ширина по содержимому. Текст ответа не трогаем.
    `${FEED_PLATES}{width:fit-content !important;max-width:100% !important;align-self:flex-end !important;margin-inline-start:auto !important;justify-content:flex-end}`,
    // WF119 → WF176 (#9198): «✓ сделал» — маленькая кнопка под первой строкой пункта, без своей
    // колонки слева (она отъедала у списка до 9 rem пустого места); список и продолжения —
    // на родных отступах. Наведение, нажатие и «сделано» (амбер) — общие правила кнопок выше.
    `[${DONE_LIST_ATTRIBUTE}],[${DONE_CONT_ATTRIBUTE}]{box-sizing:border-box;min-width:0}`,
    `li[${DONE_ITEM_ATTRIBUTE}]{min-width:0;max-width:100%;overflow-wrap:anywhere}`,
    `li[${DONE_ITEM_ATTRIBUTE}]>[${NAZH_BUTTON_ATTRIBUTE}="done"]{display:flex;width:fit-content;margin:.3em 0 .2em;padding:0 7px;font-size:11px;line-height:18px;white-space:nowrap;transition:background-color .15s,border-color .15s}`,
    `li[${DONE_ITEM_ATTRIBUTE}]>[${NAZH_BUTTON_ATTRIBUTE}="done"]:active{background:rgba(245,158,11,.32)}`,
    `li[${DONE_ITEM_ATTRIBUTE}]>[${NAZH_BUTTON_ATTRIBUTE}="done"]:focus-visible{outline:2px solid rgba(245,158,11,.7);outline-offset:1px}`,
    `li[${DONE_ITEM_ATTRIBUTE}]>[${NAZH_BUTTON_ATTRIBUTE}="done"][${NAZH_ON_ATTRIBUTE}]:hover{background:rgb(250,176,51)}`,
    `li[${DONE_ITEM_ATTRIBUTE}] :is(p,pre,div,ul,ol){box-sizing:border-box;min-width:0;max-width:100%}`,
    `li[${DONE_ITEM_ATTRIBUTE}] pre,[${DONE_CONT_ATTRIBUTE}] pre,pre[${DONE_CONT_ATTRIBUTE}]{overflow-x:auto}`,
    `#${MIC_ID}>svg{display:block;width:14px;height:14px;pointer-events:none}`,
    `html[data-myclaude-ring-hover] [role="tooltip"],html[data-myclaude-ring-hover] [data-cds="Tooltip"]{display:none !important}`,
    // Нижняя строка поля ввода (#7206, вариант 8.1). Правила бьют только в
    // помеченные узлы (markChin, раздел 12з¹): чужое в строке не трогаем.
    // Микрофон Claude и стрелку ⌄ прячем стилем — узлы живы, и наш микрофон у
    // кружка в режиме «claude» жмёт родную кнопку и спрятанной (#7054).
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="hide"]{display:none !important}`,
    // Кнопки с подписью (режим, модель, эффорт): 11 px, строка 16.
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{font-size:11px !important;line-height:16px !important;height:16px !important;min-height:16px !important;padding-top:0 !important;padding-bottom:0 !important}`,
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"] *{font-size:inherit !important;line-height:inherit !important}`,
    // Короткие подписи не режутся (#7206, замер 23.09: в окне 177 кнопки ужаты
    // до 14/22/22 px, видна одна буква): кнопка не уже своего текста, текст в
    // одну строку и без обреза; обёртки кнопок («row») не уже содержимого. Не
    // хватает места — ужимаются зазоры (правило узкого окна ниже), не текст.
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{flex-shrink:0 !important;min-width:max-content !important;max-width:none !important;white-space:nowrap !important;overflow:visible !important}`,
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"] *{flex-shrink:0 !important;max-width:none !important;white-space:nowrap !important;overflow:visible !important;text-overflow:clip !important}`,
    // Обёртки кнопок — по середине строки (#9195: левая группа Claude прижата кверху, «BP» стоял выше
    // «O 5.5» на 2 точки); цифры — табличные.
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="row"]{min-width:min-content !important;align-self:center !important}`,
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{font-variant-numeric:tabular-nums}`,
    // Все подписи строки — одним цветом, притемнённым цветом темы (WF183, слово Элвиса 09.10 03:05:
    // «нижняя строка — всё разными цветами»: режим Bypass у Claude — свой яркий, модель и эффорт — белые).
    // От этого цвета (chinInk) берут свой и полоса Рика, «Галерея» и число недели.
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"],${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"] *{color:var(--cds-text-secondary,currentColor) !important}`,
    // Кружок токенов не ужимается и не уходит за край (WF183: «ему нельзя пропадать»): правое поле строки —
    // как левое у значка микрофона (MIC_ROOM_INSET); тесная строка ужимает поля подписей и зазоры, не кружок.
    `${CHIN_ROW_SELECTOR}{padding-inline-end:${MIC_ROOM_INSET}px !important}`,
    `${CHIN_SELECTOR} ${USAGE_RING_SELECTOR}{flex-shrink:0 !important}`,
    `${CHIN_SELECTOR}[${CHIN_ROW_ATTRIBUTE}] [${CHIN_ATTRIBUTE}="text"]{padding-left:3px !important;padding-right:3px !important}`,
    `${CHIN_SELECTOR}[${CHIN_ROW_ATTRIBUTE}] [${CHIN_ATTRIBUTE}="row"]:not(${CHIN_ROW_SELECTOR.replace(CHIN_SELECTOR, "").trim()}){gap:2px !important;column-gap:2px !important}`,
    `${CHIN_SELECTOR}[${CHIN_ROW_ATTRIBUTE}] [${CHIN_ATTRIBUTE}="row"][class*="ms-auto"]{padding-inline-start:2px !important}`,
    // Кнопки-значки (плюс): 16×16, значок 13.
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="icon"]{width:16px !important;min-width:16px !important;height:16px !important;min-height:16px !important;padding:0 !important}`,
    `${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="icon"] svg{width:13px !important;height:13px !important}`,
    // Подписи коротко ВСЕГДА — при любой ширине строки и окна (WF195, слово Элвиса 09.10 04:05–04:10:
    // «Op5.5 — мелко написать, только мелко… Bp… внизу опять всё едет»; до WF195 — только в тесной строке,
    // и широкая строка с длинными подписями раздувала пол колонки). Полное имя — подсказкой (title, markChin).
    // Тесная строка (метка chinRowFit) ужимает только поля и зазоры; кегль узкого окна ниже сильнее.
    `${CHIN_SELECTOR} [${CHIN_SHORT_ATTRIBUTE}]{font-size:0 !important;letter-spacing:0 !important}`,
    // WF226 (снимок Элвиса 10.10, замер живого окна): «Bp», «Op5.5», «Ex» стояли на 1,5–2 px выше цифр
    // галереи и недели и середины значков строки. Причина — распорка строки у держателя с кеглем 0: при
    // высоте строки 16 она раздувала строку подписи с 16 до 20, и подпись уезжала вверх. Без распорки
    // строка — ровно 16: базовая линия та же, что у родной подписи Claude и у цифр рядом. Хвост «5.5»
    // мельче головы — его строка 12, а не 16: иначе он один раздувал бы строку подписи модели вниз.
    `${CHIN_SELECTOR} [${CHIN_SHORT_ATTRIBUTE}]{line-height:0 !important}`,
    `${CHIN_SELECTOR} [${CHIN_SHORT_ATTRIBUTE}]::after{content:attr(${CHIN_SHORT_ATTRIBUTE});font-size:11px;line-height:16px}`,
    // Модель и эффорт в две строки (#9813, WF266; до того — «Op5.5» слитно, #9181): слово мелко сверху —
    // ::before («Opus», «Effort»), номер или код крупно снизу — ::after («5.5», «Ex») кеглем и строкой соседних
    // подписей (11/16), на одной базовой линии с «Bp», «PMP» и цифрами галереи. Держатель — inline-block: его
    // базовая линия — нижняя строка, ширина — по длинной из двух («Sonnet» над «5»). Слово поднято над строкой
    // отрицательным полем: высота подписи — те же 16, строка не растёт (узкое окно — правило ниже, 10 и 7).
    `${CHIN_SELECTOR} [${CHIN_TAIL_ATTRIBUTE}]{display:inline-block !important;vertical-align:baseline;text-align:center}`,
    `${CHIN_SELECTOR} [${CHIN_TAIL_ATTRIBUTE}]::before{content:attr(${CHIN_SHORT_ATTRIBUTE});display:block;margin-top:-8px;font-size:7.5px !important;line-height:8px}`,
    `${CHIN_SELECTOR} [${CHIN_TAIL_ATTRIBUTE}]::after{content:attr(${CHIN_TAIL_ATTRIBUTE});display:block;font-size:11px !important;line-height:16px;margin-left:0}`,
    // Узкое окно: 10 px. Подпись Claude не переписываем (её держит React) — она спрятана
    // кеглем 0 правилом выше (всегда, WF195), своя рисуется из атрибута. Полное имя
    // остаётся в aria-label и подсказке Claude.
    `@media (max-width:${CHIN_NARROW_MAX}px){${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{font-size:10px !important;padding-left:3px !important;padding-right:3px !important}${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="row"],${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{gap:2px !important;column-gap:2px !important}${CHIN_SELECTOR} [${CHIN_SHORT_ATTRIBUTE}]::after{content:attr(${CHIN_SHORT_ATTRIBUTE});font-size:10px !important;line-height:16px}}`,
    `@media (max-width:${CHIN_NARROW_MAX}px){${CHIN_SELECTOR} [${CHIN_TAIL_ATTRIBUTE}][${CHIN_SHORT_ATTRIBUTE}]::after{content:attr(${CHIN_TAIL_ATTRIBUTE});font-size:10px !important;line-height:16px;margin-left:0}${CHIN_SELECTOR} [${CHIN_TAIL_ATTRIBUTE}]::before{font-size:7px !important}}`,
    // Совсем узкое окно (#7206, 23.09 ~21:05): поля подписей и зазоры — 1 px.
    `@media (max-width:${CHIN_TINY_MAX}px){${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{padding-left:1px !important;padding-right:1px !important}${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="row"],${CHIN_SELECTOR} [${CHIN_ATTRIBUTE}="text"]{gap:1px !important;column-gap:1px !important}}`,
    // Значок Диктатора в поле узкого окна (WF92-ap2): отступ строки меньше.
    `@media (max-width:${MIC_ROOM_TINY_MAX}px){${CHIN_SELECTOR}[${MIC_ROOM_ATTRIBUTE}]{padding-left:${MIC_ROOM_PAD_TINY}px !important}}`,
    // Время под сообщением (#7747, раздел 14): текст рисуется из атрибута, в
    // textContent строки его нет — чтение ответов (полоса, «Обкэшить», копия)
    // его не видит. Родное время Claude в строке есть (последний ответ, реплика
    // человека, строка действий под мышью) — наше прячется, дубля рядом нет.
    `[${STAMP_ATTRIBUTE}]{display:block !important;pointer-events:none;user-select:none;-webkit-user-select:none}`,
    `[${STAMP_ATTRIBUTE}]::after{content:attr(${STAMP_ATTRIBUTE})}`,
    `${MESSAGE_ROW_SELECTOR}:has([aria-label="Message actions"] time)>[${STAMP_ATTRIBUTE}]{display:none !important}`,
    // #11618: строка действий русского Claude — «Действия с сообщением».
    `${MESSAGE_ROW_SELECTOR}:has([aria-label="Действия с сообщением"] time)>[${STAMP_ATTRIBUTE}]{display:none !important}`,
    // Время последнего сообщения при warm/cold — красное (и наше, и родное;
    // #7750, раздел 12о). Полоски окна не красятся и не мигают — серые (#7848).
    `${MESSAGE_ROW_SELECTOR}[${STALE_ATTRIBUTE}]>[${STAMP_ATTRIBUTE}],${MESSAGE_ROW_SELECTOR}[${STALE_ATTRIBUTE}] [aria-label="Действия с сообщением"] time,${MESSAGE_ROW_SELECTOR}[${STALE_ATTRIBUTE}] [aria-label="Message actions"] time{color:#ef4444 !important}`,
    `[${RING_ATTRIBUTE}]{position:absolute !important;right:${RING_INSET_RIGHT}px !important;bottom:${RING_INSET_BOTTOM}px !important;opacity:1 !important;pointer-events:auto !important;z-index:2147483645 !important}`,
    // Растягиваем скролл-контейнер, а сам редактор освобождаем от его
    // собственного максимума (в Claude Code это max-h-[218px] на .tiptap) —
    // иначе текст остаётся полосой сверху. Прокрутка одна: у контейнера,
    // редактор внутри не скроллит, поэтому вторая полоса не появляется.
    `[${EDITOR_ROOT_ATTRIBUTE}="true"]{box-sizing:border-box !important;height:var(${HEIGHT_VARIABLE}) !important;min-height:var(${HEIGHT_VARIABLE}) !important;max-height:var(${HEIGHT_VARIABLE}) !important;overflow-y:auto !important}`,
    `[${EDITOR_ROOT_ATTRIBUTE}="true"] [${EDITOR_ATTRIBUTE}="true"],[${EDITOR_ROOT_ATTRIBUTE}="true"][${EDITOR_ATTRIBUTE}="true"]{max-height:none !important;min-height:100% !important;height:auto !important;overflow-y:visible !important}`,
  ];

  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = RULES.join("\n");
  (document.head ?? document.documentElement).appendChild(style);
  track(() => style.remove());
  // CSP страницы может не пустить наш <style>. Молча это выглядит как
  // «полоски нет», поэтому проверяем сразу и отдаём наружу через
  // __myclaude.status(): резерв — перенести правила в claude.css, его лоадер
  // вставляет как cssOrigin:"user" и CSP страницы его не касается.
  state.cssOk = (() => {
    try { return (style.sheet?.cssRules?.length ?? 0) > 0; } catch { return false; }
  })();
  if (!state.cssOk) {
    try { console.warn("[MyClaude] стили ручки не применились (CSP?) — правила надо перенести в claude.css"); } catch {}
  }
  on(document, "securitypolicyviolation", event => {
    if (state.cssViolations.length >= 5) return;
    state.cssViolations.push({
      directive: String(event?.effectiveDirective ?? ""),
      blocked: String(event?.blockedURI ?? "").slice(0, 120),
    });
  });

  const handle = document.createElement("div");
  handle.id = HANDLE_ID;
  handle.setAttribute("role", "separator");
  handle.setAttribute("aria-orientation", "horizontal");
  handle.setAttribute("aria-label", "Изменить высоту поля ввода");
  // Подсказки при наведении нет: всплывающее «Потяни вверх или вниз» мешало
  // читать переписку и закрывало строку модели (слово Элвиса 12.09.2026,
  // #5857). Слепым полоска не стала — её называет aria-label.
  // Кнопки на полоске нет: стрелка получалась крошечной, сидела у правого края
  // и попасть в неё было нечем. Свёрнутое поле разворачивает одиночный клик по
  // любому месту полоски.
  handle.appendChild(document.createElement("span"));
  (document.body ?? document.documentElement).appendChild(handle);
  track(() => handle.remove());
  // Дубли полоски у краёв окна (#6743) — тем же приёмом, что и ручка: свой узел
  // в body, ставится по координатам. Роль у них кнопочная: тянуть нельзя.
  const makeSuperRail = id => {
    const node = document.createElement("div");
    node.id = id;
    node.setAttribute("role", "button");
    node.setAttribute("aria-label", "Свернуть или вернуть поле ввода");
    node.appendChild(document.createElement("span"));
    (document.body ?? document.documentElement).appendChild(node);
    track(() => node.remove());
    return node;
  };
  const superTop = makeSuperRail(SUPER_TOP_ID);
  const superBottom = makeSuperRail(SUPER_BOTTOM_ID);
  // Рейка ширины правой колонки (раздел 2г) — тем же приёмом: один узел на окно,
  // в body, ставится по координатам; в узком виде спрятана.
  const rail = document.createElement("div");
  rail.id = SIDE_RAIL_ID;
  rail.setAttribute("role", "separator");
  rail.setAttribute("aria-orientation", "vertical");
  rail.setAttribute("aria-label", "Изменить ширину правой колонки");
  rail.appendChild(document.createElement("span"));
  (document.body ?? document.documentElement).appendChild(rail);
  track(() => rail.remove());
  // Резерв на случай, когда CSP страницы не пустила наш <style>: положение
  // полоски и саму линию ставим напрямую через CSSOM — его CSP не касается
  // (запрещён бывает <style> и атрибут style, а не element.style.setProperty).
  // Без этого незастилованная полоска встала бы обычным блоком в поток страницы.
  // Сворачивание и высота этим не спасаются: их правила переносит в claude.css
  // оркестратор.
  if (!state.cssOk) {
    const box = {
      position: "fixed", display: "none", "align-items": "center", "justify-content": "center",
      height: `${HANDLE_HEIGHT}px`, padding: "0", border: "0", background: "transparent",
      cursor: "ns-resize", "user-select": "none", "-webkit-app-region": "no-drag",
      "touch-action": "none", "z-index": "2147483646",
    };
    const line = {
      display: "block", width: "100%", height: "2px", "border-radius": "999px",
      background: "currentColor", opacity: ".10", "pointer-events": "none",
    };
    for (const [name, value] of Object.entries(box)) handle.style.setProperty(name, value);
    const span = handle.firstElementChild;
    if (span) for (const [name, value] of Object.entries(line)) span.style.setProperty(name, value);
    // Дубли у краёв окна — та же полоска, только курсор не «тянуть» (#6891).
    for (const node of [superTop, superBottom]) {
      for (const [name, value] of Object.entries({ ...box, cursor: "pointer" })) node.style.setProperty(name, value);
      const own = node.firstElementChild;
      if (own) for (const [name, value] of Object.entries(line)) own.style.setProperty(name, value);
    }
    for (const [name, value] of Object.entries({
      position: "fixed", display: "none", width: `${SIDE_RAIL_WIDTH}px`, padding: "0", border: "0",
      background: "transparent", cursor: "col-resize", "user-select": "none", "touch-action": "none",
      "z-index": "2147483646",
    })) rail.style.setProperty(name, value);
  }
  // По ЖИВОМУ узлу (#6766): до WF78 здесь стояло одно только display, и
  // окно, из которого узел вынесло вместе с содержимым body, бодро
  // отвечало «полоска есть».
  statusPart("handleVisible", () => handle.isConnected && handle.style.display !== "none");
  // Дубли полоски у краёв окна (#6743): на гейте по ним видно, что полоска
  // на месте. Нижняя у свёрнутого поля уступает основной (#6892) — там
  // false и есть «как задумано».
  statusPart("superVisible", () => superTop.isConnected && superTop.style.display !== "none");
  statusPart("superBottomVisible", () => superBottom.isConnected && superBottom.style.display !== "none");
  HATCH && Object.assign(HATCH, { RULES });

  // ---- 5. Поиск поля ввода ------------------------------------------------
  // Свёрнутый блок ввода схлопнут в ноль и прижат к нижнему краю окна: у
  // редактора внутри геометрия перестаёт быть «видимой», хотя сам он живой и
  // держит черновик. Без этой поблажки поле терялось, свёрнутость снималась,
  // блок разворачивался — и на следующем кадре всё повторялось: низ окна
  // начинал мигать с частотой перерисовки.
  // Ниже этой ширины найденное считается не полем ввода, а чужим элементом
  // страницы. Порог не голые 200 точек: окна Элвиса бывают по 280, поле внутри
  // получается 194 — и по голому порогу поля в подчинённых окнах не находилось
  // вовсе, а вместе с ним пропадала и полоска над ним (#5857). В узком окне
  // порог считается от самого окна, в широком остаётся прежним.
  const narrowLimit = () => Math.min(200, innerWidth * 0.6);
  const visibleEditor = element => {
    const computed = getComputedStyle(element);
    if (element.disabled || computed.display === "none" || computed.visibility === "hidden") return false;
    if (element.closest(COLLAPSED_BLOCK_SELECTOR)) return true;
    const rect = element.getBoundingClientRect();
    // Само поле ввода Claude в узкой правой колонке бывает уже порога (09.10: 190 px при полях 24
    // по 33.5) — раскладка теряла поле, а с ним полосу Рика, шрифт поля и вложения. Порог узкого
    // окна — для чужих редакторов; поле composer'а видно от 120 px.
    const floor = element.closest('[data-cds="ChatComposer"]') ? Math.min(120, narrowLimit()) : narrowLimit();
    return rect.width >= floor && rect.bottom > 0 && rect.top < innerHeight;
  };
  // Кэш держится не на счётчике мутаций (во время набора дерево меняется каждую
  // букву), а на проверке самого ответа: прежнее поле всё ещё в документе, всё
  // ещё видно и всё ещё .ProseMirror. Держимся только за .ProseMirror — textarea
  // выигрывает развёртку лишь когда composer'а нет вовсе. И считаем ЖИВЫЕ
  // .ProseMirror: их число изменилось — значит рядом появился ещё один, и
  // выбирать надо заново (React пересоздаёт composer при смене чата).
  let editorHit = null;
  let editorSeen = -1;
  const findEditor = () => {
    const live = document.getElementsByClassName("ProseMirror");
    if (editorHit?.isConnected && live.length === editorSeen &&
        editorHit.classList.contains("ProseMirror") && visibleEditor(editorHit)) {
      return editorHit;
    }
    editorSeen = live.length;
    editorHit = [...document.querySelectorAll(EDITOR_SELECTOR)]
      .filter(visibleEditor)
      .map(element => ({ element, score: (element.matches(".ProseMirror") ? 100000 : 0) + element.getBoundingClientRect().bottom * 10 }))
      .sort((left, right) => right.score - left.score)[0]?.element ?? null;
    return editorHit;
  };
  // ---- 5а. Размер текста только в поле ввода (Dictator, #6186) -------------
  // Отдельная настройка: size.question принадлежит отправленным вопросам.
  // Один размер на все окна (WF107, #8126, К2): localStorage общий у окон Claude,
  // событие storage ставит новое значение в остальных окнах сразу. Приложение
  // шлёт команду composer-font (px или null); колесо Диктатора (⌃⌥⌘[ ]) и загрузка
  // страницы говорят значение приложению запросом /composer-font — для возврата
  // после переустановки Claude (px=none — приложение пришлёт своё зеркало командой).
  // Примерки размера поля нет (WF248 П2): её слало только меню жёлтой кнопки, а его сняли (лист 48 · 2.1).
  const COMPOSER_FONT_KEY = "myclaude-composer-font-size-v1";
  const COMPOSER_FONT_MIN = 11;
  const COMPOSER_FONT_MAX = 32;
  const composerFontOk = value => (Number.isInteger(value) && value >= COMPOSER_FONT_MIN &&
    value <= COMPOSER_FONT_MAX ? value : undefined);
  const readComposerFont = () => {
    try {
      const raw = localStorage.getItem(COMPOSER_FONT_KEY);
      return raw == null ? null : (composerFontOk(Number(raw)) ?? null);
    } catch { return null; }
  };
  let composerFontPx = readComposerFont();
  // loaded — запрос загрузки ушёл; pinged — сколько запросов ушло приложению.
  const composerFontState = { loaded: false, pinged: 0 };
  const COMPOSER_FONT_MARK = "data-myclaude-composer-font";
  // findEditor имеет геометрический fallback на чужие поля. Здесь он не годится:
  // нужен живой ProseMirror внутри известного блока ввода Claude.
  const isFontComposer = editor => editor?.isConnected &&
    editor.matches('.ProseMirror[contenteditable="true"]') &&
    !!editor.closest('.epitaxy-prompt, [data-cds="ChatComposer"]');
  let composerFontStyle = null;
  const clearComposerFont = () => {
    if (!composerFontStyle) return;
    const { editor, previous, priority, applied, previousMark } = composerFontStyle;
    // Чужую более позднюю правку стиля не откатываем.
    if (editor.style.getPropertyValue("font-size") === applied) {
      if (previous) editor.style.setProperty("font-size", previous, priority);
      else editor.style.removeProperty("font-size");
    }
    if (editor.getAttribute(COMPOSER_FONT_MARK) === "true") {
      if (previousMark == null) editor.removeAttribute(COMPOSER_FONT_MARK);
      else editor.setAttribute(COMPOSER_FONT_MARK, previousMark);
    }
    composerFontStyle = null;
  };
  const applyComposerFont = editor => {
    const px = composerFontPx;
    if (!themable || px == null || !isFontComposer(editor)) {
      clearComposerFont();
      return;
    }
    if (composerFontStyle?.editor !== editor) {
      clearComposerFont();
      composerFontStyle = {
        editor, previous: editor.style.getPropertyValue("font-size"),
        previousMark: editor.getAttribute(COMPOSER_FONT_MARK),
        priority: typeof editor.style.getPropertyPriority === "function"
          ? editor.style.getPropertyPriority("font-size") : "", applied: "",
      };
    }
    if (editor.getAttribute(COMPOSER_FONT_MARK) !== "true") editor.setAttribute(COMPOSER_FONT_MARK, "true");
    const size = `${px}px`;
    if (editor.style.getPropertyValue("font-size") !== size) {
      editor.style.setProperty("font-size", size, "important");
    }
    composerFontStyle.applied = size;
  };
  track(clearComposerFont);
  const onComposerFontKey = event => {
    if (!themable || !state.alive || !document.hasFocus() || event.defaultPrevented || event.isComposing ||
        !event.ctrlKey || !event.altKey || !event.metaKey || event.shiftKey ||
        !["BracketLeft", "BracketRight"].includes(event.code)) return false;
    const editor = state.editor;
    if (!isFontComposer(editor) || editor !== findEditor() || overlayOpen()) return false;
    const current = composerFontPx ?? parseFloat(getComputedStyle(editor).getPropertyValue("font-size"));
    if (!Number.isFinite(current)) return false;
    composerFontPx = Math.max(COMPOSER_FONT_MIN, Math.min(COMPOSER_FONT_MAX,
      Math.round(current) + (event.code === "BracketRight" ? 1 : -1)));
    applyComposerFont(editor);
    try { localStorage.setItem(COMPOSER_FONT_KEY, String(composerFontPx)); } catch {}
    composerFontPing();
    event.preventDefault();
    event.stopImmediatePropagation();
    scheduleLayout();
    return true;
  };
  // GET /composer-font?px=<N|none>&chat=<id> (К2): запрос CORS без credentials,
  // дошёл — и ладно. Без id чата не шлём: приложение без chat ничего не делает.
  const composerFontPing = () => {
    if (!themable || typeof fetch !== "function") return false;
    let chat = null;
    try { chat = myChatId(); } catch { chat = null; }
    if (typeof chat !== "string" || !chat) return false;
    try {
      fetch(`http://127.0.0.1:${HTML_CHROME_PORT}/composer-font?px=${composerFontPx ?? "none"}` +
        `&chat=${encodeURIComponent(chat)}`, { mode: "cors", credentials: "omit", cache: "no-store" }).catch(() => {});
    } catch { return false; }
    composerFontState.pinged += 1;
    composerFontState.loaded = true;
    return true;
  };
  // Один раз за загрузку, как только известен id чата (попап узнаёт его позже);
  // колесо раньше этого — тоже ответ, второго не нужно. fetch нет — и не будет.
  const composerFontLoadPing = () => {
    if (composerFontState.loaded) return;
    if (typeof fetch !== "function") composerFontState.loaded = true;
    else composerFontPing();
  };
  // Команда composer-font (К2). px — целое 11…32 или null («Как у Claude»),
  // прочее — мусор, ничего. Команда с preview:true (её слало снятое меню; старое
  // приложение) — мимо: иначе размер, мимо которого проехала мышь, лёг бы в хранилище.
  const runComposerFontCommand = detail => {
    if (!themable || !detail || typeof detail !== "object" || !("px" in detail) || detail.preview === true) return false;
    const px = detail.px === null ? null : composerFontOk(detail.px);
    if (px === undefined) return false;
    composerFontPx = px;
    try {
      if (px == null) localStorage.removeItem(COMPOSER_FONT_KEY);
      else localStorage.setItem(COMPOSER_FONT_KEY, String(px));
    } catch {}
    applyComposerFont(state.editor);
    scheduleLayout();
    return true;
  };
  // Колесо или команда в другом окне — сразу и здесь. key null — хранилище очищено целиком.
  const onComposerFontStorage = event => {
    if (!themable || (event?.key !== COMPOSER_FONT_KEY && event?.key !== null)) return;
    composerFontPx = readComposerFont();
    applyComposerFont(state.editor);
    scheduleLayout();
  };
  // Размер шрифта поля (WF107, К2): px — что на поле сейчас (null — как у
  // Claude), pinged — запросов приложению.
  statusPart("composerFont", () => ({ px: composerFontPx, pinged: composerFontState.pinged }));

  // ---- 5б. Последняя картинка поля ввода для Back в Dictator --------------
  // Метки границы поля и штатной кнопки: Dictator видит их через AX.
  // Нет перехвата Cmd+Z, команд в файлах, нового таймера или смены фокуса.
  const COMPOSER_IMAGE_UNDO_ID = "myclaude-remove-last-composer-image-v1";
  const COMPOSER_IMAGE_UNDO_SCOPE_ID = "myclaude-image-undo-composer-v1";
  let composerImageUndoMark = null;
  let composerImageUndoScopeMark = null;
  const clearComposerImageUndo = () => {
    for (const [mark, id] of [[composerImageUndoMark, COMPOSER_IMAGE_UNDO_ID],
      [composerImageUndoScopeMark, COMPOSER_IMAGE_UNDO_SCOPE_ID]]) {
      if (!mark || mark.node.getAttribute("id") !== id) continue;
      if (mark.previous == null) mark.node.removeAttribute("id");
      else mark.node.setAttribute("id", mark.previous);
    }
    if (composerImageUndoScopeMark?.addedRole &&
        composerImageUndoScopeMark.node.getAttribute("role") === "group") {
      composerImageUndoScopeMark.node.removeAttribute("role");
    }
    composerImageUndoMark = null;
    composerImageUndoScopeMark = null;
  };
  const composerImageUndoVisible = element => {
    if (!element?.isConnected) return false;
    // opacity:0 — нормальный крестик до наведения; display:none/hidden — нет.
    for (let node = element; node; node = node.parentElement) {
      const style = getComputedStyle(node);
      if (node.hasAttribute("hidden") || node.hasAttribute("inert") ||
          node.getAttribute("aria-hidden") === "true" || style.display === "none" ||
          style.visibility === "hidden" || style.visibility === "collapse") return false;
    }
    const rect = element.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  };
  const composerImageUndoScope = () => {
    if (!themable || !state.alive || overlayOpen()) return null;
    // findEditor выбирает по геометрии; отмена при двух полях выбирать не смеет.
    const editors = [...document.querySelectorAll('.ProseMirror[contenteditable="true"]')]
      .filter(editor => isFontComposer(editor) && visibleEditor(editor));
    if (editors.length !== 1 || editors[0] !== state.editor) return null;
    const editor = editors[0];
    const composer = editor.closest('[data-cds="ChatComposer"]') ?? editor.closest('.epitaxy-prompt');
    const role = composer.getAttribute("role");
    // Явно скрытый от AX контейнер не переопределяем. У div без роли ставим
    // временную group ниже, иначе Chromium вправе пропустить его в AXParent.
    if (role != null && (!role.trim() || /(?:^|\s)(?:generic|none|presentation)(?:\s|$)/i.test(role))) return null;
    // Метка нужна ещё ДО первой картинки. Высота широкого поля не ограничена:
    // оно занимает всю колонку, а блок вложений — сосед редактора внутри него.
    return composerImageUndoVisible(composer) &&
      composer.querySelectorAll('[data-cds-composer-attachments]').length <= 1 ? composer : null;
  };
  const composerImageUndoButton = (composer = composerImageUndoScope()) => {
    if (!composer) return null;
    const boxes = composer.querySelectorAll('[data-cds-composer-attachments]');
    if (boxes.length !== 1) return null;
    const images = boxes[0].querySelectorAll('[data-cds="MessageAttachmentsImage"][data-cds-attachment]');
    const last = images[images.length - 1];
    if (!last) return null;
    const buttons = [...last.querySelectorAll('button[aria-label]')].filter(button => {
      const label = String(button.getAttribute("aria-label") ?? "").trim();
      return attachRemoveLabel(label);
    });
    if (buttons.length !== 1) return null;
    const button = buttons[0];
    if (!button.isConnected || button.disabled || button.hasAttribute("disabled") ||
        button.getAttribute("aria-disabled") === "true") return null;
    return composerImageUndoVisible(button) ? button : null;
  };
  const syncComposerImageUndo = () => {
    const composer = composerImageUndoScope();
    const button = composerImageUndoButton(composer);
    if (composer && composer === composerImageUndoScopeMark?.node &&
        composer.getAttribute("id") === COMPOSER_IMAGE_UNDO_SCOPE_ID &&
        button === (composerImageUndoMark?.node ?? null) &&
        (!button || button.getAttribute("id") === COMPOSER_IMAGE_UNDO_ID)) return;
    clearComposerImageUndo();
    if (!composer || document.getElementById(COMPOSER_IMAGE_UNDO_SCOPE_ID)) return;
    const addedRole = !composer.hasAttribute("role");
    composerImageUndoScopeMark = { node: composer, previous: composer.getAttribute("id"), addedRole };
    composer.setAttribute("id", COMPOSER_IMAGE_UNDO_SCOPE_ID);
    if (addedRole) composer.setAttribute("role", "group");
    if (!button || document.getElementById(COMPOSER_IMAGE_UNDO_ID)) return;
    composerImageUndoMark = { node: button, previous: button.getAttribute("id") };
    button.setAttribute("id", COMPOSER_IMAGE_UNDO_ID);
  };
  track(clearComposerImageUndo);
  statusPart("composerImageUndo", () => ({
    version: 1,
    composer: Boolean(composerImageUndoScopeMark &&
      composerImageUndoScopeMark.node === composerImageUndoScope() &&
      composerImageUndoScopeMark.node.getAttribute("id") === COMPOSER_IMAGE_UNDO_SCOPE_ID),
    available: Boolean(composerImageUndoMark &&
      composerImageUndoMark.node === composerImageUndoButton() &&
      composerImageUndoMark.node.getAttribute("id") === COMPOSER_IMAGE_UNDO_ID),
  }));

  // ---- 5в. Только метаданные вложений для Dictator -----------------------
  // AXDescription содержит JSON; текста, имён, URL и файлов здесь нет.
  // Отсутствующая метка означает unknown, а не пустое поле. Число относится
  // только к карточкам текущего composer, не к серверному лимиту Claude.
  const COMPOSER_ATTACHMENTS_ID = "myclaude-composer-attachments-v1";
  const attachmentSession = globalThis.crypto?.randomUUID?.()
    ?? `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
  let attachmentGeneration = 0;
  let attachmentRevision = 0;
  let attachmentNextID = 0;
  let attachmentIDs = new WeakMap();
  let attachmentContext = null;
  let attachmentMembers = [];
  let attachmentMarker = null;
  let attachmentObserver = null;
  const clearAttachmentMarker = () => {
    attachmentMarker?.remove();
    attachmentMarker = null;
  };
  const invalidateAttachments = () => {
    clearAttachmentMarker();
    attachmentGeneration += 1;
    attachmentRevision = 0;
    attachmentMembers = [];
    attachmentIDs = new WeakMap();
  };
  const attachmentRoute = () => {
    const chat = myChatId();
    // Не угадываем попап по заголовку; используем существующее опознание Pimp.
    // У нового чата ещё нет id: DOM + маршрут + поколение задают его жизнь.
    const fresh = isMainWindow() && /^\/(?:epitaxy|new)\/?$/.test(location.pathname);
    // myChatId знает локальные чаты; обычный веб-чат опознаём отдельно.
    // Сам маршрут остаётся внутри замыкания, AX получает только поколение.
    const webChat = isMainWindow() && /^\/chat\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/?$/i.test(location.pathname);
    if (!chat && !fresh && !webChat) return null;
    return `${location.pathname}\n${location.search}\n${location.hash}\n${chat ?? "new"}`;
  };
  const attachmentCardReady = card => {
    if (!["MessageAttachmentsImage", "MessageAttachmentsFile"].includes(card.getAttribute("data-cds")) ||
        !composerImageUndoVisible(card) || card.querySelector('[data-cds-attachment]') ||
        card.matches('[aria-busy="true"],[data-state="loading"],[data-status="uploading"],[data-status="error"]') ||
        card.querySelector('[role="progressbar"],[role="alert"],[aria-busy="true"],[data-state="loading"],[data-status="uploading"],[data-status="error"]')) return false;
    if (card.getAttribute("data-cds") === "MessageAttachmentsImage") {
      const images = [...card.querySelectorAll("img")];
      if (images.length !== 1 || !images[0].complete || !(images[0].naturalWidth > 0)) return false;
    }
    const remove = [...card.querySelectorAll('button[aria-label]')].filter(button => attachRemoveLabel(button.getAttribute("aria-label")));
    return remove.length === 1 && !remove[0].disabled && !remove[0].hasAttribute("disabled") &&
      remove[0].getAttribute("aria-disabled") !== "true" && composerImageUndoVisible(remove[0]);
  };
  const syncComposerAttachments = () => {
    const composer = composerImageUndoScope();
    const route = attachmentRoute();
    const editor = state.editor;
    if (!composer || !route || composer.getAttribute("id") !== COMPOSER_IMAGE_UNDO_SCOPE_ID) {
      if (attachmentContext) invalidateAttachments();
      attachmentContext = null;
      attachmentObserver?.disconnect();
      return;
    }
    if (attachmentContext?.composer !== composer || attachmentContext?.editor !== editor ||
        attachmentContext?.route !== route) {
      invalidateAttachments();
      attachmentContext = { composer, editor, route };
      attachmentObserver?.disconnect();
      attachmentObserver ??= new MutationObserver(records => {
        const relevant = records.filter(record => {
          if (record.target === attachmentMarker) return false;
          const nodes = [...(record.addedNodes ?? []), ...(record.removedNodes ?? [])];
          return record.type !== "childList" || !nodes.length ||
            !nodes.every(node => node.id === COMPOSER_ATTACHMENTS_ID);
        });
        if (!relevant.length) return;
        // Полная замена содержимого редактора — возможный submit/reset.
        // Текст не читаем; лучше новый ticket, чем вставка в новое сообщение.
        if (relevant.some(record => record.target === attachmentContext?.editor &&
            (record.removedNodes?.length ?? 0) > 0)) invalidateAttachments();
        syncComposerAttachments();
      });
      attachmentObserver.observe(composer, { childList: true, subtree: true, attributes: true,
        attributeFilter: ["aria-busy", "aria-disabled", "disabled", "data-state", "data-status", "data-cds", "data-cds-attachment", "hidden", "inert", "aria-hidden", "contenteditable"] });
    }
    const boxes = [...composer.querySelectorAll('[data-cds-composer-attachments]')];
    const cards = boxes.length === 1 ? [...boxes[0].querySelectorAll('[data-cds-attachment]')] : [];
    // Ноль коробок в опознанном composer — нормальное состояние до первого
    // вложения. Чужие карточки без штатной коробки и неизвестная разметка — нет.
    // С 30.10 плитки лежат в коробке через обёртки (столбец → ряд прокрутки, #11187):
    // всё, что не плитка и не внутри неё, обязано держать плитку — заглушка
    // загрузки, чип папки или записи без плитки — неизвестная разметка.
    if (boxes.length > 1 || cards.length > 100 ||
        (boxes.length === 1 && [...boxes[0].querySelectorAll("*")].some(node =>
          !node.closest('[data-cds-attachment]') && !node.querySelector('[data-cds-attachment]'))) ||
        composer.querySelectorAll('[data-cds-attachment]').length !== cards.length ||
        composer.matches('[aria-busy="true"]') ||
        composer.querySelector('[role="progressbar"],[aria-busy="true"]') ||
        !cards.every(attachmentCardReady)) { clearAttachmentMarker(); return; }
    const members = cards.map(card => {
      if (!attachmentIDs.has(card)) attachmentIDs.set(card, `m${++attachmentNextID}`);
      return attachmentIDs.get(card);
    }).sort();
    // Удаление/замена прежней карточки не подтверждает наш paste и закрывает
    // прошлый ticket, даже если общее количество осталось прежним.
    if (attachmentMembers.some(id => !members.includes(id))) {
      invalidateAttachments();
      syncComposerAttachments();
      return;
    }
    if (members.join(",") !== attachmentMembers.join(",")) {
      attachmentRevision += 1;
      attachmentMembers = members;
    }
    if (attachmentMarker && attachmentMarker.parentElement !== composer) clearAttachmentMarker();
    if (!attachmentMarker) {
      if (document.getElementById(COMPOSER_ATTACHMENTS_ID)) return;
      attachmentMarker = document.createElement("span");
      attachmentMarker.id = COMPOSER_ATTACHMENTS_ID;
      attachmentMarker.setAttribute("role", "img");
      Object.assign(attachmentMarker.style, { position: "absolute", width: "1px", height: "1px",
        overflow: "hidden", clipPath: "inset(50%)", pointerEvents: "none" });
      composer.appendChild(attachmentMarker);
    }
    const payload = JSON.stringify({ v: 1, session: attachmentSession, generation: attachmentGeneration,
      revision: attachmentRevision, count: members.length, members });
    if (attachmentMarker.getAttribute("aria-label") !== payload) attachmentMarker.setAttribute("aria-label", payload);
  };
  const onAttachmentBoundary = event => {
    attachUndoMark(event);
    const context = attachmentContext;
    if (!context) return;
    const target = event.target;
    const inside = context.composer.contains(target) || target?.contains?.(context.editor);
    const sendKey = event.type === "keydown" && event.key === "Enter" && !event.shiftKey &&
      !event.metaKey && !event.altKey && !event.isComposing && context.editor.contains(target);
    const sendClick = event.type === "click" && (target?.closest?.('[data-testid="code-prompt-send"]') ||
      (inside && target?.closest?.('button[type="submit"]')));
    if (sendKey || sendClick || (inside && ["submit", "reset"].includes(event.type))) {
      attachUndoClear();
      if (event.type === "reset") { shotDraft().attempt = null; for (const job of shotState.jobs) shotCancel(job); }
      else shotAttempt();
      invalidateAttachments();
      scheduleLayout();
    }
  };
  track(() => { attachmentObserver?.disconnect(); clearAttachmentMarker(); attachmentContext = null; });
  // Скролл-контейнер редактора: высотой управляет он, поэтому кнопки composer
  // остаются на месте, а текст внутри прокручивается штатно.
  const findEditorRoot = editor => {
    let element = editor.parentElement;
    for (let depth = 0; element && depth < 5; depth += 1, element = element.parentElement) {
      const computed = getComputedStyle(element);
      if (computed.overflowY === "auto" || computed.overflowY === "scroll") return element;
    }
    return editor.parentElement;
  };
  // Видимая строка под узлом: строка модели или любая другая полоса. sr-only и
  // пустые обёртки в счёт не идут — по этой же примете разбирается низ блока в
  // findComposerParts.
  const rowUnder = node => {
    for (let sibling = node.nextElementSibling; sibling; sibling = sibling.nextElementSibling) {
      if (sibling.classList.contains("sr-only") || sibling.getAttribute("aria-hidden") === "true") continue;
      if (sibling.getBoundingClientRect().height >= MODEL_ROW_MIN_HEIGHT) return sibling;
    }
    return null;
  };
  // Внешняя рамка composer: полоску ставим на её верхнюю границу — над строкой
  // вложений, а не между вложениями и текстом. В нынешней сборке рамка зовётся
  // .epitaxy-prompt (замер оркестратора), и если она на месте — берём её. Если
  // класс переименуют, остаётся разбор донора по геометрии: признак рамки —
  // скругление, у контейнеров вокруг его нет вовсе. Скруглённый предок не
  // считается рамкой, если поднялся над полем выше, чем помещается строка
  // вложений: это уже разметка страницы.
  //
  // В сборке 12.09.2026 .epitaxy-prompt держит уже не рамку поля, а ВЕСЬ низ
  // окна: рамку и строку модели под ней. Отдать его рамкой — значит остаться
  // без внешнего блока: findComposerBlock возвращает тогда тот же узел,
  // collapseTargets — пустой список, и одинарный клик перестаёт сворачивать
  // поле вовсе (#5857, замер в живом окне: блок ввода на 566 точек из 784).
  // Поэтому рамку ищем ВНУТРИ него — берём самого верхнего предка поля, под
  // которым в том же родителе стоит ещё одна видимая строка. Именно она и есть
  // строка модели, а всё, что выше неё, — рамка со вложениями.
  const framedInside = (named, start) => {
    let frame = null;
    for (let node = start; node && node !== named && named.contains(node); node = node.parentElement) {
      if (rowUnder(node)) frame = node;
    }
    return frame;
  };
  const findShell = (editor, editorRoot) => {
    const named = editor?.closest?.(".epitaxy-prompt");
    if (named?.isConnected) return framedInside(named, editorRoot ?? editor) ?? named;
    const start = editorRoot ?? editor;
    const base = start.getBoundingClientRect();
    let shell = start;
    let frame = null;
    let element = start.parentElement;
    for (let depth = 0; element && depth < 12; depth += 1, element = element.parentElement) {
      const rect = element.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) continue;  // обёртки display:contents
      if (rect.width > base.width + 220 || rect.height > base.height + 260) break;
      if (rect.bottom < base.bottom - 40) break;
      shell = element;
      const radius = parseFloat(getComputedStyle(element).borderTopLeftRadius) || 0;
      if (radius >= FRAME_RADIUS && rect.top >= base.top - FRAME_RISE) frame = element;
    }
    return frame ?? shell;
  };
  // Блок ввода целиком: рамка поля, плашка проекта и строка модели. Сворачиваем
  // не его — иначе вместе с полем уезжает строка модели и effort, а она нужна
  // на виду всегда.
  //
  // Донор искал блок по .epitaxy-composer-width. В сборке 1.40609.1 такого
  // класса уже нет: боковые поля задаёт `ps-[var(--chat-gutter…)]` (тот же
  // контейнер, что известен как group/approval-dock). Поэтому селектора два, а
  // третьим — разбор по дереву: предок рамки, у которого под ней есть ещё один
  // видимый и невысокий сосед. Глубина ограничена: выше начинается лента
  // разговора, и схлопнуть её было бы катастрофой.
  const findComposerBlock = (editor, shell) => {
    const named = editor?.closest?.(".epitaxy-composer-width");
    if (named?.isConnected) return named;
    const gutter = editor?.closest?.('[class*="ps-[var(--chat-gutter"]');
    // Тот же класс носит и широкая обёртка вместе с лентой разговора. Свернуть
    // её значило бы спрятать весь разговор, поэтому кандидата проверяем дважды:
    // по содержимому (нет ли внутри ленты) и по росту.
    if (gutter?.isConnected && gutter !== shell &&
        !gutter.querySelector(TRANSCRIPT_SELECTOR) &&
        gutter.getBoundingClientRect().height <= innerHeight * 0.6) return gutter;
    let child = shell ?? editor;
    for (let depth = 0; child?.parentElement && depth < 3; depth += 1, child = child.parentElement) {
      const block = child.parentElement;
      for (let node = child.nextElementSibling; node; node = node.nextElementSibling) {
        const rect = node.getBoundingClientRect();
        if (rect.height >= MODEL_ROW_MIN_HEIGHT && rect.height <= 200) return block;
      }
    }
    return shell ?? null;
  };

  // Строка модели — единственный обычный сосед рамки ввода снизу внутри блока.
  // Ищем не селектором, а обходом соседей: рамкой может оказаться не прямой
  // ребёнок блока, а .sr-only и пустые обёртки надо пропускать по факту, а не по
  // имени класса. Не нашли — возвращаем null, и всё откатывается к прежнему
  // поведению «схлопнуть одну рамку поля».
  const findComposerParts = (block, shell) => {
    if (!block?.isConnected || !shell?.isConnected) return null;
    if (shell === block || !block.contains(shell)) return null;
    let frameChild = shell;
    while (frameChild && frameChild.parentElement !== block) frameChild = frameChild.parentElement;
    if (!frameChild) return null;
    for (let node = frameChild.nextElementSibling; node; node = node.nextElementSibling) {
      if (node.classList.contains("sr-only") || node.getAttribute("aria-hidden") === "true") continue;
      const computed = getComputedStyle(node);
      if (computed.display === "none" || computed.visibility === "hidden") continue;
      // Высотой отсеиваем пустые обёртки: строка модели место занимает, а
      // технический div между рамкой и ней — нет.
      if (node.getBoundingClientRect().height < MODEL_ROW_MIN_HEIGHT) continue;
      return { frameChild, modelRow: node };
    }
    return null;
  };

  // ---- 6. Сворачивание ----------------------------------------------------
  // Что именно схлопывать: рамка поля, всё, что стоит над ней (плашка проекта,
  // вложения, строка окружения), строка модели под ней и шапка чата сверху —
  // свёрнутое поле с 20.09 это режим чтения (#6651, слово Элвиса: «скрывалось
  // вообще всё внизу… и всё, что сверху, чтобы текст шёл на самый верх»). На виду
  // остаётся одна полоска: она живёт в body и садится на нижний край окна.
  const collapseTargets = () => {
    const block = state.composerBlock;
    if (!block?.isConnected) return [];
    // Блок целиком не схлопываем ни при каких обстоятельствах: вместе с ним
    // уезжает строка модели («Auto · Opus 5 · Max»), низ окна превращается в
    // чёрную полосу, и вернуть поле мышью становится нечем. Разбор низа
    // composer не удался — сворачиваем одну рамку поля, а если и её нет, не
    // сворачиваем вовсе: открытое поле лучше слепого окна.
    if (!state.frameChild?.isConnected || !state.modelRow?.isConnected) {
      const shell = state.shell;
      return shell?.isConnected && block.contains(shell) && shell !== block ? [shell] : [];
    }
    const targets = [];
    for (let node = block.firstElementChild; node; node = node.nextElementSibling) {
      if (isFocusGuard(node)) continue;
      targets.push(node);
      if (node !== state.modelRow) continue;
      const titlebar = document.querySelector(".epitaxy-titlebar");
      if (titlebar?.isConnected) targets.push(titlebar);
      return targets;
    }
    const shell = state.shell;
    return shell?.isConnected && block.contains(shell) && shell !== block ? [shell] : [];
  };

  // Режим чтения: лента идёт от самого верха окна, и первые строки просвечивали
  // сквозь кнопки окна и «Show sidebar» (слово Элвиса 20.09 06:10: «угловой фейд,
  // не на всю длину»). Не накладка, а маска самой ленты: текст в углу плавно
  // сходит на нет, цвет фона подбирать не надо и кнопки Claude ничем не закрыты.
  const CORNER_FADE_ATTRIBUTE = "data-myclaude-corner-fade";
  const CORNER_FADE_REACH_MAIN = 118;
  const CORNER_FADE_REACH_POPOUT = 78;
  const CORNER_FADE_DROP = 40;
  // Зеркальный фейд под кружком (#6737) МЕНЬШЕ левого верхнего намеренно: слева
  // под фейдом пустая шапка окна, а справа внизу — свежий текст, который Элвис
  // прямо сейчас читает; зеркало 118×40 съело бы конец последнего ответа.
  const CORNER_FADE_RING_REACH = 72;
  const CORNER_FADE_RING_RISE = 30;
  const cornerFade = { node: null };
  const clearRingFade = node => {
    if (!node) return;
    try {
      node.removeAttribute(RING_FADE_ATTRIBUTE);
      node.style.removeProperty("--myclaude-ring-fade-w");
      node.style.removeProperty("--myclaude-ring-fade-h");
    } catch {}
  };
  const clearCornerFade = () => {
    const node = cornerFade.node;
    cornerFade.node = null;
    if (!node) return;
    clearRingFade(node);
    try {
      node.removeAttribute(CORNER_FADE_ATTRIBUTE);
      node.style.removeProperty("--myclaude-fade-w");
      node.style.removeProperty("--myclaude-fade-h");
    } catch {}
  };
  track(clearCornerFade);
  const applyCornerFade = panel => {
    let scroller = null;
    // Главное окно (#7913) без шапки всегда: затухание и без режима чтения.
    const reading = state.stage === STAGE_COLLAPSED || (isMainWindow() && Boolean(panel?.isConnected));
    try { scroller = reading ? panel?.querySelector?.('[data-testid="epitaxy-virtual-transcript"]') ?? null : null; } catch {}
    const box = scroller?.isConnected ? scroller.getBoundingClientRect() : null;
    const reach = location.href === "about:blank" ? CORNER_FADE_REACH_POPOUT : CORNER_FADE_REACH_MAIN;
    const width = box ? reach - box.left : 0;
    const height = box ? CORNER_FADE_DROP - box.top : 0;
    // Открыта боковая панель — кнопки стоят над ней, а не над лентой.
    if (!box || box.width <= 0 || box.left >= TITLEBAR_CLEARANCE_LEFT || width <= 0 || height <= 0) { clearCornerFade(); return; }
    if (cornerFade.node !== scroller) clearCornerFade();
    cornerFade.node = scroller;
    const w = `${Math.round(width * 1.25)}px`;
    const h = `${Math.round(height * 1.35)}px`;
    if (scroller.style.getPropertyValue("--myclaude-fade-w") !== w) scroller.style.setProperty("--myclaude-fade-w", w);
    if (scroller.style.getPropertyValue("--myclaude-fade-h") !== h) scroller.style.setProperty("--myclaude-fade-h", h);
    if (!scroller.hasAttribute(CORNER_FADE_ATTRIBUTE)) scroller.setAttribute(CORNER_FADE_ATTRIBUTE, "");
    // Второй угол — только когда кружок и правда всплыл (#6737): нет кружка —
    // нет и фейда, и правило с двумя масками не применяется вовсе.
    const ringWidth = ringState.button?.isConnected ? CORNER_FADE_RING_REACH - (innerWidth - box.right) : 0;
    const ringHeight = ringState.button?.isConnected ? CORNER_FADE_RING_RISE - (innerHeight - box.bottom) : 0;
    if (ringWidth <= 0 || ringHeight <= 0) { clearRingFade(scroller); return; }
    const rw = `${Math.round(ringWidth * 1.25)}px`;
    const rh = `${Math.round(ringHeight * 1.35)}px`;
    if (scroller.style.getPropertyValue("--myclaude-ring-fade-w") !== rw) scroller.style.setProperty("--myclaude-ring-fade-w", rw);
    if (scroller.style.getPropertyValue("--myclaude-ring-fade-h") !== rh) scroller.style.setProperty("--myclaude-ring-fade-h", rh);
    if (!scroller.hasAttribute(RING_FADE_ATTRIBUTE)) scroller.setAttribute(RING_FADE_ATTRIBUTE, "");
  };

  // Кружок контекста в режиме чтения (#6737, WF78). Слово Элвиса 20.09: «кружок
  // — правый нижний угол, там же, где он и сейчас, он на своём месте остаётся
  // стоять, тот же кружок, просто плавает».
  //
  // Кружок НЕ вынимается из дерева и не клонируется — React потерял бы свой
  // узел. Вместо этого сужается действие свёртки на одну ветку: тому ОДНОМУ
  // прямому ребёнку блока ввода, внутри которого лежит кнопка, достаётся
  // «collapsed-ring» (свёртка без opacity, с overflow:visible и relative),
  // путь от него вниз до кнопки метится RING_PATH_ATTRIBUTE, соседи по пути
  // прячутся правилом, а сама кнопка метится RING_ATTRIBUTE и встаёт absolute
  // в правый нижний угол. Метки ставятся заново на каждом проходе: React
  // пересоздаёт узлы, как и для углового фейда.
  const ringState = { nodes: [], button: null };
  const clearRingPath = () => {
    for (const node of ringState.nodes) {
      if (node.isConnected) node.removeAttribute(RING_PATH_ATTRIBUTE);
    }
    if (ringState.button?.isConnected) ringState.button.removeAttribute(RING_ATTRIBUTE);
    ringState.nodes = [];
    ringState.button = null;
  };
  track(clearRingPath);
  // Прямой ребёнок блока ввода, внутри которого лежит кружок. Ищем подъёмом ОТ
  // КНОПКИ, а не по имени строки: разведка сама себе противоречит («над полем
  // ввода» и «в нижней строке поля ввода»), и класс тут был бы гаданием.
  // Кнопка, оказавшаяся прямым ребёнком блока, в счёт не идёт: путь до неё
  // пустой, а свёртка нулевой высоты срезала бы сам значок.
  const ringChild = block => {
    if (!block?.isConnected) return null;
    let button = null;
    try { button = block.querySelector(USAGE_RING_SELECTOR); } catch {}
    if (!button?.isConnected) return null;
    let child = button;
    while (child?.parentElement && child.parentElement !== block) child = child.parentElement;
    if (child?.parentElement !== block || child === button) return null;
    return { child, button };
  };
  const applyRingPath = ring => {
    if (!ring) { clearRingPath(); return; }
    const nodes = [];
    // Сама кнопка в путь НЕ входит: правило прячет всё, что внутри пути и не
    // помечено, а внутри кнопки лежит её собственный значок.
    for (let node = ring.button.parentElement; node && node !== ring.child; node = node.parentElement) nodes.push(node);
    nodes.push(ring.child);
    for (const node of ringState.nodes) {
      if (node.isConnected && !nodes.includes(node)) node.removeAttribute(RING_PATH_ATTRIBUTE);
    }
    if (ringState.button?.isConnected && ringState.button !== ring.button) ringState.button.removeAttribute(RING_ATTRIBUTE);
    for (const node of nodes) {
      if (!node.hasAttribute(RING_PATH_ATTRIBUTE)) node.setAttribute(RING_PATH_ATTRIBUTE, "");
    }
    if (!ring.button.hasAttribute(RING_ATTRIBUTE)) ring.button.setAttribute(RING_ATTRIBUTE, "");
    ringState.nodes = nodes;
    ringState.button = ring.button;
  };

  const clearCollapsedNodes = () => {
    for (const node of state.collapsedNodes) {
      if (node.isConnected) node.removeAttribute(BLOCK_ATTRIBUTE);
    }
    state.collapsedNodes = [];
    clearRingPath();
  };

  const applyCollapse = () => {
    const collapsed = state.stage === STAGE_COLLAPSED;
    const next = collapsed ? collapseTargets() : [];
    // Сворачивать нечего: в свёрнутой ступени не залипаем, иначе полоска
    // рисовалась бы поверх открытого поля и врала о состоянии.
    if (collapsed && next.length === 0) {
      clearCollapsedNodes();
      state.stage = STAGE_NORMAL;
      storeStage(STAGE_NORMAL);
      handle.dataset.collapsed = "false";
      return;
    }
    for (const node of state.collapsedNodes) {
      if (node.isConnected && !next.includes(node)) node.removeAttribute(BLOCK_ATTRIBUTE);
    }
    // Ветка с кружком контекста сворачивается по-своему (#6737): без opacity,
    // чтобы кружок остался виден и нажимаем. В широком виде ступень всегда
    // обычная (syncWide), поэтому сюда мы там просто не заходим.
    const ring = collapsed ? ringChild(state.composerBlock) : null;
    for (const node of next) node.setAttribute(BLOCK_ATTRIBUTE, node === ring?.child ? "collapsed-ring" : "collapsed");
    applyRingPath(next.includes(ring?.child) ? ring : null);
    state.collapsedNodes = next;
    handle.dataset.collapsed = collapsed ? "true" : "false";
    handle.setAttribute("aria-label", collapsed ? "Вернуть поле ввода" : "Изменить высоту поля ввода");
  };
  // #9859: новый узел свёрнутого поля прячется до первой отрисовки — из колбэка наблюдателя (раздел
  // 12ф, prePaintWatch), не через раскладку: та ждёт кадр, а то и LAYOUT_MIN_GAP, и пересобранная
  // React-ом строка поля мелькала раскрытой. Метится только бесспорное — прямой ребёнок блока не ниже
  // строки модели и шапка окна; ветку с кружком контекста (свой вид) и всё прочее сверит раскладка.
  const collapseOnMutation = records => {
    if (state.stage !== STAGE_COLLAPSED || !state.collapsedNodes.length) return;
    const block = state.composerBlock;
    const model = state.modelRow;
    if (!block?.isConnected || model?.parentElement !== block || !state.collapsedNodes.includes(model)) return;
    const hide = node => {
      if (node.hasAttribute(BLOCK_ATTRIBUTE)) return;
      node.setAttribute(BLOCK_ATTRIBUTE, "collapsed");
      state.collapsedNodes.push(node);
    };
    for (const record of records) {
      if (record.type !== "childList") continue;
      for (const node of record.addedNodes ?? []) {
        if (node?.nodeType !== 1 || !node.isConnected) continue;
        if (node.parentElement === block) {
          if (isFocusGuard(node)) continue;
          try { if (node.querySelector(USAGE_RING_SELECTOR)) continue; } catch { continue; }
          let above = node === model;
          for (let next = node.nextElementSibling; next && !above; next = next.nextElementSibling) above = next === model;
          if (above) hide(node);
          continue;
        }
        let bar = null;
        try { bar = node.matches?.(".epitaxy-titlebar") ? node : node.querySelector?.(".epitaxy-titlebar"); } catch {}
        if (bar?.isConnected) hide(bar);
      }
    }
  };
  HATCH && Object.assign(HATCH, { collapseTargets, collapseOnMutation });

  // ---- 7. Высота ----------------------------------------------------------
  // Куда именно упирается верх поля: в низ титульной полосы. Меряем её саму —
  // на части экранов Claude полосы просто нет, и константа врала бы.
  // Полоса есть, но нулевой высоты (замер 05.11, #11693: строка «Инструменты сессии» спрятана) — над полем пусто,
  // потолок — сам верх окна, ручка встаёт на место верхнего дубля (он уступает, раздел placeSuperRails).
  const topLimit = () => {
    const bar = document.querySelector(".epitaxy-titlebar");
    const rect = bar?.isConnected ? bar.getBoundingClientRect() : null;
    if (rect && rect.height > 0) return Math.round(rect.top + rect.height + 2);
    return rect && rect.width > 0 ? Math.round(Math.max(0, rect.top) + HANDLE_HEIGHT / 2) : SAFE_TOP_INSET;
  };
  const maximumHeight = () => {
    if (!state.shell) return 640;
    const top = state.shell.getBoundingClientRect().top;
    const current = state.height ?? state.editorRoot?.getBoundingClientRect().height ?? 0;
    return Math.max(MIN_HEIGHT, Math.floor(current + top - topLimit()));
  };
  const clampHeight = value => Math.round(Math.min(maximumHeight(), Math.max(MIN_HEIGHT, value)));
  // Обычная высота поля — та, которую Claude держит сам, без нашей подмены.
  // Меряем её только на ступени «обычная высота» и запоминаем: на других
  // ступенях померить нечего, а порог ступеней без неё не посчитать.
  const naturalHeight = () =>
    state.natural != null && state.natural >= MIN_HEIGHT ? state.natural : NATURAL_FALLBACK;

  const clearResizer = () => {
    if (state.editorRoot?.isConnected) {
      state.editorRoot.style.removeProperty(HEIGHT_VARIABLE);
      state.editorRoot.removeAttribute(EDITOR_ROOT_ATTRIBUTE);
    }
    if (state.editor?.isConnected) state.editor.removeAttribute(EDITOR_ATTRIBUTE);
    clearCollapsedNodes();
    handle.style.display = "none";
  };

  // Низ всего блока ввода: рамка поля, а под ней строка модели с кругляшком.
  const composerBottom = () => {
    const node = state.composerBlock?.isConnected
      ? state.composerBlock : (state.shell?.isConnected ? state.shell : null);
    if (node == null) return null;
    const rect = node.getBoundingClientRect();
    return rect.height > 0 ? rect.bottom : null;
  };
  const setHeightVariable = () => {
    state.height = clampHeight(state.height);
    state.editorRoot.setAttribute(EDITOR_ROOT_ATTRIBUTE, "true");
    state.editor?.setAttribute(EDITOR_ATTRIBUTE, "true");
    state.editorRoot.style.setProperty(HEIGHT_VARIABLE, `${state.height}px`);
  };
  // maximumHeight() считает место от ВЕРХА рамки: пока верх не упёрся в потолок,
  // формула разрешает расти. Но контейнер Claude верх выше своего края не
  // пускает, и лишние точки уходят ВНИЗ — вместе со строкой модели и кругляшком
  // отправки. Поэтому после каждой подстановки смотрим не на формулу, а на факт:
  // низ блока ввода обязан остаться в окне. Вылез — срезаем ровно на выступ.
  const trimToViewport = () => {
    if (state.height == null || !state.editorRoot?.isConnected) return;
    // Двух подходов хватает: первый срезает выступ, второй добирает остаток,
    // если контейнер отдал не всю высоту. Дальше ждём следующего прохода —
    // лесенка из бесконечных подрезаний хуже одной лишней точки.
    for (let step = 0; step < 2; step += 1) {
      const bottom = composerBottom();
      if (bottom == null) return;
      const over = Math.round(bottom - (innerHeight - BOTTOM_SAFE_INSET));
      if (over <= BOTTOM_TRIM_SLACK) return;
      const before = state.height;
      state.height = Math.max(MIN_HEIGHT, before - over);
      if (state.height >= before) { state.height = before; return; }
      setHeightVariable();
      // Срез не поднял низ — значит держит его не наша высота, и дальше мы
      // просто отбираем поле ни за что. Возвращаем как было.
      const after = composerBottom();
      if (after == null || after > bottom - BOTTOM_TRIM_SLACK) {
        state.height = before;
        setHeightVariable();
        return;
      }
    }
  };
  const applyHeight = () => {
    if (!state.editorRoot?.isConnected) return;
    if (state.height == null) {
      state.editorRoot.style.removeProperty(HEIGHT_VARIABLE);
      state.editorRoot.removeAttribute(EDITOR_ROOT_ATTRIBUTE);
      state.editor?.removeAttribute(EDITOR_ATTRIBUTE);
      return;
    }
    setHeightVariable();
    trimToViewport();
  };
  HATCH && Object.assign(HATCH, { clampHeight });

  // ---- 8. Полоска уступает всплывающим меню -------------------------------
  // Полоска живёт на самом верхнем z-index, поэтому меню Effort и модели она
  // перечёркивала насквозь. Ищем не по классам, а хит-тестом: стек элементов под
  // точкой уже отсортирован по z и не содержит прозрачных контейнеров
  // (pointer-events:none). Дошли до composer раньше чужого слоя — над полоской
  // ничего нет.
  const ownNode = node =>
    (state.shell?.isConnected === true && (state.shell.contains(node) || node.contains(state.shell))) ||
    (state.composerBlock?.isConnected === true &&
      (state.composerBlock.contains(node) || node.contains(state.composerBlock)));
  const popupCoversHandle = () => {
    const rect = handle.getBoundingClientRect();
    if (rect.width < 1) return false;
    const y = Math.round(rect.top + rect.height / 2);
    const points = [rect.left + 4, (rect.left + rect.right) / 2, rect.right - 4];
    for (const x of points) {
      for (const node of document.elementsFromPoint(Math.round(x), y)) {
        if (node === handle || handle.contains(node)) continue;
        if (node === document.body || node === document.documentElement) break;
        if (ownNode(node)) break;
        const computed = getComputedStyle(node);
        if (computed.position !== "fixed" && computed.position !== "absolute") continue;
        // z-index:auto — тоже слой: у попапа Effort числового z-index нет вовсе,
        // и полоска рисовалась НАСКВОЗЬ через его карточку. Безопасно, потому
        // что всё своё уже отсеяно, прозрачные обёртки в elementsFromPoint не
        // попадают, а хит-тест идёт ровно по трём точкам полоски.
        const z = Number(computed.zIndex);
        if (Number.isFinite(z)) {
          if (z >= POPUP_MIN_Z) return true;
          continue;
        }
        if (computed.position === "fixed") return true;
      }
    }
    return false;
  };
  // Есть ли вообще что прятать: открытое меню, список или модалка. Считаются только видимые узлы:
  // скрытый узел с ролью накладки (закрытая панель, постоянный [data-state="open"]) — не накладка.
  const overlayOpen = (selector = OVERLAY_SELECTOR) => {
    for (const node of document.querySelectorAll(selector)) {
      const rect = node.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) return true;
    }
    return false;
  };
  // Отступ свёрнутой полоски от краёв рамки — её собственное скругление плюс
  // пара точек.
  const handleInset = node => {
    const radius = node?.isConnected
      ? parseFloat(getComputedStyle(node).borderTopLeftRadius) || 0
      : 0;
    return Math.max(HANDLE_MIN_INSET, Math.round(radius) + 2);
  };

  // Место всех трёх полосок: ось и ширина у них общие (#6891, слово Элвиса
  // 21.09: «они все три должны быть соосными, все в одном месте… все одной
  // толщиной»). Одна функция — единственный способ не дать им разъехаться:
  // полоска поля ходит за полем, дубли стоят у краёв окна, и до 21.09 каждая
  // считала ширину и центр по-своему — расходились на несколько точек.
  //
  // Ось — центр ОКНА (слово Элвиса 21.09 про дубли: «чтобы они всегда были по
  // центру окна»), но сойти с поля полоска не имеет права: открытая боковая
  // панель уводит поле вправо, и по центру окна линия села бы на список чатов,
  // а её зона захвата съела бы нажатия по нему. Тогда ось прижимается к краю
  // поля — и все три едут вместе, иначе соосность теряется.
  //
  // Ширина — узкая полоска донора: во всю ширину рамки зона захвата накрывает
  // кнопки и надписи по краям поля («широченная», слово Элвиса). В узком окне
  // ужимается по самому полю, но не уже RAIL_MIN_WIDTH. Берём чётной: при
  // нечётной центр приходится на половину точки.
  const railSeat = () => {
    const shell = state.shell?.isConnected ? state.shell : null;
    const block = state.composerBlock?.isConnected ? state.composerBlock : null;
    const shellBox = shell ? shell.getBoundingClientRect() : null;
    // Рамка свёрнутого поля схлопнута в ноль, но ширину держит блок ввода; нет
    // и его — считаем по окну: дубли у краёв окна нужны и такому окну.
    const onShell = shellBox != null && shellBox.width >= RAIL_HOST_MIN;
    const box = onShell ? shellBox : (block ? block.getBoundingClientRect() : null);
    const rect = box != null && box.width >= RAIL_HOST_MIN ? box : null;
    const inset = rect ? handleInset(onShell ? shell : block) : HANDLE_MIN_INSET;
    const left = rect ? rect.left + inset : HANDLE_MIN_INSET;
    const right = rect ? rect.right - inset : innerWidth - HANDLE_MIN_INSET;
    const width = Math.round(Math.max(RAIL_MIN_WIDTH,
      Math.min(HANDLE_NARROW_WIDTH, right - left)) / 2) * 2;
    const half = width / 2;
    // Ось — центр ПОЛЯ (#7201, 23.09: «должно же быть по центру… и у верхнего и
    // нижнего тоже по центру, соосно»): при открытой боковой панели центр окна
    // уводил все три к краю поля. Поля нет — центр окна.
    const axis = rect ? (left + right) / 2 : innerWidth / 2;
    return { left: Math.round(axis - half), width };
  };

  // ---- 9. Раскладка -------------------------------------------------------
  // Свёрнутая рамка занимает нулевую высоту, поэтому её геометрия для
  // расстановки уже не годится: полоска садится над строкой модели — она
  // осталась на виду и держит низ блока. Строки нет — полоска возвращается на
  // нижний край окна.
  const placeCollapsedHandle = () => {
    // Место общее на все три полоски (railSeat, #6891): и ось, и ширина у
    // свёрнутой полоски те же, что у открытой и у дублей у краёв окна. Полной
    // шириной она наезжала бы зоной захвата на надпись «Opus 5 · Max» и
    // кругляшок рядом с ней, поэтому узкая — как у донора.
    const spot = railSeat();
    const row = state.modelRow?.isConnected ? state.modelRow.getBoundingClientRect() : null;
    handle.style.display = "flex";
    handle.style.left = `${spot.left}px`;
    handle.style.width = `${spot.width}px`;
    // Линия садится ровно на верхнюю кромку строки модели — так же, как на
    // открытом поле она садится на кромку рамки: зона захвата стоит верхом на
    // кромке, то есть выше неё ровно половина. Выше (на целую высоту зоны, как
    // было до 12.09) полоска висела над строкой модели поверх кнопки Claude
    // «вниз к последнему сообщению» и казалась оторванной от поля (#5866,
    // #5867). Сливаться с полосой прогресса ей больше нечем: на свёрнутом поле
    // та переехала на низ блока ввода (progressApply).
    // Кнопку Claude «вниз к последнему сообщению» зона захвата не ест: где та
    // прижата к строке модели, полоска встаёт под её низом. Ищем кнопку только
    // в свёрнутом виде и только по её собственной примете.
    let below = null;
    try {
      const down = document.querySelector('[aria-label="Scroll to bottom"],[aria-label="Прокрутить вниз"]');
      const box = down?.isConnected ? down.getBoundingClientRect() : null;
      if (box && box.height > 0) below = box.bottom;
    } catch {}
    const seat = row && row.height > 0
      ? row.top - HANDLE_HEIGHT / 2
      : innerHeight - HANDLE_HEIGHT - 4;
    handle.style.top = `${Math.round(below != null ? Math.max(seat, below) : seat)}px`;
    // Хит-тест нужен и здесь: меню модели и effort раскрываются вверх ровно над
    // этим местом. Но одного хит-теста мало: свёрнутая полоска сидит верхом на
    // кромке строки модели, то есть половиной уже вне блока ввода, и любой
    // градиент расшифровки с position:absolute спрятал бы её навсегда — а
    // вернуть поле мышью больше нечем. Поэтому прячем только когда меню
    // действительно открыто.
    state.handleCovered = !state.dragging && overlayOpen() && popupCoversHandle();
    if (state.handleCovered) handle.style.display = "none";
  };

  // Есть ли у поля в этом окне ступени: редактор нашёлся (или поле уже
  // свёрнуто) и вид узкий. В широком виде ступеней нет вовсе (syncWide), и
  // нажималка свернула бы поле, которое нечем вернуть. Поле спрашиваем САМИ, а
  // не ждём, пока его найдёт проход раскладки: полоски ставятся до всех ранних
  // выходов, и на первом же проходе после установки state.editor ещё пуст — без
  // своего вопроса они появлялись бы только со второго прохода. findEditor
  // держит свой кэш, так что вопрос дешёвый.
  const stagesLive = () => state.alive && state.watching && !wideState.on &&
    ((state.editor?.isConnected ? state.editor : findEditor()) != null || state.stage === STAGE_COLLAPSED);

  // Дубли полоски у краёв окна (#6743). Место берут у railSeat — то же, что у
  // полоски поля: ось, ширина и высота зоны у всех трёх одни (#6891).
  const placeSuperRails = () => {
    const live = stagesLive();
    const seat = live ? railSeat() : null;
    // Свёрнутое поле — режим чтения: основная полоска садится на нижнюю кромку
    // окна, ровно туда же, где стоит нижний дубль, и линии шли две в точку
    // друг от друга. Слово Элвиса 21.09 (#6892): «они не должны конфликтовать…
    // одна полоска должна по итогу быть». Уступает дубль: за основную ещё и
    // тянут, и она заметнее.
    const collapsed = state.stage === STAGE_COLLAPSED;
    // Поле развёрнуто до верха окна (#11693) — ручка поля легла на место верхнего дубля: уступает и он.
    let atTop = false;
    if (live && state.stage === STAGE_STRETCHED && state.shell?.isConnected) {
      try { atTop = state.shell.getBoundingClientRect().top - HANDLE_HEIGHT / 2 < HANDLE_HEIGHT; } catch {}
    }
    const seats = [[superTop, 0, atTop], [superBottom, Math.round(innerHeight - HANDLE_HEIGHT), collapsed]];
    for (const [node, top, yields] of seats) {
      if (!live || yields) {
        if (node.style.getPropertyValue("display") !== "none") node.style.setProperty("display", "none");
        continue;
      }
      node.style.setProperty("display", "flex");
      node.style.setProperty("left", `${seat.left}px`);
      node.style.setProperty("width", `${seat.width}px`);
      node.style.setProperty("top", `${top}px`);
    }
  };

  // Карточка разрешения — слоем над лентой (#6590). Слово Элвиса: «вот эти вот Allow,
  // которые окошки появляются... сдвигают вверх чат весь. И он скачет вверх-вниз, как на
  // лошади. Пусть появляются так же, просто сверху, над чатом, чтоб чат на месте оставался».
  // Карточка Claude (.epitaxy-approval-card) встаёт в доке над полем и отнимает у ленты свою
  // высоту: лента у низа догоняет низ (вверх), а уходя карточка отдаёт место, и лента падает
  // обратно (вниз). В узком виде дока помечена заранее, и CSS кладёт карточку слоем у верхней
  // кромки доки тем же кадром, что её вставка: место ленты не меняется ни на кадр. Сама
  // карточка, её кнопки и клавиши — Claude-овские. Переменные доки: место над ней до верха
  // ленты (потолок карточки) и края поля ввода (её ширина). Метки нет — карточка встаёт, как
  // у Claude: широкий вид (дока — своя колонка, ленту она не двигает), ленты над полем меньше
  // CARD_FLOAT_MIN (поле растянуто), слой не виден (его закрыло или обрезало чужое — тогда
  // до перезагрузки страницы: карточка в потоке лучше невидимой).
  const CARD_SELECTOR = ".epitaxy-approval-card";
  const CARD_FLOAT_ATTRIBUTE = "data-myclaude-card-float";
  const CARD_SOLID_ATTRIBUTE = "data-myclaude-card-solid";
  const CARD_FLOAT_MIN = 160;
  const CARD_FLOAT_GAP = 6;
  const CARD_VARS = ["--myclaude-card-room", "--myclaude-card-start", "--myclaude-card-end"];
  const cardFloat = { dock: null, broken: false, cards: 0 };
  const clearCardFloat = () => {
    const dock = cardFloat.dock;
    cardFloat.dock = null;
    if (!dock) return;
    try {
      dock.removeAttribute(CARD_FLOAT_ATTRIBUTE);
      for (const name of CARD_VARS) dock.style.removeProperty(name);
      for (const card of dock.querySelectorAll(`[${CARD_SOLID_ATTRIBUTE}]`)) card.removeAttribute(CARD_SOLID_ATTRIBUTE);
    } catch {}
  };
  track(clearCardFloat);
  // Слой виден: в его середине — он сам или наш узел поверх окна, а не лента под ним.
  const cardShown = (card, panel, box) => {
    if (box.top < 0 || box.bottom > innerHeight) return false;
    let hit = null;
    try { hit = document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2); } catch { return true; }
    return !hit || card.contains(hit) || !panel.contains(hit);
  };
  const placeCardFloat = (panel, wide) => {
    const dock = wide || cardFloat.broken || !panel?.isConnected ? null : sideDock(panel);
    let body = null;
    try { body = dock ? panel.querySelector(".epitaxy-chat-panel-body") : null; } catch {}
    if (cardFloat.dock && cardFloat.dock !== dock) clearCardFloat();
    if (!dock?.isConnected || !body?.isConnected) { clearCardFloat(); return; }
    const own = dock.getBoundingClientRect();
    const room = Math.round(own.top - body.getBoundingClientRect().top - CARD_FLOAT_GAP);
    if (room < CARD_FLOAT_MIN) { clearCardFloat(); return; }
    let card = null;
    try { card = dock.querySelector(CARD_SELECTOR); } catch {}
    // Края поля — от той коробки, от которой карточку ставит CSS: ближайший позиционированный
    // предок (у Claude — сама дока; пока карточки нет, считаем от доки).
    const base = card?.offsetParent?.getBoundingClientRect ? card.offsetParent.getBoundingClientRect() : own;
    let field = null;
    try { field = dock.querySelector(".epitaxy-prompt")?.getBoundingClientRect() ?? null; } catch {}
    const vars = [`${room}px`, field ? `${Math.round(field.left - base.left)}px` : null, field ? `${Math.round(base.right - field.right)}px` : null];
    CARD_VARS.forEach((name, index) => {
      const value = vars[index];
      if (value == null) dock.style.removeProperty(name);
      else if (dock.style.getPropertyValue(name) !== value) dock.style.setProperty(name, value);
    });
    if (!dock.hasAttribute(CARD_FLOAT_ATTRIBUTE)) dock.setAttribute(CARD_FLOAT_ATTRIBUTE, "");
    cardFloat.dock = dock;
    if (!card?.isConnected) return;
    const box = card.getBoundingClientRect();
    if (!(box.height > 0)) return;
    if (!cardShown(card, panel, box)) { cardFloat.broken = true; clearCardFloat(); return; }
    if (card.__myclaudeCard !== true) { card.__myclaudeCard = true; cardFloat.cards += 1; }
    // Прозрачная карточка слоем легла бы текстом на текст ленты — даём ей фон доки.
    let clear = false;
    try { clear = /^(?:transparent|rgba\([^)]*,\s*0\))$/.test(getComputedStyle(card).backgroundColor); } catch {}
    if (clear && !card.hasAttribute(CARD_SOLID_ATTRIBUTE)) card.setAttribute(CARD_SOLID_ATTRIBUTE, "");
  };
  lateRules.push(`[${CARD_FLOAT_ATTRIBUTE}] ${CARD_SELECTOR}{position:absolute !important;inset:auto var(--myclaude-card-end,0px) calc(100% + ${CARD_FLOAT_GAP}px) var(--myclaude-card-start,0px) !important;width:auto !important;margin:0 !important;max-height:var(--myclaude-card-room,50vh) !important;overflow-y:auto !important;z-index:40 !important;box-shadow:0 8px 28px rgba(0,0,0,.32) !important}`,
    `[${CARD_FLOAT_ATTRIBUTE}] ${CARD_SELECTOR}[${CARD_SOLID_ATTRIBUTE}]{background-color:var(--epitaxy-transcript-surface,var(--cds-surface-1)) !important}`);

  const noteEditorFound = () => {
    if (state.editorFound) return;
    state.editorFound = true;
    if (state.giveUpTimer) { clearTimeout(state.giveUpTimer); state.giveUpTimer = 0; }
  };

  const layout = () => {
    // Проход мог прийти в обход плана (heartbeat, команда, старт): снимаем всё
    // запланированное, иначе кадр и таймер сработают ещё раз впустую, а id
    // старого таймера потеряется и снять его будет уже нечем.
    cancelPendingLayout();
    state.scheduled = false;
    state.layoutAt = now();
    state.layoutRuns += 1;
    // Полоса прогресса (раздел 2б) переезжает вместе с полем. Зовём её дважды:
    // здесь — чтобы её достали и те проходы, что кончатся ранним выходом
    // (свёрнутое поле, потерянный редактор), и в самом конце — чтобы во время
    // тяги она не отставала на проход от только что изменённой высоты.
    placeProgress();
    // Дубли полоски стоят по окну, а не по полю: им всё равно, каким путём
    // кончится этот проход, — поэтому ставим их здесь, до всех ранних выходов.
    placeSuperRails();
    // Микрофон у кружка (#6907) — там же и по той же причине: он привязан к
    // кружку, а не к полю. Раздел 12з объявлен ниже, но зовётся он только из
    // живого прохода, а тот идёт уже после установки.
    try { placeMic(); micPaint(); } catch {}
    // Кружок — только контекст этого чата (раздел 12з², #10317): тоже по кружку, до ранних выходов.
    try { ctxRingPlace(); } catch {}
    // «▦ Галерея» (раздел 12п) — после микрофона: в свёрнутом поле встаёт левее него.
    try { placeGallery(); } catch {}
    // Enter — над кружком токенов (WF183).
    try { alignSendToRing(); } catch {}
    try { placeModeSwitch(); } catch {}
    restoreLeft();
    // Панель материалов слева (раздел 12п⁴) — после ширины боковой панели: кнопка в её строке, место правее неё.
    try { placeDock(); } catch {}
    // Чип папки у закреплённых чатов (раздел 2е) — по списку слева, а не по полю,
    // поэтому тоже до ранних выходов. Осечка волокна не должна ронять раскладку.
    try { markPinnedFolders(); pinBulkMount(); } catch {}
    // Угол «Проект · чат» (раздел 2ж, #7911) — во всех окнах, при любом поле.
    try { placeCorner(); } catch {}
    // Нижняя строка поля ввода (раздел 12з¹, #7206) — тоже до ранних выходов:
    // свёрнутое поле строку прячет, но метки ей нужны к развороту.
    try { markChin(); } catch {}
    // Кнопка «💬 Новый чат» под блоком передачи (раздел 12к, #7246).
    try { markContinue(); } catch {}
    const editor = findEditor();
    // Страховка от мигания: даже если редактор потерялся, свёрнутое состояние не
    // сбрасываем, пока жив хоть один схлопнутый узел.
    const keepCollapsed = !editor && state.stage === STAGE_COLLAPSED &&
      state.collapsedNodes.some(node => node.isConnected);
    if (keepCollapsed) { clearComposerImageUndo(); invalidateAttachments(); placeCollapsedHandle(); return; }
    if (editor !== state.editor) {
      clearComposerFont();
      clearResizer();
      state.editor = editor;
      state.editorRoot = editor ? findEditorRoot(editor) : null;
      state.shell = editor ? findShell(editor, state.editorRoot) : null;
    } else if (editor && !state.collapsedNodes.length && (!state.shell?.isConnected || !state.modelRow?.isConnected)) {
      // Рамка искалась раз на поле — а в 3.1623 строка модели (ChatComposerChin) рисуется позже поля: рамкой
      // осталась вся .epitaxy-prompt, блок совпал с ней, и свёртке нечего было сворачивать (слово Элвиса 22.10:
      // «кнопка свёртки перестала работать… один раз развернулось»). Пока строки модели нет — ищем заново;
      // свёрнутое не трогаем: там строка схлопнута и рамка нашлась бы не та.
      state.shell = findShell(editor, state.editorRoot);
    }
    syncComposerImageUndo();
    syncComposerAttachments();
    // Номера скриншотов на плитках поля (раздел 12, #7532).
    try { markShotTiles(); } catch {}
    // ⌘Z снятого вложения (раздел 12, #9193): что сейчас в поле и что из него сняли.
    try { attachUndoSync(); } catch {}
    if (!editor) { handle.style.display = "none"; placeSideRail(null, false); return; }
    noteEditorFound();
    applyComposerFont(editor);
    composerFontLoadPing();
    // Свёрнутая строка модели нулевой высоты: ни блок (он узнаётся по соседу
    // рамки ростом со строку), ни сама строка заново не нашлись бы, и поле тут
    // же развернулось бы обратно. Пока она жива и схлопнута, держим найденное.
    const rowCollapsed = state.modelRow?.isConnected && state.collapsedNodes.includes(state.modelRow) &&
      state.composerBlock?.isConnected;
    const block = rowCollapsed ? state.composerBlock : findComposerBlock(editor, state.shell);
    if (block !== state.composerBlock) {
      clearCollapsedNodes();
      state.composerBlock = block;
    }
    // Рамку и строку модели пересчитываем каждый проход: Claude перерисовывает
    // низ окна целиком (смена модели, вложения), и закэшированные узлы после
    // этого указывали бы в пустоту.
    if (!state.collapsedNodes.includes(block) && !rowCollapsed) {
      const parts = findComposerParts(block, state.shell);
      state.frameChild = parts?.frameChild ?? null;
      state.modelRow = parts?.modelRow ?? null;
    }
    // Широкий вид (раздел 2г) решается ДО сворачивания: ступень там одна,
    // обычная, — и applyCollapse ниже обязан видеть уже её. Открытие боковой
    // панели меняет ширину плитки без resize, но флаг спрашивается на каждом
    // проходе, а контейнерный запрос CSS перестраивает сетку сам.
    const panel = layoutPanel(editor);
    const wide = wideLayout(panel);
    syncWide(wide);
    applyTitleSide(panel, wide);
    applyTitleAlign(panel, wide, editor);
    applyMainHead(panel, wide);
    applyDragStrip();
    applySideMin(panel, wide);
    applyDockInset(panel, wide);
    try { placeCardFloat(panel, wide); } catch {}
    applyTextLang(panel);
    placeSideRail(panel, wide);
    applyCollapse();
    applyCornerFade(panel);
    if (!state.shell?.isConnected) { handle.style.display = "none"; return; }
    if (state.stage === STAGE_COLLAPSED) { placeCollapsedHandle(); return; }
    applyHeight();
    // В широком виде ручки нет (слово Элвиса: «давай их пока не будем вообще»),
    // а замер обычной высоты пропускается: поле растянуто на всю колонку, и туда
    // легла бы высота колонки — после возврата в узкий вид порог «растянуто»
    // стал бы недостижим.
    if (wide) { handle.style.display = "none"; placeProgress(); return; }
    // Обычная высота известна только здесь: на этой ступени подмены высоты нет и
    // поле показывает свой собственный размер.
    if (state.stage === STAGE_NORMAL && state.editorRoot?.isConnected) {
      const measured = Math.round(state.editorRoot.getBoundingClientRect().height);
      if (measured >= MIN_HEIGHT) state.natural = measured;
    }
    const rect = state.shell.getBoundingClientRect();
    if (rect.width < narrowLimit() || rect.bottom <= 0 || rect.top >= innerHeight) { handle.style.display = "none"; return; }
    handle.style.display = "flex";
    // Узкая полоска верхом на кромке рамки (донор), место — общее на все три
    // полоски (railSeat, #6891): в узком окне ужимаются все три одинаково и на
    // скругления не выезжают. Поле выше своего контейнера всё равно не
    // поднимается, поэтому кромке ничего не мешает.
    const seat = railSeat();
    handle.style.left = `${seat.left}px`;
    handle.style.width = `${seat.width}px`;
    handle.style.top = `${Math.round(Math.max(topLimit() - HANDLE_HEIGHT / 2, rect.top - HANDLE_HEIGHT / 2))}px`;
    // Проверяем после расстановки: хит-тест идёт по новому месту полоски. Во
    // время перетаскивания не прячем — курсор держит именно её.
    state.handleCovered = !state.dragging && popupCoversHandle();
    if (state.handleCovered) handle.style.display = "none";
    placeProgress();
  };

  const cancelPendingLayout = () => {
    if (state.rafId) { cancelAnimationFrame(state.rafId); state.rafId = 0; }
    if (state.layoutTimer) { clearTimeout(state.layoutTimer); state.layoutTimer = 0; }
  };
  const runLayout = () => { state.rafId = 0; if (state.alive) layout(); };
  // Проход планируется через кадр, но не чаще раза в LAYOUT_MIN_GAP: во время
  // ответа Claude мутаций сотни в секунду, а каждый проход — принудительный
  // reflow в каждом из открытых окон.
  const scheduleLayout = () => {
    // После отбоя (страница оказалась чужой) проходов больше нет: подписки на
    // resize/scroll/указатель снять нельзя — они держат ручку и команды, — но
    // работы им уже не даём.
    if (state.scheduled || !state.alive || !state.watching) return;
    state.scheduled = true;
    const wait = Math.max(0, LAYOUT_MIN_GAP - (now() - state.layoutAt));
    if (wait === 0) { state.rafId = requestAnimationFrame(runLayout); return; }
    state.layoutTimer = setTimeout(() => {
      state.layoutTimer = 0;
      state.rafId = requestAnimationFrame(runLayout);
    }, wait);
  };
  track(cancelPendingLayout);

  // Блок ввода прибит к низу окна, и лента его не двигает, поэтому реагируем
  // только на то, что задело сам блок или его предка. Всё остальное подберёт
  // страховочный проход.
  const affectsComposer = node => {
    const anchor = state.composerBlock?.isConnected ? state.composerBlock
      : (state.shell?.isConnected ? state.shell : null);
    if (anchor == null || !(node instanceof Node)) return true;
    return anchor.contains(node) || node.contains(anchor);
  };
  const onScrolled = event => {
    if (!state.watching) return;
    // Прокрутка внутри шва (раздел 13в) — не лента и не поле ввода: findScroller на каждом её scroll — пересчёт стилей.
    try { if (event.target?.closest?.(`#${SEAM_ROOT_ID}`)) return; } catch {}
    // Место чтения (раздел 13а): лента уехала к низу сама, а Элвис читает.
    try { feedHoldOnScroll(event); } catch {}
    if (!affectsComposer(event.target)) return;
    scheduleLayout();
  };
  // Подсказка над названием чата (#7342, слово Элвиса 24.09: «не надо писать More
  // options for, надо просто название, в одну строку»). Под названием лежит ⌄
  // (layoutCss), и Claude подписывает её своей строкой «More options for
  // <название>» — она же aria-label кнопки. Нашли открытую подсказку ровно с этой
  // строкой — пишем в неё одно название и метим для правила «в одну строку».
  const titleTipOnMutation = () => {
    const tips = document.querySelectorAll('[data-cds="Tooltip"] [role="tooltip"]');
    if (tips.length === 0) return;
    for (const button of document.querySelectorAll(TITLE_MENU_SELECTOR)) {
      const label = button.getAttribute("aria-label");
      const title = button.parentElement?.querySelector("[data-pane-title]")?.textContent;
      if (!label || !title) continue;
      for (const tip of tips) {
        if (tip.textContent !== label) continue;
        const walker = document.createTreeWalker(tip, NodeFilter.SHOW_TEXT);
        for (let node = walker.nextNode(); node; node = walker.nextNode()) {
          if (node.nodeValue !== label) continue;
          node.nodeValue = title;
          tip.setAttribute(TITLE_TIP_ATTRIBUTE, "");
        }
      }
    }
  };

  const ownClockText = record => {
    const label = record.type === "characterData" ? record.target?.parentNode : record.target;
    if (!label || label !== cornerClock) return false;
    return record.type === "characterData" || (record.type === "childList"
      && [...(record.addedNodes ?? []), ...(record.removedNodes ?? [])].every(node => node.nodeType === 3));
  };
  const onMutated = records => {
    state.mutationBatches += 1;
    // Только текст своего индикатора — секундных часиков угла. Удаление самого
    // узла/структурная замена проходят обычным путём.
    records = records.filter(record => !ownClockText(record));
    if (!records.length) { state.mutationSkipped += 1; return; }
    state.pageDirty = true;
    if (shotHome.shots.get(shotRoute())?.attempt) shotSync();
    if (shotState.pending) {
      for (const job of shotState.jobs) {
        // Отданная Claude вставка ждёт только плитку: пересборка поля её не отменяет (#9184).
        if (job.dispatched) { if (!shotSent(job)) shotCancel(job); continue; }
        if (!shotLive(job) || records.some(record => record.type === "childList" &&
            [...(record.removedNodes ?? [])].some(node => node === job.editor || node.contains?.(job.editor) ||
              (!job.dispatched && record.target === job.editor && job.nodes.includes(node))))) shotCancel(job);
      }
    }
    // Авто-Allow (раздел 12е) — до фильтра поля ввода: карточка разрешения живёт вне его.
    try { autoAllowOnMutation(records); } catch {}
    try { feedEnterOnMutation(records); } catch {}
    try { readOnMutation(records); } catch {}
    try { seenOnMutation(records); } catch {}
    try { titleTipOnMutation(); } catch {}
    for (const record of records) {
      if (!affectsComposer(record.target)) continue;
      // До отложенной раскладки прежняя кнопка уже может быть не последней.
      clearComposerImageUndo();
      syncComposerImageUndo();
      syncComposerAttachments();
      scheduleLayout();
      return;
    }
    state.mutationSkipped += 1;
  };
  statusPart("layout", () => (() => {
    const panel = layoutPanel(state.editor);
    const wide = wideLayout(panel);
    let width = null;
    try { width = panel ? Math.round(panel.getBoundingClientRect().width) : null; } catch {}
    return { wide, panel: width, side: wide ? sideWidth(panel) : null, sideMin: wide ? sideMinOf(panel) : null, gaps: wide ? wideState.gaps : null, justify: textJustifyOn() };
  })());
  HATCH && Object.assign(HATCH, { onMutated });

  // ---- 10. Ступени --------------------------------------------------------
  const finishDrag = () => {
    if (!state.dragging) return;
    // Тяга меняет высоту мимо setStage (высота едет прямо в applyHeight), и без
    // этих строк лента после жеста осталась бы недокрученной: поле отняло у неё
    // место, а прокрутку никто не двинул (#5869, находка проверяющего 12.09).
    if (state.dragTailDown) {
      const tail = state.dragTail;
      if (tail?.isConnected) { try { tail.scrollTop = tail.scrollHeight; } catch {} }
    }
    state.dragTail = null;
    state.dragTailDown = false;
    state.dragging = false;
    handle.dataset.dragging = "false";
    document.documentElement.style.cursor = "";
    document.documentElement.style.userSelect = "";
    storeHeight(state.height);
    scheduleLayout();
  };

  // Лента разговора за полем не следит: место, которое поле у неё отняло, она
  // отдаёт снизу, а прокрутку никто не двигает — последние строки уезжают под
  // поле, и мышью их уже не достать (#5869; замер 12.09: недокрут ленты 0 → 40
  // точек, стоило открыть поле). Поэтому на каждой смене ступени: стояла лента
  // внизу — вернём её вниз.
  //
  // Ленту ищем ТЕМ ЖЕ искателем, что и команда «Прокрутить» (раздел 13): он
  // знает виртуальную ленту по примете и иначе идёт от последнего сообщения
  // вверх. Свой обход «самый высокий прокручиваемый узел» держался в главном
  // окне на восьми точках: лента 668, боковая панель 660 — двухстрочный
  // черновик, и мы крутили бы список чатов (находка проверяющего 12.09).
  // findScroller объявлен ниже по файлу — на смене ступени он уже есть, а
  // try прикрывает единственный случай, когда ступень тронули на самом старте.
  const TAIL_SLACK = 2;
  const tailScroller = () => {
    try { return findScroller(); } catch { return null; }
  };
  const tailAtBottom = node => node != null &&
    Number(node.scrollHeight) - Number(node.clientHeight) - Number(node.scrollTop) <= TAIL_SLACK;

  // Единственная точка смены ступени: и тяга, и клики, и команды снаружи ходят
  // только через неё, поэтому ступень и высота не могут разъехаться.
  const setStage = (next, options) => {
    const value = Math.max(STAGE_COLLAPSED, Math.min(STAGE_STRETCHED, next));
    const height = options?.height;
    if (state.stage === value && (value !== STAGE_STRETCHED || height == null)) return;
    // Меряем ДО правки высоты: после неё «стояла ли лента внизу» уже не узнать.
    const tail = tailScroller();
    const tailDown = tailAtBottom(tail);
    state.stage = value;
    storeStage(value);
    if (value === STAGE_STRETCHED) {
      // Возврат в «растянуто» без явной высоты — это возврат к своему размеру, а
      // не к потолку окна: сначала последняя натянутая рукой высота и только
      // потом максимум.
      state.height = clampHeight(height ?? state.height ?? state.lastStretched ?? maximumHeight());
      state.lastStretched = state.height;
    } else {
      // Обычная высота и полоска своей высоты не хранят: подмену снимаем, и поле
      // снова слушается самого Claude. Саму цифру помним в памяти окна, иначе
      // возврат в «растянуто» открывал бы поле во всё окно вместо прежнего.
      state.lastStretched = state.height ?? state.lastStretched;
      state.height = null;
      // Достигнутый упор верен только для текущего вида: сменилась ступень —
      // считать заново.
      state.ceiling = null;
      storeHeight(null);
      if (state.editorRoot?.isConnected) {
        state.editorRoot.style.removeProperty(HEIGHT_VARIABLE);
        state.editorRoot.removeAttribute(EDITOR_ROOT_ATTRIBUTE);
      }
    }
    applyCollapse();
    applyHeight();
    if (!options?.silent) layout();
    // Доскручиваем последним: до этого высота поля ещё едет, и целиться было бы
    // не во что. Не стояла лента внизу — не трогаем: человек сам ушёл наверх.
    if (tailDown && tail?.isConnected) {
      try { tail.scrollTop = tail.scrollHeight; } catch {}
    }
  };

  // ---- Полоски и все окна разом (#6900) ------------------------------------
  // Слово Элвиса 21.09: «нажал шифт на полосочку — они все, например,
  // раскрылись, все свернулись… удобно так всеми чатами управлять». Обычное
  // нажатие по любой из трёх полосок работает с этим окном, нажатие с Shift —
  // со всеми окнами Claude разом.
  //
  // Окна разговаривают между собой напрямую, через BroadcastChannel: профиль у
  // страниц Claude общий, и канал слышат все окна. Проверено живьём 21.09:
  // всплывающие окна (about:blank) и главное окно claude.ai слышат друг друга;
  // подложки (data:) и оболочка приложения (file://) — нет, но полосок там и
  // нет вовсе. Приложение в этом не участвует: команда идёт из страницы в
  // страницу, и работает это на живом inject.js, без пересборки Пимпа.
  const RAIL_CHANNEL = "myclaude-rails";
  const railChannel = (() => {
    try { return new BroadcastChannel(RAIL_CHANNEL); } catch { return null; }
  })();
  if (railChannel) track(() => { try { railChannel.close(); } catch {} });
  // Шаг ступени по нажатию на любую из трёх полосок. Ступень считает ЭТО окно,
  // а остальные её повторяют — поэтому после Shift все окна стоят одинаково, а
  // не каждое по-своему («они все, например, раскрылись, все свернулись»).
  const railStep = all => {
    const next = state.stage === STAGE_COLLAPSED ? STAGE_NORMAL : STAGE_COLLAPSED;
    setStage(next);
    if (!all) return;
    try { railChannel?.postMessage({ kind: "stage", stage: next }); } catch {}
  };
  if (railChannel) {
    railChannel.onmessage = event => {
      const detail = event?.data;
      if (!detail || detail.kind !== "stage") return;
      const stage = Number(detail.stage);
      // Ступеней в окне нет (широкий вид, поля не нашлось) — повторять нечего:
      // чужой шаг свернул бы поле, которое нечем вернуть.
      if (!Number.isFinite(stage) || !stagesLive()) return;
      try { setStage(Math.max(STAGE_COLLAPSED, Math.min(STAGE_STRETCHED, stage))); } catch {}
    };
  }

  // В поле есть что отправить: текст или вложение (счёт отправки 12у, «Новое окно» 12б).
  const composerFilled = editor => {
    try {
      if (String(editor.textContent ?? "").trim()) return true;
      return Boolean(state.composerBlock?.querySelector?.("[data-cds-attachment]"));
    } catch { return false; }
  };

  const onPointerDown = event => {
    if (event.button !== 0 || !state.editorRoot) return;
    // Любое новое нажатие обесценивает отложенный шаг предыдущего клика: иначе
    // «щёлкнул и сразу потянул» доводит поле руками до нужной ступени, а через
    // 260 мс таймер делает ещё один шаг прямо посреди тяги.
    cancelClickStep();
    state.moved = false;
    event.preventDefault();
    state.dragging = true;
    state.startY = event.clientY;
    // Снимок высоты на момент захвата. Дальше во время тяги живую геометрию не
    // трогаем: пороги, посчитанные от неё, опрокидывали бы решение обратно.
    // Свёрнутое поле — это ноль, и тяга вверх поднимает его с нуля.
    state.startHeight = state.stage === STAGE_COLLAPSED
      ? 0
      : (state.height ?? state.editorRoot.getBoundingClientRect().height);
    state.dragNatural = naturalHeight();
    // Снимок ленты на момент захвата: стояла внизу — вернём вниз по концу тяги.
    state.dragTail = tailScroller();
    state.dragTailDown = tailAtBottom(state.dragTail);
    document.documentElement.style.cursor = "ns-resize";
    document.documentElement.style.userSelect = "none";
    handle.dataset.dragging = "true";
    try { handle.setPointerCapture(event.pointerId); } catch {}
  };
  const onPointerMove = event => {
    if (!state.dragging || !state.editorRoot) return;
    event.preventDefault();
    // Дрожь руки на пару точек — это всё ещё клик, а не перетаскивание.
    if (Math.abs(event.clientY - state.startY) > CLICK_SLACK) state.moved = true;
    // Всё решает курсор: desired — это снимок высоты плюс пройденный мышью путь,
    // живой геометрии здесь нет ни в одном пороге. Ступени разведены
    // гистерезисом, поэтому на границе они не дребезжат.
    const desired = state.startHeight - (event.clientY - state.startY);
    const natural = state.dragNatural;
    // Протянул заметно ниже минимума — значит хотел убрать поле совсем. Тягу не
    // обрываем: обратным движением вверх поле возвращается тем же жестом.
    if (state.stage !== STAGE_COLLAPSED && desired < MIN_HEIGHT - COLLAPSE_DRAG_SLACK) {
      setStage(STAGE_COLLAPSED);
      return;
    }
    // Свёрнутое ждёт минимума, дальше поле идёт за курсором с первой же точки.
    if (state.stage === STAGE_COLLAPSED && desired <= MIN_HEIGHT) return;
    // Высота непрерывная (#11693, Элвис 05.11: «оно же ниже должно иметь возможность встать… и полностью
    // разворачиваться»): и ниже своей высоты Claude — текст прокрутится (у корня overflow-y:auto), и выше. Своя
    // высота Claude — упор: в его пределах ступень «обычная», подмены нет; выйти из упора дальше, чем войти, — без дрожи.
    const snap = state.stage === STAGE_NORMAL ? STAGE_DRAG_SLACK : STAGE_DRAG_SLACK / 2;
    if (Math.abs(desired - natural) <= snap) { setStage(STAGE_NORMAL); return; }
    if (state.stage !== STAGE_STRETCHED) { setStage(STAGE_STRETCHED, { height: desired }); return; }
    state.height = clampHeight(desired);
    applyHeight();
    layout();
  };

  // Одиночный клик — шаг по лестнице: полоску разворачивает до обычной высоты,
  // любое развёрнутое поле сворачивает. Шаг отложен: второй клик двойного
  // приходит сюда же, и без задержки каждый двойной клик успевал бы сначала
  // сделать лишний шаг.
  //
  // Открывать поле на три фиксированные строки (#5868) пробовали 12.09 и сняли
  // в тот же день: жёсткая высота воюет с вложениями. Стоило положить в поле
  // пять скриншотов, как блок ввода перестал влезать в окно, trimToViewport
  // подрезал высоту, Claude перерисовывал вложения — и низ окна запрыгал вверх-
  // вниз (слово Элвиса 12.09 19:00). Ограничивать высоту надо не подменой
  // height, а потолком max-height — это отдельная задача.
  const cancelClickStep = () => {
    if (!state.clickTimer) return;
    clearTimeout(state.clickTimer);
    state.clickTimer = 0;
  };
  track(cancelClickStep);
  const onClick = event => {
    // Полоску только что тащили — это не клик. Отложенный шаг гасим и здесь:
    // после длинной тяги Chromium присылает click с detail=1, и без отмены поле
    // сделало бы лишний шаг сразу после того, как его растянули рукой.
    if (state.moved) { state.moved = false; cancelClickStep(); return; }
    event.preventDefault();
    cancelClickStep();
    if (event.detail > 1) return;
    // Shift — тот же шаг, но всеми окнами сразу (#6900). Второго клика тут не
    // ждём вовсе: двойным кликом по всем окнам никто не целится, а задержка на
    // общей команде читалась бы как «не сработало».
    if (event.shiftKey === true) { railStep(true); return; }
    state.clickTimer = setTimeout(() => {
      state.clickTimer = 0;
      // За 260 мс ожидания всё могло измениться: началась новая тяга или
      // экземпляр сняли — тогда шаг свернул бы поле, а полоски для возврата уже
      // нет.
      if (state.dragging || !state.alive) return;
      railStep(false);
    }, CLICK_STEP_DELAY);
  };

  // Дубли у краёв окна (#6743): тот же шаг, что и одиночный клик по основной
  // полоске, но без задержки на двойной — за них не тянут и не «двоят», Элвис
  // жмёт их подряд («прижал, нажал, прижал, нажал»).
  const onSuperClick = event => {
    event.preventDefault();
    cancelClickStep();
    if (!state.alive) return;
    // Shift — команда всем окнам Claude разом (#6900).
    railStep(event.shiftKey === true);
  };
  HATCH && Object.assign(HATCH, { setStage });

  // ---- 11. Разворот до потолка -------------------------------------------
  // Пустой чат: разговора ещё нет, и над полем висит шапка с приветствием и
  // выбором проекта. В Claude Code своя разметка разговора, без классов обычного
  // чата (замер донора: ноль .font-claude-response даже посреди переписки),
  // поэтому примет несколько — см. CHAT_STARTED_SELECTOR. Прежние три приметы
  // в сборке 1.40609.1 не срабатывали ни одна, и разговор считался пустым чатом:
  // из-за этого двойной клик целился в «низ шапки», найденный вплотную к полю,
  // и не растягивал поле вовсе.
  const isFreshChat = () => document.querySelectorAll(CHAT_STARTED_SELECTOR).length === 0;
  // Низ шапки пустого чата: самый нижний осмысленный блок над рамкой ввода. Не
  // по классам — Claude их перегенерирует, — а по геометрии: строка выбора
  // проекта стоит прямо над полем и попадает сюда сама.
  const freshHeaderBottom = () => {
    if (state.shell == null) return null;
    const limit = state.shell.getBoundingClientRect().top - 2;
    let bottom = null;
    for (const node of document.querySelectorAll("main h1,main h2,main button,main a,main p")) {
      // Сам блок ввода шапкой не является ни одной своей частью.
      if (state.composerBlock?.contains(node)) continue;
      const rect = node.getBoundingClientRect();
      if (rect.height < 12 || rect.width < 40) continue;
      if (rect.bottom > limit || rect.top < SAFE_TOP_INSET) continue;
      if (bottom == null || rect.bottom > bottom) bottom = rect.bottom;
    }
    return bottom == null ? null : Math.round(bottom + 12);
  };
  // Примета вида окна для замеренного упора: в пустом чате и в разговоре, в
  // узком окне и в широком контейнер держит верх поля на разной высоте, и чужой
  // замер только навредил бы.
  const ceilingFloorKey = () =>
    `${isFreshChat() ? 1 : 0}:${Math.round(innerWidth)}x${Math.round(innerHeight)}`;
  const ceilingFloorTop = () => {
    const memo = state.ceilingFloor;
    return memo != null && memo.key === ceilingFloorKey() ? memo.top : null;
  };
  // Годится ли отметка в цель. Мерим не «насколько выше нынешнего верха» (эта
  // разница у растянутого поля своя, и atCeiling с разворотом разошлись бы), а
  // сколько места отметка оставляет полю до низа рамки: низ рамки прибит к
  // строке модели и от ступени не зависит. Меньше обычной высоты с запасом —
  // отметка вырожденная, и целиться в неё нельзя.
  const aimUsable = aim => {
    if (aim == null || !state.shell?.isConnected) return false;
    return state.shell.getBoundingClientRect().bottom - aim >= naturalHeight() + CEILING_MIN_ROOM;
  };
  // Куда целимся верхом поля: обычно в низ титульной полосы, в пустом чате — в
  // низ шапки, но только пока шапка оставляет полю место. Одна точка на всех:
  // atCeiling и разворот обязаны считать одинаково, иначе двойной клик начинает
  // мигать между «растянуть» и «вернуть обычную».
  const stretchLimit = () => {
    const limit = topLimit();
    if (!isFreshChat()) return limit;
    const header = freshHeaderBottom();
    return header != null && header > limit && aimUsable(header) ? header : limit;
  };
  // Верх поля уже у потолка — значит тянуть дальше некуда. Мерим не до
  // расчётного потолка, а до замеренного упора контейнера: выше него верх поля
  // не поднимется, сколько ни тяни, и без этого повторный двойной клик перестал
  // бы возвращать обычную высоту — намеренный недобор съел бы весь допуск.
  const atCeiling = () => {
    if (state.shell == null || state.stage !== STAGE_STRETCHED) return false;
    const limit = stretchLimit();
    const floor = ceilingFloorTop();
    // Пол берём без aimUsable: в очень низком окне отвергнутый пол уводил бы цель на
    // титульную полосу, и растянутое поле никогда не считалось бы «у потолка».
    const aim = floor != null && floor > limit ? floor : limit;
    return state.shell.getBoundingClientRect().top <= aim + CEILING_UNDERSHOOT + 10;
  };
  // До упора — одним шагом и с намеренным недобором. Формуле maximumHeight()
  // верить нельзя: она считает, что прибавка высоты целиком уходит вверх, а
  // контейнер Claude верх дальше своего края не пускает, и лишние точки уходят
  // вниз, выдавливая строку модели. Поэтому целимся в ранее замеренный упор, а
  // промах разбираем по факту: второй шаг разрешён только на грубом промахе и
  // всегда последний — лесенки из трёх подходов быть не должно.
  const stretchToCeiling = ceilingTop => {
    const shell = state.shell;
    if (shell == null) return;
    // setStage перерисовывает низ окна, и рамка под руками может смениться или
    // исчезнуть. Дальше меряем только ту, с которой начинали, и на каждой смене
    // уходим: замеры от чужой рамки бессмысленны, а от исчезнувшей — падение.
    const gone = () => state.shell !== shell || !shell.isConnected;
    const limit = ceilingTop ?? topLimit();
    const floor = ceilingFloorTop();
    const aim = floor != null && floor > limit && aimUsable(floor) ? floor : limit;
    const before = shell.getBoundingClientRect().top;
    // Опорная высота годится только осмысленная: свёрнутое поле даёт нули, и от
    // нуля цель вышла бы вдвое больше нужного.
    const measured = state.editorRoot?.isConnected
      ? Math.round(state.editorRoot.getBoundingClientRect().height) : 0;
    const base = state.height ?? (measured >= MIN_HEIGHT ? measured : naturalHeight());
    const target = Math.max(base, Math.round(base + (before - aim) - CEILING_UNDERSHOOT));
    setStage(STAGE_STRETCHED, { height: target });
    state.stretchSteps = 1;
    if (gone()) return;
    // clampHeight внутри setStage мог урезать запрошенное — дальше считаем по
    // тому, что реально применилось.
    const applied = state.height ?? target;
    const after = shell.getBoundingClientRect().top;
    const grew = applied - base;
    const moved = before - after;
    // Прибавка, не ушедшая вверх. Она и показывает настоящий упор контейнера.
    const wasted = grew - moved;
    if (wasted > CEILING_WASTE_SLACK) {
      // Упор запоминаем, только если рамка вообще сдвинулась. Замер по
      // неподвижной рамке равен её нынешнему верху, а он потом идёт целью —
      // и разворот запирается на обычной высоте навсегда. Причин не сдвинуться
      // хватает и без упора контейнера: черновик выше поля, подрезка по низу
      // окна, чужая раскладка. Тогда высоту так же отдаём назад, но память
      // чистим — следующая попытка начнёт с чистого листа.
      state.ceilingFloor = moved > 0 ? { key: ceilingFloorKey(), top: Math.round(after) } : null;
      // Контейнер не пустил заметно выше: поджимаем ровно на пустоту — один раз
      // и всё. В следующий раз этот же упор возьмётся из памяти.
      setStage(STAGE_STRETCHED, { height: Math.max(base, applied - wasted - CEILING_UNDERSHOOT) });
      state.stretchSteps = 2;
    } else if (grew > 0 && after - limit > CEILING_RETRY_GAP) {
      // Прибавка уходила вверх целиком, а до настоящего потолка всё равно
      // далеко. Меряем именно до limit, а не до запомненного упора: иначе
      // однажды записанная память навсегда запирает разворот низко. Раз места
      // оказалось больше, память устарела — стираем её.
      state.ceilingFloor = null;
      setStage(STAGE_STRETCHED, { height: applied + (after - limit) - CEILING_UNDERSHOOT });
      state.stretchSteps = 2;
    }
    if (gone()) return;
    state.ceiling = state.height ?? applied;
    // Отступление от донора: он писал высоту только по концу тяги, и разворот
    // двойным кликом перезагрузку страницы не переживал. Раз высота теперь
    // сессионная (своя у каждого окна), сохранить её здесь ничего не стоит.
    storeHeight(state.height);
  };
  // Разворот до упора одним движением. Вынесен отдельно от обработчика двойного
  // клика: тем же путём поле разворачивает вставка «Обкэшить».
  const stretchToMax = () => {
    // Пока поле свёрнуто, мерить нечего — сначала молча возвращаем обычный вид.
    // Именно обычный, а не растянутый: setStage(STRETCHED) без высоты подставил
    // бы запомненный чужой размер, и это лишний скачок на глазах.
    if (state.stage === STAGE_COLLAPSED) setStage(STAGE_NORMAL, { silent: true });
    // В пустом чате шапку не съедаем: над полем стоят приветствие и кнопки
    // проекта, и без них непонятно даже, в какой папке откроется разговор.
    // Низ шапки меряем уже по возвращённому полю: у свёрнутого верх стоит ниже,
    // и в замер попали бы блоки, которые поле собой закроет. Разбор «шапка или
    // титульная полоса» — в stretchLimit(), общий с atCeiling.
    stretchToCeiling(stretchLimit());
    layout();
  };
  // Двойной клик — сразу максимум, без лесенки. Ступени остались за одиночным
  // кликом и тягой. Повторный двойной клик по уже развёрнутому до упора полю
  // возвращает обычную высоту: иначе из максимума не выйти тем же жестом.
  // «Уже до упора» решаем по верху поля, а не по высоте: у высоты цифра пляшет
  // от прохода к проходу, а верх на упоре стоит намертво.
  const onDoubleClick = event => {
    event.preventDefault();
    cancelClickStep();
    state.moved = false;
    if (atCeiling()) { setStage(STAGE_NORMAL); return; }
    stretchToMax();
  };

  // ---- 12. «Обкэшить» -----------------------------------------------------
  // Переносит в поле ввода нового чата последний ответ Claude и текущий
  // черновик. Само открытие нового чата делает Hammerspoon (⌘N) — здесь только
  // запись переноса и вставка на другой стороне. Донор тут не помощник: у него
  // для этого свой канал наружу.
  const rawText = node => {
    if (!node?.isConnected) return "";
    if (typeof node.value === "string") return node.value;
    return node.innerText ?? node.textContent ?? "";
  };
  // Пустой ProseMirror держит переносы и невидимые заполнители — они не текст.
  const editorText = (node = state.editor) => rawText(node).replace(/[\s\u200B\uFEFF]+/g, "");
  // Примета реплики самого Элвиса — .epitaxy-user-turn внутри или снаружи; ещё
  // отсеиваем строку действий под ответом (там «3 minutes ago», а не текст) и
  // само поле ввода.
  const answerUsable = node =>
    !node.closest('[aria-label="Message actions"],[aria-label="Действия с сообщением"]') &&
    !node.closest(".epitaxy-user-turn") &&
    !node.querySelector(".epitaxy-user-turn") &&
    !state.composerBlock?.contains(node) &&
    Boolean((node.textContent ?? "").trim());
  // Последний по документу — но только среди внешних узлов: один ответ даёт
  // несколько совпадений (вложенные куски), и «просто последний» брал бы кусок.
  const pickAnswer = list => {
    const nodes = [...list].filter(answerUsable);
    const outer = nodes.filter(node => !nodes.some(other => other !== node && other.contains(node)));
    return outer[outer.length - 1] ?? null;
  };
  // Строгая примета разметки, если она сегодня жива, надёжнее общего списка.
  // Claude 2.9939.2 (#7725): testid «assistant-message» пропал, ответ разбит на
  // строки ленты [data-testid="transcript-row"] (data-perf-row assistant_tool,
  // assistant_text, …), aria-label «Message N» — только у первой, обычно у
  // вызова инструмента. Запасной селектор брал её — без текста ответа, и блок
  // «ОТКРОЙ НОВЫЙ ЧАТ» не находился. Текст — в последней строке assistant_text.
  // Живьём 26.09 ~07:20 (попап VkusnoffKz): законченный ход бывает ОДНОЙ строкой data-perf-row="assistant"
  // (текст, инструменты и блок вместе, «Claude responded: …»), без «_text» — блок передачи не находился, ни
  // ссылки на «ОТКРОЙ НОВЫЙ ЧАТ», ни кнопки. Такая строка — ответ наравне с assistant_text.
  const lastAnswerNode = () =>
    pickAnswer(document.querySelectorAll('[data-testid="assistant-message"]'))
    ?? pickAnswer(document.querySelectorAll('[data-testid="transcript-row"][data-perf-row="assistant_text"],[data-testid="transcript-row"][data-perf-row="assistant"]'))
    ?? pickAnswer(document.querySelectorAll(ANSWER_SELECTOR));
  // Последнее сообщение агента на 2.9939.2 целиком (WF93-g): одно сообщение —
  // несколько строк ленты подряд с общим data-epitaxy-entry (текст, вызов
  // инструмента, снова текст), и блок «ОТКРОЙ НОВЫЙ ЧАТ» с хвостовым повтором
  // заголовка может лечь в разные строки. Отдаём строки текста агента
  // (assistant_text и assistant) всего хода после последней реплики человека,
  // по порядку. Ниже последнего сообщения агента реплика человека
  // (data-perf-row="human", живая проба 25.09) — ответа на неё ещё нет: [], и
  // старый блок над ней не наш (К1). Строк ленты нет — null, старая разметка.
  const ANSWER_ROW_SELECTOR = '[data-testid="transcript-row"][data-perf-row]';
  const answerRowKind = row => String(row.getAttribute("data-perf-row") ?? "");
  const answerRowAgent = kind => kind === "assistant" || kind.startsWith("assistant_");
  const lastAnswerRows = () => {
    let rows = [];
    try { rows = [...document.querySelectorAll(ANSWER_ROW_SELECTOR)]; } catch { return null; }
    let at = rows.length - 1;
    for (; at >= 0; at -= 1) {
      const kind = answerRowKind(rows[at]);
      if (kind === "human") return [];
      if (answerRowAgent(kind)) break;
    }
    if (at < 0) return null;
    // Весь ход агента после последней реплики человека, а не одно сообщение (entry): после
    // текста с блоком агент часто зовёт ещё инструмент, и 2.9939.2 кладёт его новым entry —
    // блок тогда оказывался «не в последнем ответе» (живьём 26.09, попап VkusnoffKz).
    const parts = [];
    for (; at >= 0; at -= 1) {
      const kind = answerRowKind(rows[at]);
      if (kind === "human") break;
      if ((kind === "assistant_text" || kind === "assistant") && answerUsable(rows[at])) parts.unshift(rows[at]);
    }
    return parts;
  };
  const lastAnswerText = () => {
    const hit = lastAnswerNode();
    if (hit == null) return "";
    // innerText исключает именно свои узлы: совпавшие «3», «ok», «…» в ответе
    // остаются. Inline display и его приоритет возвращаем даже при ошибке чтения.
    const hidden = [];
    try {
      for (const node of hit.querySelectorAll(`[${RUN_ATTRIBUTE}],[${RUN_OUT_ATTRIBUTE}]`)) {
        hidden.push([node, node.style.getPropertyValue("display"), node.style.getPropertyPriority?.("display") ?? ""]);
        node.style.setProperty("display", "none", "important");
      }
      return rawText(hit).trim();
    } finally {
      for (const [node, display, priority] of hidden) {
        if (display) node.style.setProperty("display", display, priority);
        else node.style.removeProperty("display");
      }
    }
  };
  const clearCashout = () => { try { localStorage.removeItem(CASHOUT_KEY); } catch {} };
  const readCashout = () => {
    try {
      const raw = localStorage.getItem(CASHOUT_KEY);
      if (!raw) return null;
      const data = JSON.parse(raw);
      const at = Number(data?.at);
      const text = typeof data?.text === "string" ? data.text : "";
      // Запись «Нового чата» (К1, #7072) живёт и с пустым текстом: блока
      // «ОТКРОЙ НОВЫЙ ЧАТ» в последнем ответе нет — новый чат пустой, а не отказ.
      const handoff = data?.handoff === true;
      if ((!text && !handoff) || !Number.isFinite(at)) return null;
      const record = { at, text };
      if (handoff) {
        record.handoff = true;
        record.sent = data?.sent === true;
        // Модель и ступень из строки «Модель:» блока (WF85, К7.3, критик В1):
        // без них цепочка new-window не узнала бы, что просил блок.
        const model = typeof data?.model === "string" ? data.model.trim().slice(0, 80) : "";
        const effort = typeof data?.effort === "string" ? data.effort.trim().slice(0, 20) : "";
        if (model) record.model = model;
        if (effort) record.effort = effort;
      }
      // Поля переноса (WF37, эталоны tests/fixtures/cashout): to — кому запись
      // предназначена (CASHOUT_PENDING — адресата ещё нет), title — заголовок
      // строки сайдбара нового чата, stampedAt — когда штамповали. Поля to нет
      // — это обычная запись главного окна, и правила у неё прежние.
      const to = typeof data?.to === "string" ? data.to.trim() : "";
      if (!to) return record;
      record.to = to;
      record.title = typeof data?.title === "string" ? data.title.trim() : "";
      const stampedAt = Number(data?.stampedAt);
      record.stampedAt = Number.isFinite(stampedAt) ? stampedAt : null;
      // Отказ цепочки «Нового окна» (#5592, cashoutRefuse): почему перенос не уедет.
      const refused = typeof data?.refused === "string" ? data.refused.trim().slice(0, 200) : "";
      if (refused) record.refused = refused;
      return record;
    } catch { return null; }
  };
  // Последний отказ «Обкэшить» — то же слово, что показала плашка. Гейту по нему
  // видно, почему записи нет; удачный перенос его снимает.
  let cashoutRefusal = null;
  // Приговор доставки ЭТОГО окна и запись, которой он принадлежит (WF50, #5779).
  // Живёт в памяти окна и переживает снос записи: приложение спрашивает страницу
  // уже после того, как перенос лёг и запись стёрта.
  //
  // `cashoutVerdictUntil` — докуда могла бы дожить САМА запись (#5788): дольше
  // неё приговор не живёт ни при каких условиях.
  let cashoutVerdict = "";
  let cashoutVerdictAt = 0;
  let cashoutVerdictUntil = 0;
  const cashoutSay = (at, until, word) => {
    cashoutVerdict = word;
    cashoutVerdictAt = Number(at) || 0;
    cashoutVerdictUntil = Number(until) || 0;
  };
  // Срок жизни записи: у переноса он считается от ШТАМПА (адресата называют
  // через несколько секунд после нажатия), у обычной записи главного окна — от
  // нажатия. Те же два срока проверяет tryPasteCashout, когда решает, не
  // протухла ли запись.
  const cashoutLife = record => (record.stampedAt != null
    ? record.stampedAt + CASHOUT_STAMP_FRESH_MS
    : record.at + CASHOUT_FRESH_MS);
  // Один понятный ответ приложению: доехал текст или нет (#5779). До WF50
  // приложение знало только, что новое окно появилось, — и закрывало донора по
  // факту появления окна, хотя между «окно есть» и «текст в поле» пять путей
  // отказа.
  //   «ждём»          — запись переноса есть, доезд не подтверждён;
  //   «вставлено»     — это окно подтвердило доезд;
  //   «отказ: <что>»  — приговор: вставить не вышло, ждать нечего, донора
  //                     трогать НЕЛЬЗЯ;
  //   «»              — этой странице сказать нечего (записи нет и не было).
  // Приговор принадлежит СВОЕЙ записи (находка гейта WF50) и умирает вместе с
  // ней: другая запись на месте — забываем сразу, записи нет вовсе — держим
  // слово ровно до того мгновения, когда УМЕРЛА БЫ САМА ЗАПИСЬ (#5788). Раньше
  // тут стоял общий срок в 150 с, ни к какой записи не привязанный: окно, куда
  // перенос лёг две минуты назад, отвечало «вставлено» и на следующее нажатие —
  // а если то нажатие вовсе не дошло до страницы (записи никто не создал),
  // приложение закрывало донора по ответу про ПРОШЛЫЙ перенос и теряло текст.
  const cashoutForget = record => {
    if (!cashoutVerdict) return;
    const stale = record != null
      ? record.at !== cashoutVerdictAt
      : Date.now() > cashoutVerdictUntil;
    if (stale) { cashoutVerdict = ""; cashoutVerdictAt = 0; cashoutVerdictUntil = 0; }
  };
  const cashoutDelivery = record => {
    cashoutForget(record);
    if (cashoutVerdict && (record == null || record.at === cashoutVerdictAt)) return cashoutVerdict;
    if (record?.refused) return `${CASHOUT_REFUSED}: ${record.refused}`;
    return record == null ? "" : CASHOUT_WAIT;
  };
  // Отказ переноса из попапа (#5592). Перенос едет цепочкой «Нового окна» главного окна; та
  // отказала (черновик в поле домашнего экрана, стор, папка, отправка) — раньше плашка вставала
  // в главном окне, а донор и приложение ждали до потолка (90 и 135 с). Теперь главное окно
  // пишет причину в саму запись (её localStorage общий): слово доезда у всех окон становится
  // «отказ: <причина>» — приложение бросает ожидание на ближайшем круге probe, — а донор
  // показывает плашку у себя сразу, по событию storage. chat — запись уже штампована этим
  // чатом (чат создан, а в окно не вынесся): она тоже не доедет.
  const cashoutRefuse = (why, chat = "") => {
    const record = readCashout();
    if (record == null || record.refused || !why) return false;
    if (record.to !== CASHOUT_PENDING && !(chat && record.to === chat)) return false;
    try {
      const raw = JSON.parse(localStorage.getItem(CASHOUT_KEY));
      localStorage.setItem(CASHOUT_KEY, JSON.stringify({ ...raw, refused: String(why).slice(0, 200) }));
    } catch { return false; }
    return true;
  };
  // Донор узнаёт себя по тексту записи — тем же правилом, каким его собрал runCashout (ответ и
  // черновик) или «Новый чат» (блок передачи); черновик успели поправить — хватает ответа.
  // Двойник того же чата в другом окне тоже узнает — плашка там не во вред.
  const cashoutDonorMine = record => {
    if (isMainWindow() || !record?.text) return false;
    if (record.handoff) {
      try { return cashoutCodeText(cashoutHandoffFind()?.code) === record.text; } catch { return false; }
    }
    const answer = lastAnswerText();
    const draft = rawText(state.editor).trim();
    if ([answer, draft].filter(Boolean).join("\n\n") === record.text) return true;
    return Boolean(answer) && record.text.startsWith(answer);
  };
  const CASHOUT_REFUSED_NOTE_MS = 6000;
  let cashoutRefusedShown = 0;
  const cashoutRefusedShow = () => {
    const record = readCashout();
    if (!record?.refused || cashoutRefusedShown === record.at || !cashoutDonorMine(record)) return;
    cashoutRefusedShown = record.at;
    cashoutRefusal = record.refused;
    try { newWindowNote(`Перенос не уехал: ${record.refused}.\nТекст остался здесь`, false, CASHOUT_REFUSED_NOTE_MS); } catch {}
  };
  on(window, "storage", event => {
    if (event?.key !== CASHOUT_KEY && event?.key !== null) return;
    try { cashoutRefusedShow(); } catch {}
  });
  // Счёт вложений для гейта: сколько плашек видел донор (want), сколько уехало
  // грузом (sent) и сколько доехало карточками в новом окне (done).
  let cashoutFilesCount = { want: 0, sent: 0, done: 0 };
  // Слепок записи для гейта (status().cashout): есть ли она, кому адресована,
  // под каким заголовком её ждут, когда штамповали, почему отказали, доехала ли
  // и что с вложениями. `deliveryAt` — время нажатия ТОЙ записи, о которой
  // сказано слово (#5788): по нему видно, о каком именно переносе речь.
  const cashoutState = () => {
    // Запасной путь плашки донора (#5592): storage не дошёл — скажем на вопросе приложения.
    try { cashoutRefusedShow(); } catch {}
    const record = readCashout();
    const delivery = cashoutDelivery(record);
    return {
      record: record != null,
      to: record?.to ?? null,
      title: record?.title || null,
      stampedAt: record?.stampedAt ?? null,
      refusal: cashoutRefusal,
      delivery,
      deliveryAt: cashoutVerdict ? cashoutVerdictAt : null,
      files: { ...cashoutFilesCount },
    };
  };

  // Вложения переноса (WF50, #5773) -----------------------------------------
  // File из разметки не достать: у картинки в плашке живёт одно blob-превью, а у
  // pdf и txt нет и его — сам File лежит во внутреннем состоянии Claude (замер
  // донора ElvisOS). Поэтому ловим файлы НА ВХОДЕ в поле — вставку, перетаскивание
  // и выбор через «Add», — и держим их на полке окна.
  //
  // Везём их НЕ через localStorage (квота origin ~5 МБ на все наши ключи разом,
  // base64 раздувает на треть, а setItem у нас под глухим try/catch — один
  // retina-скриншот съел бы молча даже текст) и НЕ через probe.js (канал общий и
  // ответ уже весит мегабайты). Все окна Claude — окна ОДНОГО экземпляра и
  // одного origin, поэтому File едет ссылкой через память ГЛАВНОГО окна: тем же
  // путём, каким попап спрашивает у родителя свой чат (раздел 12в).
  const cashoutHome = () => {
    let home = window[CASHOUT_FILES_GLOBAL];
    if (!home || typeof home !== "object") { home = {}; window[CASHOUT_FILES_GLOBAL] = home; }
    if (!Array.isArray(home.shelf)) home.shelf = [];
    // Протухший груз освобождает байты сам: цепочка «Обкэшить» рвётся регулярно,
    // и без этой строки десятки мегабайт висели бы в главном окне до следующего
    // переноса.
    if (home.carry && Date.now() - home.carry.at > CASHOUT_CARRY_FRESH_MS) home.carry = null;
    return home;
  };
  const cashoutFileHash = async file => {
    const head = new Uint8Array(await file.slice(0, CASHOUT_HASH_BYTES).arrayBuffer());
    let hash = 5381;
    for (let at = 0; at < head.length; at += 1) hash = (((hash << 5) + hash) ^ head[at]) >>> 0;
    return `${file.size}:${file.type}:${hash}`;
  };
  // Положить файлы на полку. Дедуп двойной: сразу по ссылке (одно действие
  // Элвиса приходит двумя событиями — paste и change — тем же объектом File) и
  // позже по содержимому, уже на сборе груза. Именем с размером на полке не
  // сравниваем: два РАЗНЫХ скриншота одного веса схлопнулись бы молча.
  const cashoutRemember = list => {
    if (!themable || !list || !list.length) return;
    const home = cashoutHome();
    shotIncoming(list);
    const at = Date.now();
    for (const file of Array.from(list)) {
      const size = Number(file?.size) || 0;
      if (!size) continue;
      const already = home.shelf.findIndex(item => item.file === file);
      if (already >= 0) home.shelf.splice(already, 1);
      const item = { name: String(file.name ?? ""), size, type: String(file.type ?? ""), file, at, hash: null };
      home.shelf.push(item);
      try { Promise.resolve(cashoutFileHash(file)).then(value => { item.hash = value; }, () => {}); } catch {}
    }
    while (home.shelf.length > CASHOUT_FILES_MAX) home.shelf.shift();
    let total = home.shelf.reduce((sum, item) => sum + item.size, 0);
    while (total > CASHOUT_BYTES_MAX && home.shelf.length > 1) total -= home.shelf.shift().size;
    startCashoutSweep();
  };
  // Файлы на входе в поле: положить на полку и — если поле свёрнуто — открыть
  // его. Свёрнутая рамка схлопнута в ноль (height:0, opacity:0), и вложение
  // прикрепляется невидимо: Элвис видит, что скриншот «не вставился», хотя
  // Claude его уже взял (#5870). Перехватывать событие нам нечем и незачем —
  // открыли поле и отпустили его своим ходом к Claude.
  const cashoutFiles = list => {
    cashoutRemember(list);
    if (list?.length && state.stage === STAGE_COLLAPSED) setStage(STAGE_NORMAL);
  };
  // Слушатели ставятся на ЗАХВАТЕ (раздел 16): Claude зовёт preventDefault, и на
  // всплытии события до нас доходят не всегда.
  const onCashoutPaste = event => { try { cashoutFiles(event?.clipboardData?.files); } catch {} };
  const onCashoutDrop = event => { try { cashoutFiles(event?.dataTransfer?.files); } catch {} };
  const onCashoutPick = event => {
    try {
      const target = event?.target;
      // Кнопка «+» живёт в строке модели, а она видна и при свёрнутом поле:
      // выбранный ею файл прикреплялся так же невидимо, как вставленный (#5870).
      if (target?.tagName === "INPUT" && target.type === "file") cashoutFiles(target.files);
    } catch {}
  };

  // ⌘V из любого места окна (WF64, #6030). Слово Элвиса (пересказ): жать Command V
  // в любом месте окна, и скриншот должен вставляться.
  // Вставку Claude отдаёт тому узлу, где стоит курсор: кликнул в ленте разговора
  // — скриншот уезжал в никуда, и приходилось сперва вставать в поле ввода.
  //
  // Дорог две, и спорить им не о чем. Неизвестно, шлёт ли Electron `paste` в
  // страницу, когда фокус стоит вне редактируемого узла, и неизвестно, доходит
  // ли `keydown` до страницы мимо меню «Правка», — каждая дорога закрывает
  // провал другой. Задвоения по устройству не бывает: сработала первая — фокус
  // уже в поле, у вставки цель редактируемая, и вторая выходит первой проверкой.
  //
  // Редактируемая цель — это и само поле ввода, и поиск чатов, и любое чужое
  // поле: туда вставка идёт как раньше, мы её не трогаем вовсе. Спрашиваем
  // closest, а не matches: при вставке В поле целью приходит вложенный <p>
  // самого ProseMirror. Цель бывает и пустой (событие без узла) — отсюда `?.`.
  const PASTE_EDITABLE_SELECTOR = "input,textarea,[contenteditable]";
  const pasteOutside = target => !target?.closest?.(PASTE_EDITABLE_SELECTOR);
  // Поле, куда уводим вставку, — строго .ProseMirror: EDITOR_SELECTOR пускает
  // ещё и чужую textarea, и на странице без композера скриншот уехал бы в
  // соседнее поле вместо того, чтобы никуда не поехать.
  const pasteEditor = () => {
    const editor = findEditor();
    return editor?.isConnected && editor.classList.contains("ProseMirror") ? editor : null;
  };
  // Дорога 1 — фокус на клавише: курсор встаёт в поле ДО того, как браузер
  // решит, куда класть вставку, и событие отпускается своим ходом. Ни
  // preventDefault, ни синтетики здесь нет намеренно — дальше работает родная
  // вставка Claude со всеми её повадками.
  //
  // Клавишу узнаём ДВУМЯ приметами. `key` зависит от раскладки: на русской та же
  // физическая клавиша отдаёт «м», и по одному `key` дорога 1 у Элвиса не
  // срабатывала бы никогда — а он в русской раскладке и сидит. `code` от
  // раскладки не зависит; так же (обеими приметами) в этом файле выставляются
  // все синтетические клавиши.
  const onPasteKey = event => {
    onAttachUndoKey(event);
    onAttachmentBoundary(event);
    try {
      if (!event?.metaKey) return;
      const isV = String(event.key ?? "").toLowerCase() === "v" || event.code === "KeyV";
      if (!isV) return;
      if (!pasteOutside(event.target)) return;
      pasteEditor()?.focus();
    } catch {}
  };
  // Дорога 2 — пересылка вставки: нужна, если фокус увести не вышло, а `paste`
  // до страницы всё же дошёл. clipboardData живёт только внутри обработчика
  // (после него files пустеют), поэтому файлы перекладываются в свежий
  // DataTransfer СИНХРОННО, прямо здесь, и уезжают в поле тем же способом,
  // каким их кладёт перенос «Обкэшить» (cashoutAttach).
  //
  // Едут только ФАЙЛЫ. Текст из буфера не трогаем вовсе: Элвис просил про
  // скриншот, а текст, упавший в черновик от случайного ⌘V, откатить нечем.
  //
  // Сторож «это наше событие» — флаг на время пересылки, а НЕ isTrusted: своей
  // синтетике его не выставить, и отличить по нему свою вставку от чужой
  // нельзя. Без флага наше же событие, всплыв обратно до document, уехало бы в
  // поле второй раз.
  let pasteRelaying = false;
  const onPasteAnywhere = event => {
    try {
      // Живой скриншот едет с номером (#7532) — и в поле, и мимо поля: ниже.
      if (!pasteRelaying && shotPaste(event)) return;
      if (pasteRelaying || !pasteOutside(event?.target)) return;
      const files = event?.clipboardData?.files;
      if (!files?.length) return;
      const editor = pasteEditor();
      if (!editor) return;
      const fresh = attachFresh(Array.from(files), "relay");
      event.preventDefault();
      if (!fresh.length) { newWindowNote(ATTACH_DUP_NOTE); return; }
      const data = new DataTransfer();
      for (const file of fresh) data.items.add(file);
      pasteRelaying = true;
      try {
        editor.focus();
        editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
      } finally { pasteRelaying = false; }
    } catch {}
  };
  // «Обкэшить»: есть ли запись переноса, кому она адресована (id чата или
  // «ждёт адресата»), под каким заголовком её ждут и когда штамповали (WF37).
  statusPart("cashout", () => cashoutState());
  HATCH && Object.assign(HATCH, { readCashout, cashoutHome, cashoutRefuse });

  // ---- 12 · Номера скриншотов в поле (#7532, WF120) -----------------------
  // Штампуем только PNG/JPEG/WebP из доверенного paste/drop без текста.
  // Черновик хранится рядом с полкой File: переживает reinject/возврат в чат.
  // Pending принадлежит экземпляру, редактору и поколению; его отмена запрещает
  // позднюю вставку. Отправка разрешается только новым действием после вставки.
  const SHOT_TYPES = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp" };
  const SHOT_NAME = "Скриншот";
  // Значок — обе стороны короче SHOT_SIDE_MIN: кладём как есть. Узкая полоса (снимок строки меню 1052×61, #10288 —
  // у второй картинки Элвиса не было «2») номер получает, пока плашка влезает по высоте: кегль 16 → плашка 24 и поля 8.
  const SHOT_SIDE_MIN = 64;
  const SHOT_SHORT_MIN = 40;
  // Больше — холст не потянет: как есть, с плашкой.
  const SHOT_SIDE_MAX = 16384;
  const SHOT_PIXELS_MAX = 50e6;
  // Кегль номера — доля короткой стороны в пределах 16…96 px: Claude ужимает
  // картинку до ~1568 px по длинной стороне, и номер ретина-скриншота остаётся
  // около 50 px — модель его читает.
  const SHOT_FONT_SHARE = 0.05;
  const SHOT_FONT_MIN = 16;
  const SHOT_FONT_MAX = 96;
  // Разбор и сборка большого PNG — до секунды; дольше — кладём как есть.
  const SHOT_WAIT_MS = 5000;
  // Дольше этого — плашка ожидания: без неё ⌘V жмут второй раз.
  const SHOT_BUSY_MS = 300;
  const SHOT_NOTE_BUSY = "Ставлю номер на скриншот…";
  const SHOT_NOTE_PLAIN = "Номер не поставлен — картинка вставлена как есть";
  const SHOT_NOTE_LOST = "Скриншот не вставлен: поле ввода пропало или чат сменился — вставь ещё раз";
  const shotHome = cashoutHome();
  shotHome.shots ??= new Map();
  const shotState = { chain: Promise.resolve(), revision: 0, pending: 0, jobs: new Set(), busyTimer: 0, busyShown: false };
  const shotRoute = () => myChatId() ?? location.href;
  const shotDraft = () => {
    const route = shotRoute();
    if (!shotHome.shots.has(route)) {
      shotHome.shots.set(route, { last: 0, generation: 0, issued: new Map(), hashes: new Map(), attempt: null });
      // Только метаданные черновиков; байты не удерживаются этим реестром.
    }
    const draft = shotHome.shots.get(route);
    draft.hashes ??= new Map(); // черновик прежнего экземпляра (реестр переживает reinject)
    return draft;
  };
  // Коробки поля нет (React пересобрал композер на первом вложении, раскладка ещё
  // не нашла новый) — плитки поля ищем по штатной разметке вложений композера во
  // всём документе: иначе первая плитка «не доезжала» и оставалась без номера (#9184).
  const shotTiles = () => {
    const box = cashoutBox();
    if (box) return [...box.querySelectorAll(PROGRESS_TILES_SELECTOR)];
    try { return [...document.querySelectorAll("[data-cds-composer-attachments] [data-cds-attachment]")]; } catch { return []; }
  };
  const shotTileName = tile => {
    for (const button of tile.querySelectorAll("button[aria-label]")) {
      const label = String(button.getAttribute("aria-label") ?? "");
      if (attachRemoveLabel(label)) return attachRemoveName(label);
    }
    return "";
  };
  // #11245 (слово Элвиса 30.10 ~20:15: «А зачем ты вот ещё раз добавил картинки? Они же уже здесь добавлены»):
  // что уже лежит в поле, второй раз туда не кладём — ни вставкой с номером, ни переносом, ни ⌘Z, ни «Обкэшить».
  // Плитка поля узнаётся по имени («Remove <имя>»); оригинал, уже вставленный «Скриншотом N», — по ключу
  // источника (имя, вес, тип), который выдача номера запоминает рядом с номером.
  const ATTACH_DUP_NOTE = "Эти файлы уже в поле — второй раз не кладу";
  const attachDup = { skipped: 0, last: null };
  const attachInField = () => new Set(shotTiles().map(shotTileName).filter(Boolean));
  const shotSourceKey = file => `${Number(file?.size) || 0}:${String(file?.type ?? "")}:${String(file?.name ?? "")}`;
  const attachSkip = (where, files) => {
    if (!files.length) return;
    attachDup.skipped += files.length;
    attachDup.last = { at: Date.now(), where, names: files.map(file => String(file?.name ?? "")).slice(0, 10) };
  };
  // Файлы, которых в поле ещё нет; лишние — в счёт status().attachDup.
  const attachFresh = (files, where) => {
    const have = attachInField();
    const fresh = [];
    const dup = [];
    for (const file of files ?? []) (have.has(String(file?.name ?? "")) ? dup : fresh).push(file);
    attachSkip(where, dup);
    return fresh;
  };
  // Связь с обработанным File запоминается только после вставки. Слабая ссылка
  // не удерживает байты после уборки полки; новый чужой File с тем же именем
  // отзывает связь (в том числе «+»). Одного похожего имени недостаточно.
  const shotIncoming = files => {
    const draft = shotDraft();
    for (const file of files ?? []) {
      const issued = draft.issued.get(file.name);
      if (issued && issued.file.deref() !== file) draft.issued.delete(file.name);
    }
  };
  const shotTileNumber = tile => {
    const name = shotTileName(tile);
    const issued = shotDraft().issued.get(name);
    return issued?.delivered ? issued.number : 0;
  };
  const shotMessageKeys = () => new Set([...document.querySelectorAll(
    '[data-testid="transcript-row"][data-perf-row="human"],[data-testid="user-message"],.epitaxy-user-turn')].map(node =>
      node.getAttribute("data-message-id") ?? node.getAttribute("data-epitaxy-entry") ??
      node.querySelector('[data-epitaxy-entry]')?.getAttribute("data-epitaxy-entry") ?? node.getAttribute("data-rs-index") ?? node.getAttribute("data-index")
    ).filter(Boolean));
  const shotAttempt = () => {
    const draft = shotDraft();
    if (!draft.last || shotState.pending || draft.attempt) return;
    draft.attempt = { before: shotMessageKeys(), at: Date.now() };
  };
  const shotSync = () => {
    for (const job of shotState.jobs) if (!(job.dispatched ? shotSent(job) : shotLive(job))) shotCancel(job);
    shotAdopt();
    for (const [route, draft] of shotHome.shots) if (route !== shotRoute()) draft.attempt = null;
    const draft = shotHome.shots.get(shotRoute());
    const attempt = draft?.attempt;
    if (!attempt) return;
    if (Date.now() - attempt.at > 30000) {
      draft.attempt = null; return;
    }
    const editor = findEditor();
    // Пустое поле само по себе ничего не доказывает: нужен новый постоянный id
    // реплики человека после пропущенной отправки в том же чате. React может
    // заменить редактор при успешной отправке; сам по себе remount не сбрасывает счёт.
    if (editor?.isConnected && !rawText(editor).trim() && !shotTiles().length &&
        [...shotMessageKeys()].some(key => !attempt.before.has(key))) {
      draft.last = 0;
      draft.generation += 1;
      draft.issued.clear();
      draft.hashes?.clear();
      draft.attempt = null;
    }
  };
  // Новый чат: до первой отправки у черновика нет id чата, и счёт живёт под
  // адресом страницы. Claude дал чату id, а плитки с нашими номерами уже в поле —
  // черновик переезжает вместе с ними, иначе номера на плитках пропадали (#9184).
  const shotAdopt = () => {
    const route = shotRoute();
    if (shotHome.shots.get(route)?.last) return;
    let names = null;
    for (const [key, draft] of shotHome.shots) {
      if (key === route || !/^[a-z]+:/i.test(key) || !draft.last) continue;
      names ??= new Set(shotTiles().map(shotTileName));
      if (![...draft.issued].some(([name, issued]) => issued.delivered && names.has(name))) continue;
      shotHome.shots.delete(key);
      shotHome.shots.set(route, draft);
      return;
    }
  };
  const markShotTiles = () => {
    shotSync();
    for (const tile of shotTiles()) {
      const number = shotTileNumber(tile);
      if (!number) { if (tile.hasAttribute(SHOT_ATTR)) tile.removeAttribute(SHOT_ATTR); }
      else if (tile.getAttribute(SHOT_ATTR) !== String(number)) tile.setAttribute(SHOT_ATTR, String(number));
    }
  };
  const shotNext = draft => {
    let number = ++draft.last;
    const names = new Set(shotTiles().map(shotTileName));
    while (Object.values(SHOT_TYPES).some(ext => names.has(`${SHOT_NAME} ${number}.${ext}`))) number = ++draft.last;
    return number;
  };
  const shotLive = job => state.alive && !job.cancelled && job.route === shotRoute() && job.where === location.href &&
    job.editor.isConnected && findEditor() === job.editor && job.draft.generation === job.generation;
  // После вставки картинка уже у Claude, и с номером в пикселях. Первое вложение
  // пересобирает композер (редактор, адрес нового чата), и прежняя проверка
  // «тот же редактор» роняла ожидание плитки: номер на плитке не вставал (#9184).
  // Дальше ждём только плитку: живой экземпляр и не отменено.
  const shotSent = job => state.alive && !job.cancelled;
  const shotCancel = job => {
    job.cancelled = true;
    for (const cancel of job.cancels) cancel();
  };
  // Не теряем поздний ImageBitmap при timeout/dispose и снимаем свои таймеры.
  const shotWait = (promise, job, late = () => {}, live = shotLive) => new Promise((resolve, reject) => {
    let finished = false;
    let timer = null;
    const done = (value, error) => {
      if (finished) { if (!error) late(value); return; }
      finished = true;
      clearTimeout(timer);
      job.cancels.delete(cancel);
      if (error) reject(error); else resolve(value);
    };
    const cancel = () => done(null, new Error("cancelled"));
    job.cancels.add(cancel);
    timer = setTimeout(() => done(null, new Error("timeout")), SHOT_WAIT_MS);
    Promise.resolve(promise).then(value => done(value), error => done(null, error));
    if (!live(job)) cancel();
  });
  // Белая цифра на тёмной плашке с белой каймой — читается на любом снимке.
  const shotBadge = (context, width, height, number) => {
    const text = String(number);
    const size = Math.round(Math.min(SHOT_FONT_MAX, Math.max(SHOT_FONT_MIN, Math.min(width, height) * SHOT_FONT_SHARE)));
    context.font = `700 ${size}px -apple-system, "Helvetica Neue", Arial, sans-serif`;
    const boxHeight = Math.round(size * 1.5);
    const boxWidth = Math.max(boxHeight, Math.round(context.measureText(text).width + size));
    // #11217 (слово Элвиса 30.10 17:20: «цифры… сильно прижаты… к низу… чтоб они чуть-чуть дышали»): от края — кегль,
    // а не полкегля; узкая полоса (#10288) — сколько влезает, плашка целиком внутри.
    const margin = Math.max(0, Math.min(size, Math.floor((height - boxHeight) / 2), Math.floor((width - boxWidth) / 2)));
    const top = height - margin - boxHeight;
    context.beginPath();
    context.roundRect(margin, top, boxWidth, boxHeight, boxHeight / 2);
    context.fillStyle = "rgba(0, 0, 0, 0.8)";
    context.fill();
    context.lineWidth = Math.max(1, Math.round(size / 12));
    context.strokeStyle = "#ffffff";
    context.stroke();
    context.fillStyle = "#ffffff";
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText(text, margin + boxWidth / 2, top + boxHeight / 2);
  };
  // Одна картинка → { file, failed }. Не наш тип или значок — как есть и молча;
  // не разобралась, велика, холст отказал — как есть, с плашкой.
  const shotDraw = async (file, job) => {
    if (!SHOT_TYPES[file?.type] || !(file.size > 0)) return { file, failed: false };
    let bitmap = null;
    let number = 0;
    try {
      bitmap = await shotWait(createImageBitmap(file), job, value => { try { value?.close?.(); } catch {} });
      if (!shotLive(job)) return { file, failed: true };
      const width = Number(bitmap?.width) || 0;
      const height = Number(bitmap?.height) || 0;
      if (width > 0 && height > 0 && (Math.max(width, height) < SHOT_SIDE_MIN || Math.min(width, height) < SHOT_SHORT_MIN)) {
        return { file, failed: false };
      }
      if (!(width > 0 && height > 0) || Math.max(width, height) > SHOT_SIDE_MAX || width * height > SHOT_PIXELS_MAX) {
        return { file, failed: true };
      }
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d");
      if (!context) return { file, failed: true };
      context.drawImage(bitmap, 0, 0);
      number = shotNext(job.draft);
      shotBadge(context, width, height, number);
      const blob = await shotWait(new Promise(resolve => canvas.toBlob(resolve, file.type, 0.92)), job);
      if (!shotLive(job) || !(blob?.size > 0)) throw new Error("toBlob");
      const type = blob.type;
      if (!SHOT_TYPES[type]) throw new Error("blob type");
      return { file: new File([blob], `${SHOT_NAME} ${number}.${SHOT_TYPES[type]}`, { type }), number, failed: false };
    } catch {
      // Номер выдан, а картинка не собралась — возвращаем его: дыры в счёте нет.
      if (number && job.draft.last === number) job.draft.last -= 1;
      return { file, failed: true };
    } finally {
      try { bitmap?.close?.(); } catch {}
    }
  };
  const shotBusyEnd = () => {
    if (shotState.busyTimer) { clearTimeout(shotState.busyTimer); shotState.busyTimer = 0; }
    if (shotState.busyShown) { shotState.busyShown = false; newWindowNoteHide(false); }
  };
  track(() => {
    for (const job of shotState.jobs) shotCancel(job);
    shotBusyEnd();
    for (const tile of document.querySelectorAll(`[${SHOT_ATTR}]`)) tile.removeAttribute(SHOT_ATTR);
  });
  // Оригинал уже в поле: его номерованная копия («Скриншот N») — плиткой этого черновика (#11245). Тот же
  // буфер вставили второй раз (Диктатор на «Стоп» оставил в буфере снимки вместо текста, и ⌘V по плашке
  // «Текст не вставлен · ⌘V» клал их снова — 1 = 3, 2 = 4).
  // Плитка с отпечатком содержимого (#11689, ниже) сверяется им: два разных снимка одного веса — оба «image.png».
  const shotAlready = (draft, file, have) => {
    const key = shotSourceKey(file);
    for (const [name, issued] of draft.issued) if (issued.source === key && have.has(name) && !draft.hashes.has(name)) return true;
    return false;
  };
  // #11689 (слово Элвиса 05.11 ~18:13: «Картинка была вставлена, я диктовку начал, она опять вставляется… Ты каждый
  // раз перед вставкой проверяй, картинка вставлена ли уже или нет»): Диктатор вставил снимок файлом из папки снимков
  // («Снимок … 18.13.08-762774.png»), а на старте записи понёс его же копией из стопки («shot-…png») — байты те же,
  // имя другое, и ключ источника его не узнал. Поэтому сверяем ещё содержимое (ключ полки «Обкэшить»: вес, тип и
  // djb2 первых 8 КБ) со всем, что этот черновик уже положил в поле: плитка → ключ её исходника, в draft.hashes.
  const shotHash = async file => { try { return await cashoutFileHash(file); } catch { return ""; } };
  const shotDeliver = async job => {
    const ready = [];
    let failed = false;
    try {
      // Сверка — здесь, а не в shotTake: очередь вставок к этому мгновению доставила все прежние.
      const hashes = new Map();
      for (const file of job.files) hashes.set(file, await shotHash(file));
      const have = attachInField();
      const known = new Set([...job.draft.hashes].filter(([name]) => have.has(name)).map(([, hash]) => hash));
      const dup = job.files.filter(file => {
        if (shotAlready(job.draft, file, have)) return true;
        const hash = hashes.get(file);
        if (!hash) return false;
        if (known.has(hash)) return true;
        known.add(hash); // один снимок дважды в одной вставке — тоже дубль
        return false;
      });
      if (dup.length) {
        attachSkip("shot", dup);
        job.files = job.files.filter(file => !dup.includes(file));
        if (!job.files.length) { if (state.alive) { shotBusyEnd(); newWindowNote(ATTACH_DUP_NOTE); } return; }
      }
      for (const file of job.files) {
        if (!shotLive(job)) break;
        const done = await shotDraw(file, job);
        ready.push(done);
        failed ||= done.failed;
      }
      if (!shotLive(job) || ready.length !== job.files.length) {
        if (state.alive) newWindowNote(SHOT_NOTE_LOST);
        return;
      }
      const data = new DataTransfer();
      for (const item of ready) data.items.add(item.file);
      cashoutRemember(ready.map(item => item.file));
      // Связь имя → номер — сразу доставленная: плитка с этим именем появится
      // только от этой вставки, а ждать её «тем же редактором» нельзя (#9184).
      ready.forEach(({ file, number }, at) => {
        const hash = hashes.get(job.files[at]);
        if (hash) job.draft.hashes.set(file.name, hash);
        if (number) job.draft.issued.set(file.name, { number, file: new WeakRef(file), delivered: true, source: shotSourceKey(job.files[at]) });
      });
      pasteRelaying = true;
      job.dispatched = true;
      try {
        job.editor.focus();
        job.editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
      } finally { pasteRelaying = false; }
      // React может дорисовать плитки позже события paste. До них барьер остаётся.
      const arrived = () => {
        const names = shotTiles().map(shotTileName);
        return ready.every(item => names.includes(item.file.name));
      };
      if (!arrived()) await shotWait(new Promise((resolve, reject) => {
        let timer;
        const stop = () => { clearTimeout(timer); job.cancels.delete(stop); reject(new Error("cancelled")); };
        job.cancels.add(stop);
        const check = () => {
          if (!shotSent(job)) { stop(); return; }
          if (arrived()) { job.cancels.delete(stop); resolve(); return; }
          timer = setTimeout(check, 50);
        };
        check();
      }), job, () => {}, shotSent);
      if (shotSent(job)) markShotTiles();
      if (failed && state.alive) { shotBusyEnd(); newWindowNote(SHOT_NOTE_PLAIN); }
    } catch {
      if (state.alive) { shotBusyEnd(); newWindowNote(SHOT_NOTE_LOST); }
    } finally {
      shotCancel(job);
      shotState.jobs.delete(job);
      shotState.pending -= 1;
      if (!shotState.pending) shotBusyEnd();
    }
  };
  const shotBlocked = () => {
    if (!shotState.pending) return false;
    newWindowNote(SHOT_NOTE_BUSY, true, SHOT_WAIT_MS * 2);
    shotState.busyShown = true;
    return true;
  };
  // Текст рядом с картинкой — обычно чужая разметка (Excel, страница): её не
  // трогаем. Но Диктатор, Finder и съёмщики кладут рядом со снимком его путь или
  // имя (`/…/Снимок 01.png`, `file:///…`, с `\ ` перед пробелами) — это тот же
  // снимок, а не текст, и он обязан получить номер (WF173: снимок остался без №).
  const SHOT_PATH_EXT = /\.(png|jpe?g|webp|gif|tiff?|heic|bmp)$/i;
  const shotTextIsPaths = (text, files) => {
    const names = new Set(files.map(file => String(file?.name ?? "")));
    const isPath = raw => {
      let token = raw.replace(/\\(.)/g, "$1");
      if (/^file:\/\//i.test(token)) {
        try { token = decodeURIComponent(token.slice(7)); } catch { return false; }
      }
      const base = token.slice(token.lastIndexOf("/") + 1);
      if (names.has(base) || names.has(token)) return true;
      // Фраза «смотри shot.png» — текст, не путь: голое имя только без пробелов.
      return SHOT_PATH_EXT.test(base) && (/^[/~]/.test(token) || !/\s/.test(token));
    };
    const lines = String(text).split(/[\r\n]+/).map(line => line.trim()).filter(Boolean);
    // Строка целиком — имя с пробелами (Finder); иначе пути через пробел, где
    // пробел с обратной косой — часть имени (Диктатор, Терминал).
    return lines.length > 0 && lines.every(line => isPath(line) ||
      line.split(/(?<!\\) +/).filter(Boolean).every(isPath));
  };
  const shotTake = (event, transfer, inField) => {
    if (event?.isTrusted !== true) return false;
    const files = Array.from(transfer?.files ?? []);
    if (!files.some(file => SHOT_TYPES[file?.type])) return false;
    const text = String(transfer.getData?.("text/plain") ?? "").trim();
    if (text && !shotTextIsPaths(text, files)) return false;
    const editor = pasteEditor();
    if (!editor || !inField(editor)) return false;
    shotSync();
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    // Исходники этой вставки полка «Обкэшить» запомнила раньше нас (её слушатель на захвате первый), а в
    // поле поедут номерованные копии — их на полку кладёт shotDeliver. Без этого ⇧⌘N в первые 10 с увозил
    // оригинал последнего снимка вместо «Скриншот 1» (ревизия WF247).
    const home = cashoutHome();
    home.shelf = home.shelf.filter(item => !files.includes(item.file));
    const draft = shotDraft();
    draft.attempt = null;
    const job = { files, editor, nodes: [...editor.childNodes], dispatched: false, where: location.href, route: shotRoute(), draft, generation: draft.generation, cancels: new Set(), cancelled: false };
    shotState.jobs.add(job);
    shotState.pending += 1;
    shotState.revision += 1;
    // Ожидавшее автоматическое сообщение не отправляется после обработки само.
    for (const queued of sendTextQueue.splice(0)) sendTextDone(queued.id, "field-busy");
    sendDelayStop("cancelled", "screenshot");
    sendDelayState.token += 1; // отменяет и запасной click уже отпущенного Enter
    sayDisarm("Ставлю номер…");
    nazhDisarm("Ставлю номер…");
    if (!shotState.busyTimer && !shotState.busyShown) {
      shotState.busyTimer = setTimeout(() => {
        shotState.busyTimer = 0;
        if (state.alive) shotBlocked();
      }, SHOT_BUSY_MS);
    }
    shotState.chain = shotState.chain.then(() => shotDeliver(job));
    return true;
  };
  // ⌘V — в само поле или мимо любого поля (дорога 2); поиск чатов и чужие поля — нет.
  const shotPaste = event => shotTake(event, event?.clipboardData,
    editor => editor.contains(event.target) || pasteOutside(event.target));
  // Бросок картинки — в любое место окна, кроме чужих полей и терминала: Claude
  // кладёт брошенное в поле и мимо блока ввода (лента, его подложка «брось сюда»),
  // и без номера (#11310, слово Элвиса 31.10 ~02:58: «я его драгдропом перенёс…
  // номера же у скриншотов есть, а здесь номера не стоят»). Номер — общий ряд со
  // вставками, дубль — К-ATTACH-DUP. Терминал и поиск получают бросок как раньше.
  const SHOT_DROP_SKIP = ".xterm";
  // Свой бросок Claude не увидел: пустой бросок той же цели гасит его подложку
  // «брось сюда», файлов в нём нет — вложить нечего.
  const shotDropRelease = target => {
    try { target?.dispatchEvent?.(new DragEvent("drop", { bubbles: true, cancelable: true, dataTransfer: new DataTransfer() })); } catch {}
  };
  const onShotDrop = event => {
    try {
      const target = event?.target;
      const taken = shotTake(event, event?.dataTransfer, editor => Boolean(cashoutBox()?.contains(target) ||
        sideDock(layoutPanel(editor))?.contains(target) || editor.contains(target) ||
        (pasteOutside(target) && !target?.closest?.(SHOT_DROP_SKIP))));
      if (taken) shotDropRelease(target);
    } catch {}
  };
  // «+» Claude → файл (#9184: «все скриншоты должны нумероваться, когда я их
  // добавляю»). Выбор файла приходит доверенным change поля <input type=file>
  // блока ввода: картинки забираем до Claude и везём в поле той же вставкой, что
  // ⌘V, — с номером. Поле выбора очищаем: тот же файл выбирается снова.
  const onShotPick = event => {
    try {
      const input = event?.target;
      if (input?.tagName !== "INPUT" || input.type !== "file") return;
      const editor = pasteEditor();
      const panel = layoutPanel(editor);
      const near = node => Boolean(node && (cashoutBox()?.contains(node) || sideDock(panel)?.contains(node) ||
        node.closest?.('[data-cds="ChatComposer"],.epitaxy-prompt')));
      if (!shotTake(event, { files: input.files, getData: () => "" }, () => near(input))) return;
      try { input.value = ""; } catch {}
    } catch {}
  };
  statusPart("attachDup", () => ({ skipped: attachDup.skipped, last: attachDup.last }));
  HATCH && Object.assign(HATCH, { shotState, shotPaste, attachDup });

  // ---- 12 · ⌘Z возвращает снятое вложение (#9193) --------------------------
  // Слово Элвиса 09.10 02:35: «скриншот один удалил по случайке… ⌘Z не работает на
  // удаление скриншотов. Сделай, чтобы можно было отменить». Своей отмены у
  // вложений Claude нет: снятое крестиком (или Backspace) уходит из поля насовсем.
  // Каждый проход раскладки запоминает плитки поля вместе с их File (полка
  // «Обкэшить», номер скриншота); плитка пропала сразу после крестика/Backspace —
  // её File кладём в стек. ⌘Z в поле (или мимо любого поля — фокус после крестика
  // уходит в никуда) возвращает верхнюю той же вставкой, какой страница кладёт
  // вложения, — с тем же именем «Скриншот N», а значит с тем же номером; ⌘⇧Z
  // снимает её снова. Перехват — только когда стек не пуст и текст поля с
  // момента снятия не правили: иначе ⌘Z — обычная отмена текста, а до вложения
  // очередь дойдёт, когда текст вернётся к тому виду. Стек живёт в черновике
  // одного чата: отправка, иная пропажа плиток (не крестик), смена чата и
  // dispose его очищают; Esc — нет (вложений он не трогает).
  const ATTACH_UNDO_MAX = 10;
  // Крестик/Backspace и пропажа плитки — одно действие: столько ждём перерисовку.
  const ATTACH_UNDO_SIGNAL_MS = 3000;
  const attachUndo = { undo: [], redo: [], tiles: [], route: null, signal: null, restored: 0, removed: 0 };
  const attachUndoClear = () => { attachUndo.undo = []; attachUndo.redo = []; attachUndo.signal = null; };
  track(() => { attachUndoClear(); attachUndo.tiles = []; });
  const attachUndoFile = (name, previous) => {
    const issued = shotHome.shots.get(shotRoute())?.issued.get(name)?.file?.deref?.();
    if (issued) return issued;
    const shelf = cashoutHome().shelf;
    for (let at = shelf.length - 1; at >= 0; at -= 1) if (shelf[at].name === name && shelf[at].file) return shelf[at].file;
    return previous.find(tile => tile.name === name)?.file ?? null;
  };
  const attachRemoveButton = node => {
    for (const button of node?.querySelectorAll?.("button[aria-label]") ?? []) {
      const label = String(button.getAttribute("aria-label") ?? "");
      if (attachRemoveLabel(label)) return button;
    }
    return null;
  };
  // Повод снять: крестик плитки поля (имя — из его подписи), Backspace/Delete в
  // блоке ввода (имени нет), отправка — стек прочь.
  const attachUndoMark = event => {
    try {
      const target = event?.target;
      if (event.type === "click") {
        const button = target?.closest?.("button[aria-label]");
        const label = String(button?.getAttribute?.("aria-label") ?? "");
        if (button && attachRemoveLabel(label) &&
            button.closest?.("[data-cds-composer-attachments]") && !attachUndo.signal?.redo) {
          attachUndo.signal = { at: Date.now(), name: attachRemoveName(label) };
        }
      } else if (event.type === "keydown" && (event.key === "Backspace" || event.key === "Delete") && !event.metaKey &&
          (state.editor?.contains?.(target) || cashoutBox()?.contains?.(target))) {
        attachUndo.signal = { at: Date.now(), name: null };
      }
    } catch {}
  };
  const attachUndoSync = () => {
    const route = shotRoute();
    if (attachUndo.route !== route) { attachUndoClear(); attachUndo.route = route; attachUndo.tiles = []; }
    const editor = pasteEditor();
    // Поля нет (пересборка композера) — сверять не с чем: молчание поля не «сняли».
    if (!editor) return;
    const names = shotTiles().map(shotTileName).filter(Boolean);
    const previous = attachUndo.tiles;
    const left = [...names];
    const gone = [];
    for (const tile of previous) {
      const at = left.indexOf(tile.name);
      if (at >= 0) left.splice(at, 1); else gone.push(tile);
    }
    if (gone.length) {
      const signal = attachUndo.signal && Date.now() - attachUndo.signal.at < ATTACH_UNDO_SIGNAL_MS ? attachUndo.signal : null;
      if (!signal) attachUndoClear();
      else {
        const text = rawText(editor);
        for (const tile of gone) {
          if (!tile.file || (signal.name && signal.name !== tile.name)) continue;
          attachUndo.undo.push({ name: tile.name, file: tile.file, route, text });
        }
        if (!signal.redo) attachUndo.redo = [];
        while (attachUndo.undo.length > ATTACH_UNDO_MAX) attachUndo.undo.shift();
        attachUndo.signal = null;
      }
    }
    attachUndo.tiles = names.map(name => ({ name, file: attachUndoFile(name, previous) }));
  };
  const attachUndoRestore = (entry, editor) => {
    if (!attachFresh([entry.file], "undo").length) return false;
    const data = new DataTransfer();
    data.items.add(entry.file);
    cashoutRemember([entry.file]);
    pasteRelaying = true;
    try {
      editor.focus();
      editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
    } finally { pasteRelaying = false; }
    attachUndo.redo.push({ ...entry, text: rawText(editor) });
    attachUndo.restored += 1;
    return true;
  };
  const attachUndoRemove = entry => {
    const tile = shotTiles().filter(node => shotTileName(node) === entry.name).pop();
    const button = attachRemoveButton(tile);
    if (!button) return false;
    attachUndo.signal = { at: Date.now(), name: entry.name, redo: true };
    button.click();
    attachUndo.removed += 1;
    return true;
  };
  // ⌘Z / ⌘⇧Z (на русской раскладке та же клавиша — «я»: узнаём и по code).
  const onAttachUndoKey = event => {
    try {
      if (!event?.metaKey || event.altKey || event.ctrlKey || event.isComposing) return;
      if (String(event.key ?? "").toLowerCase() !== "z" && event.code !== "KeyZ") return;
      const redo = Boolean(event.shiftKey);
      const stack = redo ? attachUndo.redo : attachUndo.undo;
      if (!stack.length) return;
      const editor = pasteEditor();
      if (!editor || (!editor.contains(event.target) && !pasteOutside(event.target))) return;
      const entry = stack[stack.length - 1];
      if (entry.route !== shotRoute()) { attachUndoClear(); return; }
      if (rawText(editor) !== entry.text || shotState.pending) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      stack.pop();
      if (redo) attachUndoRemove(entry); else attachUndoRestore(entry, editor);
      scheduleLayout();
    } catch {}
  };

  // Сколько вложений видно в поле ввода. Одной приметы мало: разметка Claude
  // меняется без предупреждения, поэтому считаем тремя независимыми и берём
  // наибольшее — превью есть не у всякого файла (pdf), а кнопка снятия есть у
  // каждого. «Remove from queue» — не вложение, это очередь сообщений.
  const CASHOUT_PILL_CARD = '.epitaxy-attachment-pill,[data-testid$="attachment"],[data-testid$="attachment-pill"],[data-testid$="file-pill"]';
  // Превью считаем разбором src, а не селектором: значок самого композера тоже
  // бывает картинкой data: (svg), и селектор насчитал бы вложений больше, чем
  // их есть, — а лишнее «не доехало» такая же неправда, как молчание.
  const cashoutPreviews = box => {
    let seen = 0;
    for (const node of box.querySelectorAll("img[src]")) {
      const src = String(node.getAttribute("src") ?? "");
      if (src.startsWith("blob:") || /^data:image\/(?!svg)/i.test(src)) seen += 1;
    }
    return seen;
  };
  // Коробка поля ввода: рамка композера, а пока её не нашли — оболочка.
  const cashoutBox = () => (state.composerBlock?.isConnected ? state.composerBlock
    : (state.shell?.isConnected ? state.shell : null));
  const cashoutPills = () => {
    const box = cashoutBox();
    if (!box) return 0;
    try {
      const previews = cashoutPreviews(box);
      const cards = box.querySelectorAll(CASHOUT_PILL_CARD).length;
      let buttons = 0;
      for (const node of box.querySelectorAll("button[aria-label]")) {
        const label = String(node.getAttribute("aria-label") ?? "").trim().toLowerCase();
        if (!attachRemoveLabel(label)) continue;
        buttons += 1;
      }
      return Math.max(previews, cards, buttons);
    } catch { return 0; }
  };
  // Как ПОДПИСАНЫ вложения, видимые в поле. Счёт плашек говорит «сколько», а
  // уборке нужно «какие»: снятое крестиком лежит на полке вперемешку с живым, и
  // по одному числу не понять, какая запись осталась без плашки. Берём подпись
  // кнопки снятия («Remove снимок.png»), а если её сегодня нет — текст самой
  // карточки. Сверяем ВХОЖДЕНИЕМ имени: вокруг него бывает и слово «Remove», и
  // размер файла. Имя — только подсказка: у pdf подписи может не быть вовсе, и
  // тогда за него отвечает общий счёт плашек.
  const cashoutPillNames = () => {
    const box = cashoutBox();
    if (!box) return [];
    try {
      const names = [];
      for (const node of box.querySelectorAll("button[aria-label]")) {
        const label = String(node.getAttribute("aria-label") ?? "").trim();
        if (!attachRemoveLabel(label)) continue;
        names.push(label);
      }
      if (names.length) return names;
      for (const node of box.querySelectorAll(CASHOUT_PILL_CARD)) {
        const text = String(node.textContent ?? "").trim();
        if (text) names.push(text);
      }
      return names;
    } catch { return []; }
  };
  // Уборка полки (#5789, у донора ElvisOS она зовётся sweep). Полка обязана
  // отражать то, что ВИДНО в поле: Элвис снимает плашку крестиком или отправляет
  // сообщение — вложение ушло из поля, а из памяти окна нет. Тогда «Обкэшить»
  // увозит не то, что видно, и снятый файл выигрывает у нового с тем же именем
  // (🟣 Kaban 2869 — месяц отладки у донора). Плюс вес: без уборки в каждом окне
  // висят ссылки на 24 файла и 48 МБ до самого закрытия Claude.
  //
  // Сверяемся не наблюдателем документа (он работал бы на каждом кадре ответа),
  // а редким опросом ПОЛЯ и только пока на полке что-то лежит. Свежая запись
  // неприкосновенна: между вставкой файла и появлением плашки проходит заметное
  // время, и без отсрочки уборка съедала бы только что положенное.
  let cashoutSweepTimer = 0;
  const stopCashoutSweep = () => {
    if (!cashoutSweepTimer) return;
    clearInterval(cashoutSweepTimer);
    cashoutSweepTimer = 0;
  };
  track(stopCashoutSweep);
  const cashoutSweep = () => {
    const home = cashoutHome();
    if (!home.shelf.length) { stopCashoutSweep(); return; }
    // Поля на месте нет (React пересобрал композер, чат переключается) — сверять
    // не с чем, и молчание поля это не «вложений не осталось». Пропускаем тик:
    // полка дождётся следующего, а вычеркнуть живое вложение мы права не имеем.
    if (!cashoutBox()) return;
    const now = Date.now();
    const free = cashoutPillNames();
    // Плашек в поле бывает больше, чем читаемых подписей: незанятые ими места
    // достаются самым свежим записям — ровно тот порядок, каким полку читает
    // cashoutHaul.
    let room = Math.max(0, cashoutPills() - free.length);
    const keep = [];
    for (let at = home.shelf.length - 1; at >= 0; at -= 1) {
      const item = home.shelf[at];
      const hit = item.name
        ? free.findIndex(label => label === item.name || label.includes(item.name))
        : -1;
      if (hit >= 0) { free.splice(hit, 1); keep.unshift(item); continue; }
      if (now - item.at < CASHOUT_SWEEP_GRACE_MS) { keep.unshift(item); continue; }
      if (room > 0) { room -= 1; keep.unshift(item); }
    }
    if (keep.length !== home.shelf.length) home.shelf = keep;
    if (!keep.length) stopCashoutSweep();
  };
  const startCashoutSweep = () => {
    if (!themable || cashoutSweepTimer || !cashoutHome().shelf.length) return;
    cashoutSweepTimer = setInterval(cashoutSweep, CASHOUT_SWEEP_MS);
  };
  // Что уезжает: столько файлов с КОНЦА полки, сколько плашек видно в поле.
  // Счёт штуками, а не именами: восемь скриншотов зовутся одинаково, и проверка
  // по имени засчитывала бы восемь по одной доехавшей. С конца — потому что
  // снятое крестиком и уже отправленное ушло из поля раньше.
  const cashoutHaul = () => {
    const want = cashoutPills();
    if (want <= 0) return { want: 0, files: [] };
    const shelf = cashoutHome().shelf;
    const seen = new Set();
    const files = [];
    for (let at = shelf.length - 1; at >= 0 && files.length < want; at -= 1) {
      const item = shelf[at];
      if (item.hash) {
        if (seen.has(item.hash)) continue;
        seen.add(item.hash);
      }
      files.unshift(item);
    }
    return { want, files };
  };
  // Одинаковые имена Claude склеивает в ОДНО вложение — разводим суффиксом
  // (донор делает это же по той же причине), иначе восемь image.png доедут одной
  // картинкой.
  const cashoutUniqueName = (name, taken) => {
    const base = name || "файл";
    if (!taken.has(base)) return base;
    const dot = base.lastIndexOf(".");
    const stem = dot > 0 ? base.slice(0, dot) : base;
    const tail = dot > 0 ? base.slice(dot) : "";
    for (let copy = 2; copy <= CASHOUT_FILES_MAX + 1; copy += 1) {
      const next = `${stem}-${copy}${tail}`;
      if (!taken.has(next)) return next;
    }
    return `${stem}-${Date.now()}${tail}`;
  };
  // Копию делает то окно, где груз ЛЕЖИТ (главное), своим конструктором File:
  // донора закрывают сразу после доезда текста, и объекты его умершего окна
  // стали бы негодны. Конструктора нет — везём как есть и честно теряем
  // разведение имён, но не файл.
  const cashoutCopyFile = (file, name, type) => {
    if (!file) return null;
    try { return new File([file], name, type ? { type } : undefined); } catch { return file; }
  };
  // Принять груз: зовёт ДОНОР у окна-родителя (или сам у себя, если он главное
  // окно). Возвращает, сколько файлов принято.
  const cashoutCarry = (list, at, want) => {
    const home = cashoutHome();
    const stamp = Number(at);
    const items = Array.isArray(list) ? list : [];
    if (!items.length || !Number.isFinite(stamp)) { home.carry = null; return 0; }
    const files = [];
    const names = new Set();
    let total = 0;
    for (const item of items) {
      if (files.length >= CASHOUT_FILES_MAX) break;
      const size = Number(item?.size) || 0;
      if (!size || total + size > CASHOUT_BYTES_MAX) continue;
      const name = cashoutUniqueName(String(item?.name ?? ""), names);
      const copy = cashoutCopyFile(item?.file, name, String(item?.type ?? ""));
      if (!copy) continue;
      names.add(name);
      total += size;
      files.push(copy);
    }
    home.carry = files.length
      ? { at: stamp, want: Math.max(Number(want) || 0, files.length), files }
      : null;
    return files.length;
  };
  // Забрать груз: зовёт НОВОЕ окно у того же родителя. done:true — груз больше не
  // нужен, байты можно отпустить.
  const cashoutTake = (at, done) => {
    const home = cashoutHome();
    const carry = home.carry;
    if (!carry || !Array.isArray(carry.files) || Number(at) !== carry.at) return null;
    const taken = { at: carry.at, want: carry.want, files: carry.files.slice() };
    if (done === true) home.carry = null;
    return taken;
  };
  // Где лежит груз: у главного окна — у себя, у попапа — у родителя. Родителя
  // нет или он старой версии — груз не поедет, и об этом говорит плашка.
  const cashoutHost = () => {
    try {
      if (isMainWindow()) return { carry: cashoutCarry, take: cashoutTake };
      const parent = window.opener;
      const outside = parent?.__myclaude;
      if (typeof outside?.cashoutCarry !== "function" || typeof outside?.cashoutTake !== "function") return null;
      return {
        carry: (list, at, want) => outside.cashoutCarry(list, at, want),
        take: (at, done) => outside.cashoutTake(at, done),
      };
    } catch { return null; }
  };
  // Курсор в самое начало поля: вставка ложится ПЕРЕД черновиком и не затирает
  // его. Пустому полю это ничего не стоит.
  const caretToStart = (editor) => {
    try {
      const selection = (typeof getSelection === "function" ? getSelection() : null) ?? document.getSelection?.();
      if (!selection) return;
      const range = document.createRange();
      range.setStart(editor, 0);
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);
    } catch {}
  };
  // Курсор в конец поля (кнопка «Отчёт» панели PMP, 12п³; слова-действия, 12р).
  const caretToEnd = (editor) => {
    try {
      const selection = (typeof getSelection === "function" ? getSelection() : null) ?? document.getSelection?.();
      if (!selection) return;
      const range = document.createRange();
      range.selectNodeContents(editor);
      range.collapse(false);
      selection.removeAllRanges();
      selection.addRange(range);
    } catch {}
  };
  // Приметный кусок вставки: по нему видно, что в поле попал ИМЕННО наш текст.
  // Нужен он только при вставке ПЕРЕД черновиком — там поле непусто и до
  // вставки, и «поле не пусто» ничего не доказывает. В пустое поле критерий
  // прежний: поле стало непустым. Требовать примету и там нельзя — ProseMirror
  // переписывает вставленное по-своему (списки, кавычки, разметка), примета не
  // находится, и второй путь клал бы текст ВТОРОЙ раз: так дублился «Обкэшить».
  const insertProbe = (text) => String(text).replace(/\s+/g, " ").trim().slice(0, 40);
  const insertLength = (editor) => rawText(editor).replace(/\s+/g, " ").length;
  const insertLanded = (editor, probe, before) => {
    const after = rawText(editor).replace(/\s+/g, " ");
    return after.length > before && (probe === "" || after.includes(probe));
  };
  // Вставка текста в редактор. Сначала execCommand — Chromium проводит его через
  // штатный ввод, и ProseMirror видит обычный набор; если тот его проглотил (в
  // разных сборках бывает и так), досылаем то же самое событием paste с
  // DataTransfer. Отправку не трогаем ни в одном из путей: Enter не шлём.
  // atStart: true — перед черновиком, "end" — в конец (курсор туда же), иначе — где курсор.
  // Вставленное потом видно: поле прокручивается к нему (#10333, composerScrollToEnd).
  const insertIntoEditor = (editor, text, atStart) => {
    const landed = insertIntoEditorNow(editor, text, atStart);
    composerScrollToEnd(editor);
    return landed;
  };
  const insertIntoEditorNow = (editor, text, atStart) => {
    const caret = () => { if (atStart === "end") caretToEnd(editor); else if (atStart) caretToStart(editor); };
    const probe = atStart ? insertProbe(text) : "";
    const before = insertLength(editor);
    try { editor.focus(); } catch {}
    caret();
    try { document.execCommand("insertText", false, text); } catch {}
    if (insertLanded(editor, probe, before)) return true;
    // Поле выросло, а примета не нашлась: текст всё-таки лёг, просто редактор
    // переписал его. Второй путь поверх — это ровно дубль, поэтому его нет.
    if (insertLength(editor) > before) return true;
    // ProseMirror не принял execCommand — досылаем то же самое событием paste.
    try { editor.focus(); } catch {}
    caret();
    try {
      const data = new DataTransfer();
      data.setData("text/plain", text);
      editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
    } catch {}
    return insertLanded(editor, probe, before);
  };
  // Подтверждение доезда переноса (WF50, #5780) ------------------------------
  // Сравнение нормализованное: NBSP становится пробелом, пробелы схлопываются.
  const cashoutNorm = value => String(value ?? "").replace(/\u00a0/g, " ").replace(/\s+/g, " ").trim();
  // Доехало ли: голова в 40 знаков нашлась ИЛИ длина добрала до 90 % нужной.
  // Второе — про редактор, который переписал вставленное по-своему.
  const cashoutArrived = (editor, text) => {
    const want = cashoutNorm(text);
    if (!want) return true;
    const got = cashoutNorm(rawText(editor));
    const head = want.slice(0, CASHOUT_HEAD);
    return got.length >= Math.min(want.length, CASHOUT_HEAD) &&
      (got.includes(head) || got.length >= want.length * CASHOUT_RATIO);
  };
  // То же, но строго по голове. Спрашивается ДО вставки: длина сама по себе
  // ничего не доказывает (в поле мог лежать чужой черновик той же длины), а
  // голова доказывает, что текст уже лёг, — значит вставлять второй раз нельзя.
  const cashoutHeadHit = (editor, text) => {
    const head = cashoutNorm(text).slice(0, CASHOUT_HEAD);
    return head !== "" && cashoutNorm(rawText(editor)).includes(head);
  };
  // Два способа вставки, между которыми переключается подтверждение. Первый —
  // execCommand (Chromium проводит его через штатный ввод), второй — событие
  // paste с DataTransfer: бывают сборки, где ProseMirror глотает первый.
  // Непустое поле выделяется целиком: черновик Элвиса уже внутри переноса,
  // поэтому вставка ПОВЕРХ ничего не теряет и не задваивает (#5781).
  const cashoutPut = (editor, text, way) => {
    try { editor.focus(); } catch {}
    if (editorText(editor)) { try { document.execCommand("selectAll"); } catch {} }
    // Второй способ — событие paste: поле прокрутит слушатель раздела «Вставка прокручивает поле» (#10333).
    if (way !== 2) { try { document.execCommand("insertText", false, text); } catch {} composerScrollToEnd(editor); return; }
    try {
      const data = new DataTransfer();
      data.setData("text/plain", text);
      editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
    } catch {}
  };
  // «Эта запись — мне?» (WF37). true — да, false — точно нет, null — сказать
  // нечего: своего id окно ещё не знает, а заголовок не совпал.
  //
  // Свой id знаем — он и решает ОДИН (#5787): не сошёлся с адресатом, значит
  // запись чужая, и совпадение заголовка её не спасает. Правило WF37 («мой id
  // ИЛИ мой заголовок») писалось, когда id почти никогда не был известен, — а
  // заголовок попапа это снимок имени чата на момент выноса: после
  // переименования его носит уже другое окно, и чужой перенос уезжал бы в чат,
  // где Элвис работает.
  //
  // Заголовок остаётся вторым, запасным признаком ровно там, где первого нет:
  // попап получает имя от сессии в момент выноса, и до первого ответа probe это
  // единственное, чем он себя знает. Заглушки («Claude», «New chat») в
  // сопоставлении не участвуют вовсе — их носят разные чаты во всех окнах разом.
  const cashoutMine = record => {
    const id = myChatId();
    if (id) return id === record.to;
    const title = windowTitle();
    if (title && record.title === title && !THEME_TITLE_STUBS.has(title.toLowerCase())) return true;
    return null;
  };
  // Попап узнаёт свой id только у окна-родителя (раздел 12в), и сторож спрашивает
  // его РОВНО один раз на запись: ответ ложится в кэш myclaude-chat-v1, и
  // следующий тик берёт id уже оттуда. Не ответили — ждём круга probe от
  // приложения, а не долбим родителя каждые 300 мс.
  const cashoutAskParent = () => {
    if (state.cashoutAsked) return;
    state.cashoutAsked = true;
    try { Promise.resolve(chatsAsk(true)).catch(() => {}); } catch {}
  };
  // С какого мгновения в поле стоит чужой черновик и у какой записи (#5781).
  let cashoutDraftFor = 0;
  let cashoutDraftSince = 0;
  // Работа доставки (WF50): одна на окно, свой таймер, две фазы. «text» —
  // вставили и ждём доезда, «files» — текст доехал, ждём карточек вложений.
  // Своего интервала работа не заводит: тикает собственным setTimeout, потому
  // что паузы у фаз разные (150 мс против 200 мс).
  let cashoutJob = null;
  const clearCashoutJob = () => {
    if (!cashoutJob) return;
    if (cashoutJob.timer) clearTimeout(cashoutJob.timer);
    cashoutJob = null;
  };
  track(clearCashoutJob);
  const cashoutLater = () => {
    if (!cashoutJob) return;
    cashoutJob.timer = setTimeout(cashoutTick,
      cashoutJob.phase === "files" ? CASHOUT_ATTACH_MS : CASHOUT_CONFIRM_MS);
  };
  // Приговор: вставить не вышло. Запись НЕ чистим — она умрёт по сроку сама, а
  // приложение по этому слову поймёт, что донора трогать нельзя.
  const cashoutGiveUp = (job, why) => {
    const at = job.at;
    const until = job.until;
    clearCashoutJob();
    clearCashoutWatch();
    cashoutSay(at, until, `${CASHOUT_REFUSED}: ${why}`);
  };
  // Текст доехал: только теперь чистим запись (#5780) и берёмся за вложения.
  const cashoutLanded = (job, editor) => {
    const at = job.at;
    const until = job.until;
    clearCashoutJob();
    clearCashoutWatch();
    clearCashout();
    cashoutSay(at, until, CASHOUT_DONE);
    setStage(STAGE_NORMAL);
    try { cashoutAttach(at, editor); } catch {}
  };
  // Вложения кладём ПОСЛЕ текста: вставка текста идёт с выделением всего поля и
  // смахнула бы прикреплённое. Прикладываем только НЕДОСТАЮЩИЕ — иначе повтор
  // работы приложил бы те же файлы второй раз.
  const cashoutAttach = (at, editor) => {
    const host = cashoutHost();
    const carry = host ? host.take(at, false) : null;
    const files = carry?.files ?? [];
    if (!files.length) return;
    const have = cashoutPills();
    cashoutFilesCount = { want: carry.want, sent: files.length, done: Math.min(have, carry.want) };
    const missing = have < files.length ? attachFresh(files.slice(have), "cashout") : [];
    if (missing.length) {
      try {
        const data = new DataTransfer();
        for (const file of missing) data.items.add(file);
        try { editor.focus(); } catch {}
        editor.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true }));
      } catch {}
    }
    cashoutJob = { at, text: "", editor, phase: "files", way: 0, tries: 0, timer: 0, want: files.length, carry: carry.want };
    cashoutLater();
  };
  const cashoutTick = () => {
    const job = cashoutJob;
    if (!job || !state.alive) { clearCashoutJob(); return; }
    const editor = job.editor?.isConnected ? job.editor : findEditor();
    if (!editor?.isConnected) {
      if (job.phase === "files") { cashoutFinishFiles(job); return; }
      cashoutGiveUp(job, "поле ввода пропало");
      return;
    }
    if (job.phase === "files") {
      const done = cashoutPills();
      cashoutFilesCount = { ...cashoutFilesCount, done: Math.min(done, job.carry) };
      job.tries += 1;
      if (done >= job.want || job.tries >= CASHOUT_ATTACH_TRIES) { cashoutFinishFiles(job); return; }
      cashoutLater();
      return;
    }
    if (cashoutArrived(editor, job.text)) { cashoutLanded(job, editor); return; }
    job.tries += 1;
    if (job.way === 1 && job.tries >= CASHOUT_CONFIRM_FIRST) {
      // Первый способ не взял — досылаем то же самое вторым и ждём ещё.
      job.way = 2;
      job.tries = 0;
      cashoutPut(editor, job.text, 2);
    } else if (job.way === 2 && job.tries >= CASHOUT_CONFIRM_SECOND) {
      cashoutGiveUp(job, "текст не попал в поле");
      return;
    }
    cashoutLater();
  };
  // Конец работы с вложениями: груз отпускаем, недоехавшее называем плашкой —
  // молчаливая потеря вложений и была жалобой Элвиса.
  const cashoutFinishFiles = job => {
    clearCashoutJob();
    const host = cashoutHost();
    try { host?.take(job.at, true); } catch {}
    const done = cashoutFilesCount.done;
    if (done < cashoutFilesCount.want) {
      try { newWindowNote(CASHOUT_NOTE_PART(done, cashoutFilesCount.want)); } catch {}
    }
  };
  const tryPasteCashout = () => {
    const record = readCashout();
    if (record == null) return "нет записи";
    // Работа уже идёт или приговор по ЭТОЙ записи уже вынесен — второй раз не
    // вставляем: дубль текста хуже задержки.
    if (cashoutJob) return "ждём доезда";
    if (cashoutVerdict && record.at === cashoutVerdictAt) return cashoutVerdict;
    // Запись «Нового чата» главного окна (К1, Б2) сторож не вставляет никогда:
    // её забирает цепочка new-window с sendTransfer и стирает сама.
    if (record.handoff && record.to == null) return CASHOUT_HANDOFF_MAIN;
    if (record.to != null) {
      // Перенос из подчинённого окна (WF37, #5575) адресован НОВОМУ окну,
      // которое родит цепочка «Нового окна». Главное окно такие записи не
      // трогает вовсе: ⌘N в нём случается по десять раз на дню, и перенос
      // уехал бы в чат, где Элвис работает.
      if (isMainWindow()) return "перенос не главному окну";
      if (record.to === CASHOUT_PENDING) {
        // Цепочка сорвалась и адресата так и не назвала: запись умирает молча
        // по общему сроку от нажатия (риск 3 плана WF37).
        if (Date.now() - record.at > CASHOUT_FRESH_MS) { clearCashout(); return "запись протухла"; }
        return "адресат не назначен";
      }
      if (record.stampedAt == null || Date.now() - record.stampedAt > CASHOUT_STAMP_FRESH_MS) {
        clearCashout();
        return "перенос протух";
      }
      const mine = cashoutMine(record);
      if (mine === null) { cashoutAskParent(); return "чат не опознан"; }
      if (!mine) return "перенос не в это окно";
      // «Новый чат» (К2, Б2): текст уже ушёл первым сообщением (sent) или его
      // не было вовсе — вставлять нечего, доезд подтверждаем сразу: по этому
      // слову приложение закрывает донора.
      if (record.handoff && (record.sent || record.text === "")) {
        const until = cashoutLife(record);
        clearCashoutWatch();
        clearCashout();
        cashoutSay(record.at, until, CASHOUT_DONE);
        return CASHOUT_DONE;
      }
    } else if (Date.now() - record.at > CASHOUT_FRESH_MS) { clearCashout(); return "запись протухла"; }
    const editor = state.editor?.isConnected ? state.editor : findEditor();
    if (!editor?.isConnected) return "нет редактора";
    // Вставляем только в свежий чат: иначе перенос лёг бы посреди разговора.
    // Свежесть спрашиваем только у записи БЕЗ адресата: у переноса окно названо
    // поимённо, а первым сообщением в нём может оказаться что угодно.
    if (record.to == null && !isFreshChat()) return "чат не свежий";
    // Черновик в поле — больше НЕ отказ (#5781). Раньше перенос из-за него молча
    // протухал, а окно-донор к тому времени уже закрыто (#5768) — терялся текст
    // Элвиса. Свежий чат иногда доезжает с прошлым черновиком, и Claude убирает
    // его сам: столько ждём, а дальше вставляем поверх выделения всего поля.
    if (editorText(editor)) {
      if (cashoutDraftFor !== record.at) { cashoutDraftFor = record.at; cashoutDraftSince = Date.now(); }
      if (Date.now() - cashoutDraftSince < CASHOUT_DRAFT_WAIT_MS) return "ждём черновик";
    }
    // Текст уже в поле (инжект перечитали посреди доставки) — вторую вставку не
    // делаем, только подтверждаем.
    if (!cashoutHeadHit(editor, record.text)) cashoutPut(editor, record.text, 1);
    cashoutJob = { at: record.at, until: cashoutLife(record), text: record.text, editor,
      phase: "text", way: 1, tries: 0, timer: 0 };
    cashoutLater();
    return "ждём доезда";
  };
  const clearCashoutWatch = () => {
    if (!state.cashoutTimer) return;
    clearInterval(state.cashoutTimer);
    state.cashoutTimer = 0;
  };
  track(clearCashoutWatch);
  // Сторож вставки. ⌘N может открыть новый чат и в этом же окне (страница не
  // перезагружается, инжект заново не приходит), поэтому ждём появления свежего
  // чата, а не одного лишь момента установки. Живёт ровно пока запись свежая.
  const CASHOUT_WATCH_DONE = new Set([
    "запись протухла", "нет записи",
    // Перенос протух или достался главному окну — ждать в этом окне больше
    // нечего: свою запись главное окно заведёт заново, вместе со сторожем.
    "перенос протух", "перенос не главному окну",
    // Запись «Нового чата» в главном окне — дело цепочки new-window, не сторожа.
    CASHOUT_HANDOFF_MAIN,
  ]);
  // Дальше сторожу делать нечего: работа доставки вынесла приговор (доехало или
  // не доехало) — она же и гасит сторожа, но повтор тика не должен его заводить.
  const cashoutWatchDone = result => CASHOUT_WATCH_DONE.has(result) ||
    result === CASHOUT_DONE || result.startsWith(`${CASHOUT_REFUSED}:`);
  const armCashoutWatch = () => {
    clearCashoutWatch();
    if (readCashout() == null) return;
    // Вопрос родителю — один на запись, а не на сторожа: новая запись имеет
    // право спросить заново (см. cashoutAskParent).
    state.cashoutAsked = false;
    state.cashoutTimer = setInterval(() => {
      if (!state.alive) { clearCashoutWatch(); return; }
      const result = tryPasteCashout();
      if (cashoutWatchDone(result)) clearCashoutWatch();
    }, CASHOUT_TICK_MS);
  };
  // Текст передачи «Нового чата» (К1, #7072, критик Б3): ТОЛЬКО из последнего
  // ответа — заголовок с «ОТКРОЙ НОВЫЙ ЧАТ», дальше первый блок кода
  // [data-code-text] после него. Блок трёхответной давности или текст панели
  // не годятся: первым сообщением ушёл бы чужой или старый текст. Нет узла —
  // пустая строка, запасного пути нет.
  const CASHOUT_HANDOFF_HEAD_RE = /ОТКРОЙ\s+НОВЫЙ\s+ЧАТ/i;
  // Заголовок и узел блока передачи — их же ищет кнопка «💬 Новый чат» (12к).
  // Берём ПОСЛЕДНИЙ заголовок, у которого после него есть непустой блок кода
  // (WF85, К7.1): по правилу ELVIS.md ответ кончается ещё одним «🆕 ОТКРОЙ
  // НОВЫЙ ЧАТ» без кода, и до WF85 этот хвостовой повтор сбрасывал находку —
  // кнопки под таким ответом не было, ⌘B слал пустой текст.
  // Ищем по всем строкам последнего сообщения (lastAnswerRows) подряд; answer
  // находки — строка с блоком, rows — всё сообщение (на нём ссылки и «Модель:»).
  const cashoutHandoffFind = (answer = lastAnswerRows() ?? lastAnswerNode()) => {
    const rows = Array.isArray(answer) ? answer : answer ? [answer] : [];
    let head = null;
    let hit = null;
    let taken = true;
    // Инлайн-код и чип файла у Claude 2.9939.2 тоже несут data-code-text —
    // с пометкой data-epitaxy-inline-code; блоком передачи они не бывают.
    for (const row of rows) {
      for (const node of row.querySelectorAll('h1,h2,h3,h4,h5,h6,[role="heading"],[data-code-text]:not([data-epitaxy-inline-code])')) {
        if (node.hasAttribute?.("data-code-text")) {
          if (!taken && cashoutCodeText(node)) { hit = { answer: row, rows, head, code: node }; taken = true; }
          continue;
        }
        if (CASHOUT_HANDOFF_HEAD_RE.test(node.textContent ?? "")) { head = node; taken = false; }
      }
    }
    return hit;
  };
  const cashoutCodeText = node => String(node?.getAttribute?.("data-code-text") || node?.textContent || "").trim();
  // Строка «Модель:» между заголовком и блоком (WF85, К7.2, критик В2): фразу и
  // строку модели markdown склеивает в один <p>, поэтому ищем СТРОКУ, а не
  // узел. textContent держит мягкий перенос «\n», innerText — <br>; смотрим оба.
  // Узлы, внутри которых сам блок или заголовок, не берём: иначе строкой
  // «Модель:» могла бы оказаться строка текста передачи.
  const HANDOFF_MODEL_RE = /\b(opus|sonnet|haiku|fable)\s+(\d+(?:\.\d+)?)/i;
  const HANDOFF_EFFORT_RE = /\b(xhigh|extra|low|medium|high|max)\b/i;
  const cashoutHandoffModelLine = hit => {
    if (!hit?.head || !hit.code) return "";
    let after = false;
    for (const row of hit.rows ?? [hit.answer]) {
      for (const node of row.querySelectorAll("*")) {
        if (node === hit.code) return "";
        if (node === hit.head) { after = true; continue; }
        if (!after || node.contains(hit.code) || node.contains(hit.head)) continue;
        for (const text of [node.textContent, node.innerText]) {
          for (const line of String(text ?? "").split("\n")) {
            const clean = line.replace(/^[\s*_>·•-]+/, "");
            if (/^Модель\s*:/i.test(clean)) return clean;
          }
        }
      }
    }
    return "";
  };
  // «Opus 5.5 · 🔥 XHIGH» → {model:"Opus 5.5", effort:"Extra"}; не разобралось — поля нет.
  const cashoutHandoffModel = line => {
    const out = {};
    const model = String(line ?? "").match(HANDOFF_MODEL_RE);
    if (!model) return out;
    out.model = `${model[1][0].toUpperCase()}${model[1].slice(1).toLowerCase()} ${model[2]}`;
    const step = String(line).slice(model.index + model[0].length).match(HANDOFF_EFFORT_RE)?.[1]?.toLowerCase();
    if (step) out.effort = step === "xhigh" || step === "extra" ? "Extra" : `${step[0].toUpperCase()}${step.slice(1)}`;
    return out;
  };
  const runCashout = (detail = null) => {
    if (detail?.handoff === true) return runCashoutHandoff();
    const answer = lastAnswerText();
    const draft = rawText(state.editor).trim();
    const parts = [];
    if (answer) parts.push(answer);
    if (draft) parts.push(draft);
    const text = parts.join("\n\n");
    if (!text) {
      // Молчать нельзя: ⌘N жмёт приложение независимо от нашего ответа, и без
      // плашки Элвис видит только пустой новый чат.
      cashoutRefusal = CASHOUT_NOTE_EMPTY;
      try { newWindowNote(CASHOUT_NOTE_EMPTY); } catch {}
      return false;
    }
    cashoutRefusal = null;
    // Из подчинённого окна перенос уезжает в НОВОЕ окно (WF37, #5575): ⌘N в
    // попапе исполняет главное окно Claude, и старый путь бил по чату, где
    // Элвис ведёт диктовку. Адресата назовёт цепочка «Нового окна»
    // (cashoutStamp), поэтому здесь только пометка «ждёт адресата». Своего
    // сторожа донор не заводит и чужого не оставляет: вставлять перенос ему
    // некуда, а тикать 300 мс впустую незачем.
    const transfer = !isMainWindow();
    const at = Date.now();
    const record = transfer
      ? { at, text, to: CASHOUT_PENDING }
      : { at, text };
    try { localStorage.setItem(CASHOUT_KEY, JSON.stringify(record)); } catch { return false; }
    // Прошлый приговор снимаем: он принадлежал прошлой записи, а новая только
    // поехала (status().cashout.delivery обязан сказать «ждём»).
    cashoutVerdict = "";
    cashoutVerdictAt = 0;
    cashoutVerdictUntil = 0;
    // Вложения (WF50, #5773) уезжают тем же нажатием: File из донора кладём в
    // память главного окна, а забирает их новое окно после доезда текста. Из
    // донора не снимаем НИЧЕГО — только копируем: испорченное окно при отказе и
    // было главной бедой донора ElvisOS.
    const haul = cashoutHaul();
    const host = haul.files.length ? cashoutHost() : null;
    let carried = 0;
    try { carried = host ? host.carry(haul.files, at, haul.want) : 0; } catch { carried = 0; }
    cashoutFilesCount = { want: haul.want, sent: carried, done: 0 };
    // Груз не взяли вовсе (родителя нет или файлов на полке не осталось) —
    // говорим об этом здесь: молча Элвис узнал бы о потере только глазами.
    if (haul.want > 0 && carried === 0) {
      try { newWindowNote(CASHOUT_NOTE_LEFT(haul.want)); } catch {}
    }
    if (transfer) clearCashoutWatch(); else armCashoutWatch();
    return true;
  };
  // «Обкэшить» с handoff (К1): запись без черновика и вложений, сторожа нет ни
  // в попапе, ни в главном окне (Б2). Пустой текст — не отказ: новый чат пустой.
  const runCashoutHandoff = () => {
    const hit = cashoutHandoffFind();
    const text = cashoutCodeText(hit?.code);
    // Кнопка в чате (12к) ждала именно этой команды: приложение её услышало.
    try { continueAck(); } catch {}
    // Ответ ушёл в новый чат (⌘B, кнопка или «сам») — сам его больше не откроет.
    try { autoTaken(hit); } catch {}
    cashoutRefusal = null;
    const at = Date.now();
    const record = isMainWindow() ? { at, text, handoff: true } : { at, text, to: CASHOUT_PENDING, handoff: true };
    // К7.3 (WF85): model и effort — ПОСЛЕ handoff и только разобранные.
    Object.assign(record, cashoutHandoffModel(cashoutHandoffModelLine(hit)));
    try { localStorage.setItem(CASHOUT_KEY, JSON.stringify(record)); } catch { return false; }
    cashoutVerdict = "";
    cashoutVerdictAt = 0;
    cashoutVerdictUntil = 0;
    cashoutFilesCount = { want: 0, sent: 0, done: 0 };
    clearCashoutWatch();
    return true;
  };
  // Штамп переноса (WF37): цепочка «Нового окна» с полем transfer называет
  // адресата записи, оставленной попапом-донором, — id только что рождённого
  // чата и заголовок его строки сайдбара. Записи без пометки «ждёт адресата»
  // не трогаем вовсе: чужой перенос и обычная запись главного окна обязаны
  // остаться как были (критик плана, блокер 2).
  // sent (К2) — текст передачи уже ушёл первым сообщением: эталон record-sent.
  const cashoutStamp = (id, title, sent = false) => {
    const record = readCashout();
    if (record == null || record.to !== CASHOUT_PENDING) return false;
    const chat = typeof id === "string" ? id.trim() : "";
    if (!chat) return false;
    const stamped = {
      at: record.at,
      text: record.text,
      to: chat,
      title: typeof title === "string" ? title.trim() : "",
      stampedAt: Date.now(),
    };
    if (record.handoff) {
      stamped.handoff = true;
      stamped.sent = sent === true;
    }
    try { localStorage.setItem(CASHOUT_KEY, JSON.stringify(stamped)); } catch { return false; }
    return true;
  };
