    link.removeAttribute(CONTINUE_LINK_ATTRIBUTE);
    link.removeAttribute(CONTINUE_LINK_STATE_ATTRIBUTE);
    link.removeAttribute(CONTINUE_LINK_TEXT_ATTRIBUTE);
