    for (const orphan of document.querySelectorAll(`#${PMP_PANEL_ID}`)) orphan.remove();
    const node = document.createElement("div");
    node.id = PMP_PANEL_ID;
    node.setAttribute("role", "group");
    node.setAttribute("aria-label", PMP_TITLE);
