    // в атрибуте): блок — её тело до </details>, без самой головы (12с³ сделал бы ссылкой «ЖДЁТ ТЕБЯ»). DOM, не
    // foldState: раздел 12ф склеен ниже.
    try { heads = [...document.querySelectorAll(`[${FOLD_HEAD_ATTRIBUTE}]`)]; } catch { heads = []; }
