    thead.appendChild(row(head, "th"));
    table.appendChild(thead);
    const tbody = seamEl("tbody");
    let j = i + 2;
    for (; j < lines.length && lines[j].trim() && lines[j].includes("|"); j += 1) tbody.appendChild(row(seamCells(lines[j]), "td"));
