    "--cds-assistant-message-text-inset": ["a", "4px"],
    "--cds-assistant-message-text-stop": ["a", "clamp(0px, (100% - 384px) * .175, 56px)"],
    "--cds-message-bubble-radius": ["u", "12px"],
    "--cds-message-bubble-pad-x": ["u", "16px"],
    "--cds-message-bubble-pad-y": ["u", "12px"],
