    try { bubble = feed?.querySelector('[data-cds="UserMessage"] > div'); } catch {}
    try { rowA = feed?.querySelector('[data-cds="AssistantMessage"]'); } catch {}
    try { rowU = feed?.querySelector('[data-cds="UserMessage"]'); } catch {}
